def _abs_path(raw: str) -> Path:
    p = Path(str(raw or "").strip())
    if p.is_absolute():
        return p
    return BASE_DIR / p


STATUS_FILE = _abs_path(WATCHDOG_STATUS_FILE)


def _parse_ids(raw: str) -> set[int]:
    out: set[int] = set()
    for x in re.split(r"[,\s]+", str(raw or "")):
        x = x.strip()
        if not x:
            continue
        try:
            out.add(int(x))
        except Exception:
            pass
    return out


ALLOWED_USERS = _parse_ids(PANEL_ALLOWED_USER_IDS)
ALLOWED_CHATS = _parse_ids(PANEL_ALLOWED_CHAT_IDS)
NOTIFY_CHATS = _parse_ids(PANEL_NOTIFY_CHAT_IDS)



def _connect_panel_db() -> sqlite3.Connection:
    parent = os.path.dirname(os.path.abspath(TPILOT_DB_PATH))
    if parent:
        os.makedirs(parent, exist_ok=True)
    con = sqlite3.connect(TPILOT_DB_PATH, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    return con


def _ensure_panel_runtime_tables() -> None:
    con = _connect_panel_db()
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS panel_subscribers(
                chat_id INTEGER PRIMARY KEY,
                user_id INTEGER DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS panel_notifications(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                kind TEXT NOT NULL DEFAULT '',
                title TEXT NOT NULL DEFAULT '',
                body TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'new',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS panel_active_message(
                chat_id INTEGER PRIMARY KEY,
                message_id INTEGER NOT NULL DEFAULT 0,
                user_id INTEGER DEFAULT 0,
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS panel_wizard_state(
                chat_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                wizard TEXT NOT NULL DEFAULT '',
                step TEXT NOT NULL DEFAULT '',
                payload_json TEXT NOT NULL DEFAULT '{}',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(chat_id, user_id)
            );
        """)
        con.execute("CREATE INDEX IF NOT EXISTS panel_notifications_status_idx ON panel_notifications(status, id)")
        con.commit()
    finally:
        con.close()


def _utc_now_iso() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat()


def _register_panel_subscriber(chat_id: int, user_id: int = 0) -> None:
    try:
        _ensure_panel_runtime_tables()
        now = _utc_now_iso()
        con = _connect_panel_db()
        try:
            con.execute(
                "INSERT INTO panel_subscribers(chat_id, user_id, updated_at) VALUES(?,?,?) ON CONFLICT(chat_id) DO UPDATE SET user_id=excluded.user_id, updated_at=excluded.updated_at",
                (int(chat_id), int(user_id or 0), now),
            )
            con.commit()
        finally:
            con.close()
    except Exception:
        pass


def _notification_targets() -> List[int]:
    targets: set[int] = set(int(x) for x in NOTIFY_CHATS if int(x))
    targets.update(int(x) for x in ALLOWED_CHATS if int(x))
    try:
        _ensure_panel_runtime_tables()
        con = _connect_panel_db()
        try:
            rows = con.execute("SELECT chat_id FROM panel_subscribers ORDER BY updated_at DESC LIMIT 20").fetchall()
            for row in rows or []:
                try:
                    targets.add(int(row[0]))
                except Exception:
                    pass
        finally:
            con.close()
    except Exception:
        pass
    return [x for x in targets if x]


def _take_panel_notifications(limit: int = 10) -> List[dict]:
    _ensure_panel_runtime_tables()
    con = _connect_panel_db()
    try:
        con.execute("BEGIN IMMEDIATE")
        rows = con.execute("SELECT * FROM panel_notifications WHERE status='new' ORDER BY id ASC LIMIT ?", (int(limit),)).fetchall()
        ids = [int(r['id']) for r in rows or []]
        if ids:
            q = ','.join(['?'] * len(ids))
            now = _utc_now_iso()
            con.execute(f"UPDATE panel_notifications SET status='running', updated_at=? WHERE id IN ({q})", (now, *ids))
        con.commit()
        return [dict(r) for r in rows or []]
    except Exception:
        try:
            con.rollback()
        except Exception:
            pass
        return []
    finally:
        con.close()


def _finish_panel_notification(notification_id: int, ok: bool = True) -> None:
    try:
        _ensure_panel_runtime_tables()
        con = _connect_panel_db()
        try:
            # HNV2 D9: CAS on status='running' -- if a reaper (see
            # _reap_stale_running_panel_notifications below) already
            # returned this row to 'new' (e.g. this delivery attempt is
            # itself a zombie from a crashed prior loop iteration racing
            # a fresh pickup), this UPDATE must become a no-op rather than
            # overwriting the fresh attempt's own eventual outcome.
            con.execute(
                "UPDATE panel_notifications SET status=?, updated_at=? WHERE id=? AND status='running'",
                ('done' if ok else 'error', _utc_now_iso(), int(notification_id)),
            )
            con.commit()
        finally:
            con.close()
    except Exception:
        pass


def _reap_stale_running_panel_notifications(max_age_sec: int = 600) -> int:
    """HNV2 D9: returns panel_notifications rows stuck in 'running' longer
    than max_age_sec back to 'new' so the next loop iteration re-delivers
    them, instead of losing them forever. Mirrors panel_bridge.py's own
    reap_stale_running_panel_commands for the OTHER queue (panel_commands)
    -- panel_notifications never had an equivalent durability guard before
    this fix: a PanelBot crash between _take_panel_notifications' claim
    (status='running') and _finish_panel_notification's own write would
    strand the row in 'running' permanently. Returns the number of rows
    reaped. Never raises."""
    try:
        _ensure_panel_runtime_tables()
        cutoff = (datetime.utcnow() - timedelta(seconds=max(60, int(max_age_sec or 600)))).replace(microsecond=0).isoformat()
        con = _connect_panel_db()
        try:
            cur = con.execute(
                "UPDATE panel_notifications SET status='new', updated_at=? WHERE status='running' AND updated_at < ?",
                (_utc_now_iso(), cutoff),
            )
            con.commit()
            return int(cur.rowcount or 0)
        finally:
            con.close()
    except Exception:
        return 0



