def _event_message_id(event) -> int:
    for attr in ("message_id", "msg_id"):
        try:
            v = int(getattr(event, attr, 0) or 0)
            if v:
                return v
        except Exception:
            pass
    try:
        q = getattr(event, "query", None)
        v = int(getattr(q, "msg_id", 0) or 0)
        if v:
            return v
    except Exception:
        pass
    return 0


