def _auth_chooser_buttons(context: str, ref: str):
    # TPILOT AUTH SAFETY 20260809 (Ф4, unified auth UX): ONE chooser builder
    # for all three contexts (add/relogin/replace). ADD reuses the EXISTING,
    # already-safe wiz:qr_start / wiz:tdimport_start callback_data verbatim
    # (zero behavior change to the already-tested onboarding QR/session/tdata
    # entry points) -- only its Phone/Back buttons are new. relogin/replace
    # route QR/Session/TData through the new auth:<ctx>:<method>:<ref>
    # namespace, wired to the Ф3/Ф4 backend entry points in main.py.
    ref = str(ref or "")
    ctx = str(context or "add")
    if ctx == "add":
        qr_cb = f"wiz:qr_start:{ref}".encode()
        session_cb = f"wiz:tdimport_start:{ref}".encode()
        tdata_cb = f"wiz:tdimport_start:{ref}".encode()
        phone_cb = f"auth:{ctx}:phone:{ref}".encode()
        back_cb = f"auth:{ctx}:back:{ref}".encode()
    elif ctx == "relogin":
        # relogin's own existing "relogin:phone:<key>"/"relogin:cancel:<key>"
        # callbacks already do exactly what is needed (phone: sets step=phone
        # and shows the prompt; cancel: calls /manager_relogin_cancel, which
        # does real server-side temp-file cleanup -- more thorough than the
        # generic auth:*:back handler's plain wizard_clear) -- both reused
        # verbatim instead of duplicating them under the new namespace.
        qr_cb = f"auth:{ctx}:qr:{ref}".encode()
        session_cb = f"auth:{ctx}:session:{ref}".encode()
        tdata_cb = f"auth:{ctx}:tdata:{ref}".encode()
        phone_cb = f"relogin:phone:{ref}".encode()
        back_cb = f"relogin:cancel:{ref}".encode()
    elif ctx == "prepare":
        # TPILOT PREPARED ACCOUNTS PHASE 6: 📦 Подготовить на потом. Same
        # generic auth:prepare:{method}:<key> namespace the fallback branch
        # below already produces -- named explicitly (not folded into
        # `else`) only so this context is self-documenting at the call site.
        qr_cb = f"auth:{ctx}:qr:{ref}".encode()
        session_cb = f"auth:{ctx}:session:{ref}".encode()
        tdata_cb = f"auth:{ctx}:tdata:{ref}".encode()
        phone_cb = f"auth:{ctx}:phone:{ref}".encode()
        back_cb = f"auth:{ctx}:back:{ref}".encode()
    else:
        qr_cb = f"auth:{ctx}:qr:{ref}".encode()
        session_cb = f"auth:{ctx}:session:{ref}".encode()
        tdata_cb = f"auth:{ctx}:tdata:{ref}".encode()
        phone_cb = f"auth:{ctx}:phone:{ref}".encode()
        back_cb = f"auth:{ctx}:back:{ref}".encode()
    return [
        [Button.inline("◻️ QR", qr_cb)],
        [Button.inline("📱 Номер телефона", phone_cb)],
        [Button.inline("📁 Session", session_cb)],
        [Button.inline("📦 TData", tdata_cb)],
        [Button.inline("⬅️ Назад", back_cb)],
    ]


