def _qr_png_bytes(url: str):
    """Render a local QR PNG for the given tg://login URL using segno. Returns a
    BytesIO on success, or None if segno is unavailable or rendering fails for any
    reason (caller must fall back to text-only)."""
    if segno is None or not url:
        return None
    try:
        buf = BytesIO()
        segno.make(url).save(buf, kind="png", scale=6, border=2)
        buf.seek(0)
        buf.name = "qr.png"
        return buf
    except Exception:
        return None


def _qr_image_caption(text: str) -> str:
    expiry_line = ""
    for line in str(text or "").splitlines():
        line = line.strip()
        if line.startswith("Код действителен до:"):
            expiry_line = line
            break
    lines = ["🔳 QR для входа"]
    if expiry_line:
        lines.append(expiry_line)
    lines.append("Сканируйте QR в Telegram на устройстве, где уже залогинен нужный аккаунт: Настройки → Устройства → Подключить устройство")
    return _safe_text("\n".join(lines), 1000)


async def _send_qr_screen(event, chat_id: int, key: str, text: str, qr_url: str) -> None:
    # TPILOT PREPARED ACCOUNTS PHASE 6: `event` is now optional (None) so this
    # same renderer can also be reached from the proxy-continuation seam
    # (_prep_resume_after_proxy), which is invoked from three existing
    # continuation points that only ever have chat_id/user_id, never a
    # callback `event` object. Every original caller still passes a real
    # event and keeps its exact prior behavior (in-place edit/delete).
    buttons = _manager_qr_screen_buttons(key, qr_url)
    png = _qr_png_bytes(qr_url)
    if png is not None:
        try:
            await client.send_file(chat_id, png, caption=_qr_image_caption(text), buttons=buttons)
        except Exception:
            if event is not None:
                await _safe_event_edit(event, _safe_text(text), buttons=buttons)
            else:
                await client.send_message(chat_id, _safe_text(text), buttons=buttons)
            return
        if event is not None:
            try:
                await event.delete()
            except Exception:
                pass
        return
    warn_text = str(text or "") + "\n\n⚠️ Модуль QR-изображения не установлен (segno). Показан только текстовый код/ссылка."
    if event is not None:
        await _safe_event_edit(event, _safe_text(warn_text), buttons=buttons)
    else:
        await client.send_message(chat_id, _safe_text(warn_text), buttons=buttons)


def _parse_qr_url(text: str) -> str:
    for line in str(text or "").splitlines():
        line = line.strip()
        if line.startswith("QR_URL="):
            return line[len("QR_URL="):].strip()
    return ""


# --- TPILOT PREPARED ACCOUNTS PHASE 6 (2026-08-11) AUTH SEAMS BEGIN ----------
# `_auth_start_qr`/`_auth_enter_phone` are the ONLY implementation of "start a
# QR login"/"ask for a phone number" in the whole panel. Both the ORIGINAL
# callback branches (wiz:qr_start:, auth:add:phone:) and the NEW prepared-
# account proxy-continuation seam (_prep_resume_after_proxy, below) call
# these same two functions -- neither branch body is duplicated anywhere.
# `event` is optional: the three existing proxy-continuation points
# (_tpilot_panel_handle_proxy_line, _pbuy_run_confirm/_pbuy_run_recover,
# _frompool_run_assign) only ever have chat_id/user_id, never a callback
# event, so every event-only call (`event.answer`, in-place edit/delete) is
# skipped in favor of a plain client.send_message when event is None.
async def _auth_start_qr(chat_id: int, user_id: int, key: str, *, event=None) -> None:
    key = normalize_manager_key(key or "")
    if not key:
        if event is not None:
            await _pb_safe_answer(event, "Пустой manager_key", alert=True)
        return
    if event is not None:
        await _pb_safe_answer(event, "Открываю вход по QR…")
    row = await _submit_and_wait(f"/manager_qr_start {key}", user_id, chat_id, chat_id)
    text = str(row.get("result_text") or row.get("error_text") or "")
    qr_url = _parse_qr_url(text)
    if str(row.get("status") or "") == "done" and qr_url:
        _wizard_set(chat_id, user_id, "add_manager", "qr", {"key": key})
        try:
            scrub_panel_command_result(TPILOT_DB_PATH, int(row.get("id") or 0))
        except Exception:
            pass
        await _send_qr_screen(event, chat_id, key, text, qr_url)
    else:
        fail_text = "⚠️ " + _safe_text(text or "Не удалось начать вход по QR.")
        if event is not None:
            await _safe_event_edit(event, fail_text, buttons=_manager_phone_recovery_buttons(key))
        else:
            await client.send_message(chat_id, fail_text, buttons=_manager_phone_recovery_buttons(key))


async def _auth_enter_phone(chat_id: int, user_id: int, key: str, *, event=None) -> None:
    key = normalize_manager_key(key or "")
    if not key:
        if event is not None:
            await _pb_safe_answer(event, "Пустой manager_key", alert=True)
        return
    _wizard_set(chat_id, user_id, "add_manager", "phone", {"key": key})
    prompt = "📱 Введите номер телефона менеджера."
    buttons = _manager_qr_entry_button(key) + _back_to_panel_buttons()
    if event is not None:
        await _safe_event_edit(event, prompt, buttons=buttons)
    else:
        await client.send_message(chat_id, prompt, buttons=buttons)


async def _prep_resume_after_proxy(chat_id: int, user_id: int, key: str, *, event=None) -> bool:
    """Durable proxy-continuation seam for 📦 Подготовить на потом (◻️ QR /
    📱 Номер телефона track only). Reads the durably-stored auth method via
    the existing read-only /prepared_pending controller command (NOT the
    wizard payload, which is rebuilt on almost every step and cannot be
    trusted to survive a multi-screen proxy flow) and, if found, resumes
    that SAME method through the SAME helpers the original screens use --
    no second auth chooser is ever shown. Returns False for every non-
    prepared manager (or a prepared account whose method is session/tdata,
    which never reaches this seam at all), in which case the caller must
    continue its normal, unmodified "▶️ Подключить сейчас" behavior."""
    key = normalize_manager_key(key or "")
    if not key:
        return False
    row = await _submit_and_wait(f"/prepared_pending {key}", user_id, chat_id, chat_id)
    method = str(row.get("result_text") or "").strip().lower()
    if method not in ("qr", "phone"):
        return False
    if method == "qr":
        await _auth_start_qr(chat_id, user_id, key, event=event)
    else:
        await _auth_enter_phone(chat_id, user_id, key, event=event)
    return True
