# --- TPILOT PROXY FORCE ONE-LINE PANEL HELPERS 20260508 START ---
def _pxm_manager_identity(row: dict) -> str:
    """Safe 'display_name | @username' identity line -- never a bare '@',
    never 'None'; falls back to 'без username' when no telegram_username
    is on file (never silently omits the segment, unlike _manager_short_label,
    which this intentionally does not touch/replace -- that helper is used
    elsewhere and its own convention stays as-is)."""
    r = row or {}
    name = str(r.get("display_name") or r.get("manager_key") or "").strip() or str(r.get("manager_key") or "").strip()
    user = str(r.get("telegram_username") or "").strip()
    if user:
        return f"{name} | @{user}"
    return f"{name} | без username"


# TPILOT PROXY METHOD MENU 20260718: manual-format text below is scoped to
# what proxy_parser.parse_proxy_line genuinely accepts (verified directly
# against proxy_parser.py) -- deliberately does NOT advertise
# username:password:host:port, space-separated input, multiline input,
# http(s):// schemes (rejected downstream by _tpilot_proxy_parse_set_args_v5
# in main.py, which requires scheme=='socks5'), or passwords containing a
# space/'@'/URL-encoding (silently mishandled by the whitespace-strip /
# reassembly in that same main.py parser).
def _tpilot_proxy_one_line_prompt(key: str, *, new_manager: bool = False) -> str:
    if new_manager:
        title = f"🌐 Proxy для нового менеджера {key}"
    else:
        row = _manager_row_by_key(key)
        title = f"🌐 Proxy для {_pxm_manager_identity(row)}" if row else f"🌐 Proxy для {key}"
    return (
        f"{title}\n\n"
        "Вставьте SOCKS5 одной строкой — ровно один proxy.\n\n"
        "Можно использовать любой из поддерживаемых форматов:\n\n"
        "1. `host:port:login:password` — рекомендуемый\n"
        "2. `login:password@host:port`\n"
        "3. `socks5://login:password@host:port`\n"
        "4. `host:port` — если proxy без логина и пароля\n\n"
        "Хост может быть IP-адресом или доменом.\n"
        "Логин и пароль указывайте без пробелов и символа @.\n\n"
        "Примеры:\n\n"
        "`203.0.113.10:1080:proxyuser:Kx92mPl4`\n\n"
        "`proxyuser:Kx92mPl4@203.0.113.10:1080`\n\n"
        "`socks5://proxyuser:Kx92mPl4@203.0.113.10:1080`\n\n"
        "`203.0.113.10:1080`"
    )


def _tpilot_parse_socks5_one_line(raw: str):
    """Compatibility wrapper around the central proxy_parser.parse_proxy_line.

    Kept for callers still expecting the old (host, port, login, password)
    tuple with "-" as the placeholder for "no credential" (the convention
    the /manager_proxy_set command text below already understands). Now
    accepts every format proxy_parser supports, not just host:port /
    host:port:login:password."""
    text = str(raw or "").strip().replace(" ", "")
    parsed = proxy_parser.parse_proxy_line(text)
    if not parsed:
        return None
    host = parsed["host"]
    port = str(parsed["port"])
    login = parsed.get("login") or "-"
    password = parsed.get("password") or "-"
    return host, port, login, password


def _tpilot_proxy_text_success(text: str) -> bool:
    t = str(text or "").lower()
    if any(
        m in t
        for m in (
            "ошибка",
            "не подключ",
            "failed",
            "error",
            "timeout",
            "invalid",
            "unauthorized",
            "авторизация заблокирована",
            "proxy guard не пройден",
            "⛔",
        )
    ):
        return False
    return (
        "прокси подключ" in t
        or "proxy подключ" in t
        or "proxy проверен" in t
        or "auth guard готов" in t
        or "proxy сохранён" in t
        or "можно продолжать авторизацию" in t
        or ("tcp ok" in t and "telethon ok" in t)
        or ("tcp ok" in t and "telegram ok" in t)
        or ("ip-check через proxy ok" in t and "telethon ok" in t)
    )


async def _tpilot_panel_handle_proxy_line(chat_id: int, user_id: int, key: str, raw: str, *, new_manager: bool):
    key = normalize_manager_key(str(key or ""))
    parsed = _tpilot_parse_socks5_one_line(raw)
    if not key or not parsed:
        wizard_name = "add_manager" if new_manager else "proxy_set"
        step_name = "proxy_line" if new_manager else "line"
        _wizard_set(chat_id, user_id, wizard_name, step_name, {"key": key})
        await client.send_message(
            chat_id,
            "⚠️ Неверный формат proxy.\n\n" + _tpilot_proxy_one_line_prompt(key or "manager", new_manager=new_manager),
            buttons=_back_to_panel_buttons(),
        )
        return True

    host, port, login, password = parsed
    row = await _submit_and_wait(f"/manager_proxy_set {key} SOCKS5 {host} {port} {login} {password}", user_id, chat_id, chat_id)
    text = str(row.get("result_text") or row.get("error_text") or "")
    success = str(row.get("status") or "") == "done" and _tpilot_proxy_text_success(text)

    if new_manager:
        if success:
            if await _prep_resume_after_proxy(chat_id, user_id, key):
                return True
            _wizard_set(chat_id, user_id, "add_manager", "auth_choice", {"key": key})
            # PROXY USAGE DETECTION 20260711: clean success card. Creds come
            # straight from the operator's own just-parsed input above --
            # never from panel_commands result_text (that never carried the
            # raw password to begin with).
            mrow = _manager_row_by_key(key)
            card_text = _proxy_success_card_text(
                manager_key=key, display_name=str(mrow.get("display_name") or "") or key,
                telegram_username=str(mrow.get("telegram_username") or ""),
                host=host, port=port, login=login, password=password,
            )
            await client.send_message(chat_id, _safe_text(card_text) + "\n\n" + _auth_chooser_text(), buttons=_auth_chooser_buttons("add", key))
        else:
            _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
            await client.send_message(chat_id, "⚠️ " + _safe_text(text or "Proxy не прошёл проверку."), buttons=_add_manager_proxy_choice_buttons(key))
    else:
        _wizard_clear(chat_id, user_id)
        if success:
            # TPILOT PROXY RESULT CARD 20260718: this is the (only) caller of
            # the non-onboarding manual-replace path -- shows the masked
            # result card (password hidden behind the existing PIN reveal)
            # instead of immediately exposing the just-parsed password, and
            # re-reads the manager row fresh rather than using the locally
            # parsed host/port/login/password directly.
            await _pxm_send_result_card(chat_id, key)
        else:
            await _send_text_result_with_panel(chat_id, user_id, text or "Готово")
    return True
# --- TPILOT PROXY FORCE ONE-LINE PANEL HELPERS 20260508 END ---


# --- TPILOT PROXY METHOD MENU 20260718 START ---
# "✏️ Заменить proxy" on an existing manager's Proxy card now opens a
# method-selection screen (pxm: namespace) instead of jumping straight into
# manual SOCKS5 entry. All three methods below REUSE the existing
# implementations byte-for-byte (manual: wiz:proxy:set:*/_tpilot_panel_
# handle_proxy_line; pool: _frompool_run_*/_frompool_callback; purchase:
# _pbuy_run_*/_pbuy_callback) -- nothing here re-implements parsing,
# assignment, pool listing, or provider calls. The only new behavior is
# routing: a "ret"="proxy_card" flag threaded through each subflow's own
# wizard-state payload (never through callback_data -- callback_data stays
# exactly as compact as every sibling flow's) so that, when this screen was
# the entry point, "Back"/cancel from a subflow returns to THIS menu and a
# successful assignment/purchase returns to the manager's updated Proxy
# card instead of the onboarding "phone number" step. When ret is absent
# (i.e. reached the old way, from onboarding), every existing behavior is
# 100% unchanged -- confirmed by construction: every ret-aware branch below
# is a new `if ret == "proxy_card": ... return` inserted BEFORE the
# original code, which is otherwise untouched.

# TPILOT PROXY RESULT CARD 20260718: masked post-assignment result card
# (pool/purchase/manual) + PIN-protected full reveal. Reuses the EXISTING
# Stage 6.1C PIN mechanism (_ppool_pin_env_value -- same PANEL_ADMIN_PASSWORD/
# MANAGER_ADMIN_PASSWORD source, same trust tier, same "deny, never fall
# open" rule) for a MANAGER-keyed context instead of the existing flow's
# lease-keyed one -- proxy_lease_to_manager_proxy_fields (storage.py,
# verified directly) already mirrors host/port/login/password from a
# newly-assigned/bought lease onto managers.proxy_host/port/username/
# password, and the manual-set path (/manager_proxy_set) writes the exact
# same columns -- so managers.* is a single, always-current source of
# truth for "this manager's current proxy" across all three methods; no
# lease_id bridging or second data path is needed.
#
# Security: the wizard payload during PIN entry carries ONLY manager_key
# (never proxy fields) -- the current proxy is re-read fresh from the DB
# only AFTER a correct PIN, so a proxy changed mid-wait, or a manager
# deleted mid-wait, can never leak stale/wrong credentials. No new PIN
# value, table, or authorization path is introduced.

def _pxm_result_card_text(key: str) -> str:
    row = _manager_row_by_key(key) or {}
    identity = _pxm_manager_identity(row) if row else key
    host = str(row.get("proxy_host") or "").strip()
    port = str(row.get("proxy_port") or "").strip()
    login = str(row.get("proxy_username") or "").strip()
    proxy_line = f"{host}:{port}" if host and port else "не настроен"
    login_line = login if login else "без логина"
    return (
        "✅ Proxy назначен\n\n"
        f"Менеджер:\n{identity}\n\n"
        f"Proxy:\n{proxy_line}\n\n"
        f"Login:\n{login_line}\n\n"
        "Password:\n****"
    )


def _pxm_result_card_buttons(key: str) -> list:
    key = normalize_manager_key(key or "")
    return [
        [Button.inline("🔐 Показать полный proxy", f"pxm:reveal:{key}".encode())],
        [Button.inline("🔄 Проверить proxy", f"cmd:/manager_proxy_check {key}".encode())],
        [Button.inline("🌐 Карточка proxy", f"menu:proxy:{key}".encode())],
        [Button.inline("⬅️ Способ замены", f"pxm:menu:{key}".encode())],
        [Button.inline("🏠 Главная", b"menu:main")],
    ]


async def _pxm_send_result_card(chat_id: int, key: str) -> None:
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, replacement
        # completed report.
        await client.send_message(int(chat_id), _safe_text(_pxm_result_card_text(key)), buttons=_pxm_result_card_buttons(key) + _terminal_ok_button())
    except Exception:
        pass


def _pxm_full_reveal_text(key: str) -> str:
    """Called ONLY after a verified-correct PIN. Re-reads the manager row
    FRESH (never a value captured before/during the PIN wait) so a proxy
    changed while the PIN was pending is never shown stale. Markdown
    backticks (the SAME code-span convention _ppool_reveal_pin_input
    already uses -- this project has no parse_mode='html' usage anywhere)
    render as Telegram's monospace/copyable code span."""
    row = _manager_row_by_key(key) or {}
    identity = _pxm_manager_identity(row) if row else key
    host = str(row.get("proxy_host") or "").strip()
    port = str(row.get("proxy_port") or "").strip()
    login = str(row.get("proxy_username") or "").strip()
    password = str(row.get("proxy_password") or "").strip()
    if not host or not port:
        return f"🔐 Полный proxy\n\nМенеджер:\n{identity}\n\nУ этого менеджера сейчас не настроен proxy."
    if login and password:
        proxy_row = f"{host}:{port}:{login}:{password}"
    else:
        # Never a bare "host:port::" -- a credential-free proxy shows only
        # host:port, matching the confirmed proxy_parser format support.
        proxy_row = f"{host}:{port}"
    proxy_row = proxy_row.replace("`", "'")
    return f"🔐 Полный proxy\n\nМенеджер:\n{identity}\n\nСкопируйте строку:\n\n`{proxy_row}`"


