async def _delete_active_panel(chat_id: int, *, except_message_id: int = 0) -> None:
    old_mid = _get_active_panel_message(int(chat_id))
    if not old_mid or (except_message_id and int(old_mid) == int(except_message_id)):
        return
    try:
        await client.delete_messages(int(chat_id), [int(old_mid)])
    except Exception:
        pass
    finally:
        _clear_active_panel_message(int(chat_id))

async def _send_text_result_with_panel(chat_id: int, user_id: int, text: str, *, terminal: bool = True) -> None:
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): almost every call site
    # is a genuine terminal result (wizard already cleared, nothing further
    # to do from THIS message -- the fresh panel sent right after is a
    # SEPARATE message). terminal=False is for the one known exception
    # (_tp_gq_panel_schedule_input's bad-format retry, which keeps the
    # wizard open and reuses this helper only for its text-delivery
    # convenience) -- callers must pass it explicitly when the wizard was
    # NOT cleared before calling this.
    buttons = _back_to_panel_buttons() + _terminal_ok_button() if terminal else _back_to_panel_buttons()
    await client.send_message(int(chat_id), _safe_text(str(text or "Готово")), buttons=buttons)
    await _send_fresh_panel(int(chat_id), int(user_id or 0), delete_previous=True)


# ONBOARDING SOURCE PICK 20260711: this exact string must stay byte-identical to
# the copy in main.py (_ONBOARDING_SOURCE_PICK_MARKER) -- the two processes
# communicate only through returned command text (sync wizard) or notification
# body (QR path), never a shared Python object, so both sides must detect the
# same literal marker.
_ONBOARDING_SOURCE_PICK_MARKER = "В какой источник определить менеджера?"


def _source_pick_buttons(manager_key: str) -> list:
    """ONBOARDING SOURCE PICK 20260711: buttons for the post-login 'pick a
    traffic source' prompt -- one active source per row, plus a skip button.
    TPILOT SOURCE PICK CALLBACK SIZE FIX 20260719: the callback carries ONLY
    short numeric IDs (traffic_sources rowid + managers.id) -- never the raw
    source_key/manager_key, which have no enforced max length and could push
    "cmd:/source link <key> <mk>" past Telegram's 64-byte callback_data limit
    for realistic long keys (confirmed reachable: neither key is length-
    capped by validate_manager_key/_structure_key). The srcpick: handler
    resolves both IDs back to keys locally, then submits the SAME UNCHANGED
    "/source link <key> <mk>" command through the existing generic cmd:
    pipeline -- no source-assignment logic is duplicated here. Never raises --
    falls back to just the skip button on any error."""
    mk = normalize_manager_key(manager_key or "")
    rows: list = []
    try:
        manager_row = _manager_row_by_key(mk)
        manager_id = int((manager_row or {}).get("id") or 0)
        if manager_id > 0:
            for src in _traffic_sources_rows():
                if str(src.get("status") or "active").strip().lower() != "active":
                    continue
                source_id = int(src.get("id") or 0)
                key = str(src.get("source_key") or "").strip()
                if source_id <= 0 or not key:
                    continue
                name = str(src.get("name") or key).strip() or key
                rows.append([Button.inline(f"📦 {name}", f"srcpick:{source_id}:{manager_id}".encode())])
    except Exception:
        rows = []
    rows.append([Button.inline("⏭ Пропустить (привязать позже)", b"menu:main")])
    return rows


async def _send_text_result_with_source_pick(chat_id: int, user_id: int, text: str, manager_key: str) -> None:
    """ONBOARDING SOURCE PICK 20260711: like _send_text_result_with_panel, but
    renders the post-login result with source-pick buttons instead of the
    generic back-to-panel row -- the fresh main panel is still sent below it,
    exactly like the existing helper does."""
    await client.send_message(int(chat_id), _safe_text(str(text or "Готово")), buttons=_source_pick_buttons(manager_key))
    await _send_fresh_panel(int(chat_id), int(user_id or 0), delete_previous=True)


async def _send_text_result_with_prepared(chat_id: int, user_id: int, text: str) -> None:
    """TPILOT PREPARED ACCOUNTS PHASE 6: terminal screen for a prepared
    ◻️ QR / 📱 Номер телефона flow that just finished Telegram auth
    (_PREPARED_READY_MARKER in the finalize result text). Unlike
    _ONBOARDING_SOURCE_PICK_MARKER (a real Russian sentence, safe to leave
    visible if a caller forgets to intercept it), PREPARED_READY_MARKER is a
    pure technical sentinel and must never reach the operator's screen --
    stripped here before display. No source chooser: the account stays
    'prepared', not 'active'."""
    clean = str(text or "").replace(_prepared_model.PREPARED_READY_MARKER, "").rstrip()
    await client.send_message(int(chat_id), _safe_text(clean or "✅ Аккаунт подготовлен"), buttons=_prepared_terminal_buttons())
    await _send_fresh_panel(int(chat_id), int(user_id or 0), delete_previous=True)


def _wizard_get(chat_id: int, user_id: int) -> dict:
    try:
        _ensure_panel_runtime_tables()
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT * FROM panel_wizard_state WHERE chat_id=? AND user_id=?",
                (int(chat_id), int(user_id or 0)),
            ).fetchone()
            if not row:
                return {}
            d = dict(row)
            try:
                d["payload"] = json.loads(str(d.get("payload_json") or "{}"))
            except Exception:
                d["payload"] = {}
            return d
        finally:
            con.close()
    except Exception:
        return {}


def _wizard_set(chat_id: int, user_id: int, wizard: str, step: str, payload: dict | None = None) -> None:
    _ensure_panel_runtime_tables()
    now = _utc_now_iso()
    con = _connect_panel_db()
    try:
        con.execute(
            """
            INSERT INTO panel_wizard_state(chat_id, user_id, wizard, step, payload_json, created_at, updated_at)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(chat_id, user_id) DO UPDATE SET
                wizard=excluded.wizard,
                step=excluded.step,
                payload_json=excluded.payload_json,
                updated_at=excluded.updated_at
            """,
            (int(chat_id), int(user_id or 0), str(wizard or ""), str(step or ""), json.dumps(payload or {}, ensure_ascii=False), now, now),
        )
        con.commit()
    finally:
        con.close()


def _wizard_clear(chat_id: int, user_id: int) -> None:
    try:
        _ensure_panel_runtime_tables()
        con = _connect_panel_db()
        try:
            con.execute("DELETE FROM panel_wizard_state WHERE chat_id=? AND user_id=?", (int(chat_id), int(user_id or 0)))
            con.commit()
        finally:
            con.close()
    except Exception:
        pass

def _is_allowed(event) -> bool:
    try:
        uid = int(getattr(event, "sender_id", 0) or 0)
        cid = int(getattr(event, "chat_id", 0) or 0)
    except Exception:
        return False
    if ALLOWED_USERS and uid not in ALLOWED_USERS:
        return False
    if ALLOWED_CHATS and cid not in ALLOWED_CHATS and uid not in ALLOWED_USERS:
        return False
    return True


def _manager_rows(only_active=True, only_enabled=True, include_removed: bool = False, exclude_closers: bool = True, include_prepared: bool = False) -> List[dict]:
    try:
        rows = list_manager_rows_from_db_sync(
            TPILOT_DB_PATH,
            only_active=only_active,
            only_enabled=only_enabled,
            include_removed=bool(include_removed),
        )
    except Exception:
        rows = []
    out = []
    for r in rows or []:
        key = normalize_manager_key(r.get("manager_key") or "")
        if not key:
            continue
        # --- TPILOT TRANSFERS STAGE1 M2.7A START ---
        # Default-safe closer fence: role='closer' accounts are excluded from every
        # ordinary operational/stat manager list unless a screen explicitly opts out
        # (e.g. the closer-management screen itself passes exclude_closers=False).
        if exclude_closers and str(r.get("role") or "manager").strip().lower() == "closer":
            continue
        # --- TPILOT TRANSFERS STAGE1 M2.7A END ---
        # --- TPILOT PREPARED ACCOUNTS PHASE 3 START ---
        # Default-safe prepared fence, same shape as the closer fence above: a
        # prepared account (managers.status=='prepared') has no runtime, no
        # source, no schedule, no ManagerBot access -- it must not appear in
        # any ordinary operational AdminBot list by default. Deliberately
        # implemented HERE (the panel-side enumeration choke point), never
        # inside storage.manager_list_rows/list_manager_rows_from_db_sync --
        # that storage-level primitive must keep returning prepared rows
        # unfiltered, because proxy-pool ownership logic
        # (_ppool_manager_usage_map in main.py) depends on seeing them.
        if (not include_prepared) and str(r.get("status") or "").strip().lower() == "prepared":
            continue
        # --- TPILOT PREPARED ACCOUNTS PHASE 3 END ---
        rr = dict(r)
        rr["manager_key"] = key
        out.append(rr)
    return out


def _manager_rows_all(exclude_closers: bool = True, include_prepared: bool = False) -> List[dict]:
    # В админском разделе должны быть видны active/stopped/disabled менеджеры.
    # Исключаем только archived, чтобы остановленного менеджера можно было запустить кнопкой.
    return _manager_rows(only_active=None, only_enabled=None, include_removed=False, exclude_closers=exclude_closers, include_prepared=include_prepared)

def _norm_path(s: str) -> str:
    return str(s or "").replace("\\", "/").lower()


def _parse_iso_dt(raw: str) -> datetime | None:
    txt = str(raw or "").strip()
    if not txt:
        return None
    try:
        dt = datetime.fromisoformat(txt.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except Exception:
        return None


def _load_status_file() -> Dict[str, Any]:
    try:
        if not STATUS_FILE.exists():
            return {"source": "none"}
        raw = STATUS_FILE.read_text(encoding="utf-8", errors="ignore")
        data = json.loads(raw or "{}")
        if not isinstance(data, dict):
            return {"source": "bad"}
        dt = _parse_iso_dt(str(data.get("time_utc") or ""))
        fresh = False
        age_sec = None
        if dt:
            now = datetime.now(timezone.utc)
            age_sec = max(0, int((now - dt).total_seconds()))
            fresh = age_sec <= max(30, int(PANEL_STATUS_STALE_SEC or 180))
        data["source"] = "file"
        data["fresh"] = bool(fresh)
        data["age_sec"] = age_sec
        return data
    except Exception as e:
        return {"source": "error", "error": repr(e)}


def _get_python_processes() -> "list | None":
    """Live process-list scan (PowerShell CIM on Windows, `ps aux`
    elsewhere).

    N5.4.6 (RF1, independent-review fix): the contract used to conflate
    "scan ran and found nothing" with "scan failed/timed out/produced
    garbage" -- both returned `[]`, which every downstream caller
    (_pb_manager_process_running, the N5.4.2 status resolver) read as a
    CONFIRMED negative, causing every enabled manager to show 🔴 "process
    stopped" whenever the PowerShell scan merely failed. Fixed contract:
      - a LIST (possibly empty) means the scan genuinely completed and its
        content can be trusted -- an empty list is a real, confirmed
        "nothing matched";
      - None means the scan itself could not be trusted (subprocess
        failure, timeout, non-zero exit with no usable output, or
        unparseable output) -- callers MUST treat this as UNKNOWN, never
        as a confirmed negative.
    _pb_service_scan_cached/_pb_manager_process_running/_pb_service_proc_
    running already implemented the correct None-means-unknown handling
    (their docstrings said so); this was the one place actually violating
    it."""
    if os.name == "nt":
        ps = (
            "Get-CimInstance Win32_Process | "
            "Where-Object { $_.Name -like 'python*' -and $_.CommandLine } | "
            "Select-Object ProcessId,ParentProcessId,Name,CommandLine | "
            "ConvertTo-Json -Compress"
        )
        try:
            cp = subprocess.run(
                ["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
                cwd=str(BASE_DIR), capture_output=True, text=True, timeout=10,
            )
        except Exception:
            return None  # scan itself failed/unavailable (timeout, spawn error, ...)
        raw = (cp.stdout or "").strip()
        if not raw:
            if cp.returncode != 0:
                return None  # PowerShell errored, nothing usable on stdout
            return []  # successful run, genuinely nothing matched
        try:
            data = json.loads(raw)
        except Exception:
            return None  # malformed/unparseable output -- untrustworthy
        if isinstance(data, dict):
            data = [data]
        out = []
        for row in data or []:
            out.append({
                "pid": str(row.get("ProcessId", "")),
                "ppid": str(row.get("ParentProcessId", "")),
                "name": str(row.get("Name", "")),
                "cmd": str(row.get("CommandLine", "")),
            })
        return out
    try:
        cp = subprocess.run(["ps", "aux"], capture_output=True, text=True, timeout=10)
    except Exception:
        return None
    if cp.returncode != 0 and not (cp.stdout or "").strip():
        return None
    return [{"pid": "", "ppid": "", "name": "python", "cmd": line} for line in (cp.stdout or "").splitlines() if "python" in line]


def _scan_process_state() -> Dict[str, Any]:
    procs = _get_python_processes()
    # N5.4.6 (RF1): _get_python_processes may now return None (scan
    # unavailable) instead of always a list. This function's own "ok"/
    # "tpilot_ok" semantics predate N5.4 and are intentionally left
    # UNCHANGED here (same behavior as before the RF1 fix, when a failed
    # scan already came back as an empty list) -- this guard only prevents
    # a crash on `for p in procs`. The genuine None-is-unknown signal is
    # consumed correctly downstream via _pb_service_scan_cached/
    # _pb_manager_process_running (the actual N5.4.2 resolver path).
    procs = procs or []
    base_norm = _norm_path(str(BASE_DIR))
    tpilot_ok = False
    watchdog_ok = False
    manager_procs_by_key: Dict[str, int] = {}

    for p in procs:
        cmd = _norm_path(p.get("cmd", ""))
        if base_norm not in cmd:
            continue
        if "main.py" in cmd:
            if "--manager" not in cmd:
                tpilot_ok = True
            m = re.search(r"--manager\s+([a-z0-9_-]+)", cmd, flags=re.I)
            if m:
                key = m.group(1).lower()
                manager_procs_by_key[key] = manager_procs_by_key.get(key, 0) + 1
        if "soft_watchdog_pinger.py" in cmd:
            watchdog_ok = True

    active_keys = [str(r.get("manager_key") or "").strip().lower() for r in _manager_rows() if str(r.get("manager_key") or "").strip()]
    manager_running = sum(1 for k in active_keys if manager_procs_by_key.get(k, 0) > 0)
    return {
        "source": "scan",
        "fresh": True,
        "ok": bool(tpilot_ok and watchdog_ok and manager_running == len(active_keys)),
        "tpilot_ok": bool(tpilot_ok),
        "watchdog_ok": bool(watchdog_ok),
        "active_managers": active_keys,
        "manager_processes": manager_procs_by_key,
        "manager_running": manager_running,
    }


def _panel_health() -> Dict[str, Any]:
    data = _load_status_file()
    if data.get("source") == "file" and data.get("fresh"):
        active_keys = [str(x).strip().lower() for x in (data.get("active_managers") or []) if str(x).strip()]
        manager_procs = data.get("manager_processes") or {}
        if not isinstance(manager_procs, dict):
            manager_procs = {}
        manager_running = sum(1 for k in active_keys if int(manager_procs.get(k) or 0) > 0)
        reasons = [str(x) for x in (data.get("reasons") or [])]
        tpilot_ok = not any("tpilot process not found" in r.lower() for r in reasons)
        # If status file is fresh, watchdog itself is alive enough to refresh it.
        watchdog_ok = True
        ok = bool(data.get("ok"))
        return {
            "source": "watchdog",
            "ok": ok,
            "tpilot_ok": bool(tpilot_ok),
            "watchdog_ok": bool(watchdog_ok),
            "active_managers": active_keys,
            "manager_running": manager_running,
            "reasons": reasons,
            "age_sec": data.get("age_sec"),
        }
    # Fallback: PanelBot is alive, so scan local processes directly.
    scan = _scan_process_state()
    active_keys = scan.get("active_managers") or []
    return {
        "source": "scan",
        "ok": bool(scan.get("ok")),
        "tpilot_ok": bool(scan.get("tpilot_ok")),
        "watchdog_ok": bool(scan.get("watchdog_ok")),
        "active_managers": active_keys,
        "manager_running": int(scan.get("manager_running") or 0),
        "reasons": [] if scan.get("ok") else ["нет свежего status-файла, выполнена прямая проверка процессов"],
        "age_sec": data.get("age_sec") if isinstance(data, dict) else None,
    }


def _status_icon(ok: bool) -> str:
    return "🟢" if ok else "🔴"


def _panel_header() -> str:
    h = _panel_health()
    tpilot_ok = bool(h.get("tpilot_ok"))
    watchdog_ok = bool(h.get("watchdog_ok"))
    active = list(h.get("active_managers") or [])
    total = len(active)
    running = int(h.get("manager_running") or 0)
    managers_ok = (running == total) if total else True

    if tpilot_ok and managers_ok and watchdog_ok:
        title = "🤖 TPilot Panel 🟢 ON"
    elif not tpilot_ok:
        title = "🤖 TPilot Panel 🔴 OFF"
    else:
        title = "🤖 TPilot Panel 🟡 PARTIAL"

    if total <= 0:
        mgr_icon = "🟡"
    elif managers_ok:
        mgr_icon = "🟢"
    elif running <= 0:
        mgr_icon = "🔴"
    else:
        mgr_icon = "🟡"

    # W3.2 correction (TZ-3 branch #1, F-1): silent OS-local fallback removed --
    # storage.w3_now() raises W3TimezoneError instead of quietly returning a non-Kyiv
    # instant, matching _pf_kyiv_now (19586) and preflight_check.py's helpers. This
    # specific def of _panel_header is shadowed (see 24256's def, the active
    # last-definition-wins winner) -- fixed anyway per the frozen contract and to
    # prevent this dead branch from becoming a silent trap if ever reactivated.
    from storage import w3_now as _ph_w3_now
    updated_at = _ph_w3_now().strftime("%d.%m.%y %H:%M")

    lines = [
        title,
        f"Обновлено: {updated_at}",
        "",
        f"TPilot: {_status_icon(tpilot_ok)}",
        f"Watchdog: {_status_icon(watchdog_ok)}",
        f"Менеджеры: {mgr_icon} {running}/{total}",
    ]
    return "\n".join(lines).rstrip()


def _manager_short_label(row: dict) -> str:
    key = str(row.get("manager_key") or "").strip()
    name = str(row.get("display_name") or key).strip() or key
    user = str(row.get("telegram_username") or "").strip()
    if user:
        return f"{name} | @{user}"
    return name


def _manager_hist_label(row: dict) -> str:
    # --- TPILOT HISTSTATS M2.6H START ---
    label = _manager_short_label(row)
    status = str(row.get("status") or "").strip()
    is_enabled = int(row.get("is_enabled") if row.get("is_enabled") is not None else 1)
    if status == "archived":
        label += " (архив)"
    elif status == "deleted":
        label += " (аккаунт удалён)"
    elif is_enabled == 0:
        label += " (отключён)"
    return label
    # --- TPILOT HISTSTATS M2.6H END ---


_PB_PROXY_BADGE_TEXT = {
    "bypass": "🔓 no proxy",
    "not_configured": "▫️ no proxy",
    "healthy": "✅ proxy ok",
    "degraded": "⚠️ proxy degraded",
    "broken": "⚠️ proxy check",
    "stale": "❓ proxy stale",
    "never": "🕓 proxy pending",
}


def _manager_proxy_badge(row: dict) -> str:
    """R2 (2026-07-25, independent-review follow-up): now routed through
    the single shared _pb_proxy_effective_state predicate defined below in
    this file -- the SAME classification the shared manager-status resolver
    (proxy_bad/warning/ok) and the full card's ПРОКСИ section use -- instead
    of the dead proxy_test_ok/proxy_last_error fields and an unbounded
    (non-freshness-gated) auth_guard_ok check that used to let this badge
    silently disagree with the list emoji/counters/full card on the same
    screens. No timestamp parsing or health logic is duplicated here -- only
    the short list-row wording differs from the full card's longer verdict
    text, never the underlying verdict. Never reads/returns any credential
    (proxy_effective/_pb_proxy_guard_state never touch the password
    column)."""
    return _PB_PROXY_BADGE_TEXT.get(_pb_proxy_effective_state(row or {}), "❓ proxy stale")


def _manager_row_by_key(key: str) -> dict:
    wanted = normalize_manager_key(key or "")
    # Сначала ищем во всех non-archived, чтобы stopped/disabled менеджеры не пропадали из админки.
    # include_prepared=True: this is a single-key LOOKUP, not a list
    # enumeration -- prepared accounts must still be findable by key (the
    # prepared-accounts card and the reused per-manager proxy screens rely
    # on this), only the DEFAULT/ordinary manager LISTS above hide them.
    for row in _manager_rows_all(include_prepared=True):
        if normalize_manager_key(row.get("manager_key") or "") == wanted:
            return dict(row)
    return {}


def _manager_row_by_id(manager_id) -> dict:
    """TPILOT DEVICE-LOGIN 20260719: resolve the SHORT numeric managers.id
    (the "index" a callback_data may safely embed instead of a long/Unicode
    manager_key) back to the exact manager row. Exact primary-key match only
    -- never a prefix/fuzzy match -- so a stale/unknown/malformed id can
    never resolve to the wrong manager. Fails safely (returns {}) on
    anything that isn't a clean positive integer."""
    try:
        mid = int(str(manager_id or "").strip())
    except (TypeError, ValueError):
        return {}
    if mid <= 0:
        return {}
    # include_prepared=True: exact primary-key lookup, not a list
    # enumeration -- see _manager_row_by_key's matching note.
    for row in _manager_rows_all(include_prepared=True):
        try:
            if int(row.get("id") or 0) == mid:
                return dict(row)
        except (TypeError, ValueError):
            continue
    return {}




def _slug_key(raw: str, prefix: str = "item") -> str:
    s = str(raw or "").strip().lower().replace("ё", "е")
    translit = {
        "а":"a","б":"b","в":"v","г":"g","д":"d","е":"e","ж":"zh","з":"z","и":"i","й":"y","к":"k","л":"l","м":"m","н":"n","о":"o","п":"p","р":"r","с":"s","т":"t","у":"u","ф":"f","х":"h","ц":"c","ч":"ch","ш":"sh","щ":"sch","ъ":"","ы":"y","ь":"","э":"e","ю":"yu","я":"ya",
    }
    s = "".join(translit.get(ch, ch) for ch in s)
    s = re.sub(r"[^a-z0-9_-]+", "_", s)
    s = re.sub(r"_+", "_", s).strip("_")
    if not s:
        s = prefix
    return s[:32]


def _ensure_structure_tables_sync() -> None:
    con = _connect_panel_db()
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS traffic_sources(
                source_key TEXT PRIMARY KEY,
                name TEXT NOT NULL DEFAULT '',
                description TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'active',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS manager_source_links(
                manager_key TEXT PRIMARY KEY,
                source_key TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS manager_groups(
                group_key TEXT PRIMARY KEY,
                name TEXT NOT NULL DEFAULT '',
                description TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'active',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.execute("""
            CREATE TABLE IF NOT EXISTS manager_group_members(
                group_key TEXT NOT NULL DEFAULT '',
                manager_key TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                PRIMARY KEY(group_key, manager_key)
            );
        """)
        con.commit()
    finally:
        con.close()


def _traffic_sources_rows() -> List[dict]:
    try:
        _ensure_structure_tables_sync()
        con = _connect_panel_db()
        try:
            # TPILOT SOURCE PICK CALLBACK SIZE FIX 20260719: traffic_sources has
            # no separate autoincrement id column (its declared PK is the TEXT
            # source_key, and adding a column would be a schema migration --
            # out of scope). SQLite still assigns every normal (non-WITHOUT-
            # ROWID) table an implicit rowid, so aliasing it as "id" gives a
            # short, callback-safe numeric handle with zero schema change.
            rows = con.execute("SELECT rowid AS id, * FROM traffic_sources ORDER BY status ASC, name COLLATE NOCASE ASC, source_key ASC").fetchall()
            return [dict(r) for r in rows or []]
        finally:
            con.close()
    except Exception:
        return []


def _traffic_source_row_by_id(source_id) -> dict:
    """TPILOT SOURCE PICK CALLBACK SIZE FIX 20260719: resolve the short numeric
    rowid a callback_data may safely embed back to the exact source row. Exact
    rowid match only. Residual risk (accepted, no schema migration available):
    unlike managers.id (INTEGER PRIMARY KEY AUTOINCREMENT), traffic_sources'
    rowid is not AUTOINCREMENT-protected, so deleting the highest-rowid source
    and creating a new one could in principle reuse that rowid -- worst case a
    stale button links to a different still-legitimate active source, never a
    cross-manager leak or crash. Fails safely (returns {}) on anything that
    isn't a clean positive integer or an unknown id."""
    try:
        sid = int(str(source_id or "").strip())
    except (TypeError, ValueError):
        return {}
    if sid <= 0:
        return {}
    for row in _traffic_sources_rows():
        try:
            if int(row.get("id") or 0) == sid:
                return dict(row)
        except (TypeError, ValueError):
            continue
    return {}


def _traffic_source_by_key(key: str) -> dict:
    wanted = _slug_key(key, "source")
    try:
        _ensure_structure_tables_sync()
        con = _connect_panel_db()
        try:
            row = con.execute("SELECT * FROM traffic_sources WHERE source_key=?", (wanted,)).fetchone()
            return dict(row) if row else {}
        finally:
            con.close()
    except Exception:
        return {}


