def _button_pairs(buttons: List[Any]) -> List[list]:
    rows: List[list] = []
    cur: list = []
    for btn in buttons:
        cur.append(btn)
        if len(cur) == 2:
            rows.append(cur)
            cur = []
    if cur:
        rows.append(cur)
    return rows


