def _today_iso() -> str:
    # W3.2 correction (TZ-3 branch #2, F-1): silent OS-local fallback removed. This is
    # the ACTIVE, reachable branch (13 call sites treat the result as "today" -- a
    # business-date derivation, not display text) -- storage.w3_now() raises
    # W3TimezoneError instead of quietly returning a non-Kyiv date.
    from storage import w3_now as _ti_w3_now
    return _ti_w3_now().date().isoformat()


def _parse_iso_date(raw: str) -> str:
    txt = str(raw or "").strip()
    if not txt:
        return _today_iso()
    try:
        return datetime.strptime(txt[:10], "%Y-%m-%d").date().isoformat()
    except Exception:
        pass
    for fmt in ("%d.%m.%y", "%d.%m.%Y"):
        try:
            return datetime.strptime(txt, fmt).date().isoformat()
        except Exception:
            pass
    return _today_iso()


def _date_obj(iso_date: str):
    return datetime.strptime(_parse_iso_date(iso_date), "%Y-%m-%d").date()


def _clamp_iso_date(iso_date: str) -> str:
    d = _date_obj(iso_date)
    today = _date_obj(_today_iso())
    min_day = today - timedelta(days=31)
    if d > today:
        d = today
    if d < min_day:
        d = min_day
    return d.isoformat()


def _shift_iso_date(iso_date: str, days: int) -> str:
    d = _date_obj(_clamp_iso_date(iso_date)) + timedelta(days=int(days or 0))
    return _clamp_iso_date(d.isoformat())


def _display_date(iso_date: str) -> str:
    return _date_obj(_clamp_iso_date(iso_date)).strftime("%d.%m.%y")


def _cmd_date(iso_date: str) -> str:
    return _display_date(iso_date)


def _cmd_for(kind: str, target: str, iso_date: str = "") -> str:
    kind = str(kind or "stats").strip().lower()
    target = normalize_manager_key(target or "all") or "all"
    date_part = (" " + _cmd_date(iso_date)) if iso_date else ""
    if kind == "export":
        return f"/export {target}{date_part}".strip()
    if kind == "flights":
        return f"/flight {target}{date_part}".strip()
    return f"/stat det {target}{date_part}".strip()


def _callback_data(kind: str, target: str, iso_date: str) -> bytes:
    txt = f"cal:{kind}:{normalize_manager_key(target or 'all') or 'all'}:{_clamp_iso_date(iso_date)}"
    return txt.encode("utf-8")


