# -------------------- silent mode panel helpers --------------------
def _silent_panel_connect() -> sqlite3.Connection:
    con = sqlite3.connect(TPILOT_DB_PATH, timeout=30)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA journal_mode=WAL;")
    except Exception:
        pass
    return con


def _silent_panel_key(raw: str, prefix: str = "item") -> str:
    try:
        s = _slug_key(raw, prefix)
    except Exception:
        s = str(raw or "").strip().lower().replace("ё", "е")
        s = re.sub(r"[^a-z0-9_-]+", "", s)
    return s


def _silent_panel_table_exists(table: str) -> bool:
    try:
        con = _silent_panel_connect()
        try:
            row = con.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=? LIMIT 1", (str(table or ""),)).fetchone()
            return bool(row)
        finally:
            con.close()
    except Exception:
        return False


def _silent_panel_rows(table: str, order_sql: str) -> list[dict]:
    if not _silent_panel_table_exists(table):
        return []
    try:
        con = _silent_panel_connect()
        try:
            rows = con.execute(f"SELECT * FROM {table} {order_sql}").fetchall()
            return [dict(r) for r in rows or []]
        finally:
            con.close()
    except Exception:
        return []


def _silent_panel_sources() -> list[dict]:
    return _silent_panel_rows("traffic_sources", "ORDER BY status ASC, name COLLATE NOCASE ASC, source_key ASC")


def _silent_panel_groups() -> list[dict]:
    return _silent_panel_rows("manager_groups", "ORDER BY status ASC, name COLLATE NOCASE ASC, group_key ASC")
# -------------------- silent mode panel helpers end --------------------

