def _source_window_hhmm(total_minutes) -> str:
    h, m = divmod(int(total_minutes) % 1440, 60)
    return f"{h:02d}:{m:02d}"


def _source_window_display_from_cfg(cfg: dict | None) -> dict:
    """Return display fields for the source window screen.

    None/malformed cfg -> default display (08:00-17:00 day, 17:00-08:00 flights,
    light_include_dolyoty=0, pro_include_dolyoty=1), matching the engine/PartnerBot
    fail-open defaults. Never raises.
    """
    try:
        if cfg:
            ds = int(cfg.get("day_start"))
            de = int(cfg.get("day_end"))
            if 0 <= ds < de <= 1439:
                return {
                    "mode": "Включено",
                    "day": f"{_source_window_hhmm(ds)}-{_source_window_hhmm(de)}",
                    "flights": f"{_source_window_hhmm(de)}-{_source_window_hhmm(ds)}",
                    "light_include_dolyoty": 1 if int(cfg.get("light_include_dolyoty") or 0) == 1 else 0,
                    "pro_include_dolyoty": 1 if int(cfg.get("pro_include_dolyoty") or 0) == 1 else 0,
                    "updated_at": str(cfg.get("updated_at") or ""),
                }
    except Exception:
        pass
    return {
        "mode": "По умолчанию",
        "day": "08:00-17:00",
        "flights": "17:00-08:00",
        "light_include_dolyoty": 0,
        "pro_include_dolyoty": 1,
        "updated_at": "",
    }


def _source_stat_text(row: dict) -> str:
    key = str((row or {}).get("source_key") or "").strip()
    name = str((row or {}).get("name") or key).strip() or key
    status = "активен" if str((row or {}).get("status") or "active").lower() == "active" else "выключен"
    try:
        cfg = _sww_get(key, TPILOT_DB_PATH)
    except Exception:
        cfg = None
    disp = _source_window_display_from_cfg(cfg)
    lines = [
        "⏰ Окна статистики источника",
        "",
        f"📦 Источник: {name}",
        f"🔑 Ключ: {key}",
        f"Статус: {status}",
        "",
        f"Режим: {disp['mode']}",
    ]
    lines.append(f"📊 День: {disp['day']}")
    lines.append(f"🌙 Долёты: {disp['flights']}")
    lines.append("")
    lines.append("LIGHT долёты: " + ("включены" if disp["light_include_dolyoty"] == 1 else "выключены"))
    lines.append("PRO долёты: " + ("включены" if disp["pro_include_dolyoty"] == 1 else "выключены"))
    if disp["pro_include_dolyoty"] == 0:
        lines.append("")
        lines.append("PRO день: 00:00-00:00")
        lines.append("PRO долёты: отключены")
    if disp["updated_at"]:
        lines.append("")
        lines.append(f"Обновлено: {disp['updated_at']}")
    return "\n".join(lines).rstrip()


