# --- TPILOT PATCH C2B: Source greeting/away work-TIME schedule UI 20260623 START ---
# Source-level day/night client-message TIME windows for "Приветствие / нет на месте".
# Inert until an admin enables inheritance here (source_message_schedule.enabled=1). Uses the
# same _slug_key(key, "source") normalization as the rest of the source UI so the key matches
# manager_source_links.source_key for the main.py _tp_gq_get_schedule resolver (Patch C2c).
# This controls greeting/away TIME only, NOT stats/dolyoty windows (those stay in
# "⏰ Окна статистики" / source_work_windows) and NOT work DAYS (those stay in "📅 График дней").
_TPC2B_SMS_DEFAULTS = {"day_start": "08:00", "day_end": "17:00", "night_start": "17:00", "night_end": "08:00"}


def _tpc2b_parse_time(raw):
    """HH:MM (or H, HH) -> minutes, or None. Mirrors main.py _tp_gq_parse_time."""
    s = str(raw or "").strip()
    m = re.fullmatch(r"(\d{1,2})(?::|\.)(\d{2})", s)
    if not m:
        m = re.fullmatch(r"(\d{1,2})", s)
        if not m:
            return None
        h, mm = int(m.group(1)), 0
    else:
        h, mm = int(m.group(1)), int(m.group(2))
    if not (0 <= h <= 23 and 0 <= mm <= 59):
        return None
    return h * 60 + mm


def _tpc2b_segments(start_min, end_min):
    start_min = int(start_min) % 1440
    end_min = int(end_min) % 1440
    if start_min == end_min:
        return []
    if start_min < end_min:
        return [(start_min, end_min)]
    return [(start_min, 1440), (0, end_min)]


def _tpc2b_overlap_minutes(ds, de, ns, ne):
    total = 0
    for a1, b1 in _tpc2b_segments(ds, de):
        for a2, b2 in _tpc2b_segments(ns, ne):
            total += max(0, min(b1, b2) - max(a1, a2))
    return int(total)


def _tpc2b_validate_times(day_start, day_end, night_start, night_end):
    """Mirror main.py _tp_gq_validate_schedule: HH:MM, no equal endpoints, no day/night overlap,
    midnight crossing allowed. Returns (ok, err, dict of HH:MM strings)."""
    ds = _tpc2b_parse_time(day_start)
    de = _tpc2b_parse_time(day_end)
    ns = _tpc2b_parse_time(night_start)
    ne = _tpc2b_parse_time(night_end)
    if None in (ds, de, ns, ne):
        return False, "⚠️ Время нужно писать в формате HH:MM. Пример: 09:00 18:00 18:00 09:00", {}
    if ds == de or ns == ne:
        return False, "⚠️ Начало и конец окна не могут совпадать.", {}
    if _tpc2b_overlap_minutes(ds, de, ns, ne) > 0:
        return False, "⚠️ Дневное и ночное окно пересекаются. Сохранение запрещено.", {}

    def _fmt(v):
        return f"{v // 60:02d}:{v % 60:02d}"
    return True, "", {"day_start": _fmt(ds), "day_end": _fmt(de), "night_start": _fmt(ns), "night_end": _fmt(ne)}


def _tpc2b_source_time_cfg(key):
    """Return (cfg_or_None, display_dict, enabled_bool). Falls back to standard defaults when no
    row exists. include_disabled=True so the config shows even while inheritance is off."""
    try:
        cfg = _sms_get(key, db_path=TPILOT_DB_PATH, include_disabled=True)
    except Exception:
        cfg = None
    disp = {
        "day_start": str((cfg or {}).get("day_start") or _TPC2B_SMS_DEFAULTS["day_start"]),
        "day_end": str((cfg or {}).get("day_end") or _TPC2B_SMS_DEFAULTS["day_end"]),
        "night_start": str((cfg or {}).get("night_start") or _TPC2B_SMS_DEFAULTS["night_start"]),
        "night_end": str((cfg or {}).get("night_end") or _TPC2B_SMS_DEFAULTS["night_end"]),
    }
    enabled = bool(cfg and int(cfg.get("enabled") or 0) == 1)
    return cfg, disp, enabled


