def _safe_text(s: str, limit: int = 3900) -> str:
    txt = str(s or "").strip()
    if len(txt) <= limit:
        return txt
    return txt[:limit - 50].rstrip() + "\n\n...обрезано, текст слишком длинный"


async def _submit_and_wait(command_text: str, requested_by: int, source_chat_id: int, response_chat_id: int) -> dict:
    cmd_id = submit_panel_command(
        TPILOT_DB_PATH,
        command_text,
        requested_by=int(requested_by or 0),
        source_chat_id=int(source_chat_id or 0),
        response_chat_id=int(response_chat_id or source_chat_id or 0),
    )
    if command_text.startswith("/baseline"):
        timeout_s = 360
    elif command_text.startswith("/manager_replace_commit"):  # TPILOT FIX-5 20260718b: up to 90s readiness + 15 link creates -- was falling through to the 45s default, guaranteeing a false "TPilot не ответил" while the (idempotent, resumable) commit kept running in the controller
        timeout_s = 900
    elif command_text.startswith("/export"):
        timeout_s = 120
    elif command_text.startswith("/nmstat"):  # TPILOT NMSTAT STAGE3A
        timeout_s = 180
    elif command_text.startswith("/bizlink_create_n"):
        timeout_s = 630
    elif command_text.startswith("/bizlink_create_all"):
        timeout_s = 45
    elif command_text.startswith("/bizlink_create_15"):
        timeout_s = 255
    elif command_text.startswith("/bizlink_delete_tpilot"):  # M2.13D-3A — before generic /bizlink
        timeout_s = 255
    elif command_text.startswith("/bizlink_list_telegram"):  # M2.13D-3B — before generic /bizlink
        timeout_s = 60
    elif command_text.startswith("/bizlink_delete_telegram"):  # M2.13D-3B — before generic /bizlink
        timeout_s = 255
    elif command_text.startswith("/bizlink_del_tg"):  # M2.13D-3B short alias — before generic /bizlink
        timeout_s = 255
    elif command_text.startswith("/bizlink"):
        timeout_s = 75
    elif command_text.startswith("/manager_proxy_buy_confirm"):  # TPILOT PROXY BUY STAGE4 — real purchase + up to 5min provisioning poll (live incident 2026-07-09: was 120s, too short)
        timeout_s = 380
    elif command_text.startswith("/manager_proxy_buy_recover"):  # TPILOT PROXY BUY HOTFIX 2026-07-09 — no-spend recovery re-check
        timeout_s = 60
    elif command_text.startswith("/manager_proxy_buy_calc"):  # TPILOT PROXY BUY STAGE4 — no-spend price preview
        timeout_s = 60
    elif command_text.startswith("/proxy_pool_list"):  # TPILOT PROXY POOL STAGE6 P2 — read-only
        timeout_s = 30
    elif command_text.startswith("/proxy_pool_card"):  # TPILOT PROXY POOL STAGE6 P2 — read-only
        timeout_s = 30
    elif command_text.startswith("/proxy_pool_assign"):  # TPILOT PROXY POOL STAGE6 P3 — no-spend, guard can take time
        timeout_s = 120
    elif command_text.startswith("/proxy_pool_unassign"):  # TPILOT PROXY POOL STAGE6 P3 — no-spend, storage-only
        timeout_s = 45
    elif command_text.startswith("/proxy_pool_check"):  # TPILOT PROXY POOL STAGE6 P4 — no-spend, one provider call
        timeout_s = 60
    elif command_text.startswith("/proxy_pool_sync"):  # TPILOT PROXY POOL STAGE6 P4 — no-spend, full list + upserts
        timeout_s = 120
    elif command_text.startswith("/proxy_pool_autorenew"):  # TPILOT PROXY POOL STAGE6.1F — no-spend, storage-only
        timeout_s = 30
    elif command_text.startswith("/manager_tdimport_confirm"):  # TPILOT TDATA/SESSION IMPORT 20260719 — atomic install + spawn + up to 90s runtime-readiness poll
        timeout_s = 150
    elif command_text.startswith("/manager_tdimport_start"):  # archive extraction/parse + one live Telegram connect+get_me through the verified proxy
        timeout_s = 75
    elif command_text.startswith("/manager_tdimport_status"):  # read-only DB lookup
        timeout_s = 30
    elif command_text.startswith("/manager_tdimport_cancel"):  # DB update + local cleanup, no network
        timeout_s = 30
    elif command_text.startswith("/manager_devlogin_start"):  # TPILOT DEVICE-LOGIN 20260719: DB row + fast manager_commands enqueue only, no network/wait
        timeout_s = 30
    elif command_text.startswith("/manager_devlogin_cancel"):  # DB update + bridge-close signal, no network wait
        timeout_s = 30
    else:
        timeout_s = 45
    deadline = asyncio.get_event_loop().time() + timeout_s
    while asyncio.get_event_loop().time() < deadline:
        row = get_panel_command(TPILOT_DB_PATH, cmd_id)
        if row and str(row.get("status") or "") in ("done", "error"):
            return row
        await asyncio.sleep(0.7)
    return {"status": "error", "error_text": "TPilot не ответил на panel-команду за отведенное время."}




# -------------------- Partner / Buyer access UI --------------------
def _ensure_partner_access_tables_sync() -> None:
    con = _connect_panel_db()
    try:
        con.execute("""
            CREATE TABLE IF NOT EXISTS partner_buyers(
                user_id INTEGER PRIMARY KEY,
                username TEXT DEFAULT '',
                first_name TEXT DEFAULT '',
                last_name TEXT DEFAULT '',
                source_key TEXT DEFAULT '',
                is_enabled INTEGER NOT NULL DEFAULT 1,
                can_view_stats INTEGER NOT NULL DEFAULT 1,
                can_live_leads INTEGER NOT NULL DEFAULT 0,
                can_view_contacts INTEGER NOT NULL DEFAULT 0,
                can_excel INTEGER NOT NULL DEFAULT 0,
                can_view_screenshots INTEGER NOT NULL DEFAULT 0,
                show_duplicates INTEGER NOT NULL DEFAULT 1,
                stat_format TEXT NOT NULL DEFAULT 'pro',
                live_enabled_at TEXT DEFAULT '',
                created_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                last_seen_at TEXT DEFAULT ''
            );
        """)
        try:
            cols = [str(r[1]) for r in con.execute("PRAGMA table_info(partner_buyers)").fetchall()]
            if "stat_format" not in cols:
                con.execute("ALTER TABLE partner_buyers ADD COLUMN stat_format TEXT NOT NULL DEFAULT 'pro'")
            # M2.9B0: buyer screenshot access permission.
            if "can_view_screenshots" not in cols:
                con.execute("ALTER TABLE partner_buyers ADD COLUMN can_view_screenshots INTEGER NOT NULL DEFAULT 0")
            # M2.14: buyer duplicate visibility toggle.
            if "show_duplicates" not in cols:
                con.execute("ALTER TABLE partner_buyers ADD COLUMN show_duplicates INTEGER NOT NULL DEFAULT 1")
        except Exception:
            pass
        con.execute("""
            CREATE TABLE IF NOT EXISTS partner_access_requests(
                user_id INTEGER PRIMARY KEY,
                username TEXT DEFAULT '',
                first_name TEXT DEFAULT '',
                last_name TEXT DEFAULT '',
                status TEXT NOT NULL DEFAULT 'new',
                requested_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT ''
            );
        """)
        con.commit()
    finally:
        con.close()


def _partner_label(row: dict) -> str:
    uid = int((row or {}).get("user_id") or 0)
    username = str((row or {}).get("username") or "").strip()
    first = str((row or {}).get("first_name") or "").strip()
    last = str((row or {}).get("last_name") or "").strip()
    name = " ".join([x for x in (first, last) if x]).strip()
    if username:
        return f"@{username.lstrip('@')}" + (f" | {name}" if name else "")
    if name:
        return f"{name} | ID {uid}"
    return f"ID {uid}"


def _partner_buyers_rows() -> List[dict]:
    try:
        _ensure_partner_access_tables_sync()
        con = _connect_panel_db()
        try:
            rows = con.execute("SELECT * FROM partner_buyers ORDER BY is_enabled DESC, updated_at DESC, user_id ASC").fetchall()
            return [dict(r) for r in rows or []]
        finally:
            con.close()
    except Exception:
        return []


def _partner_requests_rows() -> List[dict]:
    try:
        _ensure_partner_access_tables_sync()
        con = _connect_panel_db()
        try:
            rows = con.execute("SELECT * FROM partner_access_requests WHERE status='new' ORDER BY requested_at ASC").fetchall()
            return [dict(r) for r in rows or []]
        finally:
            con.close()
    except Exception:
        return []


