def _pb_followup_enabled(key: str) -> bool:
    """N3: synchronous read of the same table main.py's
    _get_manager_followup_enabled/_set_manager_followup_enabled read/write
    (manager_followup_settings.enabled), default-enabled to match main.py's
    own default (missing table/row -> True)."""
    key = normalize_manager_key(key or "")
    if not key:
        return True
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT enabled FROM manager_followup_settings WHERE manager_key=?", (key,)
            ).fetchone()
            return True if not row else int(row[0] or 0) == 1
        finally:
            con.close()
    except Exception:
        return True


