@client.on(events.NewMessage(pattern=r"^/(continue|resume|продолжить)$"))
async def panel_continue_wizard_command(event):
    if not _is_allowed(event):
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, no recovery.
        await event.reply("⛔ Нет доступа к TPilot Panel.", buttons=_terminal_ok_button())
        return
    _register_panel_subscriber(int(event.chat_id or 0), int(event.sender_id or 0))
    text, buttons = _panel_wizard_resume_text_buttons(int(event.chat_id or 0), int(event.sender_id or 0))
    await event.reply(text, buttons=buttons)


@client.on(events.NewMessage(pattern=r"^/(cancel_wizard|cancel|сброс)$"))
async def panel_cancel_wizard_command(event):
    if not _is_allowed(event):
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, no recovery.
        await event.reply("⛔ Нет доступа к TPilot Panel.", buttons=_terminal_ok_button())
        return
    _wizard_clear(int(event.chat_id or 0), int(event.sender_id or 0))
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, wizard cleared.
    await event.reply("✅ Незавершённое действие сброшено.", buttons=_back_to_panel_buttons() + _terminal_ok_button())
# --- TPILOT_PANEL_CMD_BACKGROUND_SAFE_STEP4_COMMANDS END ---


@client.on(events.CallbackQuery)
async def on_callback(event):
    if not _is_allowed(event):
        await _pb_safe_answer(event, "Нет доступа", alert=True)
        return
    _register_panel_subscriber(int(event.chat_id or 0), int(event.sender_id or 0))

    data = (event.data or b"").decode("utf-8", errors="ignore")

    # --- TPILOT AUTH SAFETY 20260809 (Ф4, unified auth UX) START ---
    if data.startswith("auth:"):
        auth_parts = data.split(":", 3)
        auth_ctx = auth_parts[1] if len(auth_parts) > 1 else ""
        auth_method = auth_parts[2] if len(auth_parts) > 2 else ""
        auth_ref = auth_parts[3] if len(auth_parts) > 3 else ""
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if auth_method == "back":
            await _pb_safe_answer(event, )
