def _content_editor_menu():
    return [
        [Button.inline("📋 Проверить настройки", b"cmd:/content status")],
        [Button.inline("💬 Основные тексты", b"menu:content_texts"), Button.inline("⏱ Задержки", b"menu:content_delays")],
        [Button.inline("🧩 Шаблоны анкеты", b"menu:content_profile"), Button.inline("🔁 Тексты автодожимов", b"menu:content_post_manual")],
        [Button.inline("♻️ Сбросить всё", b"menu:content_reset_confirm")],
        [Button.inline("⬅️ Назад", b"menu:nm_automation")],
    ]


def _content_texts_menu():
    rows = [[Button.inline("📋 Список текстов", b"cmd:/content text list")]]
    for key, label in _CONTENT_TEXT_BUTTONS:
        rows.append([Button.inline(f"✏️ {label}", f"wiz:content_text:{key}".encode()), Button.inline("♻️", f"cmd:/content text reset {key}".encode())])
    rows.append([Button.inline("⬅️ Назад", b"menu:content")])
    return rows


def _content_delays_menu():
    rows = [[Button.inline("📋 Список задержек", b"cmd:/content delay list")]]
    for key, label in _CONTENT_DELAY_BUTTONS:
        rows.append([Button.inline(f"⏱ {label}", f"wiz:content_delay:{key}".encode()), Button.inline("♻️", f"cmd:/content delay reset {key}".encode())])
    rows.append([Button.inline("⬅️ Назад", b"menu:content")])
    return rows


def _content_profile_menu():
    rows = []
    for cat, label in _CONTENT_CATS:
        rows.append([Button.inline(f"🧩 {label}", f"menu:content_cat:{cat}".encode())])
    rows.append([Button.inline("⬅️ Назад", b"menu:content")])
    return rows


def _content_cat_menu(cat: str):
    return [
        [Button.inline("📋 Показать варианты", f"cmd:/content variant list {cat}".encode())],
        [Button.inline("➕ Добавить", f"wiz:content_variant_add:{cat}".encode())],
        [Button.inline("✏️ Изменить номер", f"wiz:content_variant_set:{cat}".encode())],
        [Button.inline("🔁 Вкл/выкл номер", f"wiz:content_variant_toggle:{cat}".encode())],
        [Button.inline("🗑 Удалить номер", f"wiz:content_variant_delete:{cat}".encode())],
        [Button.inline("♻️ Сбросить категорию", f"cmd:/content variant reset_category {cat}".encode())],
        [Button.inline("⬅️ Назад", b"menu:content_profile")],
    ]


_CONTENT_ORIG_MAIN_MENU = globals().get("_main_menu")
def _main_menu():  # type: ignore[override]
    rows = _CONTENT_ORIG_MAIN_MENU() if callable(_CONTENT_ORIG_MAIN_MENU) else []
    try:
        btn = [Button.inline("📝 Тексты и задержки", b"menu:content")]
        if btn not in rows:
            rows.insert(max(0, len(rows) - 3), btn)
    except Exception:
        pass
    return rows


_CONTENT_ORIG_TITLE_FOR_MENU = globals().get("_title_for_menu")
def _title_for_menu(menu: str):  # type: ignore[override]
    header = _panel_header()
    raw = str(menu or "main")
    if raw == "content":
        return f"{header}\n\n📝 Тексты и задержки\nРедактирование клиентских текстов, шаблонов и задержек без изменения кода.", _content_editor_menu()
    if raw == "content_texts":
        return f"{header}\n\n💬 Основные тексты\nВыберите текст для изменения или сброса.", _content_texts_menu()
    if raw == "content_delays":
        return f"{header}\n\n⏱ Задержки\nВведите минимум и максимум одним сообщением. Пример: 5 8", _content_delays_menu()
    if raw == "content_profile":
        return f"{header}\n\n🧩 Шаблоны анкеты\nМожно смотреть, добавлять, менять и удалять варианты.", _content_profile_menu()
    if raw == "content_post_manual":
        return f"{header}\n\n🔁 Тексты автодожимов\nТексты после ручного ответа менеджера.", _content_cat_menu("post_manual")
    if raw.startswith("content_cat:"):
        cat = raw.split(":", 1)[1]
        return f"{header}\n\n🧩 Категория: {cat}\nСначала нажмите “Показать варианты”, чтобы увидеть номера.", _content_cat_menu(cat)
    if raw == "content_reset_confirm":
        return f"{header}\n\n♻️ Сбросить все тексты, задержки и шаблоны к стандарту?", [[Button.inline("♻️ Да, сбросить", b"cmd:/content reset all confirm")], [Button.inline("⬅️ Назад", b"menu:content")]]
    return _CONTENT_ORIG_TITLE_FOR_MENU(menu) if callable(_CONTENT_ORIG_TITLE_FOR_MENU) else (header, [])


@client.on(events.CallbackQuery)
async def _content_editor_callback(event):
    if not _is_allowed(event):
        return
    data = (event.data or b"").decode("utf-8", errors="ignore")
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    if data.startswith("wiz:content_text:"):
        key = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_text", "value", {"key": key})
        await event.edit(f"✏️ Новый текст\n\nКлюч: {key}\n\nОтправьте новый текст одним сообщением. Можно с переносами строк.", buttons=[[Button.inline("⬅️ Отмена", b"menu:content_texts")]])
        return
    if data.startswith("wiz:content_delay:"):
        key = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_delay", "value", {"key": key})
        await event.edit(f"⏱ Новая задержка\n\nКлюч: {key}\n\nВведите минимум и максимум через пробел. Пример: 5 8", buttons=[[Button.inline("⬅️ Отмена", b"menu:content_delays")]])
        return
    if data.startswith("wiz:content_variant_add:"):
        cat = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_variant_add", "text", {"category": cat})
        await event.edit(f"➕ Добавить вариант\n\nКатегория: {cat}\n\nОтправьте новый текст одним сообщением.", buttons=[[Button.inline("⬅️ Отмена", f"menu:content_cat:{cat}".encode())]])
        return
    if data.startswith("wiz:content_variant_set:"):
        cat = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_variant_set", "index", {"category": cat})
        await event.edit(f"✏️ Изменить вариант\n\nКатегория: {cat}\n\nОтправьте номер варианта.", buttons=[[Button.inline("⬅️ Отмена", f"menu:content_cat:{cat}".encode())]])
        return
    if data.startswith("wiz:content_variant_delete:"):
        cat = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_variant_delete", "index", {"category": cat})
        await event.edit(f"🗑 Удалить вариант\n\nКатегория: {cat}\n\nОтправьте номер варианта.", buttons=[[Button.inline("⬅️ Отмена", f"menu:content_cat:{cat}".encode())]])
        return
    if data.startswith("wiz:content_variant_toggle:"):
        cat = data.split(":", 2)[2]
        _wizard_set(chat_id, user_id, "content_variant_toggle", "index", {"category": cat})
        await event.edit(f"🔁 Вкл/выкл вариант\n\nКатегория: {cat}\n\nОтправьте номер варианта.", buttons=[[Button.inline("⬅️ Отмена", f"menu:content_cat:{cat}".encode())]])
        return


@client.on(events.NewMessage)
async def _content_editor_wizard_input(event):
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if not state:
        return
    wizard = str(state.get("wizard") or "")
    step = str(state.get("step") or "")
    payload = dict(state.get("payload") or {})
    try:
        if wizard == "content_text":
            key = str(payload.get("key") or "")
            row = await _submit_and_wait(f"/content text set {key} {raw}", user_id, chat_id, chat_id)
            _wizard_clear(chat_id, user_id)
            await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
            return
        if wizard == "content_delay":
            key = str(payload.get("key") or "")
            parts = raw.replace(",", ".").split()
            if len(parts) == 1:
                parts = [parts[0], parts[0]]
            if len(parts) < 2:
                await event.reply("⚠️ Введите два числа. Пример: 5 8", buttons=_back_to_panel_buttons())
                return
            row = await _submit_and_wait(f"/content delay set {key} {parts[0]} {parts[1]}", user_id, chat_id, chat_id)
            _wizard_clear(chat_id, user_id)
            await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
            return
        if wizard == "content_variant_add":
            cat = str(payload.get("category") or "")
            row = await _submit_and_wait(f"/content variant add {cat} {raw}", user_id, chat_id, chat_id)
            _wizard_clear(chat_id, user_id)
            await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
            return
        if wizard == "content_variant_delete":
            cat = str(payload.get("category") or "")
            row = await _submit_and_wait(f"/content variant delete {cat} {int(raw)}", user_id, chat_id, chat_id)
            _wizard_clear(chat_id, user_id)
            await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
            return
        if wizard == "content_variant_toggle":
            cat = str(payload.get("category") or "")
            row = await _submit_and_wait(f"/content variant toggle {cat} {int(raw)}", user_id, chat_id, chat_id)
            _wizard_clear(chat_id, user_id)
            await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
            return
        if wizard == "content_variant_set":
            cat = str(payload.get("category") or "")
            if step == "index":
                payload["index"] = int(raw)
                _wizard_set(chat_id, user_id, "content_variant_set", "text", payload)
                await event.reply(f"✏️ Вариант #{payload['index']}\n\nТеперь отправьте новый текст.", buttons=_back_to_panel_buttons())
                return
            if step == "text":
                row = await _submit_and_wait(f"/content variant set {cat} {int(payload.get('index') or 0)} {raw}", user_id, chat_id, chat_id)
                _wizard_clear(chat_id, user_id)
                await _send_text_result_with_panel(chat_id, user_id, str(row.get("result_text") or row.get("error_text") or "Готово"))
                return
    except Exception as e:
        _wizard_clear(chat_id, user_id)
        await _send_text_result_with_panel(chat_id, user_id, f"⚠️ Ошибка редактора: {e!r}")
