def _tp_visual_now_local() -> str:
    # W3.2 correction (TZ-3 branch #3, F-1): silent OS-local/placeholder fallback
    # removed -- storage.w3_now() raises W3TimezoneError instead. This function's only
    # caller (4657, inside the shadowed 4652 def of _panel_header) is itself dead code
    # under the active last-definition-wins _panel_header (24256), so it is currently
    # unreachable at runtime -- fixed anyway per the frozen contract.
    from storage import w3_now as _tvnl_w3_now
    return _tvnl_w3_now().strftime("%d.%m.%y %H:%M")


def _tp_visual_status_icon(ok: bool, *, partial: bool = False) -> str:
    if partial:
        return "🟡"
    return "🟢" if bool(ok) else "🔴"


def _tp_visual_partner_ok() -> bool:
    try:
        procs = _get_python_processes()
        base_norm = _norm_path(str(BASE_DIR))
        for p in procs:
            cmd = _norm_path(p.get("cmd", ""))
            if base_norm in cmd and "partner_stat_bot.py" in cmd:
                return True
    except Exception:
        pass
    return False


def _tp_visual_health_parts() -> dict:
    h = _panel_health()
    tpilot_ok = bool(h.get("tpilot_ok"))
    watchdog_ok = bool(h.get("watchdog_ok"))
    partner_ok = _tp_visual_partner_ok()
    active = list(h.get("active_managers") or [])
    total = len(active)
    running = int(h.get("manager_running") or 0)
    managers_ok = (running == total) if total else True
    if total <= 0:
        mgr_icon = "🟡"
    elif managers_ok:
        mgr_icon = "🟢"
    elif running <= 0:
        mgr_icon = "🔴"
    else:
        mgr_icon = "🟡"
    all_ok = bool(tpilot_ok and watchdog_ok and partner_ok and managers_ok)
    critical = not tpilot_ok
    if all_ok:
        overall = "🟢"
    elif critical:
        overall = "🔴"
    else:
        overall = "🟡"
    return {
        "overall": overall,
        "tpilot": _tp_visual_status_icon(tpilot_ok),
        "watchdog": _tp_visual_status_icon(watchdog_ok),
        "partner": _tp_visual_status_icon(partner_ok),
        "managers": mgr_icon,
        "running": running,
        "total": total,
    }


def _panel_header() -> str:  # type: ignore[override]
    hp = _tp_visual_health_parts()
    return "\n".join([
        f"**{hp['overall']} TPilot Admin Panel**",
        "",
        f"Обновлено: {_tp_visual_now_local()}",
        "",
        f"TPilot: {hp['tpilot']}",
        f"Watchdog: {hp['watchdog']}",
        f"Partner Bot: {hp['partner']}",
        f"Менеджеры: {hp['managers']} {hp['running']}/{hp['total']}",
    ]).rstrip()


def _tp_visual_path(*items: str) -> str:
    clean = [str(x or "").strip() for x in items if str(x or "").strip()]
    if not clean or clean[0].lower() not in ("главная", "main"):
        clean.insert(0, "Главная")
    clean = ["Главная" if x.lower() == "main" else x for x in clean]
    return " ⮕ ".join(clean)


def _tp_visual_screen(path_items, description: str = "", extra: str = "") -> str:
    lines = [_panel_header(), "", _tp_visual_path(*path_items)]
    if description:
        lines.extend(["", str(description).strip()])
    if extra:
        lines.extend(["", str(extra).strip()])
    return "\n".join(lines).rstrip()


