def _tp_visual_manager_groups_for_key(key: str) -> str:
    out = []
    try:
        k = normalize_manager_key(key or "")
        for grp in _manager_groups_rows():
            gk = str(grp.get("group_key") or "").strip()
            if k in _group_members_sync(gk):
                out.append(str(grp.get("name") or gk).strip() or gk)
    except Exception:
        pass
    return ", ".join(out) if out else "_"


def _tp_visual_source_for_manager(key: str) -> str:
    try:
        k = normalize_manager_key(key or "")
        con = _connect_panel_db()
        try:
            row = con.execute("SELECT source_key FROM manager_source_links WHERE manager_key=? ORDER BY source_key ASC LIMIT 1", (k,)).fetchone()
            if row:
                return _tp_visual_source_name(str(row[0] or ""))
        finally:
            con.close()
    except Exception:
        pass
    return "_"


def _tp_visual_followups_badge(key: str) -> str:
    try:
        k = normalize_manager_key(key or "")
        con = _connect_panel_db()
        try:
            row = con.execute("SELECT enabled FROM manager_followup_settings WHERE manager_key=?", (k,)).fetchone()
            if row is None:
                return "✓"
            return "✓" if int(row[0] or 0) == 1 else "×"
        finally:
            con.close()
    except Exception:
        return "✓"


