def _partner_request_notification_buttons(body: str) -> list:
    """Buttons for a 'partner_request' push notification card: parse user_id out of the
    body and offer direct approve/reject actions. Never raises -- any parse failure or
    unexpected shape falls back to the generic back-to-panel buttons so the notification
    loop can never crash because of this."""
    try:
        m = re.search(r"user_id:\s*(\d{1,15})", str(body or ""))
        if not m:
            return _back_to_panel_buttons()
        uid = int(m.group(1))
        rows = [
            [Button.inline("✅ Разрешить", f"menu:partner_request:{uid}".encode())],
            [Button.inline("❌ Отклонить", f"cmd:/partner reject {uid}".encode())],
        ]
        rows.extend(_back_to_panel_buttons())
        return rows
    except Exception:
        return _back_to_panel_buttons()


def _manager_source_pick_notification_buttons(body: str) -> list:
    """ONBOARDING SOURCE PICK 20260711: buttons for a 'manager_source_pick' push
    notification (QR-login source prompt) -- parse manager_key out of the body's
    trailing 'manager_key:<key>' line and offer the same source-pick buttons as
    the sync wizard path. Never raises -- any parse failure falls back to the
    generic back-to-panel buttons so the notification loop can never crash."""
    try:
        m = re.search(r"manager_key:(\S+)", str(body or ""))
        if not m:
            return _back_to_panel_buttons()
        return _source_pick_buttons(m.group(1))
    except Exception:
        return _back_to_panel_buttons()


# --- TPILOT HEALTH NOTIFICATION V2 20260807 (panel_bot) START ---
# Action buttons for kind='health_agg'/'telegram_health' notifications.
# Every button below carries the callback_data of an ALREADY-REGISTERED,
# already-audited handler -- no new action semantics are invented here,
# only a new namespace ('hv2:') for the two things that genuinely don't
# exist yet (a card shortcut keyed by manager_id, and the strictly
# read-only diagnostic command). See the approved plan section I.2 for
# the full family->action table (owner spec 2026-08-07).

_HNV2_KEY_RE = re.compile(r"^(?:manager|Ключ):\s*(\S+)", re.MULTILINE)
_HNV2_FAMILY_RE = re.compile(r"^family:\s*([a-z_]+)", re.MULTILINE)
# HNV2 N-2 correction (post-independent-review): approved plan section
# I.2.1 requires the button set to degrade to diagnostics-only whenever
# confidence != 'certain' (e.g. a 'probable' proxy_unavailable must never
# offer 🔁 Перезапустить). _hnv2_notify (main.py) now writes this line into
# every non-recovery health_agg body; absence (older/legacy body, or a
# telegram_health-kind alert that carries no HNV2 confidence concept at
# all) defaults to 'certain' -- i.e. no degradation -- matching pre-fix
# behavior for anything that never had this line.
_HNV2_CONFIDENCE_RE = re.compile(r"^confidence:\s*(\S+)", re.MULTILINE)



# HNV2 N-2 correction (post-independent-review, approved plan section
# I.2.1): callback_data prefixes considered "mutating/auth/restart" --
# stripped from EVERY family's button set whenever confidence != 'certain'.
# Matched against the raw (pre-truncation) callback_data string built below.
_HNV2_UNSAFE_ACTION_PREFIXES = (
    "relogin:start:", "wiz:qr_start:", "devlogin:start:", "cmd:/manager_restart",
)
# Generic diagnostics-only fallback (plan I.2.1: "не перезапускать вслепую,
# если улики стали unknown или противоречивыми -- сначала безопасная
# диагностика") -- used when confidence-degradation would otherwise leave a
# family with zero buttons (e.g. worker_crash's only action IS restart).
_HNV2_SAFE_DIAG_FALLBACK = [
    ("🩺 Проверить", "cmd:/tghealth check {k}"),
    ("🌐 Проверить прокси", "cmd:/manager_proxy_check {k}"),
]


def _hnv2_degrade_for_confidence(actions: list, family: str, manager_key: str, confidence: str) -> list:
    """Strips restart/relogin/QR/devlogin buttons whenever confidence is not
    'certain' (approved plan I.2.1). If that empties out a family that DID
    have a non-empty action set before degrading (worker_crash,
    worker_stuck_starting, network_timeout, proxy_unavailable), falls back
    to the generic safe-diagnostics pair rather than leaving the operator
    with nothing but the card button. Families that are ALREADY empty/
    restricted by design (account_blocked, sqlite_lock, telegram_limited_
    peerflood) are untouched -- there was nothing unsafe to strip."""
    if str(confidence or "certain").strip().lower() == "certain":
        return actions
    filtered = [(label, data) for label, data in actions if not any(data.startswith(p) for p in _HNV2_UNSAFE_ACTION_PREFIXES)]
    if not filtered and actions:
        return [(label, tmpl.format(k=manager_key)) for label, tmpl in _HNV2_SAFE_DIAG_FALLBACK]
    return filtered


def _hnv2_family_actions(family: str, manager_key: str, manager_id: int, *, confidence: str = "certain", cooldown_active: bool = False) -> list:
    """(label, callback_data) pairs for one family -- callback_data only,
    NEVER a fresh Button.inline object here (the 64-byte guard is applied
    once, centrally, by the caller). Deliberately excludes any restart/
    relogin/unblock action for families the approved Recovery Ownership
    Matrix marks as having no safe automatic fix (account_blocked,
    sqlite_lock, recovery_flap, floodwait-while-cooling-down) -- see
    _HNV2_RECOMMENDED_ACTION in main.py for the matching operator-facing
    text, which must never promise a button that isn't here.

    `confidence` (HNV2 N-2 correction): when not 'certain', every
    restart/relogin/QR/devlogin button is stripped (see
    _hnv2_degrade_for_confidence) before returning.
    `cooldown_active` (HNV2 N-8 correction): while an active FloodWait
    cooldown is still in the future, even the read-only 🩺 Проверить action
    is withheld -- '/tghealth check' still performs a real get_me/
    get_dialogs Telegram API round-trip, which is outgoing Telegram traffic
    during the exact window the account should be left alone. Once
    cooldown_until has passed, the existing controlled TP_HG check becomes
    available again exactly as before."""
    k = manager_key
    mid = manager_id
    if family == "session_unauthorized":
        # TPILOT AUTH SAFETY 20260809 (Ф4, unified auth UX): ONE clear
        # action instead of scattered per-method buttons -- routes into the
        # SAME relogin intro -> unified 4-method chooser (QR/Phone/Session/
        # TData) every other relogin entry point now uses (relogin:start is
        # unchanged; only what its OWN intro screen shows was updated, in
        # _relogin_intro_buttons). "Вход на устройстве" (device-login)
        # remains a SEPARATE, non-auth-chooser function, unaffected by this
        # change -- still available from the ordinary manager card, per the
        # 20260808 HNV2 UX hotfix comment this replaces.
        return _hnv2_degrade_for_confidence([
            ("🔐 Восстановить доступ", f"relogin:start:{k}"),
        ], family, k, confidence)
    if family == "account_blocked":
        return []  # card-only, appended by the caller -- no auto-fix exists
    if family == "telegram_limited_peerflood":
        return [("🩺 Проверить", f"cmd:/tghealth check {k}")]
    if family == "floodwait":
        if cooldown_active:
            return []  # card-only while cooldown is active -- no outgoing Telegram traffic
        return [("🩺 Проверить", f"cmd:/tghealth check {k}")]
    if family == "proxy_auth_failed":
        return [
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
            ("⚙️ Настройки", f"menu:manager_settings:{k}"),
        ]
    if family == "proxy_unavailable":
        # Confidence CAN be 'probable' here (classifier rule 6, the
        # 'degraded' branch) -- this is the exact case the approved plan's
        # confidence-degradation invariant exists for: a probable (not yet
        # certain) proxy failure must never offer an unattended restart.
        return _hnv2_degrade_for_confidence([
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
            ("🔁 Перезапустить", f"cmd:/manager_restart {k}"),
            ("⚙️ Настройки", f"menu:manager_settings:{k}"),
        ], family, k, confidence)
    if family == "worker_crash":
        return _hnv2_degrade_for_confidence([("🔁 Перезапустить", f"cmd:/manager_restart {k}")], family, k, confidence)
    if family == "worker_stuck_starting":
        return _hnv2_degrade_for_confidence([
            ("🔁 Перезапустить", f"cmd:/manager_restart {k}"),
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
        ], family, k, confidence)
    if family == "network_timeout":
        return _hnv2_degrade_for_confidence([
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
            ("🔁 Перезапустить", f"cmd:/manager_restart {k}"),
        ], family, k, confidence)
    if family == "sqlite_lock":
        return [("🧪 Диагностика", f"hv2:diag:{mid}")]  # no restart -- no safe auto-fix
    if family == "health_missing_stale":
        return [
            ("🩺 Проверить", f"cmd:/tghealth check {k}"),
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
        ]
    if family == "recovery_flap":
        return [
            ("🩺 Глубокая проверка", f"cmd:/tghealth deepcheck {k}"),
            ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
        ]
    # 'unknown' and any unrecognised family: safe diagnostics only, never
    # destructive.
    return [
        ("🩺 Проверить", f"cmd:/tghealth check {k}"),
        ("🌐 Проверить прокси", f"cmd:/manager_proxy_check {k}"),
    ]


def _hnv2_family_from_health_row(manager_key: str) -> str:
    """Fallback family derivation for kind='telegram_health' bodies that
    predate the family: line (should not happen post-deploy, since
    _tp_hg_build_alert_text now always writes it -- kept as a defensive
    fallback only). Reads manager_telegram_health directly -- the ONE
    place in this file that does a fresh DB read for button-building,
    used only when the body itself carries no family: line."""
    try:
        row = _pb_tg_health_row(manager_key)
        status = str((row or {}).get("health_status") or "").lower()
        error_class = str((row or {}).get("error_class") or "")
        if status == "blocked":
            return "account_blocked"
        cls_low = error_class.lower()
        if "floodwait" in cls_low or "flood_wait" in cls_low:
            return "floodwait"
        if status == "limited":
            return "telegram_limited_peerflood"
        return "unknown"
    except Exception:
        return "unknown"


def _hnv2_health_notification_buttons(body: str) -> list:
    """Action buttons for kind='health_agg'/'telegram_health' notifications.
    Parses the manager key out of the body (same convention as
    _manager_source_pick_notification_buttons/_plc_terminal_review_buttons
    above), resolves it to a card + a numeric managers.id (needed for the
    hv2: namespace's 64-byte-safe callback_data), then maps the family
    (also parsed from the body, or derived as a fallback) to buttons that
    reuse ONLY already-registered callback_data. Never raises -- any
    parse/lookup failure falls back to _back_to_panel_buttons() so the
    notification delivery loop can never crash on a malformed body."""
    try:
        km = _HNV2_KEY_RE.search(str(body or ""))
        if not km:
            return _back_to_panel_buttons()
        manager_key = normalize_manager_key(km.group(1))
        row = _manager_row_by_key(manager_key)
        manager_id = int((row or {}).get("id") or 0)
        if not manager_key or manager_id <= 0:
            return _back_to_panel_buttons()

        fm = _HNV2_FAMILY_RE.search(str(body or ""))
        family = fm.group(1) if fm else _hnv2_family_from_health_row(manager_key)

        cm = _HNV2_CONFIDENCE_RE.search(str(body or ""))
        confidence = cm.group(1) if cm else "certain"

        # HNV2 N-8 correction: cooldown_until is never in the notification
        # body (TP_HG owns floodwait entirely, never writes an HNV2-style
        # machine-readable line for it) -- a fresh read is required, same
        # established "fresh DB read for button-building" pattern
        # _hnv2_family_from_health_row already uses above. It is always a
        # naive-UTC, second-precision isoformat string -- TP_HG's sole
        # writer (main.py, manager_telegram_health.cooldown_until) never
        # attaches tzinfo.
        # RR-1 (W3.2 2026-08-07): fromisoformat here only validates the
        # shape; the "is it still in the future" check reuses the approved
        # _utc_now_iso() wrapper instead of a local datetime.utcnow()/
        # astimezone()/replace(tzinfo=...) coercion -- two same-format
        # naive-UTC ISO strings compare correctly as plain strings.
        # Malformed or unexpectedly tz-aware input fails CLOSED
        # (cooldown_active stays True -- withholds the read-only Telegram
        # probe button, same as a genuinely active cooldown).
        cooldown_active = False
        if family == "floodwait":
            try:
                hrow = _pb_tg_health_row(manager_key)
                cooldown_raw = str((hrow or {}).get("cooldown_until") or "").strip()
                if cooldown_raw:
                    cooldown_active = True
                    parsed = datetime.fromisoformat(cooldown_raw)
                    if parsed.tzinfo is None:
                        cooldown_active = cooldown_raw > _utc_now_iso()
            except Exception:
                cooldown_active = True

        rows = []
        for label, data in _hnv2_family_actions(family, manager_key, manager_id, confidence=confidence, cooldown_active=cooldown_active):
            if len(data.encode("utf-8")) > 60:
                continue
            rows.append([Button.inline(label, data.encode())])
        # Every family gets a card shortcut -- account_blocked/sqlite_lock
        # rely on it as their ONLY action (no auto-fix exists for them).
        card_data = f"menu:manager_full:{manager_key}"
        if len(card_data.encode("utf-8")) <= 64:
            rows.append([Button.inline("📋 Карточка", card_data.encode())])
        rows.extend(_back_to_panel_buttons())
        return rows
    except Exception:
        return _back_to_panel_buttons()

# --- TPILOT HEALTH NOTIFICATION V2 20260807 (panel_bot) END ---


async def _panel_notification_loop() -> None:
    while True:
        try:
            _reap_stale_running_panel_notifications()
            rows = _take_panel_notifications(limit=10)
            if not rows:
                await asyncio.sleep(10)
                continue
            targets = _notification_targets()
            for row in rows:
                body = str(row.get("body") or row.get("title") or "").strip()
                ok_any = False
                if targets and body:
                    if str(row.get("kind") or "") == "prepared_ready":
                        # TPILOT PREPARED ACCOUNTS PHASE 6: ◻️ QR (prepared
                        # track) finalizes asynchronously through the QR-wait
                        # task, so its result arrives as a notification, not
                        # a synchronous wizard reply -- this is the QR
                        # counterpart to _send_text_result_with_prepared
                        # above (📱 Номер телефона's synchronous "code"/"pass"
                        # steps). Strip the technical sentinel before display,
                        # same rule as that helper. No source chooser.
                        body = body.replace(_prepared_model.PREPARED_READY_MARKER, "").strip() or "✅ Аккаунт подготовлен"
                        btns = _prepared_terminal_buttons()
                    elif str(row.get("kind") or "") == "partner_request":
                        btns = _partner_request_notification_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_renew_warning":
                        btns = _prenew_notification_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_autorenew_failed":
                        btns = _prenew_autorenew_failed_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_autorenew_unverified":
                        btns = _prenew_autorenew_unverified_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_autorenew_blocked":
                        btns = _prenew_autorenew_blocked_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_balance_low":
                        btns = _prenew_balance_low_buttons(body)
                    elif str(row.get("kind") or "") == "manager_source_pick":
                        btns = _manager_source_pick_notification_buttons(body)
                    elif str(row.get("kind") or "") in (
                        "proxy_lifecycle_enable_required", "proxy_lifecycle_disable_required",
                        "proxy_lifecycle_confirmed_on", "proxy_lifecycle_confirmed_off",
                    ):
                        btns = _plc_action_notification_buttons(body)
                    elif str(row.get("kind") or "") == "proxy_lifecycle_terminal_review":
                        btns = _plc_terminal_review_buttons(body)
                    elif str(row.get("kind") or "") in ("health_agg", "telegram_health"):
                        btns = _hnv2_health_notification_buttons(body)
                    else:
                        btns = _back_to_panel_buttons()
                    for chat_id in targets:
                        try:
                            await client.send_message(int(chat_id), _safe_text(body), buttons=btns)
                            await _send_fresh_panel(int(chat_id), 0, delete_previous=True)
                            ok_any = True
                        except Exception:
                            pass
                _finish_panel_notification(int(row.get("id") or 0), ok=ok_any or not targets)
            await asyncio.sleep(2)
        except asyncio.CancelledError:
            return
        except Exception:
            await asyncio.sleep(15)

async def main() -> None:
    if API_ID <= 0 or not API_HASH:
        raise RuntimeError("API_ID/API_HASH пустые. Проверьте .env.TPilot")
    if not PANEL_BOT_TOKEN:
        raise RuntimeError("PANEL_BOT_TOKEN пустой. Создайте бота через @BotFather и добавьте PANEL_BOT_TOKEN в .env.TPilot")
    print("TPilot PanelBot starting...")
    await client.start(bot_token=PANEL_BOT_TOKEN)
    me = await client.get_me()
    print(f"TPilot PanelBot started: @{getattr(me, 'username', '')}")
    _pb_track_task(_panel_notification_loop())
    _pb_track_task(_schedule_request_notify_loop())  # C3c
    _pb_track_task(_preflight_admin_loop())  # TPILOT MORNING PREFLIGHT STAGE 1
    _pb_track_task(_preflight_admin_evening_loop())  # TPILOT EVENING PREFLIGHT (ADMIN, TOMORROW)
    await client.run_until_disconnected()

