# Late UI overrides. Does not touch existing visual layout, only enriches header and proxy cards.
_TPAG_PANEL_V2_ORIG_HEADER = globals().get("_panel_header")
_TPAG_PANEL_V2_ORIG_PROXY_TEXT = globals().get("_proxy_detail_text")
_TPAG_PANEL_V2_ORIG_PROXY_BUTTONS = globals().get("_proxy_detail_buttons")


def _tpag_panel_v2_mode(row: dict) -> str:
    mode = str((row or {}).get("proxy_mode") or "").strip().lower()
    if mode in ("proxy", "direct"):
        return mode
    if str((row or {}).get("proxy_host") or "").strip() and str((row or {}).get("proxy_port") or "").strip():
        return "proxy"
    if int((row or {}).get("proxy_bypass_allowed") or 0) == 1:
        return "direct"
    return "direct"


def _tpag_panel_v2_parse_dt(raw):
    txt = str(raw or "").strip()
    if not txt:
        return None
    try:
        dt = datetime.fromisoformat(txt.replace("Z", "+00:00"))
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
        return dt.replace(microsecond=0)
    except Exception:
        return None


def _tpag_panel_v2_fresh(row: dict) -> bool:
    if int((row or {}).get("auth_guard_ok") or 0) != 1:
        return False
    checked = _tpag_panel_v2_parse_dt((row or {}).get("auth_guard_checked_at"))
    if not checked:
        return False
    return 0 <= (datetime.utcnow().replace(microsecond=0) - checked).total_seconds() <= 10 * 60


def _tpag_panel_v2_proxy_counts() -> tuple[int, int, str]:
    rows = _manager_rows(only_active=True, only_enabled=True, include_removed=False)
    total = len(rows)
    ok = 0
    for r in rows:
        mode = _tpag_panel_v2_mode(r)
        if mode == "direct" and int((r or {}).get("proxy_bypass_allowed") or 0) == 1:
            ok += 1
        elif mode == "proxy" and _tpag_panel_v2_fresh(r):
            ok += 1
    icon = "🟢" if total and ok == total else ("🔴" if total and ok == 0 else "🟡")
    if total <= 0:
        icon = "🟡"
    return ok, total, icon


def _pb_proxy_counts_effective() -> tuple[int, int, str]:
    """Canonical root-header proxy count (forward-fix P1.1, post-incident
    review): driven by the SAME shared _pb_proxy_effective_state predicate
    every other proxy surface (resolver categories, unified card, badge,
    full card, proxy detail) already uses -- replaces the independent
    _tpag_panel_v2_proxy_counts/_tpag_panel_v2_fresh chain, which had its
    own 10-minute window (vs the canonical 15), read the raw auth_guard_ok
    flag (so a 'degraded' soft-fail grace period counted as fully green),
    had no clock-skew tolerance, and gated on the proxy_mode COLUMN instead
    of the live required/bypass/enabled/host/port configuration -- any of
    which could make the root header disagree with every manager card on
    the very same rendered screen. 'ok' mirrors the resolver's own green
    set (bypass/healthy); degraded/broken/stale/never/not_configured are
    NOT counted ok. Same three-tier icon policy as before (all-ok/none-ok/
    mixed), just fed from the one canonical classifier. _tpag_panel_v2_
    proxy_counts/_tpag_panel_v2_fresh are intentionally left in place
    (orphaned, not deleted -- project convention) as a rollback anchor."""
    rows = _manager_rows(only_active=True, only_enabled=True, include_removed=False)
    total = len(rows)
    ok = 0
    for r in rows:
        if _pb_proxy_effective_state(r) in ("bypass", "healthy"):
            ok += 1
    icon = "🟢" if total and ok == total else ("🔴" if total and ok == 0 else "🟡")
    if total <= 0:
        icon = "🟡"
    return ok, total, icon


def _panel_header() -> str:  # type: ignore[override]
    base = _TPAG_PANEL_V2_ORIG_HEADER() if callable(_TPAG_PANEL_V2_ORIG_HEADER) else "🟢 TPilot Admin Panel"
    if "Proxy:" in str(base):
        return str(base)
    ok, total, icon = _tpag_panel_v2_proxy_counts()
    return (str(base).rstrip() + f"\nProxy: {icon} {ok}/{total}").rstrip()


def _tpag_panel_v2_geo(country, region, city) -> str:
    bits = [str(x or "").strip() for x in (country, region, city) if str(x or "").strip()]
    return ", ".join(bits) if bits else "не определено"


def _proxy_detail_text(row: dict) -> str:  # type: ignore[override]
    row = dict(row or {})
    key = normalize_manager_key(row.get("manager_key") or "")
    label = _manager_short_label(row) if callable(globals().get("_manager_short_label")) else key
    mode = _tpag_panel_v2_mode(row)
    if mode == "direct":
        return "\n".join([
            f"🔓 Proxy {label}",
            "",
            "Режим: без proxy",
            "Telegram будет видеть IP сервера.",
            f"Server IP: {row.get('auth_direct_ip') or 'не определено'}",
        ]).rstrip()
    host = str(row.get("proxy_host") or "").strip()
    port = str(row.get("proxy_port") or "").strip()
    login = str(row.get("proxy_username") or "").strip() or "_"
    checked = str(row.get("auth_guard_checked_at") or row.get("proxy_test_at") or "").strip() or "_"
    ok = int(row.get("auth_guard_ok") or 0) == 1
    fresh = _tpag_panel_v2_fresh(row)
    guard = "🟢 готов" if ok and fresh else ("🟡 устарел" if ok else "🔴 не готов")
    err = str(row.get("auth_guard_error") or row.get("proxy_last_error") or "").strip()
    lines = [
        f"🌐 Proxy {label}",
        "",
        "Режим: через proxy",
        f"SOCKS5: {host + ':' + port if host and port else 'не задан'}",
        f"Login: {login}",
        "Password: ****" if host and port else "Password: _",
        "",
        f"Proxy IP: {row.get('auth_proxy_ip') or 'не определено'}",
        f"Proxy Geo: {_tpag_panel_v2_geo(row.get('auth_proxy_country'), row.get('auth_proxy_region'), row.get('auth_proxy_city'))}",
        f"Server IP: {row.get('auth_direct_ip') or 'не определено'}",
        f"Server Geo: {_tpag_panel_v2_geo(row.get('auth_direct_country'), row.get('auth_direct_region'), row.get('auth_direct_city'))}",
        "",
        f"Auth Guard: {guard}",
        f"Проверено: {checked}",
    ]
    if err and not (ok and fresh):
        lines.append(f"Причина: {err[:500]}")
    return "\n".join(lines).rstrip()


