def _tpag_panel_v4_latency_lines(row: dict) -> list[str]:
    tcp_ms = int((row or {}).get("auth_tcp_ms") or 0)
    http_ms = int((row or {}).get("auth_proxy_http_ms") or 0)
    tg_ms = int((row or {}).get("auth_telethon_ms") or 0)
    if tcp_ms <= 0 and http_ms <= 0 and tg_ms <= 0:
        return []
    return [
        "",
        "Скорость proxy:",
        f"TCP: {tcp_ms} ms" if tcp_ms > 0 else "TCP: не определено",
        f"IP-check через proxy: {http_ms} ms" if http_ms > 0 else "IP-check через proxy: не определено",
        f"Telegram/Telethon: {tg_ms} ms" if tg_ms > 0 else "Telegram/Telethon: не определено",
    ]


