# --- TPILOT PANEL AUTH + BULK AUTOMATION V5 20260509 START ---
# Password-gated panel access for users who open the bot by link.
# Bulk buttons for auto replies and followups.

_TP_PANEL_V5_ORIG_IS_ALLOWED = globals().get("_is_allowed")
_TP_PANEL_V5_ORIG_MANAGERS_MENU = globals().get("_managers_menu")
_TP_PANEL_V5_ORIG_FOLLOWUPS_MENU = globals().get("_followups_menu")
_TP_PANEL_V5_ORIG_AUTOMATION_MENU = globals().get("_tp_visual_automation_menu")


def _tp_panel_v5_now_iso() -> str:
    try:
        return datetime.utcnow().replace(microsecond=0).isoformat()
    except Exception:
        return ""


def _tp_panel_v5_password() -> str:
    return str(globals().get("PANEL_ADMIN_PASSWORD") or globals().get("MANAGER_ADMIN_PASSWORD") or "").strip()


def _tp_panel_v5_ids(event) -> tuple[int, int]:
    try:
        uid = int(getattr(event, "sender_id", 0) or 0)
        cid = int(getattr(event, "chat_id", 0) or 0)
        return uid, cid
    except Exception:
        return 0, 0


# R1B/F-15 (plan section 23, F1b): _tp_panel_v5_ensure_auth_table used to run
# CREATE TABLE IF NOT EXISTS on every single call to _tp_panel_v5_authorized,
# i.e. on every password-authorized callback across all ~38 unfiltered
# CallbackQuery handlers -- a fresh connection just to no-op a DDL check.
# Once-per-process is sufficient: the table, once created, is never dropped.
_TP_PANEL_V5_AUTH_TABLE_READY = False


def _tp_panel_v5_ensure_auth_table() -> None:
    global _TP_PANEL_V5_AUTH_TABLE_READY
    if _TP_PANEL_V5_AUTH_TABLE_READY:
        return
    try:
        con = _connect_panel_db()
        try:
            con.execute("""
                CREATE TABLE IF NOT EXISTS panel_authorized_users(
                    user_id INTEGER PRIMARY KEY,
                    chat_id INTEGER DEFAULT 0,
                    username TEXT DEFAULT '',
                    first_name TEXT DEFAULT '',
                    authorized_at TEXT NOT NULL DEFAULT '',
                    last_seen_at TEXT NOT NULL DEFAULT ''
                )
            """)
            con.commit()
        finally:
            con.close()
        _TP_PANEL_V5_AUTH_TABLE_READY = True
    except Exception:
        pass


# In-memory {user_id: last_confirmed_monotonic_time} cache. A HIT only ever
# skips a REDUNDANT re-check of something already confirmed moments ago --
# it never grants access the DB wouldn't have granted, because a cache MISS
# (never seen, or older than the TTL) always falls through to the real
# SELECT. This is what turns "2 fresh connections/transactions on every one
# of ~38 handler invocations per button press" (up to ~76 total, per the
# forensic audit's F-15) into at most one every TTL_SEC per user.
_TP_PANEL_V5_AUTH_CACHE: Dict[int, float] = {}
_TP_PANEL_V5_AUTH_CACHE_TTL_SEC = 30.0


def _tp_panel_v5_authorized(user_id: int) -> bool:
    uid = int(user_id or 0)
    if not uid:
        return False
    now = time.monotonic()
    cached_at = _TP_PANEL_V5_AUTH_CACHE.get(uid)
    if cached_at is not None and (now - cached_at) < _TP_PANEL_V5_AUTH_CACHE_TTL_SEC:
        return True
    try:
        _tp_panel_v5_ensure_auth_table()
        con = _connect_panel_db()
        try:
            row = con.execute("SELECT 1 FROM panel_authorized_users WHERE user_id=? LIMIT 1", (uid,)).fetchone()
            if row:
                try:
                    con.execute("UPDATE panel_authorized_users SET last_seen_at=? WHERE user_id=?", (_tp_panel_v5_now_iso(), uid))
                    con.commit()
                except Exception:
                    pass
                _TP_PANEL_V5_AUTH_CACHE[uid] = now
                return True
            _TP_PANEL_V5_AUTH_CACHE.pop(uid, None)
            return False
        finally:
            con.close()
    except Exception:
        return False


def _tp_panel_v5_allowlist_hit(user_id: int, chat_id: int) -> bool:
    try:
        allowed_users = globals().get("ALLOWED_USERS") or set()
        allowed_chats = globals().get("ALLOWED_CHATS") or set()
        if allowed_users and int(user_id or 0) in allowed_users:
            return True
        if allowed_chats and int(chat_id or 0) in allowed_chats:
            return True
    except Exception:
        pass
    return False


def _is_allowed(event) -> bool:  # type: ignore[override]
    uid, cid = _tp_panel_v5_ids(event)
    password = _tp_panel_v5_password()

    # Existing explicit allow-list keeps current admin access stable.
    if _tp_panel_v5_allowlist_hit(uid, cid):
        return True

    # If password is configured, users with the bot link must authorize once.
    if password:
        return _tp_panel_v5_authorized(uid)

    # No password configured: keep old behavior exactly.
    if callable(_TP_PANEL_V5_ORIG_IS_ALLOWED):
        try:
            return bool(_TP_PANEL_V5_ORIG_IS_ALLOWED(event))
        except Exception:
            return False
    return False


def _tp_panel_v5_store_auth(event) -> None:
    uid, cid = _tp_panel_v5_ids(event)
    if not uid:
        return
    now = _tp_panel_v5_now_iso()
    username = ""
    first_name = ""
    try:
        sender = getattr(event, "sender", None)
        username = str(getattr(sender, "username", "") or "")
        first_name = str(getattr(sender, "first_name", "") or "")
    except Exception:
        pass
    _tp_panel_v5_ensure_auth_table()
    con = _connect_panel_db()
    try:
        con.execute(
            """
            INSERT INTO panel_authorized_users(user_id, chat_id, username, first_name, authorized_at, last_seen_at)
            VALUES(?,?,?,?,?,?)
            ON CONFLICT(user_id) DO UPDATE SET
                chat_id=excluded.chat_id,
                username=excluded.username,
                first_name=excluded.first_name,
                last_seen_at=excluded.last_seen_at
            """,
            (int(uid), int(cid or 0), username, first_name, now, now),
        )
        con.commit()
    finally:
        con.close()


def _tp_panel_v5_remove_auth(user_id: int) -> bool:
    # R1B correction (2026-08-13, closes independent-review Blocker B-2, then
    # B-3): this is the single canonical revoke path (/logout is its only
    # caller). Returns True iff the authoritative DB DELETE actually
    # committed -- the caller (/logout) uses this to decide whether it is
    # allowed to tell the user they're logged out (B-3: reporting success
    # while the DB row still exists is a false promise, independent of and
    # worse than the earlier stale-cache window B-2 closed).
    #
    # The in-memory auth cache (_TP_PANEL_V5_AUTH_CACHE, F-15) is popped
    # UNCONDITIONALLY and BEFORE the DELETE is attempted (B-2's fix,
    # preserved as-is): a cache entry surviving a reported-or-attempted
    # logout would be strictly worse than the DB delete itself failing, and
    # popping it never grants access the DB wouldn't -- a miss just falls
    # through to a real DB read (which, if the DELETE below failed, will
    # correctly still find the row and return True; that is the DB telling
    # the truth, not the cache lying).
    uid = int(user_id or 0)
    _TP_PANEL_V5_AUTH_CACHE.pop(uid, None)
    try:
        _tp_panel_v5_ensure_auth_table()
        con = _connect_panel_db()
        try:
            con.execute("DELETE FROM panel_authorized_users WHERE user_id=?", (uid,))
            con.commit()
        finally:
            con.close()
        return True
    except Exception as exc:
        print(f"panel auth revoke failed uid={uid} error_class={type(exc).__name__}")
        return False


async def _tp_panel_v5_send_auth_prompt(event, wrong: bool = False) -> None:
    password = _tp_panel_v5_password()
    if not password:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, admin
        # misconfiguration, no in-chat recovery.
        await event.reply("⛔ Нет доступа к TPilot Panel. Пароль панели не задан в .env.TPilot.", buttons=_terminal_ok_button())
        return
    text = "🔐 Доступ к TPilot Admin Panel\n\nВведите пароль администратора одним сообщением."
    if wrong:
        text = "⛔ Неверный пароль.\n\nВведите пароль администратора ещё раз."
    await event.reply(text)


@client.on(events.NewMessage(pattern=r"^/(logout|panel_logout)$"))
async def _tp_panel_v5_logout(event):
    uid, _cid = _tp_panel_v5_ids(event)
    revoked = _tp_panel_v5_remove_auth(uid)
    # B-3 correction (2026-08-13, closes independent-review Blocker B-3):
    # the success message is a promise about the AUTHORITATIVE DB state, not
    # about the (already-cleared) cache -- it must only be sent if the DB
    # DELETE actually committed. Sending it unconditionally meant a user
    # could be told "you're logged out" while their DB row -- and therefore
    # their real access -- was untouched.
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal.
    if revoked:
        await event.reply("✅ Вы вышли из TPilot Panel. Для нового входа отправьте /start и введите пароль.", buttons=_terminal_ok_button())
    else:
        await event.reply("⚠️ Не удалось выйти из TPilot Panel. Попробуйте ещё раз.", buttons=_terminal_ok_button())


@client.on(events.NewMessage)
async def _tp_panel_v5_auth_input(event):
    # Existing allowed or already authorized users should continue to the normal panel handlers.
    if _is_allowed(event):
        return
    raw = str(getattr(event, "raw_text", "") or "").strip()
    if not raw:
        return
    password = _tp_panel_v5_password()
    if not password:
        return
    if raw.startswith("/"):
        if raw.lower() in ("/start", "/panel"):
            await _tp_panel_v5_send_auth_prompt(event)
        return
    if raw == password:
        try:
            await event.delete()
        except Exception:
            pass
        _tp_panel_v5_store_auth(event)
        chat_id = int(getattr(event, "chat_id", 0) or 0)
        user_id = int(getattr(event, "sender_id", 0) or 0)
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal; the
        # fresh panel sent right after is a separate message.
        await client.send_message(chat_id, "✅ Д��ступ подтверждён. Открываю панель.", buttons=_terminal_ok_button())
        _register_panel_subscriber(chat_id, user_id)
        await _send_fresh_panel(chat_id, user_id, delete_previous=True)
        return
    await _tp_panel_v5_send_auth_prompt(event, wrong=True)


def _tp_panel_v5_confirm_buttons(kind: str, action: str):
    # N3.1 fix R3 + N5.3 fix D10: kind-aware Back target, returning to the
    # IMMEDIATE screen each bulk action is actually launched from (whose own
    # Back rows are canonical after D6/D7): "silent" -> menu:profile
    # (emergency-silence screen), "followup" -> menu:followups,
    # "autoreply" -> menu:managers (autoreply list). The old catch-all
    # menu:automation (retired Gen-2 hub) is no longer used as a cancel
    # destination from the canonical tree.
    if kind == "silent":
        back_route = b"menu:profile"
    elif kind == "followup":
        back_route = b"menu:followups"
    else:
        back_route = b"menu:managers"
    return [
        [Button.inline("✅ Да, применить ко всем", f"bulk:run:{kind}:{action}".encode())],
        [Button.inline("⬅️ Назад", back_route), Button.inline("🏠 Главная", b"menu:main")],
    ]


def _pb_active_manager_count() -> int:
    """N3 (fixed in N3.1): synchronous count matching main.py's own 'active
    manager' bulk-scope definition (_tp_main_v5_active_manager_keys, used by
    /followup ... all -> manager_list_rows(include_removed=False), which
    applies NO role filter) -- is_enabled==1 AND status in ('', 'active',
    'enabled'), closers INCLUDED. exclude_closers=False here is deliberate:
    the real bulk command actually changes closer rows too (N3.1 fix R2),
    so the confirm-screen count must not understate the blast radius."""
    try:
        rows = _manager_rows_all(exclude_closers=False)
    except Exception:
        rows = []
    n = 0
    for r in rows or []:
        status = str((r or {}).get("status") or "").strip().lower()
        enabled = int((r or {}).get("is_enabled") or 0) == 1
        if status and status not in ("active", "enabled"):
            continue
        if not enabled:
            continue
        n += 1
    return n


def _tp_panel_v5_confirm_text(kind: str, action: str) -> str:
    # N3: bulk actions (H/I) stay deliberate two-action pairs (not toggles);
    # the requirement added here is showing the affected-manager count.
    count = _pb_active_manager_count()
    if kind == "autoreply" and action == "auto":
        return "⚠️ Подтвердите действие\n\nВключить режим “Авто по графику” всем активным менеджерам?"
    if kind == "autoreply" and action == "silent":
        return "⚠️ Подтвердите действие\n\nОтключить клиентские автоответы всем активным менеджерам?\n\nРежим будет: “Не писать клиентам”."
    if kind == "followup" and action == "on":
        return f"⚠️ Подтвердите действие\n\nВключить автодожимы всем активным менеджерам?\n\nЗатронет менеджеров: {count}"
    if kind == "followup" and action == "off":
        return f"⚠️ Подтвердите действие\n\nВыключить автодожимы всем активным менеджерам?\n\nЗатронет менеджеров: {count}"
    if kind == "silent" and action == "on":
        # N3.1 fix R5: /silent manager on all writes ONE global flag, not N
        # independent per-manager rows -- wording must not imply per-manager
        # scoping; the manager count stays purely informational context.
        return (
            "⚠️ Подтвердите действие\n\n"
            "Тишина будет включена для всех.\n"
            "Все авто-сообщения клиентам будут остановлены.\n\n"
            f"Активных менеджеров сейчас: {count}"
        )
    return "⚠️ Подтвердите действие"


def _tp_panel_v5_command_for(kind: str, action: str) -> str:
    if kind == "silent" and action == "on":
        return "/silent manager on all"
    if kind == "autoreply" and action == "auto":
        return "/autoreply auto all"
    if kind == "autoreply" and action == "silent":
        return "/autoreply silent all"
    if kind == "followup" and action == "on":
        return "/followup on all"
    if kind == "followup" and action == "off":
        return "/followup off all"
    return ""


