@client.on(events.CallbackQuery(pattern=b"^bulk:"))
async def _tp_panel_v5_bulk_callback(event):
    if not _is_allowed(event):
        await _pb_safe_answer(event, "Введите пароль", alert=True)
        return
    data = (event.data or b"").decode("utf-8", errors="ignore")
    parts = data.split(":")
    if len(parts) < 4:
        await _pb_safe_answer(event, "Неверная команда", alert=True)
        return
    _prefix, step, kind, action = parts[:4]
    if step == "ask":
        await _safe_event_edit(event, _tp_panel_v5_confirm_text(kind, action), buttons=_tp_panel_v5_confirm_buttons(kind, action))
        return
    if step == "run":
        command = _tp_panel_v5_command_for(kind, action)
        if not command:
            await _pb_safe_answer(event, "Неверная команда", alert=True)
            return
        await _pb_safe_answer(event, "⏳ Выполняю")
        chat_id = int(getattr(event, "chat_id", 0) or 0)
        user_id = int(getattr(event, "sender_id", 0) or 0)
        row = await _submit_and_wait(command, user_id, chat_id, chat_id)
        status = str(row.get("status") or "")
        text = str(row.get("result_text") or row.get("error_text") or "")
        if status != "done":
            text = "⚠️ " + (text or "Ошибка выполнения команды")
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): bulk action applied
        # to all managers -- terminal, done.
        await _safe_event_edit(event, _safe_text(text or "✅ Готово"), buttons=_back_to_panel_buttons() + _terminal_ok_button())
        return
    await _pb_safe_answer(event, "Неверная команда", alert=True)
