def _tp_v8_manager_label_by_key(key: str) -> str:
    try:
        nk = normalize_manager_key(key)
    except Exception:
        nk = str(key or "").strip()
    try:
        for r in _manager_rows():
            if normalize_manager_key(str((r or {}).get("manager_key") or "")) == nk:
                return _manager_short_label(r)
    except Exception:
        pass
    return nk or "менеджер"


def _tp_v8_manager_action_rows():
    """The per-manager baseline action rows (status/mark/reset) -- moved out
    of the main service menu into their own screen (menu:baseline_managers)
    20260713, since up to 25 managers x up to 3 rows made the service menu
    unusably long. Same callbacks, same business logic, just rendered on a
    separate screen instead of inline."""
    try:
        managers = _manager_rows()[:25]
    except Exception:
        managers = []
    rows = []
    for r in managers:
        key = str((r or {}).get("manager_key") or "").strip()
        if not key:
            continue
        label = _manager_short_label(r)
        rows.append([
            Button.inline(f"📊 Проверить: {label}", f"cmd:/baseline status {key}".encode()),
            Button.inline(f"📌 Пометить: {label}", f"cmd:/baseline create {key}".encode()),
        ])
        rows.append([
            Button.inline(f"♻️ Сбросить: {label}", f"menu:baseline_clear_confirm:{key}".encode()),
        ])
    return rows


