def _panel_wizard_resume_text_buttons(chat_id: int, user_id: int):  # type: ignore[override]
    state = _wizard_get(int(chat_id or 0), int(user_id or 0))
    wizard = str((state or {}).get("wizard") or "")
    step = str((state or {}).get("step") or "")
    if wizard == "profile_lead_check":
        return _tpac_profile_lead_prompt(), _tpac_back_profile_buttons()
    if wizard == "profile_period_check":
        return _tpac_profile_period_prompt(), _tpac_back_profile_buttons()
    if wizard == "profile_apply_code":
        return _tpac_profile_apply_prompt(), _tpac_back_profile_buttons()
    if callable(_TPAC_PANEL_ORIG_PANEL_WIZARD_RESUME):
        return _TPAC_PANEL_ORIG_PANEL_WIZARD_RESUME(chat_id, user_id)
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): informational terminal
    # card -- there is genuinely nothing to resume, no further step.
    return "Незавершённых действий нет.", _back_to_panel_buttons() + _terminal_ok_button()


@client.on(events.CallbackQuery)
async def _tpac_profile_panel_callback(event):
    if not _is_allowed(event):
        return
    data = (event.data or b"").decode("utf-8", errors="ignore")
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    if data == "wiz:profile_lead:start":
        _wizard_set(chat_id, user_id, "profile_lead_check", "chat_id", {})
        await _safe_event_edit(event, _tpac_profile_lead_prompt(), buttons=_tpac_back_profile_buttons())
        return
    if data == "wiz:profile_period:start":
        _wizard_set(chat_id, user_id, "profile_period_check", "range", {})
        await _safe_event_edit(event, _tpac_profile_period_prompt(), buttons=_tpac_back_profile_buttons())
        return
    if data == "wiz:profile_apply:start":
        _wizard_set(chat_id, user_id, "profile_apply_code", "code", {})
        await _safe_event_edit(event, _tpac_profile_apply_prompt(), buttons=_tpac_back_profile_buttons())
        return


@client.on(events.NewMessage)
async def _tpac_profile_panel_wizard_input(event):
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    wizard = str((state or {}).get("wizard") or "")
    if wizard not in ("profile_lead_check", "profile_period_check", "profile_apply_code"):
        return
    try:
        if wizard == "profile_lead_check":
            candidate = re.sub(r"[^0-9\-]", "", raw).strip()
            if not candidate:
                await event.reply("⚠️ Введите числовой ID клиента.", buttons=_tpac_back_profile_buttons())
                return
            _wizard_clear(chat_id, user_id)
            row = await _submit_and_wait(f"/lead profile {candidate}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _send_text_result_with_panel(chat_id, user_id, text or "Готово")
            return
        if wizard == "profile_period_check":
            dates = re.findall(r"\b\d{1,4}[.\-]\d{1,2}[.\-]\d{1,4}\b", raw)
            if len(dates) < 2:
                await event.reply("⚠️ Нужно две даты. Пример: 01.05.26 11.05.26", buttons=_tpac_back_profile_buttons())
                return
            _wizard_clear(chat_id, user_id)
            row = await _submit_and_wait(f"/lead repair range {dates[0]} {dates[1]} dry", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _send_text_result_with_panel(chat_id, user_id, text or "Готово")
            return
        if wizard == "profile_apply_code":
            code = re.sub(r"[^0-9A-Za-z_\-]", "", raw).strip()
            if not code:
                await event.reply("⚠️ Введите код проверки. Например repair_20260512_021530", buttons=_tpac_back_profile_buttons())
                return
            _wizard_clear(chat_id, user_id)
            row = await _submit_and_wait(f"/lead repair apply {code} confirm", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _send_text_result_with_panel(chat_id, user_id, text or "Готово")
            return
    except Exception as e:
        _wizard_clear(chat_id, user_id)
        await _send_text_result_with_panel(chat_id, user_id, f"⚠️ Ошибка проверки анкет: {e!r}")

