def _cmd_for(kind: str, target: str = "all", iso_date: str | None = None):  # type: ignore[override]
    target = normalize_manager_key(target or "all") or "all"
    date_part = f" {_cmd_date(iso_date)}" if iso_date else ""
    raw = str(kind or "stats").lower()
    if raw == "export":
        return f"/export {target}{date_part}".strip()
    if raw in ("export_flights", "flight_export", "flights_export"):
        return f"/export flight {target}{date_part}".strip()
    if raw == "flights":
        return f"/flight {target}{date_part}".strip()
    return f"/stat {target}{date_part}".strip()


