def _calendar_menu(kind: str, target: str, iso_date: str):  # type: ignore[override]
    raw_kind = str(kind or "").lower()
    if raw_kind == "export":
        kind = "export"
    elif raw_kind in ("export_flights", "flight_export", "flights_export"):
        kind = "export_flights"
    elif raw_kind == "flights":
        kind = "flights"
    else:
        kind = "stats"
    target = normalize_manager_key(target or "all") or "all"
    iso_date = _clamp_iso_date(iso_date)
    date_label = _display_date(iso_date)

    if kind == "export":
        title = "📦 Excel день"
        action_all = "📦 Excel день по всем"
        back_menu = b"menu:export"
    elif kind == "export_flights":
        title = "🌙 Excel долёты"
        action_all = "🌙 Excel долёты по всем"
        back_menu = b"menu:export"
    elif kind == "flights":
        title = "🌙 Долёты"
        action_all = "🌙 Долёты по всем"
        back_menu = b"menu:flights"
    else:
        title = "📊 Дневная статистика"
        action_all = "📊 День по всем"
        back_menu = b"menu:stats"

    prev_day = _shift_iso_date(iso_date, -1)
    next_day = _shift_iso_date(iso_date, 1)
    prev_week = _shift_iso_date(iso_date, -7)
    next_week = _shift_iso_date(iso_date, 7)
    rows = [
        [Button.inline("◀️ День назад", _callback_data(kind, target, prev_day)), Button.inline("День вперёд ▶️", _callback_data(kind, target, next_day))],
        [Button.inline("⏪ Неделя назад", _callback_data(kind, target, prev_week)), Button.inline("Неделя вперёд ⏩", _callback_data(kind, target, next_week))],
        [Button.inline(action_all, f"cmd:{_cmd_for(kind, 'all', iso_date)}".encode())],
    ]
    for r in _manager_rows()[:25]:
        key = str(r.get("manager_key") or "").strip()
        if not key:
            continue
        label = _manager_short_label(r)
        rows.append([Button.inline(f"👤 {label}", f"cmd:{_cmd_for(kind, key, iso_date)}".encode())])
    rows.append([Button.inline("⬅️ Назад", back_menu), Button.inline("🏠 Главная", b"menu:main")])
    text = f"{_panel_header()}\n\n{title}\nДата: {date_label}"
    if kind in ("flights", "export_flights"):
        text += "\n\nДата долётов = утро закрытия окна. Например 12.05 = 11.05 17:00 - 12.05 08:00."
    return text, rows

