@client.on(events.CallbackQuery)
async def _tp_gq_panel_schedule_callback(event):
    if not _is_allowed(event):
        return
    data = (event.data or b"").decode("utf-8", errors="ignore")
    if not data.startswith("wiz:autoschedule:"):
        return
    key = normalize_manager_key(data.split(":", 2)[2])
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    _wizard_set(chat_id, user_id, "autoschedule", "value", {"key": key})
    await event.edit(_tp_gq_panel_schedule_text(key), buttons=[[Button.inline("⬅️ Отмена", f"menu:manager:{key}".encode())]])


@client.on(events.NewMessage)
async def _tp_gq_panel_schedule_input(event):
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if not state or str(state.get("wizard") or "") != "autoschedule":
        return
    payload = dict(state.get("payload") or {})
    key = normalize_manager_key(payload.get("key") or "")
    parts = raw.replace(",", " ").split()
    if len(parts) != 4:
        await event.reply("⚠️ Нужно 4 времени. Пример: 08:00 17:00 17:00 08:00", buttons=_back_to_panel_buttons())
        return
    row = await _submit_and_wait(f"/autoschedule set {key} {parts[0]} {parts[1]} {parts[2]} {parts[3]}", user_id, chat_id, chat_id)
    result = str(row.get("result_text") or row.get("error_text") or "Готово")
    cleared = not result.startswith("⚠️")
    if cleared:
        _wizard_clear(chat_id, user_id)
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): the ⚠️ branch keeps
    # the wizard open for a retry -- not terminal, don't add OK there.
    await _send_text_result_with_panel(chat_id, user_id, result, terminal=cleared)

