# --- TPILOT N3.2 MANAGER-MODE TOGGLE STANDARDIZATION START ---
# Closes the remaining visible side-by-side binary pairs flagged by the N3
# independent review (R7): greeting/questionnaire on the manager-modes card
# and the per-manager row inside the emergency-silence screen. Same
# target-encoded, state-revalidating contract as N3's F/G (autostatus/LLM),
# adapted for controls whose real writes go through the existing
# panel_commands queue (main.py), not a direct panel_bot setting write --
# no business logic is duplicated here, only fresh reads + existing commands.

def _pb_gq_truth(raw, default: int) -> int:
    """N3.2: mirrors main.py's _tp_ae_truth truthy-parse for client-auto
    settings values."""
    s = str(raw if raw is not None else "").strip().lower()
    if s in {"1", "true", "yes", "on", "вкл", "да"}:
        return 1
    if s in {"0", "false", "no", "off", "выкл", "нет"}:
        return 0
    return int(default)


def _pb_gq_global_default(setting_key: str, fallback: int) -> int:
    """N3.2: synchronous read of client_auto_global_settings, mirrors
    main.py's _tp_ae_global_default (the fallback used when a manager has no
    override row in manager_client_auto_settings)."""
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT value FROM client_auto_global_settings WHERE setting_key=?", (str(setting_key),)
            ).fetchone()
            return int(fallback) if not row else _pb_gq_truth(row[0], fallback)
        finally:
            con.close()
    except Exception:
        return int(fallback)


def _pb_greeting_enabled(key: str) -> bool:
    """N3.2: synchronous read matching main.py's _tp_gq_get_settings
    default-cascade for greeting_enabled (per-manager row in
    manager_client_auto_settings -> global 'default_greeting_enabled' ->
    hardcoded default ON), same convention as N3's _pb_followup_enabled."""
    key = normalize_manager_key(key or "")
    default = _pb_gq_global_default("default_greeting_enabled", 1)
    if not key:
        return default == 1
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT greeting_enabled FROM manager_client_auto_settings WHERE manager_key=?", (key,)
            ).fetchone()
            return (default == 1) if not row else (_pb_gq_truth(row[0], default) == 1)
        finally:
            con.close()
    except Exception:
        return default == 1


def _pb_questionnaire_enabled(key: str) -> bool:
    """N3.2: same convention as _pb_greeting_enabled, for
    questionnaire_enabled (hardcoded default OFF, matching main.py's
    TP_AE_DEFAULT_QUESTIONNAIRE_ENABLED)."""
    key = normalize_manager_key(key or "")
    default = _pb_gq_global_default("default_questionnaire_enabled", 0)
    if not key:
        return default == 1
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT questionnaire_enabled FROM manager_client_auto_settings WHERE manager_key=?", (key,)
            ).fetchone()
            return (default == 1) if not row else (_pb_gq_truth(row[0], default) == 1)
        finally:
            con.close()
    except Exception:
        return default == 1


def _pb_manager_silent_enabled(key: str) -> bool:
    """N3.2: synchronous read of client_auto_silent_rules(scope='manager',
    rule_key=key) -- deliberately the manager-scope row ONLY (not the
    combined 'blocked' check that also folds in the global 'all' rule),
    because that manager-scope row is exactly what
    '/silent manager on|off {key}' reads and writes; matches the per-manager
    toggle contract (Part B: preserve per-manager scope)."""
    key = normalize_manager_key(key or "")
    if not key:
        return False
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT enabled FROM client_auto_silent_rules WHERE scope='manager' AND rule_key=?", (key,)
            ).fetchone()
            return False if not row else int(row[0] or 0) == 1
        finally:
            con.close()
    except Exception:
        return False


def _pb_toggle_btn(label: str, data: str, fallback: bytes):
    """N3.2: defensive 64-byte guard for the mmt: target-encoded toggle
    buttons, same pattern as _mcard_btn (N2) / _nm_btn (N1), but with a
    caller-supplied fallback since these toggles live on different origin
    screens (manager-modes card vs emergency-silence list)."""
    raw = str(data or "").encode("utf-8")
    if len(raw) <= 64:
        return Button.inline(label, raw)
    return Button.inline(label, fallback if len(fallback) <= 64 else b"menu:main")


def _pb_mmt_resolve(data: str) -> dict:
    """N3.2: pure parse/validate/state-revalidation logic for an mmt:
    callback, kept separate from on_callback's async Telethon dispatch so it
    is directly unit-testable (no live event loop / fake event needed).
    Never mutates anything -- only reads fresh state and returns a decision:
      {"ok": False, "reason": "malformed"}
      {"ok": False, "reason": "missing_manager", "kind": <kind or "">}
      {"ok": True, "stale": True, "kind": ..., "key": ..., "target": ...}
      {"ok": True, "stale": False, "kind": ..., "key": ..., "target": ..., "command": ...}
    A malformed kind/target/key never reaches _pb_greeting_enabled/
    _pb_questionnaire_enabled/_pb_manager_silent_enabled or a command string,
    so it can never mutate state."""
    parts = str(data or "").split(":", 3)
    kind = parts[1] if len(parts) > 1 else ""
    target = parts[2] if len(parts) > 2 else ""
    key = normalize_manager_key(parts[3] if len(parts) > 3 else "")
    if kind not in ("greeting", "quest", "silentcard", "silentlist") or target not in ("on", "off") or not key:
        return {"ok": False, "reason": "malformed"}
    if not _manager_row_by_key(key):
        return {"ok": False, "reason": "missing_manager", "kind": kind}
    if kind == "greeting":
        current_on, command = _pb_greeting_enabled(key), f"/greeting {target} {key}"
    elif kind == "quest":
        current_on, command = _pb_questionnaire_enabled(key), f"/questionnaire {target} {key}"
    else:
        current_on, command = _pb_manager_silent_enabled(key), f"/silent manager {target} {key}"
    if current_on == (target == "on"):
        return {"ok": True, "stale": True, "kind": kind, "key": key, "target": target}
    return {"ok": True, "stale": False, "kind": kind, "key": key, "target": target, "command": command}


async def _pb_mmt_rerender(event, kind: str, key: str, notice: str = "") -> None:
    """N3.2: resolves the correct canonical origin screen for a given
    manager-mode toggle kind and re-renders it from fresh state, optionally
    prefixed with a short notice (stale click / missing manager / command
    failure) -- the single rerender path used by every mmt: outcome."""
    origin = "profile" if kind == "silentlist" else (f"manager:{key}" if key else "managers")
    text, buttons = _title_for_menu(origin)
    if notice:
        text = notice + "\n\n" + text
    await _safe_event_edit(event, text, buttons=buttons)


async def _pb_mmt_run(event, chat_id: int, user_id: int, kind: str, key: str, command: str) -> None:
    """N3.2: dispatches the real, existing command through the same
    panel_commands queue every other manager action uses (no business logic
    duplicated), then rerenders the canonical origin screen from fresh
    state -- mirrors _ppool_run_autorenew_toggle's submit-then-refresh shape."""
    row = await _submit_and_wait(command, user_id, chat_id, chat_id)
    ok = str((row or {}).get("status") or "") == "done"
    notice = "" if ok else "⚠️ " + str((row or {}).get("error_text") or "Не удалось изменить настройку.")
    await _pb_mmt_rerender(event, kind, key, notice)


