# --- TPILOT EXTERNAL WATCHDOG STATUS V1 START ---
# Optional HTTP status from EXTERNAL_WATCHDOG_STATUS_URL; local soft_status fallback when unset/unreachable.

def _read_external_watchdog_status() -> bool | None:
    """Return True/False when external checker responds; None => use local _panel_health()."""
    import urllib.request

    url = (os.getenv("EXTERNAL_WATCHDOG_STATUS_URL") or "").strip()
    if not url:
        return None
    token = (os.getenv("EXTERNAL_WATCHDOG_STATUS_TOKEN") or "").strip()
    try:
        timeout = float((os.getenv("EXTERNAL_WATCHDOG_TIMEOUT_SEC") or "1.5").strip() or "1.5")
    except Exception:
        timeout = 1.5
    try:
        req = urllib.request.Request(url, method="GET")
        if token:
            req.add_header("Authorization", f"Bearer {token}")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = (resp.read() or b"").decode("utf-8", errors="ignore")
        data = json.loads(raw or "{}")
        if not isinstance(data, dict):
            return None
        if data.get("ok") is True:
            return True
        if data.get("ok") is False:
            return False
        return None
    except Exception:
        return None


_TP_EXT_WD_ORIG_PANEL_HEALTH = globals().get("_panel_health")


def _panel_health() -> Dict[str, Any]:  # type: ignore[override]
    h = _TP_EXT_WD_ORIG_PANEL_HEALTH() if callable(_TP_EXT_WD_ORIG_PANEL_HEALTH) else {}
    ext = _read_external_watchdog_status()
    if ext is not None and isinstance(h, dict):
        h = dict(h)
        h["watchdog_ok"] = bool(ext)
    return h

# --- TPILOT EXTERNAL WATCHDOG STATUS V1 END ---


