_MBA_FLAG_COL = {
    "c": "can_receive_cards",
    "s": "can_set_status",
    "v": "can_view_stats",
    "p": "allow_custom_period",
}


def _mba_safe_int(v):
    try:
        return int(v or 0)
    except Exception:
        return 0


def _mba_bool(v):
    return "\u0432\u043a\u043b" if int(v or 0) == 1 else "\u0432\u044b\u043a\u043b"


def _mba_yes(v):
    return "\u0434\u0430" if int(v or 0) == 1 else "\u043d\u0435\u0442"


def _mba_label(row):
    if not row:
        return "unknown"
    username = str(row.get("username") or row.get("au_username") or "").strip().lstrip("@")
    if username:
        return "@" + username
    display_name = str(row.get("display_name") or row.get("au_display_name") or "").strip()
    if display_name:
        return display_name
    first_name = str(row.get("first_name") or "").strip()
    last_name = str(row.get("last_name") or "").strip()
    full = " ".join([x for x in [first_name, last_name] if x]).strip()
    if full:
        return full
    uid = _mba_safe_int(row.get("tg_user_id") or row.get("user_id"))
    return f"ID {uid}" if uid else "unknown"


def _mba_rows_for_key(key):
    key = normalize_manager_key(key or "")
    if not key:
        return []
    con = _connect_panel_db()
    try:
        rows = con.execute("""
            SELECT mba.*,
                   au.username AS au_username,
                   au.display_name AS au_display_name,
                   au.is_enabled AS au_is_enabled
            FROM manager_bot_access mba
            LEFT JOIN access_users au ON au.tg_user_id = mba.tg_user_id
            WHERE mba.manager_key=?
            ORDER BY mba.revoked ASC, mba.tg_user_id ASC
        """, (key,)).fetchall()
        return [dict(r) for r in rows]
    except Exception as exc:
        print(f"m26f read rows failed: {exc!r}")
        return []
    finally:
        con.close()


def _mba_row(uid, key):
    uid = _mba_safe_int(uid)
    key = normalize_manager_key(key or "")
    if not uid or not key:
        return {}
    con = _connect_panel_db()
    try:
        row = con.execute("""
            SELECT *
            FROM manager_bot_access
            WHERE tg_user_id=? AND manager_key=?
            LIMIT 1
        """, (uid, key)).fetchone()
        return dict(row) if row else {}
    except Exception as exc:
        print(f"m26f read row failed: {exc!r}")
        return {}
    finally:
        con.close()


