def _mba_approve(uid, key, admin_id):
    uid = _mba_safe_int(uid)
    key = normalize_manager_key(key or "")
    admin_id = _mba_safe_int(admin_id)
    if not uid or not key:
        return False

    req = _mba_request_by_id(uid)
    now = _utc_now_iso()
    username = str(req.get("username") or "").strip().lstrip("@")
    first_name = str(req.get("first_name") or "").strip()
    last_name = str(req.get("last_name") or "").strip()
    display_name = " ".join([x for x in [first_name, last_name] if x]).strip()
    cutoff = _mba_event_cutoff(key)

    con = _connect_panel_db()
    try:
        con.execute("""
            INSERT INTO access_users(
                tg_user_id, display_name, username, access_level,
                scope_mode, is_enabled, created_by, created_at, updated_at
            )
            VALUES (?, ?, ?, 1, 'selected', 1, ?, ?, ?)
            ON CONFLICT(tg_user_id) DO UPDATE SET
                display_name=excluded.display_name,
                username=excluded.username,
                access_level=1,
                scope_mode='selected',
                is_enabled=1,
                updated_at=excluded.updated_at
        """, (uid, display_name, username, admin_id, now, now))

        con.execute("""
            INSERT OR IGNORE INTO access_targets(tg_user_id, manager_key, created_at)
            VALUES (?, ?, ?)
        """, (uid, key, now))

        con.execute("""
            INSERT INTO manager_bot_access(
                tg_user_id, manager_key,
                can_receive_cards, can_set_status, can_view_stats,
                stats_format, allow_custom_period,
                auto_granted, granted_by, granted_at,
                revoked, revoked_by, revoked_at,
                event_cutoff_id,
                created_at, updated_at
            )
            VALUES (?, ?, 1, 1, 0, 'light', 0, 0, ?, ?, 0, 0, '', ?, ?, ?)
            ON CONFLICT(tg_user_id, manager_key) DO UPDATE SET
                can_receive_cards=1,
                can_set_status=1,
                granted_by=excluded.granted_by,
                granted_at=excluded.granted_at,
                revoked=0,
                revoked_by=0,
                revoked_at='',
                event_cutoff_id=CASE
                    WHEN COALESCE(manager_bot_access.event_cutoff_id,0)>0
                    THEN manager_bot_access.event_cutoff_id
                    ELSE excluded.event_cutoff_id
                END,
                updated_at=excluded.updated_at
        """, (uid, key, admin_id, now, cutoff, now, now))

        con.execute("""
            UPDATE manager_access_requests
               SET status='approved',
                   updated_at=?
             WHERE user_id=?
        """, (now, uid))

        con.commit()
        return True
    except Exception as exc:
        print(f"m26f approve failed: {exc!r}")
        return False
    finally:
        con.close()


