def _mbaccess_all_text():
    rows = []
    try:
        con = _connect_panel_db()
        try:
            rows = con.execute("""
                SELECT manager_key,
                       COUNT(*) AS access_count,
                       SUM(CASE WHEN COALESCE(revoked,0)=0 THEN 1 ELSE 0 END) AS active_count,
                       SUM(CASE WHEN COALESCE(revoked,0)=1 THEN 1 ELSE 0 END) AS revoked_count
                FROM manager_bot_access
                GROUP BY manager_key
                ORDER BY manager_key
            """).fetchall()
        finally:
            con.close()
    except Exception as exc:
        print(f"m26f2 mbaccess all read failed: {exc!r}")
        rows = []

    pending = 0
    try:
        con = _connect_panel_db()
        try:
            r = con.execute("SELECT COUNT(*) FROM manager_access_requests WHERE status='new'").fetchone()
            pending = int(r[0] or 0) if r else 0
        finally:
            con.close()
    except Exception:
        pending = 0

    lines = [
        "\U0001f916 \u0414\u043e\u0441\u0442\u0443\u043f ManagerBot",
        "",
        "\u0420\u0430\u0437\u0434\u0435\u043b \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u0430\u043c\u0438 \u043c\u0435\u043d\u0435\u0434\u0436\u0435\u0440\u043e\u0432.",
        "",
        f"\u0417\u0430\u044f\u0432\u043a\u0438: {pending}",
        f"\u041c\u0435\u043d\u0435\u0434\u0436\u0435\u0440\u044b \u0441 \u0434\u043e\u0441\u0442\u0443\u043f\u0430\u043c\u0438: {len(rows)}",
    ]
    return _safe_text("\n".join(lines))


def _mbaccess_all_buttons():
    buttons = []
    buttons.append([Button.inline("\u2501\u2501\u2501\u2501 MANAGERBOT \u2501\u2501\u2501\u2501", b"noop")])

    manager_rows = []
    try:
        con = _connect_panel_db()
        try:
            manager_rows = con.execute("""
                SELECT m.manager_key,
                       COALESCE(m.display_name,'') AS display_name,
                       COALESCE(m.telegram_username,'') AS telegram_username,
                       COUNT(mba.tg_user_id) AS access_count,
                       SUM(CASE WHEN COALESCE(mba.revoked,0)=0 THEN 1 ELSE 0 END) AS active_count
                FROM managers m
                LEFT JOIN manager_bot_access mba
                  ON mba.manager_key = m.manager_key
                WHERE COALESCE(m.status,'')='active'
                  AND COALESCE(m.is_enabled,0)=1
                  AND COALESCE(m.manual_stopped,0)=0
                  AND COALESCE(m.role,'manager')!='closer'
                GROUP BY m.manager_key
                ORDER BY m.manager_key
            """).fetchall()
        finally:
            con.close()
    except Exception as exc:
        print(f"m26f2 manager list failed: {exc!r}")
        manager_rows = []

    for r in manager_rows:
        d = dict(r)
        key = normalize_manager_key(d.get("manager_key") or "")
        if not key:
            continue
        label = str(d.get("display_name") or key).strip()
        active_count = int(d.get("active_count") or 0)
        access_count = int(d.get("access_count") or 0)
        text = f"\U0001f916 {label} | {active_count}/{access_count}"
        if len(text) > 42:
            text = text[:39] + "..."
        buttons.append([Button.inline(text, f"menu:mbaccess:{key}".encode("utf-8"))])

    # N5.3 (D2): Back -> canonical \u041c\u0435\u043d\u0435\u0434\u0436\u0435\u0440\u044b section, not the retired
    # old-menu category managers_modes.
    buttons.append([Button.inline("\u2b05\ufe0f \u041d\u0430\u0437\u0430\u0434", b"menu:nm_managers")])
    buttons.append([Button.inline("\U0001f3e0 \u0413\u043b\u0430\u0432\u043d\u0430\u044f \u043f\u0430\u043d\u0435\u043b\u044c", b"menu:main")])
    return buttons

# --- TPILOT M2.6F.2 MANAGERBOT ENTRY FIX END ---

_M26F_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu):  # type: ignore[override]
    raw = str(menu or "main")
    try:
        if raw == "mbaccess_all":
            return _mbaccess_all_text(), _mbaccess_all_buttons()

        if raw.startswith("mbauser:"):
            _, key, uid = raw.split(":", 2)
            key = normalize_manager_key(key)
            return _mbauser_text(key, int(uid)), _mbauser_buttons(key, int(uid))

        if raw.startswith("mbaccess:"):
            key = normalize_manager_key(raw.split(":", 1)[1])
            return _mbaccess_text(key), _mbaccess_buttons(key)
    except Exception as exc:
        return _safe_text(f"ManagerBot access menu error: {exc!r}"), [
            [Button.inline("\U0001f3e0 \u0413\u043b\u0430\u0432\u043d\u0430\u044f", b"menu:main")]
        ]

    if callable(_M26F_PREV_TITLE_FOR_MENU):
        return _M26F_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


@client.on(events.CallbackQuery)
async def _m26f_mba_callback(event):
    try:
        if not _is_allowed(event):
            return

        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("mba:"):
            return

        parts = data.split(":")
        if len(parts) < 4:
            await _pb_safe_answer(event, "\u041d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)
            return

        action = parts[1]
        admin_id = int(getattr(event, "sender_id", 0) or 0)

        if action == "tg":
            if len(parts) != 5:
                await _pb_safe_answer(event, "\u041d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)
                return
            code = parts[2]
            key = normalize_manager_key(parts[3])
            uid = int(parts[4])
            ok = _mba_toggle(uid, key, code)
            text, buttons = _title_for_menu(f"mbauser:{key}:{uid}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, "\u0413\u043e\u0442\u043e\u0432\u043e" if ok else "\u041e\u0448\u0438\u0431\u043a\u0430", alert=not ok)
            return

        if action == "fmt":
            if len(parts) != 4:
                await _pb_safe_answer(event, "\u041d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)
                return
            key = normalize_manager_key(parts[2])
            uid = int(parts[3])
            ok = _mba_cycle_format(uid, key)
            text, buttons = _title_for_menu(f"mbauser:{key}:{uid}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, "\u0413\u043e\u0442\u043e\u0432\u043e" if ok else "\u041e\u0448\u0438\u0431\u043a\u0430", alert=not ok)
            return

        if action in ("rev", "unrev"):
            if len(parts) != 4:
                await _pb_safe_answer(event, "\u041d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)
                return
            key = normalize_manager_key(parts[2])
            uid = int(parts[3])
            ok = _mba_set_revoked(uid, key, 1 if action == "rev" else 0, admin_id)
            text, buttons = _title_for_menu(f"mbauser:{key}:{uid}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, "\u0413\u043e\u0442\u043e\u0432\u043e" if ok else "\u041e\u0448\u0438\u0431\u043a\u0430", alert=not ok)
            return

        if action in ("areq", "dreq"):
            if len(parts) != 4:
                await _pb_safe_answer(event, "\u041d\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)
                return
            key = normalize_manager_key(parts[2])
            uid = int(parts[3])

            if action == "areq":
                req = _mba_request_by_id(uid)
                if not req or str(req.get("status") or "") != "new":
                    await _pb_safe_answer(event, "\u0417\u0430\u044f\u0432\u043a\u0430 \u0443\u0436\u0435 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u0430", alert=True)
                    return
                ok = _mba_approve(uid, key, admin_id)
                answer = "\u2705 \u0414\u043e\u0441\u0442\u0443\u043f \u0432\u044b\u0434\u0430\u043d"
            else:
                ok = _mba_deny(uid)
                answer = "\U0001f6ab \u0417\u0430\u044f\u0432\u043a\u0430 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0430"

            text, buttons = _title_for_menu(f"mbaccess:{key}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, answer if ok else "\u041e\u0448\u0438\u0431\u043a\u0430", alert=not ok)
            return

        await _pb_safe_answer(event, "\u041d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u043a\u043e\u043c\u0430\u043d\u0434\u0430", alert=True)

    except Exception as exc:
        print(f"m26f mba callback failed: {exc!r}")
        try:
            await _pb_safe_answer(event, "\u041e\u0448\u0438\u0431\u043a\u0430 ManagerBot access", alert=True)
        except Exception:
            pass

