def _manager_settings_state(row):
    # N2 (unified manager card, approved 2026-07-21): canonical 3-state status
    # wording. Only 3 callers of this helper exist, all in this same block
    # (list badge extraction, card text, card buttons) -- safe to change the
    # label text directly (nothing outside this file/block pattern-matches it).
    # NOTE (N5.4.2): this stays a SEPARATE, untouched helper -- it feeds
    # LIFECYCLE BUTTON selection (start vs disable-confirm), not the new
    # display-only status resolver above (_pb_manager_status_resolve).
    enabled = int((row or {}).get("is_enabled") or 0) == 1
    stopped = int((row or {}).get("manual_stopped") or 0) == 1
    status = str((row or {}).get("status") or "").strip().lower()
    if stopped:
        return "stopped", "🟡 Остановлен вручную"
    if enabled and status != "disabled":
        return "on", "🟢 Работает"
    return "off", "🔴 Выключен"


def _mcard_btn(label: str, data: str):
    """Button.inline with a defensive 64-byte guard for the unified manager
    card (N2) -- same pattern as the NM block's _nm_btn (Phase N1). Every
    manager-card callback here carries only a manager_key or a numeric
    managers.id, never a secret, so falling back to the card itself on an
    oversized encode is always safe."""
    raw = str(data or "menu:manager_settings").encode("utf-8")
    if len(raw) > 64:
        raw = b"menu:manager_settings"
    return Button.inline(label, raw)


def _manager_settings_text():
    # N5.3 (Part B): this is now THE canonical manager list.
    # N5.4.2 (owner decision D, fixes the 15≠12+2+0 defect): counters now
    # come from the shared deterministic status resolver instead of the
    # three ad-hoc predicates that used to leave a real gap (any manager
    # with is_enabled=1, manual_stopped=0 and status NOT IN {'active',
    # 'disabled'} -- e.g. status='new', onboarding -- fell into none of the
    # three old buckets while still showing 🟢 in the list). The resolver
    # assigns EXACTLY one category per manager, so sum(counts) == len(visible)
    # by construction -- verified by tools\manager_status_resolver_selftest.py.
    rows = _manager_rows_all()
    visible = [dict(r) for r in rows if str(dict(r).get("status") or "").lower() != "archived"]
    counts = {key: 0 for key in _PB_STATUS_CATEGORIES}
    # W1 (D-26, I-25): one operation_id shared by every row of THIS render,
    # so the structured log can be replayed as one screen, not N unrelated
    # events. _pb_manager_status_resolve_live_logged returns the identical
    # (cat, icon, label) _pb_manager_status_resolve_live always returned --
    # see the parity selftest -- this call is additive only.
    _w1_render_op_id = uuid.uuid4().hex[:12]
    # PEERFLOOD RECOVERY 20260812 (P2): Telegram Health is tracked as a
    # SEPARATE signal from the runtime category above (see the P1 fix in
    # _pb_manager_status_resolve) -- tallied independently here so a LIMITED
    # manager (who now stays in the 'ok'/active count, not 'warning') is
    # still visible in a dedicated summary line.
    tg_limited_count = 0
    for d in visible:
        cat, _icon, _label = _pb_manager_status_resolve_live_logged(d, operation_id=_w1_render_op_id)
        counts[cat] = counts.get(cat, 0) + 1
        key = normalize_manager_key(d.get("manager_key") or "")
        th_status = str(_pb_tg_health_row(key).get("health_status") or "").strip().lower()
        if th_status == "limited":
            tg_limited_count += 1
    counter_line = " · ".join(
        f"{_PB_STATUS_CATEGORIES[key][0]} {_PB_STATUS_CATEGORIES[key][1]}: {counts[key]}"
        for key in _PB_STATUS_CATEGORIES if counts.get(key)
    ) or "Нет данных"
    body_lines = [
        "Выберите менеджера — карточка со статусом, скринами, доступами, заменой, "
        "резервом и опасными действиями.",
        "",
        f"Менеджеров: {len(visible)}",
        counter_line,
    ]
    if tg_limited_count:
        body_lines.append(f"⚠️ Ограничение Telegram: {tg_limited_count}")
    body = "\n".join(body_lines)
    return _tp_visual_screen(["Главная", "Менеджеры", "Список менеджеров"], body)


def _manager_settings_buttons():
    # N5.4.2 (owner decision, format §3): every row now renders
    # «<статус-иконка> <имя> / @username» (or «... / username не указан»
    # when the manager has no Telegram username on record), using the
    # shared resolver's icon instead of the old configuration-only badge
    # (which could show 🟢 for a manager whose process was not actually
    # running or whose Telegram session was not authorized).
    rows = _manager_rows_all()
    buttons = []
    # TPILOT PREP BUTTON MANAGER LIST 20260811: second UI entry point into
    # the EXISTING prep:menu screen (features/prepared_accounts, unchanged),
    # first row, before any manager button -- same callback as the
    # pre-existing entry in _manager_admin_menu (panel_bot.py:2160), no new
    # handler/logic. Literal (not _prepared_texts.SECTION_LABEL) -- this
    # function is AST-extracted by exact name into an isolated namespace by
    # tools/manager_card_unified_selftest.py (CARD_NAMES), which does not
    # inject the _prepared_texts module; text verified byte-identical to
    # SECTION_LABEL by the panel selftest (check 1c3).
    buttons.append([Button.inline("💾Подготовленные аккаунты", b"prep:menu")])
    # W1 (D-26, I-25): see _manager_settings_text above for the rationale --
    # same additive, parity-proven wrapper, one operation_id per render.
    _w1_render_op_id = uuid.uuid4().hex[:12]
    for r in rows:
        d = dict(r)
        if str(d.get("status") or "").lower() == "archived":
            continue
        key = normalize_manager_key(d.get("manager_key") or "")
        if not key:
            continue
        # PEERFLOOD RECOVERY 20260812 (P2): badged variant -- same (cat, icon,
        # label) as _pb_manager_status_resolve_live_logged, plus a separate
        # Telegram Health badge. The badge is placed directly after the icon
        # (before the name) so it is never eaten by the 42-char truncation
        # below.
        _cat, icon, _label, badge = _pb_manager_status_resolve_live_badged(d, operation_id=_w1_render_op_id)
        name = str(d.get("display_name") or key).strip()
        username = str(d.get("telegram_username") or "").strip().lstrip("@")
        uname_part = f"@{username}" if username else "username не указан"
        text = f"{icon}{badge} {name} / {uname_part}"
        if len(text) > 42:
            text = text[:39] + "..."
        buttons.append([Button.inline(text, f"menu:manager_settings:{key}".encode("utf-8"))])
    # N5.3 (Part C): the global "📷 Скрины (все)" entry moved to Отчёты (its
    # canonical owner) -- per-manager screenshots stay on the unified card.
    # N5.3 (D1): Back now returns to the canonical Менеджеры section
    # (menu:nm_managers), not the retired old-menu category managers_modes.
    buttons.append([Button.inline("⬅️ Назад", b"menu:nm_managers"), Button.inline("🏠 Главная", b"menu:main")])
    return buttons


def _manager_settings_card_text(key):
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    if not row:
        return _safe_text(f"Менеджер не найден: {key}")
    label = _manager_short_label(row)
    _, status_badge = _manager_settings_state(row)
    proxy = _manager_proxy_badge(row)
    cfg = _ss_config(key)
    mode_label = _SS_MODE_LABELS.get(cfg.get("mode") or "off", "Выкл")
    rem_badge = "🟢 Вкл" if cfg["reminder_enabled"] else "🔴 Выкл"
    exp_today, upl_today = _ss_counts_today(key)
    missing_today = max(0, exp_today - upl_today)
    body = "\n".join([
        f"Менеджер: {label}",
        f"Ключ: {key}",
        "",
        f"Статус: {status_badge}",
        f"Proxy: {proxy}",
        "",
        f"📸 Режим скринов: {mode_label}",
        f"🔔 Напоминания: {rem_badge}",
        f"⏰ Время напоминания: {cfg['reminder_time']}",
        f"📷 Сегодня: неликвидов {exp_today}, скрины {upl_today}, не хватает {missing_today}",
        "",
        "Замена аккаунта, вход на устройстве, резерв и опасные действия — в кнопках ниже.",
    ])
    return _tp_visual_screen(["Главная", "Менеджеры", "Карточка менеджера", label], body)


def _manager_settings_card_buttons(key):
    # N2 (approved unified-manager-card migration, 2026-07-21): this is now
    # the ONE canonical manager card, reached both via menu:manager_settings:
    # and (redirected) via menu:manager_admin:. It reuses every underlying
    # business flow verbatim (ssc:/mbaccess/proxy/transfer/rw:/relogin:/
    # devlogin:/reserve/guard:) -- nothing below duplicates logic that
    # already lives elsewhere; every button is a link into an existing flow.
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    if not row:
        return [
            [Button.inline("⬅️ Назад", b"menu:manager_settings")],
            [Button.inline("🏠 Главная", b"menu:main")],
        ]
    state, _status_badge = _manager_settings_state(row)
    if state == "on":
        # Disabling is confirm-gated (see _manager_disable_confirm_*); the
        # actual command is unchanged -- /manager_disable.
        toggle = _mcard_btn("⏸ Выключить менеджера", f"menu:manager_disable_confirm:{key}")
    else:
        # Reuses /manager_start (NOT /manager_enable, which never spawns the
        # runtime process -- this was the old settings-card bug: "включён"
        # in the DB but no process actually running).
        toggle = _mcard_btn("▶️ Включить менеджера", f"cmd:/manager_start {key}")
    cfg = _ss_config(key)
    mode_label = _SS_MODE_LABELS.get(cfg.get("mode") or "off", "Выкл")
    rem_badge = "🟢 Вкл" if cfg["reminder_enabled"] else "🔴 Выкл"
    # --- N5.3 (Part D): professional row ordering. Same buttons/callbacks/
    # semantics as N2/N2.1 (nothing added or removed, /manager_start-not-
    # enable and the confirm-gated disable preserved verbatim) -- only the
    # ORDER changed per the owner's UX decision: info + light daily actions
    # first, screenshots block, links to canonical flows, account
    # maintenance, then lifecycle and destructive actions at the BOTTOM.
    rows = [
        # 1. Info + frequent light action
        # N5.4.3 (owner decision B): «Полная карточка» now opens the native
        # menu:manager_full screen, not the background cmd:/manager_info
        # command queue. /manager_info remains a historical text command
        # (main.py untouched), just no longer wired to this button.
        [_mcard_btn("📄 Полная карточка", f"menu:manager_full:{key}"), _mcard_btn("✏️ Переименовать", f"wiz:rename_manager:{key}")],
        # 2-4. Daily screenshot block (short, closely related)
        [_mcard_btn(f"📸 Режим: {mode_label}", f"ssc:mode:{key}"), _mcard_btn(f"🔔 Напоминания: {rem_badge}", f"ssc:rem:{key}")],
        [_mcard_btn(f"⏰ Время: {cfg['reminder_time']}", f"ssc:time:{key}"), _mcard_btn("📷 Скрины", f"ssc:view:{key}")],
        [_mcard_btn("🔄 Обновить скрины", f"ssc:refresh:{key}")],
        # 5. Manager automation/modes -- clearly named task screen (renamed
        # from «💬 Автоответы и график» so it no longer competes with the
        # general manager settings; same route menu:manager:{key}).
        [_mcard_btn("🤖 Автоматизация менеджера", f"menu:manager:{key}")],
        # 6-7. Access + links to canonical flows (no copied business logic)
        [_mcard_btn("🤖 Доступ ManagerBot", f"menu:mbaccess:{key}")],
        [_mcard_btn("🌐 Proxy менеджера", f"menu:proxy:{key}"), _mcard_btn("🤝 Передачи", f"menu:transfer_mgr:{key}")],
        # 8. Reserve (account maintenance group starts)
        [_mcard_btn("🧩 Резерв", f"menu:reserve_admin:{key}")],
    ]
    status = str((row or {}).get("status") or "").strip().lower()
    if status not in ("archived", "deleted"):
        # Same guard the old admin card used for relogin/replace/devlogin:
        # never offered for an archived/deleted/missing manager row.
        active_op = _replace_active_op_for_old_key(key)
        if active_op:
            rows.append([_mcard_btn("🔄 Продолжить замену", f"rw:recover:{key}")])
        else:
            rows.append([_mcard_btn("🔄 Заменить аккаунт", f"rw:start:{key}")])
        manager_id = row.get("id")
        if manager_id is not None:
            # Numeric managers.id, not the raw key -- same 64-byte-safe
            # index pattern the devlogin block already established. Label
            # shortened (N5.3) so it pairs with «Перезайти» on one row.
            rows.append([_mcard_btn("🔐 Перезайти", f"relogin:start:{key}"), _mcard_btn("🔐 Вход на устройстве", f"devlogin:start:{int(manager_id)}")])
        else:
            rows.append([_mcard_btn("🔐 Перезайти", f"relogin:start:{key}")])
    # Lifecycle -- near the bottom (owner decision), semantics untouched.
    rows.append([toggle])
    rows.append([_mcard_btn("🔄 Перезапустить", f"cmd:/manager_restart {key}")])
    # Destructive -- last.
    rows.append([_mcard_btn("🧨 Опасные действия", f"menu:manager_danger:{key}")])
    rows.append([Button.inline("⬅️ Назад", b"menu:manager_settings"), _mcard_btn("🔄 Обновить", f"menu:manager_settings:{key}")])
    rows.append([Button.inline("🏠 Главная", b"menu:main")])
    return rows


def _manager_disable_confirm_text(key: str) -> str:
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    if not row:
        return _safe_text(f"Менеджер не найден: {key}")
    label = _manager_short_label(row)
    state, status_badge = _manager_settings_state(row)
    if state != "on":
        # Stale-state revalidation: the card the admin saw when pressing
        # "Выключить" is out of date (someone/something already changed the
        # state) -- do not offer a duplicate disable action, just say so.
        return "\n".join([
            f"ℹ️ Менеджер {label} уже не работает.",
            f"Текущий статус: {status_badge}.",
            "",
            "Выключать нечего — карточка ниже уже актуальна.",
        ])
    return "\n".join([
        f"⚠️ Выключить менеджера {label}?",
        "",
        "Он перестанет отвечать клиентам и не будет запускаться автоматически,",
        "пока вы не включите его снова.",
    ])


def _manager_disable_confirm_buttons(key: str) -> list:
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    state, _status_badge = _manager_settings_state(row) if row else ("off", "")
    if state != "on":
        # No-op: re-render the (already up to date) card instead of a
        # confirm prompt for an action that no longer applies.
        return _manager_settings_card_buttons(key)
    return [
        [_mcard_btn("✅ Подтвердить, выключить", f"cmd:/manager_disable {key}")],
        [_mcard_btn("❌ Отмена", f"menu:manager_settings:{key}")],
    ]


def _manager_danger_zone_text(key: str) -> str:
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    label = _manager_short_label(row) if row else key
    return "\n".join([
        f"🧨 Опасные действия — {label}",
        "",
        "Все действия ниже необратимы или требуют пароль администратора и",
        "обязательный backup. Выбирайте внимательно.",
    ])


def _manager_danger_zone_buttons(key: str) -> list:
    # Exact same guard: callbacks the old admin card used inline -- the
    # danger_password wizard and every downstream flow are unchanged, only
    # the entry point moved off the main card into this one dedicated screen.
    key = normalize_manager_key(key or "")
    return [
        [_mcard_btn("🧹 Очистить базу", f"guard:db_clear:{key}"), _mcard_btn("🔄 Сбросить авторизацию", f"guard:reset:{key}")],
        [_mcard_btn("🗑 Полное удаление", f"guard:delete:{key}")],
        [_mcard_btn("♻️ Восстановить последний backup", f"guard:restore_db:{key}"), Button.inline("🧾 Журнал", b"cmd:/manager_danger_log")],
        [_mcard_btn("⬅️ Назад к карточке", f"menu:manager_settings:{key}")],
        [Button.inline("🏠 Главная", b"menu:main")],
    ]


_MS_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu):  # type: ignore[override]
    raw = str(menu or "main")
    try:
        if raw == "manager_settings":
            return _manager_settings_text(), _manager_settings_buttons()
        if raw.startswith("manager_settings:"):
            key = normalize_manager_key(raw.split(":", 1)[1])
            return _manager_settings_card_text(key), _manager_settings_card_buttons(key)
        if raw.startswith("manager_disable_confirm:"):
            key = normalize_manager_key(raw.split(":", 1)[1])
            return _manager_disable_confirm_text(key), _manager_disable_confirm_buttons(key)
        if raw.startswith("manager_danger:"):
            key = normalize_manager_key(raw.split(":", 1)[1])
            return _manager_danger_zone_text(key), _manager_danger_zone_buttons(key)
        if raw.startswith("manager_full:"):
            # N5.4.3 (owner decision B): native full-card screen -- renders
            # immediately from existing safe read-only helpers, no cmd:
            # background-command round-trip.
            parts = raw.split(":")
            key = normalize_manager_key(parts[1] if len(parts) >= 2 else "")
            page = int(parts[2]) if len(parts) >= 3 and str(parts[2]).isdigit() else 1
            return _pb_manager_full_card_text(key, page), _pb_manager_full_card_buttons(key, page)
    except Exception as exc:
        return _safe_text(f"Manager settings menu error: {exc!r}"), [
            [Button.inline("🏠 Главная", b"menu:main")]
        ]
    if callable(_MS_PREV_TITLE_FOR_MENU):
        return _MS_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []

