@client.on(events.CallbackQuery)
async def _ss_config_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("ssc:") and not data.startswith("ssr:"):
            return
        parts = data.split(":")
        prefix = parts[0]
        action = parts[1] if len(parts) > 1 else ""
        key = normalize_manager_key(parts[2]) if len(parts) > 2 else ""

        # --- ssr: refresh commands ---
        if prefix == "ssr":
            if action == "one":
                if not key:
                    await _pb_safe_answer(event, "Пустой ключ", alert=True)
                    return
                result = _ss_admin_refresh(key)
                await _pb_safe_answer(event, result)
                text, buttons = _title_for_menu(f"manager_settings:{key}")
                await _safe_event_edit(event, text, buttons=buttons)
                return
            if action == "all":
                rows = _manager_rows_all()
                total = 0
                for r in rows:
                    mk2 = normalize_manager_key(dict(r).get("manager_key") or "")
                    if mk2:
                        _ss_admin_refresh(mk2)
                        total += 1
                await _pb_safe_answer(event, f"Обновлено менеджеров: {total}")
                return
            if action == "src":
                sk = parts[2] if len(parts) > 2 else ""
                if not sk:
                    await _pb_safe_answer(event, "Пустой источник", alert=True)
                    return
                con = _connect_panel_db()
                try:
                    mk_rows = con.execute("SELECT manager_key FROM manager_source_links WHERE source_key=?", (sk,)).fetchall()
                except Exception:
                    mk_rows = []
                finally:
                    con.close()
                total = 0
                for r in (mk_rows or []):
                    mk2 = normalize_manager_key(r[0] or "")
                    if mk2:
                        _ss_admin_refresh(mk2)
                        total += 1
                await _pb_safe_answer(event, f"Обновлено источник {sk}: {total}")
                return
            await _pb_safe_answer(event, )
            return

        # --- ssc: config commands ---
        if not key:
            await _pb_safe_answer(event, "Пустой ключ", alert=True)
            return
        if action == "mode":
            cfg = _ss_config(key)
            cur_mode = cfg.get("mode") or "off"
            new_mode = _SS_MODE_CYCLE.get(cur_mode, "off")
            _ss_config_set(key, mode=new_mode)
            await _pb_safe_answer(event, f"Режим: {_SS_MODE_LABELS.get(new_mode, new_mode)}")
        elif action == "rem":
            cfg = _ss_config(key)
            _ss_config_set(key, mode=cfg.get("mode", "off"), reminder_enabled=0 if cfg["reminder_enabled"] else 1)
            await _pb_safe_answer(event, "Готово")
        elif action == "time":
            _wizard_set(int(event.chat_id or 0), int(event.sender_id or 0), "ss_remtime", "time", {"key": key})
            await _pb_safe_answer(event, )
            await event.respond("Введите время напоминания в формате ЧЧ:ММ (например 16:50)", buttons=_back_to_panel_buttons())
            return
        elif action == "view":
            await _pb_safe_answer(event, )
            text, buttons = _ssv_date_list_text_and_buttons(key)
            await _safe_event_edit(event, text, buttons=buttons)
            return
        elif action == "refresh":
            result = _ss_admin_refresh(key)
            await _pb_safe_answer(event, result)
        else:
            await _pb_safe_answer(event, )
            return
        text, buttons = _title_for_menu(f"manager_settings:{key}")
        await _safe_event_edit(event, text, buttons=buttons)
    except Exception as exc:
        print(f"ss config callback failed: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка скрин-настроек", alert=True)
        except Exception:
            pass


