def _parse_source_window_range(raw: str):
    """Parse 'HH:MM-HH:MM' (optional single-digit hour, optional spaces/dash variants).

    Returns (start_min, end_min, normalized_text) on a format match, or None otherwise.
    Does not validate start < end - callers check that separately for a distinct message.
    """
    text = str(raw or "").strip()
    m = re.match(r"^([01]?\d|2[0-3]):([0-5]\d)\s*[-–—]\s*([01]?\d|2[0-3]):([0-5]\d)$", text)
    if not m:
        return None
    sh, sm, eh, em = int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))
    start_min = sh * 60 + sm
    end_min = eh * 60 + em
    normalized = f"{sh:02d}:{sm:02d}-{eh:02d}:{em:02d}"
    return start_min, end_min, normalized


