def _reserve_admin_text(primary_key: str) -> str:
    pk = normalize_manager_key(primary_key or "")
    row = _manager_row_by_key(pk)
    label = _manager_short_label(row) if row else pk
    lines = ["🧩 Резервные аккаунты", "", f"Основной: {label}"]
    source_key = ""
    try:
        source_key = _source_links_map_sync().get(pk, "")
    except Exception:
        source_key = ""
    if source_key:
        lines.append(f"Источник: {source_key}")
    pairs = []
    try:
        pairs = _rsv_pair_list_for_primary(pk, db_path=TPILOT_DB_PATH)
    except Exception:
        pairs = []
    linked = [p for p in pairs if str(p.get("status") or "") == "linked"]
    lines.append("")
