def _reserve_pick_text(primary_key: str) -> str:
    return "🧩 Выберите уже онбордингованного менеджера для привязки в качестве резерва:"


def _reserve_pick_buttons(primary_key: str):
    pk = normalize_manager_key(primary_key or "")
    links_map = {}
    try:
        links_map = _source_links_map_sync()
    except Exception:
        links_map = {}
    source_key = links_map.get(pk, "")
    reserved_keys = set()
    try:
        con = sqlite3.connect(TPILOT_DB_PATH, timeout=30)
        try:
            pair_rows = con.execute(
                "SELECT reserve_key, primary_key FROM manager_reserve_pairs WHERE status='linked'"
            ).fetchall()
            # RESERVE RELEASE 2026-07-11: a 'linked' pair blocks its reserve ONLY while the
            # paired primary still EXISTS in the authoritative managers registry -- any
            # status/role counts (archived and closer rows still exist; /manager_delete_full
            # does a hard DELETE, so existence == row present). A pair whose primary row was
            # fully deleted is an orphan and must not hide the reserve from this picker.
            # If the managers lookup fails, fall back to the pre-patch behavior (exclude
            # every linked reserve) -- conservative, never risks a double attachment.
            try:
                existing_manager_keys = {
                    normalize_manager_key(r[0] or "")
                    for r in con.execute("SELECT manager_key FROM managers").fetchall()
                }
                reserved_keys = {
                    normalize_manager_key(r[0] or "")
                    for r in pair_rows or []
                    if normalize_manager_key(r[1] or "") in existing_manager_keys
                }
            except Exception:
                reserved_keys = {normalize_manager_key(r[0] or "") for r in pair_rows or []}
        finally:
            con.close()
    except Exception:
        reserved_keys = set()
    candidates = []
    for r in _manager_rows_all():
        key = normalize_manager_key(r.get("manager_key") or "")
        if not key or key == pk or key in reserved_keys:
            continue
        candidates.append(r)
    if source_key:
        candidates.sort(
            key=lambda r: 0 if links_map.get(normalize_manager_key(r.get("manager_key") or ""), "") == source_key else 1
        )
    rows_out = []
    for r in candidates[:50]:
        key = normalize_manager_key(r.get("manager_key") or "")
        label = _manager_short_label(r)
        rows_out.append([Button.inline(f"➕ {label}", f"rsv:pair:{pk}:{key}".encode())])
    if not rows_out:
        rows_out.append([Button.inline("Нет доступных менеджеров", f"menu:reserve_admin:{pk}".encode())])
    rows_out.append([Button.inline("⬅️ Назад", f"menu:reserve_admin:{pk}".encode())])
    rows_out.append([Button.inline("🏠 Главная панель", b"menu:main")])
    return rows_out


def _rsv_ensure_source_link(reserve_key: str, source_key: str) -> None:
    """Minimal direct write mirroring the existing manager_source_links schema
    (manager_key TEXT PRIMARY KEY, source_key, created_at, updated_at) — panel_bot.py
    has no existing write helper for this table (only read helpers), so this matches
    the schema directly rather than inventing a new shared helper."""
    rk = normalize_manager_key(reserve_key or "")
    sk = str(source_key or "").strip()
    if not rk or not sk:
        return
    now = _utc_now_iso()
    con = _connect_panel_db()
    try:
        existing = con.execute(
            "SELECT created_at FROM manager_source_links WHERE manager_key=?", (rk,)
        ).fetchone()
        created_at = str(existing[0]) if existing and existing[0] else now
        con.execute(
            "INSERT OR REPLACE INTO manager_source_links(manager_key, source_key, created_at, updated_at) "
            "VALUES(?,?,?,?)",
            (rk, sk, created_at, now),
        )
        con.commit()
    finally:
        con.close()


