async def _ssv_send_files(event, date_iso: str, manager_key: str) -> None:
    """Send screenshot files for the given date (optionally manager-filtered)."""
    mk = _ssv_norm_key(manager_key)
    rows = _ssv_rows_for_date(date_iso, mk)
    label = _ssv_date_label(date_iso)
    if not rows:
        await _pb_safe_answer(event, "Файлов не найдено", alert=True)
        return
    if len(rows) > _SSV_MAX_SHOW:
        await _pb_safe_answer(event, f"Файлов: {len(rows)} — используйте ZIP", alert=True)
        return
    await _pb_safe_answer(event, )
    cid = int(event.chat_id or 0)
    sent = 0
    for row in rows:
        path = str(row.get("screenshot_path") or "")
        if not path or not _ssv_path_is_safe(path) or not os.path.exists(path):
            continue
        row_mk = str(row.get("manager_key") or "")
        rid = int(row.get("id") or 0)
        try:
            await client.send_file(cid, path, caption=f"📷 {label} | {row_mk} | #{rid}")
            sent += 1
        except Exception as exc:
            print(f"ssv send file error row_id={rid}: {exc!r}")
    if sent == 0:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, no recovery.
        await client.send_message(cid, "❌ Файлы не найдены или удалены", buttons=_terminal_ok_button())


def _ssv_create_zip(date_iso: str, manager_key: str) -> str:
    """Create a ZIP archive of screenshots for the given date/manager.
    Returns the ZIP file path. Raises RuntimeError if no files found."""
    import zipfile
    mk = _ssv_norm_key(manager_key)
    rows = _ssv_rows_for_date(date_iso, mk)
    if not rows:
        raise RuntimeError("Файлов не найдено")
    _SSV_EXPORT_ROOT.mkdir(parents=True, exist_ok=True)
    mk_part = f"_{mk}" if mk else "_all"
    zip_name = f"screenshots_admin_{date_iso}{mk_part}.zip"
    zip_path = _SSV_EXPORT_ROOT / zip_name
    added = 0
    with zipfile.ZipFile(str(zip_path), "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for i, row in enumerate(rows, 1):
            path = str(row.get("screenshot_path") or "")
            if not path or not _ssv_path_is_safe(path) or not os.path.exists(path):
                continue
            ext = Path(path).suffix.lower() or ".jpg"
            mk_safe = _ssv_norm_key(str(row.get("manager_key") or "unknown"))
            arcname = f"{mk_safe}_{i:04d}{ext}"
            zf.write(path, arcname)
            added += 1
    if added == 0:
        try:
            os.remove(str(zip_path))
        except Exception:
            pass
        raise RuntimeError("Все файлы удалены или недоступны")
    return str(zip_path)


@client.on(events.CallbackQuery)
async def _ssv_callback(event):
    """AdminBot date-based screenshot viewer callback handler (ssv: prefix)."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("ssv:"):
            return
        parts = data.split(":")
        action = parts[1] if len(parts) > 1 else ""

        if action == "dates":
            manager_filter = _ssv_norm_key(parts[2] if len(parts) > 2 else "")
            text, buttons = _ssv_date_list_text_and_buttons(manager_filter)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, text, buttons=buttons)
            return

        if action == "date":
            date_iso = parts[2] if len(parts) > 2 else ""
            manager_filter = _ssv_norm_key(parts[3] if len(parts) > 3 else "")
            if not date_iso:
                await _pb_safe_answer(event, "Пустая дата", alert=True)
                return
            text, buttons = _ssv_date_detail_text_and_buttons(date_iso, manager_filter)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, text, buttons=buttons)
            return

        if action == "mgr":
            date_iso = parts[2] if len(parts) > 2 else ""
            mk = _ssv_norm_key(parts[3] if len(parts) > 3 else "")
            if not date_iso or not mk:
                await _pb_safe_answer(event, "Ошибка параметров", alert=True)
                return
            text, buttons = _ssv_manager_detail_text_and_buttons(date_iso, mk)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, text, buttons=buttons)
            return

        if action == "show":
            date_iso = parts[2] if len(parts) > 2 else ""
            mk_raw = parts[3] if len(parts) > 3 else "all"
            if not date_iso:
                await _pb_safe_answer(event, "Пустая дата", alert=True)
                return
            manager_key = "" if mk_raw == "all" else _ssv_norm_key(mk_raw)
            await _ssv_send_files(event, date_iso, manager_key)
            return

        if action == "zip":
            date_iso = parts[2] if len(parts) > 2 else ""
            mk_raw = parts[3] if len(parts) > 3 else "all"
            if not date_iso:
                await _pb_safe_answer(event, "Пустая дата", alert=True)
                return
            manager_key = "" if mk_raw == "all" else _ssv_norm_key(mk_raw)
            await _pb_safe_answer(event, "Создаю ZIP...")
            cid = int(event.chat_id or 0)
            zip_path = None
            try:
                zip_path = _ssv_create_zip(date_iso, manager_key)
                label = _ssv_date_label(date_iso)
                caption = f"📦 Скрины {label}" + (f" | {manager_key}" if manager_key else " | все")
                # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): file
                # delivered -- terminal.
                await client.send_file(cid, zip_path, caption=caption, buttons=_terminal_ok_button())
            except RuntimeError as exc:
                await client.send_message(cid, f"❌ {exc}", buttons=_terminal_ok_button())
            except Exception as exc:
                print(f"ssv zip error date={date_iso}: {exc!r}")
                await client.send_message(cid, "❌ Ошибка создания ZIP", buttons=_terminal_ok_button())
            finally:
                if zip_path:
                    try:
                        if os.path.exists(zip_path):
                            os.remove(zip_path)
                    except Exception as exc:
                        print(f"ssv zip cleanup warning: {exc!r}")
            return

        await _pb_safe_answer(event, )
    except Exception as exc:
        print(f"ssv callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass
# --- TPILOT M2.9B1 ADMIN SCREENSHOT VIEWER END ---


