# Restart button + runtime-status display for the per-manager AdminBot card.
# /manager_restart dispatched via existing panel command bridge.

def _m212a_read_start_status(manager_key: str) -> dict:
    """Read runtime/managers/{key}/start_status.json; return {} on any error."""
    try:
        mk = str(manager_key or "").strip().lower()
        if not mk:
            return {}
        path = BASE_DIR / "runtime" / "managers" / mk / "start_status.json"
        if not path.is_file():
            return {}
        data = json.loads(path.read_text(encoding="utf-8"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _m212a_runtime_fail_reason(reason_class: str) -> str:
    """Map reason_class to a short Russian label."""
    return {
        "proxy_timeout": "прокси timeout",
        "auth_session": "сессия/авторизация",
        "connection_error": "ошибка подключения",
        "process_exited": "процесс завершился",
        "unknown": "неизвестно",
    }.get(str(reason_class or "").strip().lower(), "неизвестно")


def _m212a_runtime_status_line(manager_key: str, row: dict) -> str:
    """Return a one-line Russian runtime status from start_status.json, or ''."""
    try:
        is_enabled = int((row or {}).get("is_enabled") or 0) == 1
        manual_stopped = int((row or {}).get("manual_stopped") or 0) == 1
        db_status = str((row or {}).get("status") or "").lower()
        if not is_enabled or manual_stopped or db_status != "active":
            return ""
        ss = _m212a_read_start_status(manager_key)
        if not ss:
            return ""
        phase = str(ss.get("phase") or "").strip()
        if phase == "running":
            return "Рантайм: 🟢 работает"
        if phase == "connected":
            return "Рантайм: 🟢 подключён"
        if phase == "starting":
            return "Рантайм: 🔄 запускается..."
        if phase == "exited":
            rc = str(ss.get("reason_class") or "unknown").strip()
            reason_label = _m212a_runtime_fail_reason(rc)
            err = str(ss.get("error") or "").strip()[:80]
            if err:
                return f"Рантайм: ⚠️ не запущен ({reason_label}) — {err}"
            return f"Рантайм: ⚠️ не запущен ({reason_label})"
    except Exception:
        pass
    return ""


_M212A_ORIG_ADMIN_DETAIL_TEXT = globals().get("_manager_admin_detail_text")


def _manager_admin_detail_text(row: dict) -> str:  # type: ignore[override]
    """M2.12A Stage1: append runtime status line to manager detail text."""
    base = _M212A_ORIG_ADMIN_DETAIL_TEXT(row) if callable(_M212A_ORIG_ADMIN_DETAIL_TEXT) else ""
    try:
        key = normalize_manager_key((row or {}).get("manager_key") or "")
        rt_line = _m212a_runtime_status_line(key, row)
        if rt_line:
            base = (base + "\n" + rt_line).rstrip()
    except Exception:
        pass
    return base


