async def _relogin_render_backend_result(event, chat_id: int, user_id: int, key: str, text: str) -> None:
    """Shared marker-parsing for the code/pass/confirm command results: renders the
    identity-mismatch confirm screen, the final success screen, or a plain error --
    exactly one of the three, matching whichever marker (if any) result_text carries."""
    key = normalize_manager_key(key or "")
    if _RELOGIN_IDENTITY_MISMATCH_MARKER in text:
        fields = _relogin_parse_marker_fields(text)
        row = _manager_row_by_key(key)
        _wizard_set(chat_id, user_id, "relogin", "identity_confirm", {"key": key})
        await client.send_message(chat_id, _safe_text(_relogin_mismatch_text(row, fields)), buttons=_relogin_mismatch_buttons(key))
        return
    if _RELOGIN_COMMIT_OK_MARKER in text:
        fields = _relogin_parse_marker_fields(text)
        _wizard_clear(chat_id, user_id)
        await client.send_message(chat_id, _safe_text(_relogin_done_text(key, fields)), buttons=_relogin_done_buttons(key))
        return
    if "Нужен пароль 2FA" in text:
        _wizard_set(chat_id, user_id, "relogin", "pass", {"key": key})
        await client.send_message(chat_id, _safe_text(text), buttons=_relogin_cancel_only_buttons(key))
        return
    # Any other result is a plain error -- wizard step is left as-is so retry (re-enter
    # phone/code) keeps working; Cancel is always offered as a way out.
    await client.send_message(chat_id, "⚠️ " + _safe_text(text or "Не удалось выполнить действие."), buttons=_relogin_cancel_only_buttons(key))


@client.on(events.CallbackQuery)
async def _relogin_callback(event):
    """AdminBot-only: '🔐 Перезайти' wizard. Every action re-validates the manager row
    (never trusts stale state) and every mutating step goes through main.py's
    /manager_relogin_* commands -- no Telethon auth logic lives in PanelBot."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("relogin:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        parts = data.split(":", 2)
        action = parts[1] if len(parts) > 1 else ""
        key = normalize_manager_key(parts[2] if len(parts) > 2 else "")
        if not key:
            await _pb_safe_answer(event, "Пустой manager_key", alert=True)
            return

        if action == "start":
            if _panel_callback_is_duplicate(chat_id, user_id, f"relogin:start:{key}"):
                await _pb_safe_answer(event, "Уже открыто...")
                return
            row = _manager_row_by_key(key)
            status = str((row or {}).get("status") or "").strip().lower()
            if not row or status in ("archived", "deleted"):
                await _pb_safe_answer(event, "Менеджер архивирован или не найден.", alert=True)
                return
            _wizard_set(chat_id, user_id, "relogin", "intro", {"key": key})
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _relogin_intro_text(row), buttons=_relogin_intro_buttons(key))
            return

        if action == "phone":
            row = _manager_row_by_key(key)
            status = str((row or {}).get("status") or "").strip().lower()
            if not row or status in ("archived", "deleted"):
                await _pb_safe_answer(event, "Менеджер архивирован или не найден.", alert=True)
                return
            _wizard_set(chat_id, user_id, "relogin", "phone", {"key": key})
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _relogin_phone_prompt_text(row), buttons=_relogin_cancel_only_buttons(key))
            return

        if action == "confirm_identity":
            if _panel_callback_is_duplicate(chat_id, user_id, f"relogin:confirm_identity:{key}"):
                await _pb_safe_answer(event, "Уже выполняю...")
                return
            wstate = _wizard_get(chat_id, user_id)
            if str(wstate.get("wizard") or "") != "relogin" or normalize_manager_key(str((wstate.get("payload") or {}).get("key") or "")) != key:
                await _pb_safe_answer(event, "Мастер сброшен, начните заново.", alert=True)
                return
            await _pb_safe_answer(event, "Заменяю сессию...")
            row = await _submit_and_wait(f"/manager_relogin_confirm {key}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _relogin_render_backend_result(event, chat_id, user_id, key, text or "Не удалось выполнить действие.")
            return

        if action == "cancel":
            await _pb_safe_answer(event, )
            row = await _submit_and_wait(f"/manager_relogin_cancel {key}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            _wizard_clear(chat_id, user_id)
            await _safe_event_edit(event, _safe_text(text or "Повторный вход отменён."), buttons=_relogin_error_buttons(key))
            return

        await _pb_safe_answer(event, )
    except Exception as exc:
        print(f"[relogin] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


@client.on(events.NewMessage)
async def _relogin_wizard_input(event):
    """Free-text steps of wizard='relogin' (phone / code / 2FA password). Gated on
    wizard name so it never interferes with any other wizard's own NewMessage handler."""
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if str(state.get("wizard") or "") != "relogin":
        return
    step = str(state.get("step") or "")
    payload = dict(state.get("payload") or {})
    key = normalize_manager_key(str(payload.get("key") or ""))
    if not key or step not in ("phone", "code", "pass"):
        return
    try:
        if step == "pass":
            try:
                await event.delete()
            except Exception:
                pass
        if step == "phone":
            row = await _submit_and_wait(f"/manager_relogin_phone {key} {raw}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            if text.startswith("✅ Код отправлен"):
                _wizard_set(chat_id, user_id, "relogin", "code", {"key": key})
                await client.send_message(chat_id, _safe_text(text), buttons=_relogin_cancel_only_buttons(key))
            else:
                await client.send_message(chat_id, "⚠️ " + _safe_text(text or "Не удалось отправить код."), buttons=_relogin_cancel_only_buttons(key))
            return
        if step == "code":
            row = await _submit_and_wait(f"/manager_relogin_code {key} {raw}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _relogin_render_backend_result(event, chat_id, user_id, key, text or "Не удалось выполнить действие.")
            return
        if step == "pass":
            row = await _submit_and_wait(f"/manager_relogin_pass {key} {raw}", user_id, chat_id, chat_id)
            text = str(row.get("result_text") or row.get("error_text") or "")
            await _relogin_render_backend_result(event, chat_id, user_id, key, text or "Не удалось выполнить действие.")
            return
    except Exception as exc:
        print(f"[relogin] wizard input error: {exc!r}")
        try:
            await client.send_message(chat_id, "⚠️ Ошибка обработки повторного входа.", buttons=_relogin_cancel_only_buttons(key))
        except Exception:
            pass

