# --- TPILOT MANAGER REPLACEMENT STAGE3 ADMINBOT 20260716 START ---
# AdminBot wizard for the fresh-session manager REPLACEMENT feature (Stage 2
# backend accepted 100%, 2026-07-15). Mirrors the relogin block's own
# architecture exactly: PanelBot and the controller are separate processes,
# so every mutating step goes through main.py's /manager_replace_* commands
# via _submit_and_wait; every command returns a JSON-encoded Stage 2 result
# dict (never Russian-text markers) that this file only ever branches on by
# ok/code/next_step, through the single _replace_message_for() mapping.
# Stops at ready_commit -- the final-confirm button is an explicit,
# no-mutation placeholder; no commit/cutover logic lives here or in main.py.

_RW_PREV_ADMIN_DETAIL_BUTTONS = globals().get("_manager_admin_detail_buttons")


def _manager_admin_detail_buttons(key: str):  # type: ignore[override]
    """Adds '🔄 Заменить аккаунт' (or '🔄 Продолжить замену' when a
    non-terminal replacement already exists for this manager) right after
    the relogin row -- ONLY for an existing, non-archived/non-deleted
    manager row, same guard as the relogin button. The button is visible to
    every admin (this panel has no per-manager ACL); actual continuation is
    still ownership-checked server-side by every /manager_replace_* command
    except start (Stage 3 forged/cross-admin-token safety)."""
    key = normalize_manager_key(key or "")
    rows = list(_RW_PREV_ADMIN_DETAIL_BUTTONS(key)) if callable(_RW_PREV_ADMIN_DETAIL_BUTTONS) else []
    row = _manager_row_by_key(key)
    status = str((row or {}).get("status") or "").strip().lower()
    if not row or status in ("archived", "deleted"):
        return rows
    active = _replace_active_op_for_old_key(key)
    if active:
        replace_row = [Button.inline("🔄 Продолжить замену", f"rw:recover:{key}".encode())]
    else:
        replace_row = [Button.inline("🔄 Заменить аккаунт", f"rw:start:{key}".encode())]
    # TPILOT DEVICE-LOGIN 20260719 (callback index-map fix): unlike
    # rw:start:<key>/pxm:*:<key> above (which embed the raw manager_key and
    # can in principle exceed Telegram's 64-byte callback_data limit for an
    # unusually long/Unicode key -- validate_manager_key does not bound
    # length), this button uses the project's existing "short numeric DB id
    # instead of a long string" index pattern (the SAME pattern proxy_leases/
    # proxy_pool callbacks already use: ppool:reveal:<lease_id>, never the
    # lease's own long fields). `row["id"]` is the managers table's own
    # INTEGER PRIMARY KEY -- always a handful of decimal digits regardless of
    # manager_key length, so "devlogin:start:<id>" is ALWAYS <=64 bytes and
    # NEVER silently omits the button. Resolved back to the exact
    # manager_key server-side by _manager_row_by_id in the devlogin: callback
    # handler (fails safely -- "not found" -- on a stale/unknown id).
    manager_id = (row or {}).get("id")
    extra_rows = [replace_row]
    if manager_id is not None:
        devlogin_cb = f"devlogin:start:{int(manager_id)}".encode()
        extra_rows.append([Button.inline("🔐 Подключить Telegram на устройстве", devlogin_cb)])
    for i, r in enumerate(rows):
        if any("Перезайти" in str(getattr(b, "text", "") or "") for b in r):
            return rows[:i + 1] + extra_rows + rows[i + 1:]
    if len(rows) >= 2:
        return rows[:-2] + extra_rows + rows[-2:]
    return rows + extra_rows


# ---------------------------------------------------------------------------
# Direct, read-only lookups against the shared DB (same convention as
# list_manager_rows_from_db_sync / _manager_row_by_key -- PanelBot reads
# shared tables directly, but every MUTATION still goes through
# panel_commands so only the controller process ever writes).
# ---------------------------------------------------------------------------

def _replace_active_op_for_old_key(old_key: str) -> dict:
    """Mirrors Stage 1's ux_repl_active_old semantics (excludes
    done/failed/cancelled). Never raises, never writes."""
    key = normalize_manager_key(old_key or "")
    if not key:
        return {}
    try:
        con = sqlite3.connect(TPILOT_DB_PATH, timeout=10)
        con.row_factory = sqlite3.Row
        cur = con.execute(
            "SELECT operation_id, status, created_by_user_id FROM manager_replacements"
            " WHERE old_manager_key=? AND status NOT IN ('done','failed','cancelled')"
            " ORDER BY id DESC LIMIT 1",
            (key,),
        )
        row = cur.fetchone()
        con.close()
        return dict(row) if row else {}
    except Exception:
        return {}


def _replace_read_op_row(operation_id: str) -> dict:
    """Read-only row fetch by operation_id -- used only to recover durable
    new_manager_key/new_display_name/proxy_ref for a phone-retry screen
    after a restart, when the transient wizard payload may be gone."""
    op = str(operation_id or "").strip()
    if not op:
        return {}
    try:
        con = sqlite3.connect(TPILOT_DB_PATH, timeout=10)
        con.row_factory = sqlite3.Row
        cur = con.execute("SELECT * FROM manager_replacements WHERE operation_id=? LIMIT 1", (op,))
        row = cur.fetchone()
        con.close()
        return dict(row) if row else {}
    except Exception:
        return {}


