def _replace_message_for(res: dict) -> str:
    code = str((res or {}).get("code") or "")
    return _REPLACE_RESULT_MESSAGES.get(code) or str((res or {}).get("message") or "Не удалось выполнить действие.")


def _replace_parse_result(row: dict) -> dict:
    """Same convention as _ppool_parse_result_json -- never raises."""
    status = str((row or {}).get("status") or "")
    if status not in ("done", "error"):
        return {"ok": False, "code": "timeout", "message": "Команда не выполнена вовремя. Попробуйте ещё раз."}
    text = str((row or {}).get("result_text") or (row or {}).get("error_text") or "")
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {"ok": False, "code": "internal_error", "message": text or "Неизвестна�� ошибка."}


def _replace_b64(text: str) -> str:
    return base64.urlsafe_b64encode(str(text or "").encode("utf-8")).decode("ascii")


