def _bsl_tomorrow_kyiv() -> str:
    tz = ZoneInfo("Europe/Kyiv")
    return (datetime.now(tz) + timedelta(days=1)).date().isoformat()


def _bsl_today_kyiv() -> str:
    tz = ZoneInfo("Europe/Kyiv")
    return datetime.now(tz).date().isoformat()


def _bsl_template_preview(text: str, max_len: int = 40) -> str:
    s = str(text or "").strip()
    if len(s) > max_len:
        return s[: max_len - 1] + "…"
    return s


def _bizlinks_menu_text() -> str:
    tomorrow = _bsl_tomorrow_kyiv()
    try:
        tmpl_rows = _bsl_tmpl_list(TPILOT_DB_PATH)
        tmpl_count = len(tmpl_rows)
        active_count = sum(1 for r in tmpl_rows if int(r.get("is_active") or 0))
    except Exception:
        tmpl_count = 0
        active_count = 0
    try:
        jobs = _bsl_jobs_for_date(tomorrow, TPILOT_DB_PATH)
        job_count = len(jobs)
        job_statuses: Dict[str, int] = {}
        for j in jobs:
            s = str(j.get("status") or "queued")
            job_statuses[s] = job_statuses.get(s, 0) + 1
    except Exception:
        job_count = 0
        job_statuses = {}
    lines = [
        _panel_header(),
        "",
        "\U0001f517 Бизнес-ссылки",
        f"Шаблонов: {tmpl_count}/15 (активных: {active_count})",
        f"Задания на завтра ({tomorrow}): {job_count}",
    ]
    if job_statuses:
        lines.append("  " + "  ".join(f"{k}: {v}" for k, v in sorted(job_statuses.items())))
    lines += [
        "",
        "M2.13B: используйте «\U0001f9ea Создать тест-ссылку» для ручного создания одной ссылки.",
    ]
    return "\n".join(lines).rstrip()


