def _main_menu():  # type: ignore[override]
    rows = list(_M213A_PREV_MAIN_MENU()) if callable(_M213A_PREV_MAIN_MENU) else []
    try:
        btn = [Button.inline("\U0001f517 Бизнес-ссылки", b"menu:bizlinks")]
        # Insert before the last row (refresh/back row)
        if len(rows) >= 2:
            rows.insert(len(rows) - 1, btn)
        else:
            rows.append(btn)
    except Exception:
        pass
    # TPILOT TRANSFERS STAGE4 VISIBILITY HOTFIX: duplicate the transfers shortcut onto
    # the main panel screen itself, so it is visible without entering the "Отчёты и
    # контроль" submenu. menu:transfer_stats logic is untouched.
    try:
        tr_btn = [Button.inline("\U0001f91d Передачи", b"menu:transfer_stats")]
        if tr_btn not in rows:
            if len(rows) >= 2:
                rows.insert(len(rows) - 1, tr_btn)
            else:
                rows.append(tr_btn)
    except Exception:
        pass
    return rows


# --- M2.13A _title_for_menu override ---
_M213A_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    try:
        if raw == "bizlinks":
            return _bizlinks_menu_text(), _bizlinks_menu_buttons()

        if raw == "bizlinks_templates":
            return _bizlinks_templates_text(), _bizlinks_templates_buttons()

        if raw == "bizlinks_pick_manager":
            return _bizlinks_pick_manager_text(), _bizlinks_pick_manager_buttons()

        if raw == "bizlinks_show" or raw.startswith("bizlinks_show:"):
            _bsh_date = raw.split(":", 1)[1] if raw.startswith("bizlinks_show:") else ""
            _bsh_today = _bsl_today_kyiv()
            _bsh_tomorrow = _bsl_tomorrow_kyiv()
            _bsh_resolved = _bsh_date or _bsh_tomorrow  # mirrors _bizlinks_show_text's own default-to-tomorrow
            return _bizlinks_show_text(_bsh_date), [
                [
                    Button.inline("\U0001f4c6 Сегодня", "menu:bizlinks_show:{}".format(_bsh_today).encode("utf-8")),
                    Button.inline("\U0001f4c5 Завтра", "menu:bizlinks_show:{}".format(_bsh_tomorrow).encode("utf-8")),
                ],
                [
                    Button.inline("\U0001f504 Проверить и исправить", "bizfix:{}".format(_bsh_resolved).encode("utf-8")),
                ],
                [
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_manage"),
                    Button.inline("\U0001f504 Обновить", ("menu:bizlinks_show:{}".format(_bsh_date) if _bsh_date else "menu:bizlinks_show").encode("utf-8")),
                ]
            ]

        if raw == "bizlinks_retry":
            text = (
                _panel_header()
                + "\n\n\U0001f504 Повторить ошибки\n\n"
                "M2.13A: реальный повтор ошибочных "
                "заданий будет доступен в M2.13B."
            )
            return text, [
                [
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_manage"),
                    Button.inline("\U0001f3e0 Главная", b"menu:main"),
                ]
            ]

        if raw == "bizlinks_schedule":
            return _bizlinks_schedule_text(), [
                [
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_manage"),
                    Button.inline("\U0001f3e0 Главная", b"menu:main"),
                ]
            ]

        if raw == "bizlinks_create_all":
            tomorrow = _bsl_tomorrow_kyiv()
            try:
                mgr_rows = _manager_rows(only_active=True, only_enabled=True)
                created = 0
                for r in mgr_rows:
                    mk = str(r.get("manager_key") or "").strip()
                    if mk:
                        _bsl_job_create(
                            mk, tomorrow,
                            created_by="admin_panel",
                            created_by_user_id=0,
                            db_path=TPILOT_DB_PATH,
                        )
                        created += 1
                msg = (
                    f"Задания созданы "
                    f"для {created} менеджеров "
                    f"на {tomorrow}.\n"
                    "M2.13A: реальное создание "
                    "ссылок будет включено в M2.13B."
                )
            except Exception as exc:
                msg = f"Ошибка создания заданий: {exc!r}"
            text = _panel_header() + f"\n\n\U0001f4c5 Создать на завтра\n\n{msg}"
            return text, [
                [
                    Button.inline("\U0001f4cb Показать ссылки", b"menu:bizlinks_show"),
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_create"),
                ]
            ]

        if raw.startswith("bizlinks_create_mgr:"):
            mk = normalize_manager_key(raw.split(":", 1)[1])
            tomorrow = _bsl_tomorrow_kyiv()
            try:
                if mk:
                    _bsl_job_create(
                        mk, tomorrow,
                        created_by="admin_panel",
                        created_by_user_id=0,
                        db_path=TPILOT_DB_PATH,
                    )
                    msg = (
                        f"Задание создано "
                        f"для {mk} на {tomorrow}.\n"
                        "M2.13A: реальное создание "
                        "ссылок будет включено в M2.13B."
                    )
                else:
                    msg = "Ошибка: пустой manager_key."
            except Exception as exc:
                msg = f"Ошибка: {exc!r}"
            text = _panel_header() + f"\n\n\U0001f464 Создать для менеджера\n\n{msg}"
            return text, [
                [
                    Button.inline("\U0001f4cb Показать ссылки", b"menu:bizlinks_show"),
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_create"),
                ]
            ]

    except Exception as exc:
        return _safe_text(f"Ошибка меню бизнес-ссылок: {exc!r}"), [
            [Button.inline("\U0001f3e0 Главная", b"menu:main")]
        ]

    if callable(_M213A_PREV_TITLE_FOR_MENU):
        return _M213A_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


# --- M2.13A template editor: callback handler for wiz:bizlink_edit:N ---
@client.on(events.CallbackQuery)
async def _m213a_bizlink_cb(event):
    if not _is_allowed(event):
        return
    data = (event.data or b"").decode("utf-8", "ignore")
    if not data.startswith("wiz:bizlink_edit:"):
        return
    try:
        slot_no = int(data.split(":", 2)[2])
    except (ValueError, IndexError):
        await _pb_safe_answer(event, "Неверный слот", alert=True)
        return
    if slot_no < 1 or slot_no > 15:
        await _pb_safe_answer(event, "Слот вне диапазона 1-15", alert=True)
        return
    try:
        row = _bsl_tmpl_get(slot_no, TPILOT_DB_PATH)
    except Exception:
        row = None
    current_text = str((row or {}).get("message_text") or "")
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    _wizard_set(chat_id, user_id, "bizlink_edit", "text", {"slot_no": slot_no})
    prompt = (
        f"✏️ Редактирование шаблона #{slot_no}\n\n"
        f"Текущий текст:\n{current_text}\n\n"
        "Отправьте новый текст "
        "(до 1024 символов).\n"
        "Или нажмите Отмена."
    )
    await _safe_event_edit(event, prompt, buttons=[
        [Button.inline("❌ Отмена", b"menu:bizlinks_templates")],
    ])
    raise events.StopPropagation


# --- M2.13A template editor: wizard message input handler ---
@client.on(events.NewMessage)
async def _m213a_bizlink_wizard_input(event):
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if not state:
        return
    if str(state.get("wizard") or "") != "bizlink_edit":
        return
    payload = dict(state.get("payload") or {})
    slot_no = int(payload.get("slot_no") or 0)
    if slot_no < 1 or slot_no > 15:
        _wizard_clear(chat_id, user_id)
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal error,
        # wizard cleared, nothing to retry from this message.
        await event.respond(
            "Ошибка: неверный номер слота.",
            buttons=_terminal_ok_button(),
        )
        try:
            await _pb_send_menu_message(chat_id, "bizlinks_templates")
        except Exception:
            pass
        raise events.StopPropagation
    ok, err = _bsl_tmpl_validate(slot_no, raw)
    if not ok:
        await event.respond(
            f"⚠️ {err}\n\nПопробуйте ещё раз или нажмите Отмена.",
            buttons=[[Button.inline("❌ Отмена", b"menu:bizlinks_templates")]],
        )
        raise events.StopPropagation
    save_ok, save_err = _bsl_tmpl_set(slot_no, raw, updated_by=user_id, db_path=TPILOT_DB_PATH)
    _wizard_clear(chat_id, user_id)
    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): both branches are
    # terminal (save succeeded or failed, wizard already cleared, nothing
    # more to do from THIS notice -- the templates menu is a separate
    # follow-up message below).
    if save_ok:
        await event.respond(
            f"✅ Текст #{slot_no} обновлён.",
            buttons=_terminal_ok_button(),
        )
    else:
        await event.respond(
            f"⚠️ Ошибка сохранения: {save_err}",
            buttons=_terminal_ok_button(),
        )
    try:
        await _pb_send_menu_message(chat_id, "bizlinks_templates")
    except Exception:
        pass
    raise events.StopPropagation

