def _bizlinks_test_confirm_text(mk: str, slot_no: int) -> str:
    tomorrow = _bsl_test_tomorrow()
    title = f"TPilot {tomorrow} #{int(slot_no):02d}"
    try:
        tmpl = _bsl_tmpl_get(int(slot_no), TPILOT_DB_PATH)
        preview = _bsl_template_preview(str((tmpl or {}).get("message_text") or ""), max_len=60)
    except Exception:
        preview = "(ошибка загрузки шаблона)"
    # Check idempotency
    exists_line = ""
    if callable(_bsl_get_one_pb):
        try:
            existing = _bsl_get_one_pb(mk, tomorrow, int(slot_no), TPILOT_DB_PATH)
            if existing and str(existing.get("status") or "") == "created" and str(existing.get("link_url") or "").strip():
                exists_line = f"\n\n⚠️ Ссылка уже создана: {existing.get('link_url','')}"
        except Exception:
            pass
    return (
        _panel_header()
        + "\n\n\U0001f9ea Подтверждение создания ссылки"
        + f"\n\nМенеджер: {mk}"
        + f"\nСлот: #{int(slot_no):02d}"
        + f"\nДата: {tomorrow}"
        + f"\nНазвание: {title}"
        + f"\nТекст: {preview}"
        + exists_line
        + "\n\nНажмите «Создать», чтобы создать одну бизнес-ссылку."
    )


