# --- M2.13B _title_for_menu override ---
_M213B_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    try:
        if raw == "bizlinks_test_pick_mgr":
            return _bizlinks_test_pick_mgr_text(), _bizlinks_test_pick_mgr_buttons()

        if raw.startswith("bizlinks_test_slot:"):
            mk = normalize_manager_key(raw.split(":", 1)[1])
            return _bizlinks_test_slot_text(mk), _bizlinks_test_slot_buttons(mk)

        if raw.startswith("bizlinks_test_confirm:"):
            # format: bizlinks_test_confirm:<key>:<slot_no>
            rest = raw[len("bizlinks_test_confirm:"):]
            parts = rest.rsplit(":", 1)
            if len(parts) == 2:
                mk = normalize_manager_key(parts[0])
                try:
                    slot_no = int(parts[1])
                except ValueError:
                    slot_no = 1
            else:
                mk = normalize_manager_key(rest)
                slot_no = 1
            return _bizlinks_test_confirm_text(mk, slot_no), _bizlinks_test_confirm_buttons(mk, slot_no)

    except Exception as exc:
        return _safe_text(f"Ошибка меню тест-ссылки: {exc!r}"), [
            [Button.inline("\U0001f3e0 Главная", b"menu:main")]
        ]

    if callable(_M213B_PREV_TITLE_FOR_MENU):
        return _M213B_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []

