# --- TPILOT M2.13D-1 ADMIN SCHEDULE UI 20260609 START ---
# AdminBot work-schedule view/edit. Any allowed admin can view or toggle any manager's schedule.
# Direct storage write (no controller round-trip), same pattern as _m26f_mba_callback.
# updated_by_role='admin'. Past days: view-only alert. Today/future: toggleable.

import calendar as _sched_pb_cal_mod
from datetime import date as _sched_pb_date_cls

try:
    from storage import (
        ensure_manager_schedule_tables as _sched_pb_ensure,
        manager_schedule_get_month as _sched_pb_get_month,
        manager_schedule_set_day as _sched_pb_set_day,
        manager_schedule_list_working_on_date as _sched_pb_working_date,
        manager_schedule_clear_day as _sched_pb_clear_day,
        manager_effective_is_working as _sched_pb_effective_is_working,
    )
    _SCHED_PB_OK = True
except Exception as _sched_pb_imp_err:
    _SCHED_PB_OK = False
    _sched_pb_ensure = None
    _sched_pb_get_month = None
    _sched_pb_set_day = None
    _sched_pb_working_date = None
    _sched_pb_clear_day = None
    _sched_pb_effective_is_working = None

try:
    if _SCHED_PB_OK and callable(_sched_pb_ensure):
        _sched_pb_ensure(TPILOT_DB_PATH)
except Exception:
    pass

_SCHED_PB_MONTH_NAMES = [
    "", "Январь", "Февраль",
    "Март", "Апрель", "Май",
    "Июнь", "Июль", "Август",
    "Сентябрь", "Октябрь",
    "Ноябрь", "Декабрь",
]


def _sched_pb_kyiv_today():
    # W3.3-B redirect: derive the business date through the canonical storage
    # timezone layer instead of a local ZoneInfo("Europe/Kyiv") construction.
    from storage import w3_business_date as _spbkt_w3_business_date
    return _sched_pb_date_cls.fromisoformat(_spbkt_w3_business_date())


def _sched_pb_manager_label(mk: str) -> str:
    """Return 'display_name / @username' for admin display."""
    try:
        for r in _manager_rows_all():
            if normalize_manager_key(r.get("manager_key") or "") == normalize_manager_key(mk or ""):
                name = str(r.get("display_name") or "").strip() or mk
                uname = str(r.get("telegram_username") or "").strip()
                return "{} / @{}".format(name, uname) if uname else name
    except Exception:
        pass
    return str(mk or "")


def _sched_pb_source_for_manager(mk: str) -> str:
    """Return the linked source_key for mk, or '' if unlinked. Mirrors _source_links_map_sync's
    manager_key normalization so the lookup matches manager_source_links."""
    try:
        return str(_source_links_map_sync().get(normalize_manager_key(mk or ""), "") or "")
    except Exception:
        return ""


def _sched_pb_month_text(mk: str, year: int, month: int) -> str:
    label = _sched_pb_manager_label(mk)
    month_name = _SCHED_PB_MONTH_NAMES[month] if 1 <= month <= 12 else ""
    try:
        month_data = _sched_pb_get_month(mk, year, month, TPILOT_DB_PATH) if callable(_sched_pb_get_month) else {}
    except Exception:
        month_data = {}
    days_in_month = _sched_pb_cal_mod.monthrange(year, month)[1]
    n_explicit_on = sum(1 for d in range(1, days_in_month + 1) if month_data.get(d, 0) == 1)
    n_explicit_off = sum(1 for d in range(1, days_in_month + 1) if d in month_data and month_data.get(d) != 1)
    n_inherited_on = 0
    for d in range(1, days_in_month + 1):
        if d in month_data:
            continue
        try:
            date_iso = "{:04d}-{:02d}-{:02d}".format(year, month, d)
            if callable(_sched_pb_effective_is_working) and _sched_pb_effective_is_working(mk, date_iso, TPILOT_DB_PATH):
                n_inherited_on += 1
        except Exception:
            pass
    n_off_total = days_in_month - n_explicit_on - n_explicit_off - n_inherited_on
    src_key = _sched_pb_source_for_manager(mk)
    if src_key:
        try:
            src_cfg = _sws_get(src_key, db_path=TPILOT_DB_PATH, include_disabled=True)
        except Exception:
            src_cfg = None
        src_state = "наследование включено" if (src_cfg and int(src_cfg.get("enabled") or 0) == 1) else "наследование выключено"
        src_line = "Источник: {} ({})".format(src_key, src_state)
    else:
        src_line = "Источник: не привязан"
    lines = [
        _panel_header(),
        "",
        "\U0001f4c5 График менеджера",
        "",
        "Менеджер: {}".format(label),
        "Месяц: {} {}".format(month_name, year),
        src_line,
        "",
        "✅ Рабочие (личные): {}".format(n_explicit_on),
        "❌ Выходные (личные): {}".format(n_explicit_off),
        "🟢 Рабочие (по источнику): {}".format(n_inherited_on),
        "⚫ Выходные (по умолчанию): {}".format(n_off_total),
    ]
    return "\n".join(lines)


def _sched_pb_month_buttons(mk: str, year: int, month: int) -> list:
    today = _sched_pb_kyiv_today()
    try:
        month_data = _sched_pb_get_month(mk, year, month, TPILOT_DB_PATH) if callable(_sched_pb_get_month) else {}
    except Exception:
        month_data = {}
    yyyymm = "{:04d}{:02d}".format(year, month)
    rows = []
    # Weekday header
    hdr_labels = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"]
    rows.append([Button.inline(d, b"sch:noop") for d in hdr_labels])
    # Calendar weeks
    cal = _sched_pb_cal_mod.Calendar(firstweekday=0)
    for week in cal.monthdayscalendar(year, month):
        row = []
        for day in week:
            if day == 0:
                row.append(Button.inline(" ", b"sch:noop"))
            else:
                if day in month_data:
                    is_working = month_data.get(day) == 1
                    label = "✅{}".format(day) if is_working else "❌{}".format(day)
                else:
                    inherited_on = False
                    try:
                        date_iso = "{:04d}-{:02d}-{:02d}".format(year, month, day)
                        inherited_on = bool(
                            callable(_sched_pb_effective_is_working)
                            and _sched_pb_effective_is_working(mk, date_iso, TPILOT_DB_PATH)
                        )
                    except Exception:
                        inherited_on = False
                    label = "🟢{}".format(day) if inherited_on else "⚫{}".format(day)
                # Marker logic above only changes the label; the tap target (sch:t:) and its
                # toggle behavior are unchanged so existing explicit set-day behavior keeps working.
                cb_str = "sch:t:{}:{}:{:02d}".format(mk, yyyymm, day)
                cb = cb_str.encode("utf-8")
                if len(cb) > 64:
                    cb = b"sch:noop"
                row.append(Button.inline(label, cb))
        rows.append(row)
    # Navigation
    prev_y, prev_m = (year, month - 1) if month > 1 else (year - 1, 12)
    next_y, next_m = (year, month + 1) if month < 12 else (year + 1, 1)
    prev_cb = "sch:p:{}:{:04d}{:02d}".format(mk, prev_y, prev_m).encode("utf-8")
    next_cb = "sch:n:{}:{:04d}{:02d}".format(mk, next_y, next_m).encode("utf-8")
    rows.append([
        Button.inline("⬅️", prev_cb if len(prev_cb) <= 64 else b"sch:noop"),
        Button.inline("➡️", next_cb if len(next_cb) <= 64 else b"sch:noop"),
    ])
    clearlist_cb = "sch:clearlist:{}:{}".format(mk, yyyymm).encode("utf-8")
    rows.append([Button.inline("↩️ Сбросить переопределения", clearlist_cb if len(clearlist_cb) <= 64 else b"sch:noop")])
    rows.append([
        Button.inline("⬅️ Список", b"menu:bizschedule"),
        Button.inline("\U0001f3e0 Главная", b"menu:main"),
    ])
    return rows


# --- TPILOT PATCH C1B: clear manager day override sub-screen 20260622 START ---
def _sched_pb_clearlist_text(mk: str, year: int, month: int) -> str:
    label = _sched_pb_manager_label(mk)
    month_name = _SCHED_PB_MONTH_NAMES[month] if 1 <= month <= 12 else ""
    try:
        month_data = _sched_pb_get_month(mk, year, month, TPILOT_DB_PATH) if callable(_sched_pb_get_month) else {}
    except Exception:
        month_data = {}
    lines = [
        _panel_header(),
        "",
        "↩️ Переопределения дней",
        "",
        "Менеджер: {}".format(label),
        "Месяц: {} {}".format(month_name, year),
        "",
    ]
    if month_data:
        lines.append("Личные настройки (нажмите, чтобы вернуть к графику источника):")
    else:
        lines.append("Личных переопределений в этом месяце нет.")
    return "\n".join(lines)


def _sched_pb_clearlist_buttons(mk: str, year: int, month: int) -> list:
    try:
        month_data = _sched_pb_get_month(mk, year, month, TPILOT_DB_PATH) if callable(_sched_pb_get_month) else {}
    except Exception:
        month_data = {}
    yyyymm = "{:04d}{:02d}".format(year, month)
    rows = []
    for day in sorted(month_data.keys()):
        is_working = month_data.get(day) == 1
        mark = "✅" if is_working else "❌"
        cb_str = "sch:clear:{}:{}:{:02d}".format(mk, yyyymm, day)
        cb = cb_str.encode("utf-8")
        if len(cb) > 64:
            continue
        rows.append([Button.inline("↩️ {} {:02d}".format(mark, day), cb)])
    open_cb = "sch:open:{}:{}".format(mk, yyyymm).encode("utf-8")
    rows.append([Button.inline("⬅️ Назад к графику", open_cb if len(open_cb) <= 64 else b"sch:noop")])
    rows.append([
        Button.inline("⬅️ Список", b"menu:bizschedule"),
        Button.inline("\U0001f3e0 Главная", b"menu:main"),
    ])
    return rows
# --- TPILOT PATCH C1B: clear manager day override sub-screen 20260622 END ---


