# M2.13D-2: Override _bizlinks_show_text — clean grouped format using format_bizlinks_grouped

def _bizlinks_show_text(target_date: str = "") -> str:  # type: ignore[override]
    if not target_date:
        target_date = _bsl_tomorrow_kyiv()
    try:
        links = _bsl_links_for_date(target_date, TPILOT_DB_PATH)
    except Exception:
        links = []
    label_map = _pb_build_label_map()
    # Readiness-denominator fix: a manager whose bizlinks rows for this date
    # are all deleted/ghost (e.g. a stale unrelated-date leftover) must not
    # inflate the footer if that manager isn't even expected to work this
    # date. Scheduled managers reuse the existing schedule helper (no new
    # schedule logic); fail-open to None (no filtering) on any error, same
    # as every other schedule-aware screen in this file.
    expected_keys = None
    try:
        if _SCHED_PB_OK and callable(_sched_pb_working_date):
            expected_keys = {
                normalize_manager_key(k) for k in (_sched_pb_working_date(target_date, TPILOT_DB_PATH) or [])
            }
    except Exception:
        expected_keys = None
    if callable(_bsl_fmt_grouped):
        # Pass the admin-configured per-manager count so the readiness footer's
        # denominator matches exactly what "Проверить и исправить" will actually
        # create -- otherwise a non-default count (e.g. 10) would leave the
        # footer permanently "incomplete" against a hardcoded assumption of 15.
        try:
            _bsh_expected_count = _pb_bizlink_default_count()
        except Exception:
            _bsh_expected_count = None
        body = _bsl_fmt_grouped(
            target_date, links, label_map,
            expected_count=_bsh_expected_count, expected_manager_keys=expected_keys,
        )
    else:
        # Fallback if storage import failed
        body = "\U0001f517 Бизнес-ссылки\nОшибка загрузки модуля."
    return _panel_header() + "\n\n" + body


