# M2.13D-2: stacked _title_for_menu override
_M213D2_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    try:
        # --- M2.13D-2: new create flow screens ---
        if raw == "bizlinks_create_scope":
            return _d2_scope_text(), _d2_scope_buttons()

        if raw == "bizlinks_create_pick_mgr":
            return _d2_pick_mgr_text(), _d2_pick_mgr_buttons()

        if raw.startswith("bizlinks_create_count_1:"):
            mk = normalize_manager_key(raw[len("bizlinks_create_count_1:"):])
            return _d2_count1_text(mk), _d2_count_buttons_for(
                ("menu:bizlinks_create_pick_mgr").encode("utf-8"), mk=mk
            )

        if raw == "bizlinks_create_count_all":
            return _d2_count_all_text(), _d2_count_buttons_for(
                b"menu:bizlinks_create_scope", mk=""
            )

        if raw.startswith("bizlinks_create_confirm:"):
            rest = raw[len("bizlinks_create_confirm:"):]
            parts = rest.rsplit(":", 1)
            if len(parts) == 2:
                mk = normalize_manager_key(parts[0])
                try:
                    count = int(parts[1])
                except ValueError:
                    count = 15
            else:
                mk = normalize_manager_key(rest)
                count = 15
            return _d2_confirm1_text(mk, count), _d2_confirm1_buttons(mk, count)

        if raw.startswith("bizlinks_create_all_confirm:"):
            try:
                count = int(raw[len("bizlinks_create_all_confirm:"):])
            except ValueError:
                count = 15
            return _d2_confirm_all_text(count), _d2_confirm_all_buttons(count)

        if raw == "bizlinks_set_default_count":
            return _d2_set_default_count_text(), _d2_set_default_count_buttons()

        # --- M2.13D-2: replace M2.13A placeholders ---
        if raw == "bizlinks_schedule":
            # Repoint to real Patch 1 schedule screen
            return _sched_pb_managers_list_text(), _sched_pb_managers_list_buttons()

        if raw == "bizlinks_create_all":
            # Old M2.13A "create for all" → new scope picker
            return _d2_scope_text(), _d2_scope_buttons()

        if raw.startswith("bizlinks_create_mgr:"):
            # Old M2.13A per-manager create → new count-pick for that manager
            mk = normalize_manager_key(raw.split(":", 1)[1])
            if mk:
                return _d2_count1_text(mk), _d2_count_buttons_for(
                    b"menu:bizlinks_create_pick_mgr", mk=mk
                )

        if raw == "bizlinks_retry":
            # Remove M2.13A placeholder — just say not available yet
            text = (
                _panel_header()
                + "\n\n\U0001f504 Повторить ошибки"
                "\n\nФункция будет доступна в Patch 3."
            )
            return text, [
                [
                    Button.inline("⬅️ Назад", b"menu:nm_bizlinks_manage"),
                    Button.inline("\U0001f3e0 Главная", b"menu:main"),
                ]
            ]

    except Exception as exc:
        return _safe_text("Ошибка M2.13D-2 меню: {!r}".format(exc)), [
            [Button.inline("\U0001f3e0 Главная", b"menu:main")]
        ]

    if callable(_M213D2_PREV_TITLE_FOR_MENU):
        return _M213D2_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


# M2.13D-2: bslcnt: callback — direct settings write for default link count
@client.on(events.CallbackQuery)
async def _m213d2_bslcnt_callback(event):
    """Handle bslcnt:N callbacks — write bizlink_default_count to settings."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("bslcnt:"):
            return
        try:
            new_count = int(data.split(":", 1)[1])
        except (ValueError, IndexError):
            await _pb_safe_answer(event, "Неверное значение", alert=True)
            return
        clamped, avail = _pb_clamp_count(new_count)
        _pb_set_setting("bizlink_default_count", str(clamped))
        note = ""
        if clamped < new_count:
            note = " (запрошено {}, доступно {})".format(new_count, avail)
        await _pb_safe_answer(event, "Сохранено: {}{}".format(clamped, note))
        try:
            text, buttons = _title_for_menu("bizlinks_set_default_count")
            await _safe_event_edit(event, text, buttons=buttons)
        except Exception:
            pass
        raise events.StopPropagation
    except events.StopPropagation:
        raise
    except Exception as exc:
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

