def _d3a_format_preview_text(mk: str, mode: str, param: str, candidates: list) -> str:
    """Build the preview screen text (what will be deleted)."""
    label = _pb_bizdel_mgr_label(_pb_bizdel_mgr_row(mk)) or mk
    if mode == "by_date":
        try:
            p = param.split("-")
            date_disp = "{}-{}-{}".format(p[2], p[1], p[0])
        except Exception:
            date_disp = param
        mode_label = "По дате {}".format(date_disp)
    elif mode == "last_n":
        mode_label = "Последние {}".format(param)
    elif mode == "oldest_n":
        mode_label = "Старые {}".format(param)
    else:
        mode_label = str(mode or "")
    n = len(candidates)
    lines = [
        "\U0001f5d1 Предпросмотр удаления",
        "",
        "Менеджер: {}".format(label),
        "Режим: {}".format(mode_label),
        "Ссылок к удалению: {}".format(n),
        "",
    ]
    for r in candidates[:15]:
        url = str(r.get("link_url") or "").strip()
        if url:
            lines.append(url)
    if n > 15:
        lines.append("... и ещё {}".format(n - 15))
    lines += [
        "",
        "⚠️ Действие необратимо.",
        "Ссылки удалятся из Telegram.",
        "Preview истекает через 5 мин.",
    ]
    return _panel_header() + "\n\n" + "\n".join(lines)


def _d3a_format_preview_buttons(preview_id: str, mk: str) -> list:
    """Confirm + cancel buttons for the preview screen."""
    confirm_text = "cmd:/bizlink_delete_tpilot {}".format(preview_id)
    cb_bytes = confirm_text.encode("utf-8")
    back_cb = "menu:bizdel_pick_mode:{}".format(mk)
    if len(cb_bytes) > 64:
        # Shouldn't happen: cmd:(27) + UUID(36) = 63 bytes
        return [[Button.inline("Ошибка ID", b"menu:nm_bizlinks_delete")]]
    return [
        [Button.inline("✅ Удалить", cb_bytes)],
        [Button.inline(
            "⬅️ Отмена",
            back_cb.encode("utf-8") if len(back_cb.encode("utf-8")) <= 64 else b"menu:bizdel_scope",
        )],
    ]


