# M2.13D-3A: stacked _title_for_menu override
_M213D3A_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    try:
        if raw == "bizdel_scope":
            return _d3a_scope_text(), _d3a_scope_buttons()

        if raw.startswith("bizdel_pick_mode:"):
            mk = normalize_manager_key(raw[len("bizdel_pick_mode:"):])
            return _d3a_pick_mode_text(mk), _d3a_pick_mode_buttons(mk)

        if raw.startswith("bizdel_pick_date:"):
            mk = normalize_manager_key(raw[len("bizdel_pick_date:"):])
            return _d3a_pick_date_text(mk), _d3a_pick_date_buttons(mk)

        if raw.startswith("bizdel_count_n:"):
            rest = raw[len("bizdel_count_n:"):]
            parts = rest.rsplit(":", 1)
            if len(parts) == 2:
                mk = normalize_manager_key(parts[0])
                mode = str(parts[1])
            else:
                mk = normalize_manager_key(rest)
                mode = "last_n"
            return _d3a_count_text(mk, mode), _d3a_count_buttons(mk, mode)

    except Exception as exc:
        return _safe_text("Ошибка M2.13D-3A меню: {!r}".format(exc)), [
            [Button.inline("\U0001f3e0 Главная", b"menu:main")]
        ]

    if callable(_M213D3A_PREV_TITLE_FOR_MENU):
        return _M213D3A_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


# M2.13D-3A: async bizdel: callback — generates preview and shows it in-place
@client.on(events.CallbackQuery)
async def _m213d3a_bizdel_callback(event):
    """Handle bizdel:gen:<mk>:<mode>:<param> — select candidates, create preview, show screen."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("bizdel:"):
            return

        # Parse: bizdel:gen:<mk>:<mode>:<param>
        parts = data.split(":", 4)
        if len(parts) < 5 or parts[1] != "gen":
            return

        mk = normalize_manager_key(parts[2])
        mode = str(parts[3])
        param = str(parts[4])

        if not mk or mode not in ("by_date", "last_n", "oldest_n"):
            await _pb_safe_answer(event, 
                "Неверные параметры",
                alert=True,
            )
            return

        if not callable(_bsd3a_select_pb):
            await _pb_safe_answer(event, 
                "Ошибка модуля",
                alert=True,
            )
            return

        target_date = ""
        count = 0
        if mode == "by_date":
            target_date = param
        else:
            try:
                count = max(1, int(param))
            except ValueError:
                count = 15

        try:
            candidates = _bsd3a_select_pb(
                mk,
                mode,
                target_date=target_date if target_date else None,
                count=count if count else None,
                db_path=TPILOT_DB_PATH,
            )
        except Exception as _sel_exc:
            await _pb_safe_answer(event, 
                "Ошибка выборки",
                alert=True,
            )
            return

        if not candidates:
            text = (
                _panel_header()
                + "\n\n\U0001f5d1 Удалить ссылки"
                "\n\nНет ссылок для "
                "удаления "
                "в выбранном "
                "режиме."
            )
            back_raw = "menu:bizdel_pick_mode:{}".format(mk)
            back_cb = back_raw.encode("utf-8") if len(back_raw.encode("utf-8")) <= 64 else b"menu:bizdel_scope"
            buttons = [[Button.inline("⬅️ Назад", back_cb)]]
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, text, buttons=buttons)
            except Exception:
                pass
            raise events.StopPropagation

        if not callable(_bsd3a_preview_create_pb):
            await _pb_safe_answer(event, 
                "Ошибка создания preview",
                alert=True,
            )
            return

        uid = int(event.sender_id or 0)
        try:
            preview_id = _bsd3a_preview_create_pb(
                mk,
                mode,
                candidates,
                target_date=target_date,
                requested_by_user_id=uid,
                ttl_seconds=300,
                db_path=TPILOT_DB_PATH,
            )
        except Exception as _prev_exc:
            await _pb_safe_answer(event, 
                "Ошибка preview: {!r}".format(_prev_exc)[:60],
                alert=True,
            )
            return

        text = _d3a_format_preview_text(mk, mode, param, candidates)
        buttons = _d3a_format_preview_buttons(preview_id, mk)
        await _pb_safe_answer(event, )
        try:
            await _safe_event_edit(event, text, buttons=buttons)
        except Exception:
            pass
        raise events.StopPropagation

    except events.StopPropagation:
        raise
    except Exception as exc:
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


