@client.on(events.CallbackQuery)
async def _tpc1b_source_days_callback(event):
    """Handle sds: callbacks for the PanelBot source weekly day-schedule editor (Patch C1b)."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("sds:"):
            return
        admin_id = int(getattr(event, "sender_id", 0) or 0)
        parts = data.split(":")

        # sds:day:<source_key>:<col>
        if len(parts) >= 4 and parts[1] == "day":
            key = _slug_key(parts[2], "source")
            col = str(parts[3] or "").strip().lower()
            if not _traffic_source_by_key(key):
                await _pb_safe_answer(event, "Источник не найден", alert=True)
                return
            if col not in _TPC1B_WEEKDAY_COLS:
                await _pb_safe_answer(event, "Ошибка дня", alert=True)
                return
            try:
                cfg = _sws_get(key, db_path=TPILOT_DB_PATH, include_disabled=True)
                cur = int((cfg or {}).get(col, 1) or 0) == 1
                _sws_set(key, **{col: 0 if cur else 1}, updated_by_user_id=admin_id, db_path=TPILOT_DB_PATH)
            except Exception:
                await _pb_safe_answer(event, "Ошибка сохранения", alert=True)
                return
            text, buttons = _title_for_menu(f"source_days:{key}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, )
            return

        # sds:toggle:<source_key>
        if len(parts) >= 3 and parts[1] == "toggle":
            key = _slug_key(parts[2], "source")
            if not _traffic_source_by_key(key):
                await _pb_safe_answer(event, "Источник не найден", alert=True)
                return
            try:
                cfg = _sws_get(key, db_path=TPILOT_DB_PATH, include_disabled=True)
                cur_enabled = bool(cfg and int(cfg.get("enabled") or 0) == 1)
                _sws_set(key, enabled=(0 if cur_enabled else 1), updated_by_user_id=admin_id, db_path=TPILOT_DB_PATH)
            except Exception:
                await _pb_safe_answer(event, "Ошибка сохранения", alert=True)
                return
            text, buttons = _title_for_menu(f"source_days:{key}")
            await _safe_event_edit(event, text, buttons=buttons)
            await _pb_safe_answer(event, )
            return

        await _pb_safe_answer(event, )
    except Exception as exc:
        print(f"sds callback failed: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass
# --- TPILOT PATCH C1B: source_days title override + sds: callback 20260622 END ---


