# --- TPILOT PATCH C3C: schedule-request push + approval inbox 20260623 START ---
# Managers' tomorrow/future schedule changes arrive as pending rows in
# manager_schedule_change_requests (Patch C3a/C3b). This block notifies admins (push) and lets them
# approve/reject from buttons (push message or the "Заявки на график" inbox). Approval applies the
# change through the EXISTING manager_schedule_set_day (explicit override, role=admin); reject only
# transitions the request. Source schedules (C1/C2) are never touched here.
_TPC3C_OK = all(callable(globals().get(n)) for n in (
    "_screq_get", "_screq_list_pending", "_screq_mark_notified", "_screq_decide", "_screq_set_day",
))


def _tpc3c_action_label(requested_is_working) -> str:
    return "✅ рабочий" if int(requested_is_working or 0) == 1 else "❌ выходной"


def _tpc3c_request_text(req: dict) -> str:
    """Concise admin-facing description of one pending schedule-change request."""
    if not req:
        return "Заявка не найдена."
    mk = str(req.get("manager_key") or "")
    try:
        label = _sched_pb_manager_label(mk)
    except Exception:
        label = mk
    lines = [
        "📅 Заявка на изменение графика",
        "",
        f"Менеджер: {label}",
        f"Дата: {req.get('work_date')}",
        f"Запрашивает: {_tpc3c_action_label(req.get('requested_is_working'))}",
    ]
    eff = req.get("effective_at_request")
    if eff is not None:
        cur = "рабочий" if int(eff or 0) == 1 else "выходной"
        src = str(req.get("source_key") or "").strip()
        inh = req.get("inherited_at_request")
        if int(inh or 0) == 1 and src:
            lines.append(f"Сейчас: {cur} (п�� источнику {src})")
        else:
            lines.append(f"Сейчас: {cur}")
    if req.get("requested_by_user_id"):
        lines.append(f"От пользователя: {req.get('requested_by_user_id')}")
    if req.get("created_at"):
        lines.append(f"Создано: {req.get('created_at')}")
    return "\n".join(lines)


def _tpc3c_request_decision_buttons(req_id):
    return [
        [Button.inline("✅ Одобрить", f"schreq:ok:{int(req_id)}".encode()),
         Button.inline("❌ Отклонить", f"schreq:no:{int(req_id)}".encode())],
        [Button.inline("🗂 Все заявки", b"menu:schedule_requests")],
    ]


def _tpc3c_inbox_text() -> str:
    header = _panel_header()
    if not _TPC3C_OK:
        return f"{header}\n\n🗂 Заявки на график\n\nФункция недоступна."
    try:
        pending = _screq_list_pending(db_path=TPILOT_DB_PATH) or []
    except Exception:
        pending = []
    lines = [header, "", "🗂 Заявки на график", ""]
    if not pending:
        lines.append("Активных заявок нет.")
        return "\n".join(lines)
    lines.append(f"Ожидают решения: {len(pending)}")
    lines.append("")
    for req in pending[:20]:
        try:
            label = _sched_pb_manager_label(str(req.get("manager_key") or ""))
        except Exception:
            label = str(req.get("manager_key") or "")
        lines.append(
            f"#{req.get('id')} · {label} · {req.get('work_date')} → {_tpc3c_action_label(req.get('requested_is_working'))}"
        )
    return "\n".join(lines)


def _tpc3c_inbox_buttons() -> list:
    rows = []
    if _TPC3C_OK:
        try:
            pending = _screq_list_pending(db_path=TPILOT_DB_PATH) or []
        except Exception:
            pending = []
        for req in pending[:20]:
            rid = int(req.get("id") or 0)
            if not rid:
                continue
            mark = _tpc3c_action_label(req.get("requested_is_working"))
            rows.append([
                Button.inline(f"✅ #{rid}", f"schreq:ok:{rid}".encode()),
                Button.inline(f"❌ #{rid}", f"schreq:no:{rid}".encode()),
            ])
    rows.append([Button.inline("🔄 Обновить", b"menu:schedule_requests")])
    # N5.3 (D3): this inbox is opened from the canonical Менеджеры section
    # (🗓 Заявки графика) -- Back must return there, not jump cross-section
    # into the bizlink-schedule area. The schedule editor stays reachable via
    # its own canonical path (Бизнес-ссылки -> Управление -> Графики ссылок).
    rows.append([Button.inline("⬅️ Назад", b"menu:nm_managers"), Button.inline("🏠 Главная", b"menu:main")])
    return rows


_TPC3C_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu):  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "schedule_requests":
        return _tpc3c_inbox_text(), _tpc3c_inbox_buttons()
    if callable(_TPC3C_PREV_TITLE_FOR_MENU):
        return _TPC3C_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


@client.on(events.CallbackQuery)
async def _tpc3c_schreq_callback(event):
    """Approve/reject a pending schedule-change request (Patch C3c)."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("schreq:"):
            return
        if not _TPC3C_OK:
            await _pb_safe_answer(event, "Функция недоступна", alert=True)
            return
        parts = data.split(":")
        if len(parts) < 3 or parts[1] not in ("ok", "no"):
            await _pb_safe_answer(event, )
            return
        try:
            req_id = int(parts[2])
        except Exception:
            await _pb_safe_answer(event, "Ошибка заявки", alert=True)
            return
        admin_id = int(getattr(event, "sender_id", 0) or 0)

        req = _screq_get(req_id, db_path=TPILOT_DB_PATH)
        if not req:
            await _pb_safe_answer(event, "Заявка не найдена", alert=True)
            return
        if str(req.get("status") or "") != "pending":
            await _pb_safe_answer(event, "Заявка уже обработана", alert=True)
            await _safe_event_edit(event, _tpc3c_inbox_text(), buttons=_tpc3c_inbox_buttons())
            return

        mk = str(req.get("manager_key") or "")
        work_date = str(req.get("work_date") or "")

        if parts[1] == "no":
            ok = _screq_decide(req_id, "rejected", admin_id, db_path=TPILOT_DB_PATH)
            if not ok:
                await _pb_safe_answer(event, "Заявка уже обработана", alert=True)
            else:
                await _pb_safe_answer(event, "Отклонено")
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): decision
            # applied, done -- terminal.
            await _safe_event_edit(
                event,
                f"❌ Заявка #{req_id} отклонена.\nМенеджер: {mk}\nДата: {work_date}",
                buttons=[[Button.inline("🗂 Все заявки", b"menu:schedule_requests")]] + _terminal_ok_button(),
            )
            return

        # Approve — refuse stale past-dated requests (the manager should re-request).
        try:
            wd_date = datetime.strptime(work_date, "%Y-%m-%d").date()
        except Exception:
            await _pb_safe_answer(event, "Ошибка даты", alert=True)
            return
        if wd_date < _sched_pb_kyiv_today():
            await _pb_safe_answer(event, "Дата уже прошла — заявка устарела", alert=True)
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): stale request,
            # no recovery besides the manager resending -- terminal error.
            await _safe_event_edit(
                event,
                f"⚠️ Заявка #{req_id} устарела (дата {work_date} уже прошла). Менеджеру нужно отправить новую.",
                buttons=[[Button.inline("🗂 Все заявки", b"menu:schedule_requests")]] + _terminal_ok_button(),
            )
            return

        riw = 1 if int(req.get("requested_is_working") or 0) == 1 else 0
        try:
            _screq_set_day(
                mk, work_date, riw,
                source="admin_approved_request",
                updated_by_user_id=admin_id,
                updated_by_role="admin",
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            print(f"schreq apply failed: {exc!r}")
            await _pb_safe_answer(event, "Ошибка применения", alert=True)
            return
        # Mark decided AFTER the override is written. If decide reports already-decided (race),
        # the override is harmless/idempotent (same explicit value).
        decided = _screq_decide(req_id, "approved", admin_id, db_path=TPILOT_DB_PATH)
        if not decided:
            await _pb_safe_answer(event, "Заявка уже обработана", alert=True)
        else:
            await _pb_safe_answer(event, "Одобрено")
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): decision applied,
        # done -- terminal.
        await _safe_event_edit(
            event,
            f"✅ Заявка #{req_id} одобрена.\nМенеджер: {mk}\nДата: {work_date}\nГрафик: {_tpc3c_action_label(riw)}",
            buttons=[[Button.inline("🗂 Все заявки", b"menu:schedule_requests")]] + _terminal_ok_button(),
        )
    except Exception as exc:
        print(f"schreq callback failed: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


async def _schedule_request_notify_loop() -> None:
    """Poll pending un-notified schedule-change requests and push them to admin chats with
    approve/reject buttons (dedicated loop — the generic panel_notifications queue cannot carry
    custom buttons). Marks a request notified only after at least one successful send."""
    if not _TPC3C_OK:
        return
    while True:
        try:
            try:
                pending = _screq_list_pending(notified=0, db_path=TPILOT_DB_PATH) or []
            except Exception:
                pending = []
            if not pending:
                await asyncio.sleep(10)
                continue
            targets = _notification_targets()
            for req in pending:
                rid = int(req.get("id") or 0)
                if not rid:
                    continue
                if not targets:
                    # No admin chat configured yet — leave un-notified, retry later; still visible
                    # in the inbox screen.
                    continue
                text = _safe_text(_tpc3c_request_text(req))
                buttons = _tpc3c_request_decision_buttons(rid)
                ok_any = False
                for chat_id in targets:
                    try:
                        await client.send_message(int(chat_id), text, buttons=buttons)
                        ok_any = True
                    except Exception:
                        pass
                if ok_any:
                    try:
                        _screq_mark_notified(rid, db_path=TPILOT_DB_PATH)
                    except Exception:
                        pass
            await asyncio.sleep(5)
        except asyncio.CancelledError:
            return
        except Exception:
            await asyncio.sleep(15)
# --- TPILOT PATCH C3C: schedule-request push + approval inbox 20260623 END ---


