@client.on(events.CallbackQuery)
async def _blovr_callback(event):
    """Handle AdminBot bizlink schedule-override confirmation (blovr: callbacks)."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("blovr:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        parts = data.split(":")
        action = parts[1] if len(parts) > 1 else ""
        if action == "n":
            await _pb_safe_answer(event, "Отменено")
            try:
                await client.edit_message(
                    chat_id, _event_message_id(event),
                    "❌ Создание ссылок отменено.",
                    buttons=_back_to_panel_buttons(),
                )
            except Exception:
                pass
            return
        if action != "y" or len(parts) < 5:
            await _pb_safe_answer(event, )
            return
        blovr_mk = parts[2]
        blovr_slot = parts[3]
        blovr_date = parts[4]
        if not blovr_mk or not blovr_slot or not blovr_date:
            await _pb_safe_answer(event, "Ошибка: неполные данные", alert=True)
            return
        await _panel_answer_fast(event, "⏳ Запускаю без графика...")
        override_cmd = f"/bizlink_create_one {blovr_mk} {blovr_slot} {blovr_date} force"
        status_msg_id = await _panel_status_send(
            chat_id,
            f"⏳ Создаю ссылку для {blovr_mk} на {blovr_date} (без графика)...",
            override_cmd,
        )
        _panel_spawn_command_task(override_cmd, user_id, chat_id, status_msg_id)
    except Exception as _blovr_exc:
        print(f"[bizlink-override] callback error: {_blovr_exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

