# --- TPILOT LLM F1 UI Stage F1 20260624 START ---
# Read-only PanelBot dashboard for LLM auto-status audit.
# Reads llm_auto_status from each per-manager DB in mode=ro.
# Does NOT write to any DB. Does NOT change statistics or statuses.
# Fail-open per manager: missing file/table/error -> silently skip.

_LLM_STATUS_PERIOD_LABELS = {
    "today": "Сегодня",
    "yesterday": "Вчера",
    "week": "Неделя",
    "month": "Месяц",
}

_LLM_STATUS_NORM_MAP = {
    "liquid": "liquid",
    "geo": "geo",
    "under18": "under18",
    "na": "na",
    "na_pending": "na",
    "trash": "trash",
    "pending": "na",
    "no_action": "na",
    "wait": "na",
}

_LLM_STATUS_ICONS = {
    "liquid": "🟢",
    "geo": "🌍",
    "under18": "🔞",
    "na": "⚪",
    "trash": "🗑",
}

_LLM_STATUS_DISPLAY = {
    "liquid": "liquid",
    "geo": "geo",
    "under18": "-18",
    "na": "NA",
    "trash": "trash",
}

_LLM_STATUS_BUCKETS = ["liquid", "geo", "under18", "na", "trash"]


def _llm_status_normalize(raw: str) -> str:
    s = str(raw or "").strip().lower()
    return _LLM_STATUS_NORM_MAP.get(s, "na")


def _llm_status_period_dates(period: str):
    """Return (date_from_iso, date_to_iso) for the given period."""
    today = _sched_pb_kyiv_today()
    if period == "yesterday":
        d = today - timedelta(days=1)
        return d.isoformat(), d.isoformat()
    elif period == "week":
        return (today - timedelta(days=6)).isoformat(), today.isoformat()
    elif period == "month":
        return (today - timedelta(days=29)).isoformat(), today.isoformat()
    else:
        return today.isoformat(), today.isoformat()


def _tp_llm_status_read_period(period: str = "today") -> dict:
    """Aggregate llm_auto_status data from all per-manager DBs for the given period.
    Returns dict with totals, per-manager data, control counters.
    Strictly read-only. Never raises."""
    try:
        date_from, date_to = _llm_status_period_dates(period)
        managers = list_manager_rows_from_db_sync(TPILOT_DB_PATH, include_removed=False)
        totals: dict = {b: 0 for b in _LLM_STATUS_BUCKETS}
        totals["total"] = 0
        control: dict = {"manual_present": 0, "needs_review": 0}
        by_manager: dict = {}
        for mgr in managers:
            mk = str(mgr.get("manager_key") or "").strip()
            if not mk:
                continue
            # --- TPILOT TRANSFERS STAGE1 N-1 FIX START ---
            if str(mgr.get("role") or "manager").strip().lower() == "closer":
                continue
            # --- TPILOT TRANSFERS STAGE1 N-1 FIX END ---
            display_name = str(mgr.get("display_name") or "").strip() or mk
            try:
                paths = build_manager_paths(str(BASE_DIR), mk)
                db_path = paths.get("db_path") or ""
                if not db_path:
                    continue
                import os as _os
                if not _os.path.isfile(db_path):
                    continue
                con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True, timeout=2)
                con.row_factory = sqlite3.Row
                try:
                    tbl = con.execute(
                        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='llm_auto_status' LIMIT 1"
                    ).fetchone()
                    if not tbl:
                        continue
                    rows = con.execute(
                        "SELECT llm_auto_status, manual_status, agrees_with_manager"
                        " FROM llm_auto_status WHERE lead_date >= ? AND lead_date <= ?",
                        (date_from, date_to),
                    ).fetchall()
                    rows = [dict(r) for r in rows]
                finally:
                    con.close()
            except Exception:
                continue
            if not rows:
                continue
            mgr_counts: dict = {b: 0 for b in _LLM_STATUS_BUCKETS}
            mgr_total = 0
            for r in rows:
                bucket = _llm_status_normalize(r.get("llm_auto_status") or "")
                mgr_counts[bucket] += 1
                mgr_total += 1
                totals[bucket] += 1
                totals["total"] += 1
                if str(r.get("manual_status") or "").strip():
                    control["manual_present"] += 1
                if r.get("agrees_with_manager") == 0:
                    control["needs_review"] += 1
            by_manager[mk] = {
                "display_name": display_name,
                "counts": mgr_counts,
                "total": mgr_total,
            }
        return {
            "period": period,
            "date_from": date_from,
            "date_to": date_to,
            "totals": totals,
            "control": control,
            "by_manager": by_manager,
        }
    except Exception:
        return {
            "period": period, "date_from": "", "date_to": "",
            "totals": {"total": 0}, "control": {}, "by_manager": {},
        }


def _tp_llm_status_screen_text(period: str = "today") -> str:
    """Format llm_auto_status as a professional dashboard Telegram message (<= 4096 chars). Never raises."""
    try:
        _md_safe = lambda s: str(s).replace("_", " ").replace("*", "").replace("`", "")
        data = _tp_llm_status_read_period(period)
        period_label = _LLM_STATUS_PERIOD_LABELS.get(period, "Сегодня")
        t = data.get("totals") or {}
        ctrl = data.get("control") or {}
        by_mgr = data.get("by_manager") or {}
        total = int(t.get("total") or 0)

        lines = [
            f"📊 LLM наблюдения audit — {period_label}",
            "Это не отчёт менеджеров: считается по lead_date и включает незавершённые наблюдения.",
            "",
        ]

        if total == 0:
            lines += [
                "За выбранный период LLM ещё не обработал лидов.",
                "",
                "ℹ️ Экран read-only. Боевые статусы и статистика не меняются.",
            ]
            return "\n".join(lines)

        lines.append(f"ИТОГО — {total}")
        for bucket in _LLM_STATUS_BUCKETS:
            icon = _LLM_STATUS_ICONS[bucket]
            label = _LLM_STATUS_DISPLAY[bucket]
            lines.append(f"{icon} {label}: {t.get(bucket, 0)}")

        sorted_mgrs = sorted(by_mgr.items(), key=lambda x: -x[1]["total"])
        hidden = 0
        for mk, mgr_data in sorted_mgrs:
            dname = _md_safe(mgr_data.get("display_name") or mk)
            counts = mgr_data.get("counts") or {}
            mgr_total = mgr_data.get("total") or 0
            block_lines = ["", f"{dname} — {mgr_total}"]
            for bucket in _LLM_STATUS_BUCKETS:
                icon = _LLM_STATUS_ICONS[bucket]
                label = _LLM_STATUS_DISPLAY[bucket]
                block_lines.append(f"{icon} {label}: {counts.get(bucket, 0)}")
            if len("\n".join(lines + block_lines)) > 3750:
                hidden += 1
                continue
            lines += block_lines

        if hidden:
            lines += ["", f"... ещё {hidden} менеджеров скрыто"]

        manual_present = int(ctrl.get("manual_present") or 0)
        needs_review = int(ctrl.get("needs_review") or 0)
        without_manual = total - manual_present
        lines += [
            "",
            "Контроль:",
            f"  Ручной статус есть: {manual_present}",
            f"  Без ручного статуса: {without_manual}",
            f"  Расхождений LLM↔детерминизм: {needs_review}",
            "",
            "ℹ️ Экран read-only. Боевые статусы и статистика не меняются.",
        ]

        text = "\n".join(lines)
        if len(text) > 4000:
            text = text[:3980] + "\n...(обрезано)"
        return text
    except Exception:
        return "Ошибка загрузки данных LLM автостатусов.\n\nℹ️ Экран read-only. Боевые статусы и статистика не меняются."


def _tp_llm_status_buttons(period: str = "today") -> list:
    curr_cb = f"menu:llm_status:{period}".encode()
    return [
        [
            Button.inline("Сегодня", b"menu:llm_status:today"),
            Button.inline("Вчера", b"menu:llm_status:yesterday"),
        ],
        [
            Button.inline("Неделя", b"menu:llm_status:week"),
            Button.inline("Месяц", b"menu:llm_status:month"),
        ],
        [Button.inline("🔄 Обновить", curr_cb)],
        [Button.inline("⬅️ Назад", b"menu:reports_control"), Button.inline("🏠 Главная", b"menu:main")],
    ]


_TPLLMF1_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu):  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "llm_status" or raw.startswith("llm_status:"):
        parts = raw.split(":", 1)
        period = parts[1] if len(parts) > 1 else "today"
        if period not in _LLM_STATUS_PERIOD_LABELS:
            period = "today"
        text = _tp_llm_status_screen_text(period)
        if _pb_get_setting("llm_supervisor_enabled") == "0":
            text = "⚠️ LLM выключен — новые наблюдения не создаются.\n\n" + text
        return text, _tp_llm_status_buttons(period)
    if raw == "llm_toggle":
        # N4 fix (Part B): this used to flip llm_supervisor_enabled
        # immediately and unconditionally on every click -- the exact unsafe
        # pattern N3/N3.1 eliminated for the canonical NM route. No second
        # toggle implementation is created here: any historical
        # "menu:llm_toggle" button (old Telegram messages, or the still-live
        # old-menu Reports screen) now renders the SAME canonical,
        # target-encoded, stale-safe confirm screen as
        # menu:nm_llm_toggle_confirm, built from fresh current state --
        # nothing is mutated by opening this screen; the actual flip still
        # only happens via nm_llm_toggle_do:{target} after confirmation.
        return _nm_llm_toggle_confirm_text(), _nm_llm_toggle_confirm_buttons()
    if callable(_TPLLMF1_PREV_TITLE_FOR_MENU):
        return _TPLLMF1_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []

