def _bld_compute_off_schedule(date_iso: str, mks: list) -> list:
    """Off-schedule subset of mks for date_iso. Fail-open (empty off list) if the schedule
    helper is unavailable, errors, or has no rows for this date at all -- exactly mirrors
    _bizlink_manual_schedule_working_keys' semantics in main.py (empty working set = no
    restriction, nobody blocked)."""
    try:
        if not callable(_sched_pb_working_date):
            return []
        working = _sched_pb_working_date(date_iso, TPILOT_DB_PATH)
        working_keys = {normalize_manager_key(k) for k in (working or [])}
        if not working_keys:
            return []
        return [mk for mk in mks if mk not in working_keys]
    except Exception:
        return []


def _bld_confirm_text(payload: dict) -> str:
    date_disp = _bld_fmt_date(payload.get("date") or "")
    mks = list(payload.get("mks") or [])
    count = int(payload.get("count") or 15)
    off = set(payload.get("off") or [])
    labels_by_key: Dict[str, str] = {}
    try:
        for r in _manager_rows(only_active=True, only_enabled=True, exclude_closers=True):
            labels_by_key[normalize_manager_key(r.get("manager_key") or "")] = _manager_short_label(r)
    except Exception:
        pass
    lines = [
        _panel_header(),
        "",
        "🔗 Ссылки на дату — подтверждение",
        "",
        f"Дата: {date_disp}",
        f"Количество ссылок: {count}",
        f"Менеджеров: {len(mks)}",
        "",
    ]
    for mk in mks:
        label = labels_by_key.get(mk, mk)
        lines.append(f"📅 {label} — не в графике" if mk in off else f"✅ {label} — по графику")
    if off:
        lines.append("")
        lines.append(f"⚠️ {len(off)} менеджер(ов) не в графике на эту дату.")
    return "\n".join(lines).rstrip()


