# --- TPILOT BDD DELETE-BY-DATE START ---
# AdminBot wizard: delete business/source links for an arbitrary selected date across
# multiple selected managers. Date-first, mirrors the bld: create wizard's UX/plumbing but
# reuses the EXISTING single-manager delete primitives -- the by_date candidate selector
# (_bsd3a_select_pb), the single-use DB-backed preview (_bsd3a_preview_create_pb), and the
# existing /bizlink_delete_tpilot command (real Telegram-side DeleteBusinessChatLinkRequest,
# expired-slug soft-delete already handled inside _manager_delete_business_links). No new
# deletion primitive, no schema changes. Does not touch bld:* (create-by-date) or bizdel:*
# (the old single-manager delete flow) -- both keep working unchanged.

_BDD_CMD_HARD_TIMEOUT_SEC = 1200  # hard cap while polling one manager's panel_commands row
_BDD_PROGRESS: Dict[str, dict] = {}  # in-memory only, same rationale as _BLD_PROGRESS


def _bdd_month_text(yyyymm: str) -> str:
    try:
        year, month = int(str(yyyymm)[:4]), int(str(yyyymm)[4:6])
    except Exception:
        today = _sched_pb_kyiv_today()
        year, month = today.year, today.month
    month_name = _SCHED_PB_MONTH_NAMES[month] if 1 <= month <= 12 else ""
    return "\n".join([
        _panel_header(),
        "",
        "🗑 Удалить ссылки по дате",
        "",
        f"Месяц: {month_name} {year}",
        "Выберите дату (доступна любая дата, включая прошедшие).",
    ])


def _bdd_month_buttons(yyyymm: str) -> list:
    # Unlike bld: (create), any date -- past, today, or future -- is selectable: deletion
    # targets links that were already created, which are typically on past/near dates.
    try:
        year, month = int(str(yyyymm)[:4]), int(str(yyyymm)[4:6])
    except Exception:
        today0 = _sched_pb_kyiv_today()
        year, month = today0.year, today0.month
    rows = []
    hdr_labels = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"]
    rows.append([Button.inline(d, b"bdd:noop") for d in hdr_labels])
    cal = _sched_pb_cal_mod.Calendar(firstweekday=0)
    for week in cal.monthdayscalendar(year, month):
        row = []
        for day in week:
            if day == 0:
                row.append(Button.inline(" ", b"bdd:noop"))
                continue
            cb = "bdd:d:{:04d}{:02d}{:02d}".format(year, month, day).encode("utf-8")
            if len(cb) > 64:
                cb = b"bdd:noop"
            row.append(Button.inline(str(day), cb))
        rows.append(row)
    prev_y, prev_m = (year, month - 1) if month > 1 else (year - 1, 12)
    next_y, next_m = (year, month + 1) if month < 12 else (year + 1, 1)
    rows.append([
        Button.inline("⬅️", "bdd:cal:{:04d}{:02d}".format(prev_y, prev_m).encode("utf-8")),
        Button.inline("➡️", "bdd:cal:{:04d}{:02d}".format(next_y, next_m).encode("utf-8")),
    ])
    rows.append([Button.inline("⬅️ Назад", b"menu:nm_bizlinks_delete")])
    return rows


def _bdd_pick_text(payload: dict) -> str:
    date_disp = _bld_fmt_date(payload.get("date") or "")
    n = len(payload.get("mks") or [])
    return "\n".join([
        _panel_header(),
        "",
        "🗑 Удалить ссылки по дате",
        "",
        f"Дата: {date_disp}",
        f"Выберите менеджеров (выбрано: {n}):",
    ])


def _bdd_pick_buttons(payload: dict) -> list:
    chosen = set(payload.get("mks") or [])
    rows = []
    try:
        mgr_rows = _manager_rows(only_active=True, only_enabled=True, exclude_closers=True)
    except Exception:
        mgr_rows = []
    for r in mgr_rows:
        mk = normalize_manager_key(r.get("manager_key") or "")
        if not mk:
            continue
        mark = "✅" if mk in chosen else "⬜"
        label = f"{mark} {_manager_short_label(r)}"[:40]
        cb = f"bdd:m:{mk}".encode("utf-8")
        if len(cb) > 64:
            continue
        rows.append([Button.inline(label, cb)])
    rows.append([
        Button.inline("Выбрать всех", b"bdd:all"),
        Button.inline("Снять всех", b"bdd:none"),
    ])
    rows.append([Button.inline(f"➡️ Далее ({len(chosen)})", b"bdd:toconfirm")])
    rows.append([
        Button.inline("⬅️ Назад", b"menu:bdd_date"),
        Button.inline("❌ Отмена", b"bdd:x"),
    ])
    return rows


def _bdd_confirm_counts(payload: dict) -> Dict[str, int]:
    """Per-manager found-link counts for the selected date. Cheap local SQLite selects via
    the existing by_date candidate selector -- no Telegram calls, no side effects."""
    date_iso = str(payload.get("date") or "")
    mks = list(payload.get("mks") or [])
    counts: Dict[str, int] = {}
    for mk in mks:
        try:
            cand = _bsd3a_select_pb(mk, "by_date", target_date=date_iso, db_path=TPILOT_DB_PATH) or []
        except Exception:
            cand = []
        counts[mk] = len(cand)
    return counts


def _bdd_confirm_text(payload: dict) -> str:
    date_iso = str(payload.get("date") or "")
    mks = list(payload.get("mks") or [])
    date_disp = _bld_fmt_date(date_iso)
    counts = _bdd_confirm_counts(payload)
    total = sum(counts.values())
    labels_by_key: Dict[str, str] = {}
    try:
        for r in _manager_rows(only_active=True, only_enabled=True, exclude_closers=True):
            labels_by_key[normalize_manager_key(r.get("manager_key") or "")] = _manager_short_label(r)
    except Exception:
        pass
    lines = [
        _panel_header(),
        "",
        "🗑 Удалить ссылки по дате",
        "",
        f"Дата: {date_disp}",
        f"Менеджеров выбрано: {len(mks)}",
        "",
    ]
    for mk in mks:
        label = labels_by_key.get(mk, mk)
        lines.append(f"{label} — найдено: {counts.get(mk, 0)}")
    lines.append("")
    lines.append(f"Всего ссылок к удалению: {total}")
    lines.append("")
    if total > 0:
        lines.append("⚠️ Ссылки будут удалены в Telegram и помечены удалёнными в БД.")
        lines.append("Действие необратимо.")
    else:
        lines.append("Ссылок на эту дату не найдено ни у одного из выбранных менеджеров.")
    return "\n".join(lines).rstrip()


def _bdd_confirm_buttons(payload: dict) -> list:
    counts = _bdd_confirm_counts(payload)
    total = sum(counts.values())
    rows = []
    if total > 0:
        rows.append([Button.inline("✅ Да, удалить", b"bdd:go")])
        rows.append([
            Button.inline("⬅️ Назад", b"bdd:backpick"),
            Button.inline("❌ Отмена", b"bdd:x"),
        ])
    else:
        rows.append([
            Button.inline("↩️ Назад", b"bdd:backpick"),
            Button.inline("❌ Отмена", b"bdd:x"),
        ])
    return rows


def _bdd_new_progress(date_iso: str, total: int) -> dict:
    return {
        "date": date_iso,
        "total": total,
        "done": 0,
        "current_mk": "",
        "stage": "",
        "started_at": _panel_loop_time(),
        "mgr_started_at": 0.0,
        "cmd_id": 0,
        # Set by bdd:go BEFORE the batch task is spawned -- so _bdd_run_batch reuses that
        # same message instead of sending a second, duplicate progress card.
        "chat_id": 0,
        "status_msg_id": 0,
        "finished": False,
        "report": None,
        "counts": {"deleted": 0, "expired": 0, "failed": 0, "notfound": 0, "timeout": 0},
    }


def _bdd_progress_text(progress: dict) -> str:
    date_disp = _bld_fmt_date(progress.get("date") or "")
    total = int(progress.get("total") or 0)
    done = int(progress.get("done") or 0)
    current = str(progress.get("current_mk") or "-")
    stage = str(progress.get("stage") or "") or "-"
    started_at = float(progress.get("started_at") or 0.0)
    elapsed = max(0, int(_panel_loop_time() - started_at)) if started_at else 0
    mgr_started_at = float(progress.get("mgr_started_at") or 0.0)
    mgr_elapsed = max(0.0, _panel_loop_time() - mgr_started_at) if mgr_started_at else 0.0
    estimate = 60  # seconds per manager -- delete is fast (preview + a handful of deletes)

    if mgr_started_at and mgr_elapsed > estimate:
        # Running well past the per-manager estimate almost always means tg_limit's own
        # cleanup/expired-slug handling is doing extra work inside the delete primitive.
        remaining_min = max(1, (int(_BDD_CMD_HARD_TIMEOUT_SEC - mgr_elapsed) + 59) // 60)
        remaining_line = f"Осталось примерно: дольше обычного, до {remaining_min} мин"
        stage = "удаляю ссылки (дольше обычного)"
    else:
        current_remaining = max(estimate - mgr_elapsed, 10) if mgr_started_at else estimate
        future_remaining = max(total - done - 1, 0) * estimate
        remaining_total = current_remaining + future_remaining
        remaining_line = f"Осталось примерно: {_bld_fmt_eta(remaining_total)}"

    lines = [
        _panel_header(),
        "",
        "🗑 Удаление ссылок по дате",
        "",
        f"Дата: {date_disp}",
        f"Менеджеров: {total}",
        "",
        f"Готово: {done}/{total}",
        f"Сейчас: {current}",
        f"Этап: {stage}",
        remaining_line,
        f"Прошло: {_bld_fmt_eta(elapsed)}",
    ]
    return "\n".join(lines).rstrip()


def _bdd_progress_buttons(batch_id: str) -> list:
    return [[Button.inline("🔄 Обновить", f"bdd:refresh:{batch_id}".encode("utf-8"))]]


async def _bdd_poll_command(cmd_id: int, progress: dict, chat_id: int, status_msg_id: int,
                             batch_id: str) -> dict:
    """Poll panel_commands for cmd_id until done/error or the hard timeout. Mirrors
    _bld_poll_command's safe patterns exactly, scoped to this wizard's own progress dict
    and hard-timeout constant. Never raises."""
    start = _panel_loop_time()
    last_edit = start
    while True:
        try:
            row = get_panel_command(TPILOT_DB_PATH, cmd_id)
        except Exception:
            row = None
        if row and str(row.get("status") or "") in ("done", "error"):
            return row
        now = _panel_loop_time()
        if now - start >= _BDD_CMD_HARD_TIMEOUT_SEC:
            return {"status": "hard_timeout", "cmd_id": cmd_id}
        if now - last_edit >= 30:
            last_edit = now
            try:
                await _bld_status_edit(
                    chat_id, status_msg_id, _bdd_progress_text(progress), buttons=_bdd_progress_buttons(batch_id),
                )
            except Exception:
                pass
        await asyncio.sleep(5)


async def _bdd_run_batch(chat_id: int, user_id: int, date_iso: str, run_mks: list, batch_id: str) -> None:
    """Batch runner: one status message for the whole run, sequential per-manager
    preview+/bizlink_delete_tpilot calls via the existing panel_commands queue. Each manager
    gets its own single-use preview (atomic consume -- existing safety, unrelated managers
    can never be double-processed). A single manager's failure never aborts the batch."""
    date_disp = _bld_fmt_date(date_iso)
    total = len(run_mks)
    labels_by_key: Dict[str, str] = {}
    try:
        for r in _manager_rows(only_active=True, only_enabled=True, exclude_closers=True):
            labels_by_key[normalize_manager_key(r.get("manager_key") or "")] = _manager_short_label(r)
    except Exception:
        pass
    progress = _BDD_PROGRESS.setdefault(batch_id, _bdd_new_progress(date_iso, total))
    # Reuse the single progress card the callback already created/edited (its message id is
    # stored in progress["status_msg_id"] before this task was spawned) -- never send a
    # second, duplicate card here. Only fall back to sending a new one if that's somehow
    # missing (defensive: this task invoked outside the normal bdd:go callback path).
    status_msg_id = int(progress.get("status_msg_id") or 0)
    if status_msg_id:
        try:
            await _bld_status_edit(
                chat_id, status_msg_id, _bdd_progress_text(progress), buttons=_bdd_progress_buttons(batch_id),
            )
        except Exception:
            pass
    else:
        status_msg_id = await _bld_status_send(chat_id, _bdd_progress_text(progress), buttons=_bdd_progress_buttons(batch_id))
        progress["status_msg_id"] = status_msg_id
        progress["chat_id"] = chat_id
    results: List[str] = []
    counts = progress["counts"]
    single_mgr_full_text = None  # sent as a separate message after the report (single-manager batch only)

    done = 0
    for mk in run_mks:
        progress["current_mk"] = labels_by_key.get(mk, mk)
        progress["stage"] = "удаляю ссылки"
        try:
            await _bld_status_edit(
                chat_id, status_msg_id, _bdd_progress_text(progress), buttons=_bdd_progress_buttons(batch_id),
            )
        except Exception:
            pass

        try:
            candidates = _bsd3a_select_pb(mk, "by_date", target_date=date_iso, db_path=TPILOT_DB_PATH) or []
        except Exception:
            candidates = []
        if not candidates:
            counts["notfound"] += 1
            results.append(f"— {mk}: ссылок на дату не найдено")
            done += 1
            progress["done"] = done
            continue

        try:
            preview_id = _bsd3a_preview_create_pb(
                mk, "by_date", candidates,
                target_date=date_iso,
                requested_by_user_id=user_id,
                ttl_seconds=600,
                db_path=TPILOT_DB_PATH,
            )
        except Exception as exc:
            counts["failed"] += 1
            results.append((f"❌ {mk} — ошибка создания preview: {exc!r}")[:120])
            done += 1
            progress["done"] = done
            continue

        cmd = f"/bizlink_delete_tpilot {preview_id}"
        try:
            cmd_id = submit_panel_command(
                TPILOT_DB_PATH, cmd,
                requested_by=int(user_id or 0),
                source_chat_id=int(chat_id or 0),
                response_chat_id=int(chat_id or 0),
            )
            progress["cmd_id"] = cmd_id
            progress["mgr_started_at"] = _panel_loop_time()
            row = await _bdd_poll_command(cmd_id, progress, chat_id, status_msg_id, batch_id)
            progress["stage"] = "обработка результата"
            status = str(row.get("status") or "")
            result_text = str(row.get("result_text") or row.get("result") or "").strip()
            if status == "hard_timeout":
                counts["timeout"] += 1
                results.append(f"⌛ {mk} — выполняется дольше 20 мин (cmd #{cmd_id})")
            elif status in ("done", "error"):
                has_deleted_marker = "Удалено:" in result_text
                if status == "error" and not has_deleted_marker:
                    counts["failed"] += 1
                    extra = f": {result_text[:80]}" if result_text else ""
                    results.append(f"❌ {mk} — ошибка удаления{extra}")
                else:
                    n_deleted = 0
                    n_expired = 0
                    n_failed = 0
                    try:
                        m = re.search(r"Удалено:\s*(\d+)", result_text)
                        if m:
                            n_deleted = int(m.group(1))
                        m = re.search(r"Вычищено мёртвых:\s*(\d+)", result_text)
                        if m:
                            n_expired = int(m.group(1))
                        m = re.search(r"Ошибок:\s*(\d+)", result_text)
                        if m:
                            n_failed = int(m.group(1))
                    except Exception:
                        pass
                    counts["deleted"] += n_deleted
                    counts["expired"] += n_expired
                    counts["failed"] += n_failed
                    results.append(f"🗑 {mk} — удалено {n_deleted}, мёртвых {n_expired}, ошибок {n_failed}")
                    if total == 1:
                        single_mgr_full_text = result_text
            else:
                counts["failed"] += 1
                results.append(f"❌ {mk} — ошибка удаления")
        except Exception as exc:
            counts["failed"] += 1
            results.append((f"❌ {mk} — {exc!r}")[:120])
        done += 1
        progress["done"] = done

    report_lines = [
        "🗑 Удаление ссылок по дате — отчёт",
        f"Дата: {date_disp}",
        "",
    ]
    report_lines.extend(results)
    report_lines.append("")
    report_lines.append(
        f"Итого: удалено {counts['deleted']} · мёртвых {counts['expired']} · "
        f"ошибок {counts['failed']} · не найдено {counts['notfound']} · ⌛ {counts['timeout']}"
    )
    report_text = "\n".join(report_lines)
    report_text = report_text + _nm_error_hint(report_text)
    progress["finished"] = True
    progress["report"] = report_text
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): batch finished,
        # final counts -- terminal.
        await _bld_status_edit(chat_id, status_msg_id, report_text, buttons=_back_to_panel_buttons() + _terminal_ok_button())
    except Exception as exc:
        print(f"[bdd] final report send failed: {exc!r}")

    if single_mgr_full_text:
        # Single-manager batch: send main.py's own full result_text as a separate message
        # so the exact deleted/expired/failed detail is visible, not just the report line.
        try:
            full_text = single_mgr_full_text
            if len(full_text) > 4000:
                full_text = full_text[:3900] + "\n…(обрезано)"
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal detail card.
            await client.send_message(int(chat_id), _safe_text(full_text), buttons=_back_to_panel_buttons() + _terminal_ok_button())
        except Exception as exc:
            print(f"[bdd] single-manager full result send failed: {exc!r}")


_BDD_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str):  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "bdd_date":
        today = _sched_pb_kyiv_today()
        yyyymm = "{:04d}{:02d}".format(today.year, today.month)
        return _bdd_month_text(yyyymm), _bdd_month_buttons(yyyymm)
    if callable(_BDD_PREV_TITLE_FOR_MENU):
        return _BDD_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


@client.on(events.CallbackQuery)
async def _bdd_callback(event):
    """AdminBot-only: date-first multi-manager business-link DELETION wizard. State lives
    in panel_wizard_state (wizard='bdd'), survives restart. Reuses the existing single-use
    preview + /bizlink_delete_tpilot command (real Telegram-side delete, expired-slug
    handling already in _manager_delete_business_links) -- no new deletion primitive, no
    schema changes. Does not touch bld:* (create) or bizdel:* (old single-manager delete)."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("bdd:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        parts = data.split(":")
        action = parts[1] if len(parts) > 1 else ""

        if action == "noop":
            await _pb_safe_answer(event, )
            return

        if action == "cal":
            yyyymm = parts[2] if len(parts) > 2 else ""
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, _bdd_month_text(yyyymm), buttons=_bdd_month_buttons(yyyymm))
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[bdd] month render failed: {exc!r}")
            return

        if action == "d":
            yyyymmdd = parts[2] if len(parts) > 2 else ""
            try:
                d_obj = datetime.strptime(yyyymmdd, "%Y%m%d").date()
            except Exception:
                await _pb_safe_answer(event, "Некорректная дата", alert=True)
                return
            iso = d_obj.isoformat()
            payload = {"date": iso, "mks": []}
            _wizard_set(chat_id, user_id, "bdd", "pick_mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _bdd_pick_text(payload), buttons=_bdd_pick_buttons(payload))
            return

        if action == "refresh":
            # Does NOT require wizard state -- by the time this button exists, the
            # wizard has already been cleared and the batch is running in the background.
            batch_id = parts[2] if len(parts) > 2 else ""
            if not batch_id:
                await _pb_safe_answer(event, "Прогресс недоступен", alert=True)
                return
            prog = _BDD_PROGRESS.get(batch_id)
            if prog is None:
                await _pb_safe_answer(event, )
                try:
                    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): explicitly
                    # says the result will arrive separately -- terminal.
                    await _safe_event_edit(
                        event,
                        "Прогресс недоступен, возможно PanelBot был перезапущен. "
                        "Итог придёт отдельным сообщением.",
                        buttons=_back_to_panel_buttons() + _terminal_ok_button(),
                    )
                except Exception as exc:
                    if "MessageNotModifiedError" not in repr(exc):
                        print(f"[bdd] refresh render failed: {exc!r}")
                return
            await _pb_safe_answer(event, )
            # Self-heal: keep the stored message id in sync with whatever message this
            # refresh button actually lives on (there is only ever one progress card).
            prog["chat_id"] = chat_id
            prog["status_msg_id"] = int(event.message_id or 0)
            try:
                if prog.get("finished"):
                    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): batch
                    # finished, re-displaying the final report -- terminal.
                    await _safe_event_edit(
                        event, str(prog.get("report") or "Готово"), buttons=_back_to_panel_buttons() + _terminal_ok_button(),
                    )
                else:
                    await _safe_event_edit(
                        event, _bdd_progress_text(prog), buttons=_bdd_progress_buttons(batch_id),
                    )
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[bdd] refresh render failed: {exc!r}")
            return

        # Every action below requires existing wizard state.
        wstate = _wizard_get(chat_id, user_id)
        if str(wstate.get("wizard") or "") != "bdd":
            await _pb_safe_answer(event, "Мастер сброшен, начните заново.", alert=True)
            try:
                await _safe_event_edit(event, _bizlinks_menu_text(), buttons=_bizlinks_menu_buttons())
            except Exception:
                pass
            return
        payload = wstate.get("payload") or {}

        if action == "m":
            mk = normalize_manager_key(parts[2] if len(parts) > 2 else "")
            if not mk:
                await _pb_safe_answer(event, )
                return
            mks = list(payload.get("mks") or [])
            if mk in mks:
                mks.remove(mk)
            else:
                mks.append(mk)
            payload["mks"] = mks
            _wizard_set(chat_id, user_id, "bdd", "pick_mgr", payload)
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, _bdd_pick_text(payload), buttons=_bdd_pick_buttons(payload))
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[bdd] pick render failed: {exc!r}")
            return

        if action == "all":
            try:
                mgr_rows = _manager_rows(only_active=True, only_enabled=True, exclude_closers=True)
            except Exception:
                mgr_rows = []
            payload["mks"] = [
                normalize_manager_key(r.get("manager_key") or "") for r in mgr_rows if r.get("manager_key")
            ]
            _wizard_set(chat_id, user_id, "bdd", "pick_mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _bdd_pick_text(payload), buttons=_bdd_pick_buttons(payload))
            return

        if action == "none":
            payload["mks"] = []
            _wizard_set(chat_id, user_id, "bdd", "pick_mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _bdd_pick_text(payload), buttons=_bdd_pick_buttons(payload))
            return

        if action == "toconfirm":
            if not (payload.get("mks") or []):
                await _pb_safe_answer(event, "Выберите хотя бы одного менеджера", alert=True)
                return
            _wizard_set(chat_id, user_id, "bdd", "confirm", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _bdd_confirm_text(payload), buttons=_bdd_confirm_buttons(payload))
            return

        if action == "backpick":
            _wizard_set(chat_id, user_id, "bdd", "pick_mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _bdd_pick_text(payload), buttons=_bdd_pick_buttons(payload))
            return

        if action == "go":
            date_iso = str(payload.get("date") or "")
            mks = list(payload.get("mks") or [])
            if not date_iso or not mks:
                await _pb_safe_answer(event, "Мастер сброшен, начните заново.", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, "bdd:go"):
                await _pb_safe_answer(event, "Уже выполняю...")
                return
            # Clear wizard state BEFORE spawning so a double-click can never start a
            # second deletion batch (the second click hits the "Мастер сброшен" branch).
            _wizard_clear(chat_id, user_id)
            batch_id = uuid.uuid4().hex[:12]
            _BDD_PROGRESS[batch_id] = _bdd_new_progress(date_iso, len(mks))
            # Record THIS message as the one-and-only progress card before spawning the
            # batch task, so _bdd_run_batch edits it in place instead of sending a second,
            # duplicate card (same fix as bld:go).
            _BDD_PROGRESS[batch_id]["chat_id"] = chat_id
            _BDD_PROGRESS[batch_id]["status_msg_id"] = int(event.message_id or 0)
            await _panel_answer_fast(event, "🗑 Запустил")
            try:
                await _safe_event_edit(
                    event,
                    _bdd_progress_text(_BDD_PROGRESS[batch_id]),
                    buttons=_bdd_progress_buttons(batch_id),
                )
            except Exception:
                pass
            task = _pb_track_task(_bdd_run_batch(chat_id, user_id, date_iso, mks, batch_id))
            _PANEL_BACKGROUND_TASKS.add(task)
            task.add_done_callback(lambda t: _PANEL_BACKGROUND_TASKS.discard(t))
            return

        if action in ("no", "x"):
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "Отменено")
            try:
                await _safe_event_edit(event, _bizlinks_menu_text(), buttons=_bizlinks_menu_buttons())
            except Exception:
                pass
            return

        await _pb_safe_answer(event, )
    except Exception as exc:
        print(f"[bdd] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

