# --- TPILOT NM NEW MENU START ---
# Stage 1: a parallel, professional navigation layer on top of the existing AdminBot menu.
# Every nm_* screen is a pure router to an EXISTING screen/command/wizard -- no business
# logic is duplicated or rewritten here. The old menu (_main_menu chain, all menu:/cmd:/
# wiz:/bld:/bdd:/bizdel:/bizdelg:/tr:/trx: routes) is completely untouched and remains the
# primary path; this block only ADDS a "🧭 Новое меню" entry point on top of it.
#
# Navigation model: every nm_* route is served through the existing generic "menu:" handler
# (see the small patch above, right before "if data.startswith('cmd:')"), which already
# does _safe_event_edit(event, ...) -- i.e. edits the current message in place. No new
# CallbackQuery handler is registered for nm_* routes, so there is no risk of duplicate
# progress-card-style bugs here (there is no long-running action in this block at all).

_NM_CATEGORY_PARENTS = {
    "nm_bizlinks_create": "nm_bizlinks",
    "nm_bizlinks_manage": "nm_bizlinks",
    "nm_bizlinks_delete": "nm_bizlinks",
}


def _nm_btn(label: str, data: str):
    """Button.inline with a defensive 64-byte guard (all our own data is short and static,
    so the fallback below should never actually trigger -- it's a safety net only)."""
    raw = str(data or "menu:nm_root").encode("utf-8")
    if len(raw) > 64:
        raw = b"menu:nm_root"
    return Button.inline(label, raw)


def _nm_row(*buttons) -> list:
    return list(buttons)


def _nm_footer(parent: str, refresh_route: str = None) -> list:
    footer = []
    if refresh_route:
        footer.append([_nm_btn("🔄 Обновить", f"menu:{refresh_route}")])
    footer.append([
        _nm_btn("⬅️ Назад", f"menu:{parent}"),
        _nm_btn("🏠 Новое меню", "menu:nm_root"),
    ])
    return footer


def _nm_canonical_path(path: str) -> str:
    """N5.3.1 (owner decision 13/14): nested canonical breadcrumbs use
    canonical names only, rooted at «Главная» -- never «Админ-бот», never
    «Новое меню»/«Старое меню». Applied centrally here so every _nm_screen
    caller's historical "Админ-бот → Новое меню → X" path renders as
    "Главная → X" without touching each call site."""
    p = str(path or "").strip()
    if p.startswith("Админ-бот → Новое меню"):
        p = "Главная" + p[len("Админ-бот → Новое меню"):]
    elif p.startswith("Админ-бот"):
        p = "Главная" + p[len("Админ-бот"):]
    return p


def _nm_screen(title_upper: str, path: str, hint: str, rows: list,
               parent: str = "nm_root", refresh_route: str = None) -> Tuple[str, list]:
    """Common screen template: bold uppercase header, breadcrumb path, italic muted hint
    (Telegram has no true gray text, so italics are the visual stand-in), then the
    caller's action rows, then the standard ⬅️ Назад / 🏠 Новое меню footer."""
    lines = [
        _panel_header(),
        "",
        f"**{title_upper}**",
        "",
        "Путь:",
        _nm_canonical_path(path),
        "",
        f"*{hint}*",
    ]
    text = "\n".join(lines).rstrip()
    all_rows = list(rows) + _nm_footer(parent, refresh_route)
    return text, all_rows


