def _nm_manager_delete_screen() -> Tuple[str, list]:
    # --- TPILOT NM2 PHASE N5.2 Part A + N5.3 Part E: stop/delete selection screen. ---
    # The root's «⏸ Остановка и удаление» button opens THIS screen. It is a pure
    # selector, nothing more:
    #   - manager inclusion rule is copied verbatim from the existing canonical list
    #     (_manager_settings_buttons: skip status == "archived", same key/label/badge
    #     construction via _manager_settings_state) -- not invented here;
    #   - every manager button lands on the thin FIRST-DECISION screen
    #     (menu:nm_mgr_decision:{key} -> _nm_mgr_decision_screen), which offers
    #     exactly two directions: the safe lifecycle stop (existing confirm-gated
    #     menu:manager_disable_confirm:) and the protected full deletion (existing
    #     guard:delete: password+backup flow) -- never the whole danger-zone
    #     collection (N5.3 owner decision);
    #   - no /manager_delete_full, /manager_remove, reset or db-clear command is
    #     emitted from this screen or from the root button; no guard action is
    #     called directly; nothing is written to the DB here; no password/backup
    #     logic is duplicated.
    # Navigation is intentionally flat: both Back and Home return to menu:main
    # (per owner spec), since this screen sits directly one level under root.
    rows_all = _manager_rows_all()
    visible = [r for r in rows_all if str(dict(r).get("status") or "").lower() != "archived"]
    rows = []
    for r in visible:
        d = dict(r)
        key = normalize_manager_key(d.get("manager_key") or "")
        if not key:
            continue
        _, badge_full = _manager_settings_state(d)
        badge = badge_full.split(" ", 1)[0]
        label = str(d.get("display_name") or key).strip()
        text = f"{badge} {label}"
        if len(text) > 42:
            text = text[:39] + "..."
        rows.append(_nm_row(_nm_btn(text, f"menu:nm_mgr_decision:{key}")))
    rows.append(_nm_row(_nm_btn("⬅️ Назад", "menu:main"), _nm_btn("🏠 Главная", "menu:main")))
    lines = [
        _panel_header(),
        "",
        "**⏸ ОСТАНОВКА И УДАЛЕНИЕ МЕНЕДЖЕРА**",
        "",
        "Путь:",
        "Главная → Остановка и удаление",
        "",
        "Выберите менеджера. Ничего не произойдёт сразу: дальше будет выбор — "
        "остановить менеджера или удалить его полностью (с паролем и обязательным "
        "подтверждением).",
    ]
    if not visible:
        lines += ["", "Менеджеры не найдены."]
    return "\n".join(lines).rstrip(), rows


def _nm_mgr_decision_screen(key: str) -> Tuple[str, list]:
    # --- TPILOT N5.3 Part E: first decision screen of the stop/delete flow. ---
    # Exactly two directions, both EXISTING protected flows reused verbatim:
    #   1. Safe lifecycle stop -- menu:manager_disable_confirm:{key} (the N2
    #      confirm-gated /manager_disable flow: kills the process AND sets
    #      is_enabled=0, the "sticky" safe stop per main.py semantics). If the
    #      manager is already off/stopped, the start action is offered instead
    #      (cmd:/manager_start, same as the unified card -- NOT /manager_enable,
    #      which never spawns the process).
    #   2. Full deletion -- guard:delete:{key} (existing choice screen
    #      «заменить/просто удалить» -> danger_password wizard ->
    #      /manager_delete_full with password validated in main.py; runtime
    #      folder is backed up + tombstoned before the hard delete).
    # The rest of the danger-zone collection (db_clear/reset/restore) is NOT
    # shown here -- it stays in the unified card's «🧨 Опасные действия»
    # (N5.3 owner decision: the root flow must not expose the cluttered
    # technical danger menu). This screen emits no destructive command itself.
    key = normalize_manager_key(key or "")
    row = _manager_row_by_key(key)
    if not row:
        text = "\n".join([
            _panel_header(), "",
            "**⏸ ОСТАНОВКА И УДАЛЕНИЕ**", "",
            f"Менеджер не найден: {key}",
        ]).rstrip()
        return text, [_nm_row(_nm_btn("⬅️ Назад", "menu:nm_manager_delete"), _nm_btn("🏠 Главная", "menu:main"))]
    state, status_badge = _manager_settings_state(row)
    label = str(dict(row).get("display_name") or key).strip()
    rows = []
    if state == "on":
        rows.append(_nm_row(_nm_btn("⏸ Остановить менеджера", f"menu:manager_disable_confirm:{key}")))
    else:
        rows.append(_nm_row(_nm_btn("▶️ Включить менеджера", f"cmd:/manager_start {key}")))
    rows.append(_nm_row(_nm_btn("🗑 Полное удаление", f"guard:delete:{key}")))
    rows.append(_nm_row(_nm_btn("⬅️ Назад", "menu:nm_manager_delete"), _nm_btn("🏠 Главная", "menu:main")))
    text = "\n".join([
        _panel_header(),
        "",
        "**⏸ ОСТАНОВКА И УДАЛЕНИЕ**",
        "",
        "Путь:",
        f"Главная → Остановка и удаление → {label}",
        "",
        f"Менеджер: {label}",
        f"Статус: {status_badge}",
        "",
        "Остановка выключает менеджера без потери данных (можно включить обратно). "
        "Полное удаление — только через пароль администратора и резервную копию. "
        "Остальные технические действия — в карточке менеджера, раздел "
        "«🧨 Опасные действия».",
    ]).rstrip()
    return text, rows


