def _nm_automation_screen() -> Tuple[str, list]:
    _nm_llm_val = _pb_get_setting("llm_supervisor_enabled")
    _nm_llm_btn_label = "🔴 LLM: ВЫКЛ" if _nm_llm_val == "0" else "🟢 LLM: ВКЛ"
    # N5 fix (menu_parity gate): auto-status status+toggle was reachable ONLY
    # from the old Automation screen (_tp_visual_automation_menu, :6760-6770)
    # -- with the new root now primary as of this phase, that left the
    # capability completely unreachable from /panel. Same exact state read
    # and target-encoded confirm route as the old screen / N3's canonical
    # flow (menu:autostatus_toggle_confirm:{target}, autostatus_status_info)
    # -- no toggle logic touched, purely a missing navigation link.
    _autostatus_val = _pb_get_setting("auto_status_enabled")
    _autostatus_on = _autostatus_val != "0"
    _autostatus_status_line = "🟢 Автоматический статус: ВКЛ" if _autostatus_on else "🔴 Автоматический статус: ВЫКЛ"
    _autostatus_label = "⏸ Выключить автостатусы" if _autostatus_on else "▶️ Включить автостатусы"
    _autostatus_target = "0" if _autostatus_on else "1"
    rows = [
        _nm_row(_nm_btn("💬 Автоответы", "menu:managers"), _nm_btn("🔥 Автодожимы", "menu:followups")),
        _nm_row(_nm_btn("📝 Тексты и задержки", "menu:content"), _nm_btn("🤫 Аварийная тишина", "menu:profile")),
        _nm_row(_nm_btn("👋 Приветствия", "cmd:/greeting status all"), _nm_btn("📋 Автоанкета", "cmd:/questionnaire status all")),
        _nm_row(_nm_btn("🗓 Автографики", "cmd:/autoschedule status all"), _nm_btn("✅ Проверка анкет", "menu:profile_check")),
        _nm_row(_nm_btn("🤖 LLM: наблюдения", "menu:nm_llm_status"), _nm_btn(_nm_llm_btn_label, "menu:nm_llm_toggle_confirm")),
        _nm_row(_nm_btn(_autostatus_status_line, "autostatus_status_info")),
        _nm_row(_nm_btn(_autostatus_label, f"menu:autostatus_toggle_confirm:{_autostatus_target}")),
    ]
    return _nm_screen(
        "🤖 АВТОМАТИЗАЦИЯ",
        "Админ-бот → Новое меню → Автоматизация",
        "Внутри: автоответы, автодожимы, тексты, задержки, аварийная тишина (полный запрет "
        "авто-сообщений), приветствия, а��тоанкета, проверка анкет, LLM-наблюдения (read-only), "
        "глобальный переключатель LLM и автоматические статусы (оба требуют подтверждения).",
        rows,
    )


