def _nm_search_match(query: str) -> list:
    """Dependency-free substring/token matching over _NM_SEARCH_INDEX. Exact label/keyword
    substring hits score highest; individual query-token vs keyword-token overlaps add a
    smaller score so multi-word queries still surface partial matches. Tokens shorter than
    3 chars (не, с, на, ip-style fillers) are skipped in the per-token loop -- they still
    work fine through the whole-string substring checks above, but excluding them from the
    token loop avoids noisy cross-matches now that some keyword phrases are full sentences
    like "менеджер не работает"."""
    q = str(query or "").strip().casefold()
    if not q:
        return []
    q_tokens = [t for t in re.split(r"[\s,]+", q) if len(t) >= 3]
    scored = []
    for item in _NM_SEARCH_INDEX:
        label_cf = item["label"].casefold()
        kw_cf = item["keywords"].casefold()
        kw_tokens = [t for t in re.split(r"[\s,]+", kw_cf) if len(t) >= 3]
        score = 0
        if q in label_cf:
            score += 3
        if q in kw_cf:
            score += 2
        for qt in q_tokens:
            if qt in label_cf:
                score += 2
            for kt in kw_tokens:
                if qt == kt:
                    score += 3
                elif qt in kt or kt in qt:
                    score += 1
        if score > 0:
            scored.append((score, item))
    scored.sort(key=lambda pair: -pair[0])
    return [item for _score, item in scored[:8]]


def _nm_search_results_screen(query: str) -> Tuple[str, list]:
    results = _nm_search_match(query)
    q_disp = str(query or "").strip()[:60] or "-"
    lines = [
        _panel_header(),
        "",
        "**🔎 РЕЗУЛЬТАТЫ ПОИСКА**",
        "",
        "Путь:",
        f"Админ-бот → Новое меню → Поиск → {q_disp}",
        "",
    ]
    rows = []
    if results:
        lines.append(f"*Найдено: {len(results)}. Выберите нужный пункт.*")
        for item in results:
            rows.append([_nm_btn(str(item["label"])[:40], str(item["route"]))])
    else:
        lines.append(
            "*Ничего точного не найдено. Попробуйте: прокси, ссылки, статистика, байер, скрины, экспорт.*"
        )
    rows.append([
        _nm_btn("🔎 Новый поиск", "menu:nm_search"),
        _nm_btn("🏠 Новое меню", "menu:nm_root"),
    ])
    return "\n".join(lines).rstrip(), rows


_NM_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")

# --- TPILOT NM STAGE 2A: contextual Back for safe report/service/control screens ---
# _nm_wrap renders an OLD screen (via the pre-NM _title_for_menu chain, captured above --
# never the current override, to avoid recursion) and replaces only its trailing pure-
# navigation row(s) with the NM footer (⬅️ Назад -> parent / 🏠 Новое меню). The old
# screen's own builder is never modified and the old menu keeps its original Back
# behavior untouched -- this only affects what NM shows when routing through menu:nm_*.

_NM_OLD_BACK_CALLBACKS = {
    b"menu:main", b"menu:reports_control", b"menu:managers_modes",
    b"menu:traffic_buyers", b"menu:automation", b"menu:service",
    b"menu:bizlinks", b"panel:back",
}

# Narrow, standalone-only case: the old Health/TG Health screens' own "🔄 Обновить" row
# refreshes via menu:health / menu:tghealth, which loses NM context if left dangling above
# the NM footer. Intentionally NOT merged into _NM_OLD_BACK_CALLBACKS (that set is checked
# against every button in a row, including multi-button content rows) -- kept as its own
# set matched only when a row has exactly one button, so it can never remove content.
_NM_REFRESH_ONLY_CALLBACKS = {b"menu:health", b"menu:tghealth"}


def _nm_row_is_old_back(row) -> bool:
    """True only when EVERY button in this row is a pure old-menu navigation button
    (⬅️/"Назад" text, or a known old back/home callback), OR the row is a standalone old
    "🔄 Обновить" button pointing at menu:health/menu:tghealth (see _NM_REFRESH_ONLY_CALLBACKS
    above). Never raises. Used only to trim trailing rows -- content rows are left
    untouched by the caller."""
    try:
        if not row:
            return False
        if len(row) == 1:
            btn = row[0]
            data = bytes(getattr(btn, "data", b"") or b"")
            text = str(getattr(btn, "text", "") or "")
            if text.startswith("🔄") and data in _NM_REFRESH_ONLY_CALLBACKS:
                return True
        for btn in row:
            data = bytes(getattr(btn, "data", b"") or b"")
            text = str(getattr(btn, "text", "") or "")
            if data in _NM_OLD_BACK_CALLBACKS or text.startswith("⬅️") or "Назад" in text:
                continue
            return False
        return True
    except Exception:
        return False


def _nm_wrap(old_menu_route: str, parent: str, extra_rows: list = None) -> Tuple[str, list]:
    """Render old_menu_route through the pre-NM chain, trim its trailing old-back row(s),
    optionally append extra_rows (e.g. month-range shortcuts), then the NM footer. Falls
    back to a safe NM error screen (with a working way back to parent) on any failure."""
    try:
        if not callable(_NM_PREV_TITLE_FOR_MENU):
            raise RuntimeError("no previous _title_for_menu to wrap")
        text, rows = _NM_PREV_TITLE_FOR_MENU(old_menu_route)
        rows = list(rows or [])
        while rows and _nm_row_is_old_back(rows[-1]):
            rows.pop()
        if extra_rows:
            rows.extend(extra_rows)
        rows.extend(_nm_footer(parent))
        return text, rows
    except Exception:
        return _nm_screen(
            "⚠️ ЭКРАН НЕДОСТУПЕН",
            f"Админ-бот → Новое меню → {parent}",
            "Произошла ошибка при открытии экрана. Вернитесь назад и попробуйте снова.",
            [],
            parent=parent,
        )


def _nm_stats_month_rows() -> list:
    """Current/previous calendar month shortcuts for nm_stats, built from the already-
    supported /stat range command (main.py, unchanged). Computed fresh on every render;
    returns [] on any failure so the screen never breaks."""
    try:
        today_iso = _today_iso()
        today = _date_obj(today_iso)
        first_this_month = today.replace(day=1)
        last_prev_month = first_this_month - timedelta(days=1)
        first_prev_month = last_prev_month.replace(day=1)
        cur_start = _cmd_date(first_this_month.isoformat())
        cur_end = _cmd_date(today.isoformat())
        prev_start = _cmd_date(first_prev_month.isoformat())
        prev_end = _cmd_date(last_prev_month.isoformat())
        cur_cb = f"cmd:/stat range all {cur_start} {cur_end}"
        prev_cb = f"cmd:/stat range all {prev_start} {prev_end}"
        if len(cur_cb.encode("utf-8")) > 64 or len(prev_cb.encode("utf-8")) > 64:
            return []
        return [_nm_row(_nm_btn("📅 Текущий месяц", cur_cb), _nm_btn("📅 Прошлый месяц", prev_cb))]
    except Exception:
        return []

def _nm_llm_status_buttons(period: str = "today") -> list:
    """New-menu button layer for the read-only LLM-observations dashboard: reuses
    _tp_llm_status_screen_text (no calc duplicated), only the navigation/Back differs from
    the old _tp_llm_status_buttons -- Back goes to nm_automation, its real new home,
    instead of the old menu:reports_control."""
    curr_cb = f"menu:nm_llm_status:{period}".encode("utf-8")
    rows = [
        [Button.inline("Сегодня", b"menu:nm_llm_status:today"), Button.inline("Вчера", b"menu:nm_llm_status:yesterday")],
        [Button.inline("Неделя", b"menu:nm_llm_status:week"), Button.inline("Месяц", b"menu:nm_llm_status:month")],
        [Button.inline("🔄 Обновить", curr_cb)],
    ]
    rows.extend(_nm_footer("nm_automation"))
    return rows


def _nm_llm_toggle_confirm_text() -> str:
    current = _pb_get_setting("llm_supervisor_enabled")
    is_on = current != "0"
    state_label = "🟢 включён" if is_on else "🔴 выключен"
    action_label = "выключить" if is_on else "включить"
    effect = ("Новые LLM-наблюдения по лидам создаваться не будут." if is_on
              else "LLM снова начнёт создавать наблюдения по новым лидам.")
    lines = [
        _panel_header(), "",
        "**🤖 LLM: подтверждение**", "",
        f"Текущее состояние: {state_label}",
        f"Если подтвердите — LLM будет **{action_label}**.",
        effect,
    ]
    return "\n".join(lines).rstrip()


def _nm_llm_toggle_confirm_buttons() -> list:
    # N3: target encoded in the confirm route (not the previously observed
    # state), so a stale/duplicate confirm click can be safely no-op'd.
    current = _pb_get_setting("llm_supervisor_enabled")
    target = "0" if current != "0" else "1"
    return [
        [Button.inline("✅ Подтвердить", f"menu:nm_llm_toggle_do:{target}".encode())],
        [Button.inline("❌ Отмена", b"menu:nm_automation")],
    ]


# --- end TPILOT NM STAGE 2A helpers ---


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "nm_root":
        return _nm_root_screen()
    if raw == "nm_reports":
        return _nm_reports_screen()
    if raw == "nm_control":
        return _nm_control_screen()
    if raw == "nm_managers":
        return _nm_managers_screen()
    if raw == "nm_traffic":
        return _nm_traffic_screen()
    if raw == "nm_sources":
        return _nm_sources_screen()
    if raw == "nm_proxy":
        return _nm_proxy_screen()
    if raw == "nm_bizlinks":
        return _nm_bizlinks_screen()
    if raw == "nm_bizlinks_create":
        return _nm_bizlinks_create_screen()
    if raw == "nm_bizlinks_manage":
        return _nm_bizlinks_manage_screen()
    if raw == "nm_bizlinks_delete":
        return _nm_bizlinks_delete_screen()
    if raw == "nm_transfers":
        return _nm_transfers_screen()
    if raw == "nm_automation":
        return _nm_automation_screen()
    if raw == "nm_system":
        return _nm_system_screen()
    if raw == "nm_export":
        return _nm_export_screen()
    if raw == "nm_search":
        return _nm_search_screen()
    # --- TPILOT NM STAGE 2A wrapper routes (contextual Back into NM) ---
    if raw == "nm_stats":
        return _nm_wrap("stats", "nm_reports", extra_rows=_nm_stats_month_rows())
    if raw == "nm_flights":
        return _nm_wrap("flights", "nm_reports")
    if raw == "nm_excel":
        return _nm_wrap("export", "nm_reports")
    if raw == "nm_unanswered":
        return _nm_wrap("unanswered", "nm_quality_w")
    if raw == "nm_duplicates":
        return _nm_wrap("duplicates", "nm_reports")
    if raw == "nm_funnel_w":
        return _nm_wrap("funnel", "nm_traffic")
    if raw == "nm_quality_w":
        # NM2 N1: canonical parent is now nm_reports (Качество merged into Отчёты).
        return _nm_wrap("quality", "nm_reports", extra_rows=[_nm_row(_nm_btn("🔔 Неотвеченные", "menu:nm_unanswered"))])
    if raw == "nm_service_w":
        # N5.1 (Part G): one extra row added on top of the unchanged wrapped
        # old service screen -- the ONLY place in the whole canonical menu
        # that leads to the old menu, hidden off the root. Old service
        # screen content itself is untouched (still _nm_wrap over the same
        # verbatim _tp_visual_service_menu).
        return _nm_wrap("service", "nm_system", extra_rows=[_nm_row(_nm_btn("↩️ Временное старое меню", "menu:old_menu_warning"))])
    if raw == "nm_health_w":
        # NM2 N1: canonical parent is now nm_system (Контроль merged into Система).
        return _nm_wrap("health", "nm_system")
    if raw == "nm_tghealth_w":
        return _nm_wrap("tghealth", "nm_system")
    if raw == "nm_llm_status" or raw.startswith("nm_llm_status:"):
        parts = raw.split(":", 1)
        period = parts[1] if len(parts) > 1 else "today"
        if period not in _LLM_STATUS_PERIOD_LABELS:
            period = "today"
        text = _tp_llm_status_screen_text(period)
        if _pb_get_setting("llm_supervisor_enabled") == "0":
            text = "⚠️ LLM выключен — новые наблюдения не создаются.\n\n" + text
        return text, _nm_llm_status_buttons(period)
    if raw == "nm_llm_toggle_confirm":
        return _nm_llm_toggle_confirm_text(), _nm_llm_toggle_confirm_buttons()
    if raw == "nm_llm_toggle_do":
        # N3: historical callback (no target encoded) -- kept working
        # verbatim as the old unconditional flip, for any already-sent
        # confirm screen. Freshly rendered confirm screens now always emit
        # the target-encoded route below instead.
        current = _pb_get_setting("llm_supervisor_enabled")
        new_val = "0" if current != "0" else "1"
        _pb_set_setting("llm_supervisor_enabled", new_val)
        return _nm_automation_screen()
    if raw.startswith("nm_llm_toggle_do:"):
        target = raw.split(":", 1)[1]
        if target not in ("0", "1"):
            # N3.1: malformed/forged target -- never written, treated as
            # stale/invalid, canonical screen rerendered from fresh state.
            text, buttons = _nm_automation_screen()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        current = _pb_get_setting("llm_supervisor_enabled")
        if (current != "0") == (target != "0"):
            # Stale-state no-op: already at target, do not reapply.
            text, buttons = _nm_automation_screen()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        _pb_set_setting("llm_supervisor_enabled", target)
        return _nm_automation_screen()
    if callable(_NM_PREV_TITLE_FOR_MENU):
        return _NM_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


_NM_PREV_MAIN_MENU = globals().get("_main_menu")


