# --- TPILOT NM ERROR HINTS START ---
# Text-only recovery hints appended to already-displayed admin-facing messages (success or
# error result text from panel_commands, and BLD/BDD final reports). Does NOT change how
# any error is detected/classified elsewhere -- purely an additive "what to do next" block
# with a path into the new menu. Never raises; returns "" when nothing matches, so callers
# can always safely do `text + _nm_error_hint(text)`.

def _nm_error_hint(text: str) -> str:
    try:
        t = str(text or "").casefold()
        if not t:
            return ""

        # A) tg_limit / CHATLINKS_TOO_MUCH -- checked first (most common business-links
        # failure once the account has an active tg_limit auto-cleanup cycle running).
        if any(tok in t for tok in (
            "chatlinks_too_much", "tg_limit", "лимит telegram", "лимит бизнес-ссылок", "too much",
        )):
            return (
                "\n\n**Что делать:**\n"
                "Достигнут лимит бизнес-ссылок Telegram. TPilot мог автоматически очистить "
                "старые или мёртвые ссылки. Если проблема осталась — удалите лишние ссылки "
                "вручную и повторите создание.\n"
                "Путь: Главная → Бизнес-ссылки → 🗑 Удаление → Удалить по дате."
            )

        # B) no_business / Premium missing -- only fires alongside an actual failure marker,
        # so a normal "Бизнес-ссылки" screen title never gets this hint attached.
        has_failure_marker = any(tok in t for tok in (
            "ошибка", "класс ошибки", "не удалось", "failed", "fail",
        ))
        if ("no_business" in t) or (has_failure_marker and any(tok in t for tok in (
            "нужен бизнес", "telegram premium", "premium", "business",
        ))):
            return (
                "\n\n**Что делать:**\n"
                "На аккаунте может отсутствовать Telegram Premium + Business. Без этого "
                "бизнес-ссылки для аккаунта не создаются.\n"
                "Что сделать: включите Premium и Business на аккаунте, затем повторите "
                "создание ссылок.\n"
                "Путь: Главная → Менеджеры → 📋 Менеджеры — список и карточки → выберите менеджера."
            )

        # C) proxy problem
        if any(tok in t for tok in (
            "proxy_error", "proxy check", "⚠️ proxy", "прокси ошибка", "ошибка прокси",
        )):
            return (
                "\n\n**Что делать:**\n"
                "Похоже на проблему с прокси аккаунта.\n"
                "Что сделать: откройте прокси менеджера, проверьте соединение или замените прокси.\n"
                "Путь: Главная → Прокси → 🌐 Прокси менеджеров → выберите "
                "менеджера → 🔄 Проверить proxy или ✏️ Заменить proxy."
            )

        # D) session / authorization / runtime / timeout
        if any(tok in t for tok in (
            "не ответил", "не запущен", "сессия/авторизация", "unauthorized", "session",
            "authorization", "auth", "runtime", "таймаут", "timeout",
        )):
            return (
                "\n\n**Что делать:**\n"
                "Менеджер не ответил или рантайм не запущен. Возможные причины: слетела "
                "сессия, нужна авторизация, проблема с Telegram Health или прокси.\n"
                "Что сделать: сначала проверьте Telegram Health, затем при необходимости "
                "выполните вход по QR.\n"
                "Путь: Главная → Система → 📡 Telegram Health. Если нужен "
                "вход: Главная → Менеджеры → 📋 Менеджеры — список и карточки → выберите "
                "менеджера → 🔐 Перезайти."
            )

        # E) unknown error -- exact phrases only, to avoid false-positives on unrelated words.
        if any(tok in t for tok in (
            "класс ошибки: unknown", "error: unknown", "unknown error",
        )):
            return (
                "\n\n**Что делать:**\n"
                "Неопознанная ошибка. Сначала проверьте здоровье аккаунта и прокси.\n"
                "Путь: Главная → Система → 📡 Telegram Health и Главная → Прокси."
            )
    except Exception:
        return ""
    return ""

# --- TPILOT NM ERROR HINTS END ---


# --- TPILOT NMS SOURCE STATS WIZARD START ---
# Stage 3A: source-first statistics wizard for the New Menu (menu:nm_stats2), replacing
# "общая статистика по всем подряд" as the primary Reports -> Statistics scenario. Reuses
# the existing /nmstat controller command (main.py, itself a thin wrapper around
# stats_engine.se_window_body) via the existing generic panel-command submit/spawn
# mechanism (_panel_spawn_command_task / _submit_and_wait) -- no stats math here, no new
# DB tables, no changes to BLD/BDD/bizdel/bizdelg/tr/trx, no changes to the duplicate
# progress-card fix, nm_search wiring, or error-hints. The classic all-managers screen
# (menu:nm_stats) remains fully reachable, not the default path -- N4: promoted out of
# this wizard (was an ambiguously-labeled "📦 Классическая статистика" fallback button
# here) to a clearly named top-level "👥 По менеджерам" entry in _nm_reports_screen.

def _nms_sources() -> list:
    """[{key, name, window_text, dolyoty, linked_count}] from traffic_sources /
    source_work_windows / manager_source_links (shared TPilot DB, read-only). Fails open
    per-table -- a missing/uninitialized source_work_windows table never hides sources,
    it just falls back to the documented default (08:00-17:00, dolyoty enabled)."""
    out = []
    try:
        con = _connect_panel_db()
    except Exception:
        return []
    try:
        try:
            src_rows = con.execute(
                "SELECT source_key, name FROM traffic_sources ORDER BY name COLLATE NOCASE"
            ).fetchall()
        except Exception:
            src_rows = []
        for r in src_rows:
            key = str(r[0] or "").strip()
            if not key:
                continue
            name = str(r[1] or key)
            window_text = "дефолт 08:00-17:00"
            dolyoty = True
            try:
                win_row = con.execute(
                    "SELECT day_start, day_end, enabled, pro_include_dolyoty "
                    "FROM source_work_windows WHERE source_key=?",
                    (key,),
                ).fetchone()
                if win_row and int(win_row[2] or 0) == 1:
                    ds, de = int(win_row[0]), int(win_row[1])
                    window_text = f"{ds // 60:02d}:{ds % 60:02d}-{de // 60:02d}:{de % 60:02d}"
                    dolyoty = int(win_row[3] or 0) != 0
            except Exception:
                pass
            linked_count = 0
            try:
                cnt = con.execute(
                    "SELECT COUNT(*) FROM manager_source_links WHERE source_key=?", (key,)
                ).fetchone()
                linked_count = int(cnt[0] or 0) if cnt else 0
            except Exception:
                pass
            out.append({
                "key": key, "name": name, "window_text": window_text,
                "dolyoty": dolyoty, "linked_count": linked_count,
            })
    finally:
        con.close()
    return out


def _nms_source_info(source_key: str) -> dict:
    for s in _nms_sources():
        if s["key"] == source_key:
            return s
    return {"key": source_key, "name": source_key, "window_text": "дефолт 08:00-17:00", "dolyoty": True, "linked_count": 0}


def _nms_linked_manager_keys(source_key: str) -> set:
    try:
        con = _connect_panel_db()
    except Exception:
        return set()
    try:
        try:
            rows = con.execute(
                "SELECT manager_key FROM manager_source_links WHERE source_key=?",
                (str(source_key or "").strip(),),
            ).fetchall()
        except Exception:
            rows = []
        return {normalize_manager_key(r[0]) for r in rows if r and r[0]}
    finally:
        con.close()


def _nms_min_yyyymm() -> str:
    """Aligned with /nmstat's _period_validate_dates limit (EXPORT_PERIOD_LIMIT_DAYS,
    default 31): the earliest selectable month is the one containing today-30 days,
    so the calendar never offers a date /nmstat will reject."""
    min_date = _sched_pb_kyiv_today() - timedelta(days=30)
    return f"{min_date.year:04d}{min_date.month:02d}"


def _nms_sources_screen() -> Tuple[str, list]:
    sources = _nms_sources()
    rows = []
    for s in sources:
        if s["linked_count"] == 0:
            suffix = "нет привязок"
        elif s["dolyoty"]:
            suffix = f"{s['window_text']} + 🌙"
        else:
            suffix = s["window_text"]
        label = f"{s['name']} · {suffix}"[:60]
        rows.append([_nm_btn(label, f"nms:src:{s['key']}")])
    if not rows:
        rows.append([_nm_btn("Источники не найдены", "nms:noop")])
    rows.append([_nm_btn("👥 По менеджерам (по окну источника)", "nms:entry:mgr")])
    # N4: the ambiguous "📦 Классическая статистика" fallback button was removed
    # from here -- the classic manager-first flow it opened (menu:nm_stats) is
    # now a clearly named, top-level "👥 По менеджерам" entry directly in
    # Отчёты (_nm_reports_screen), not a jargon-labeled fallback buried inside
    # the source-first wizard. The route/handler/business logic (menu:nm_stats,
    # _nm_wrap("stats", ...)) is completely unchanged and still fully reachable.
    return _nm_screen(
        "📊 СТАТИСТИКА ПО ИСТОЧНИКУ",
        "Админ-бот → Новое меню → Отчёты → Статистика",
        "Сначала выберите источник, либо «По менеджерам», чтобы сразу выбрать конкретного "
        "менеджера (статистика по окну его источника). Статистика по менеджерам БЕЗ окна "
        "источника — кнопка «👥 По менеджерам» на экране «Отчёты».",
        rows,
        parent="nm_reports",
    )


def _nms_styp_text(payload: dict) -> str:
    info = _nms_source_info(str(payload.get("src") or ""))
    is_mgr_entry = str(payload.get("entry") or "") == "mgr"
    title = "📊 Статистика по менеджеру — тип отчёта" if is_mgr_entry else "📊 Статистика по источнику — тип отчёта"
    lines = [_panel_header(), "", title, ""]
    if is_mgr_entry:
        lines.append(f"Менеджер: {_tp_v8_manager_label_by_key(str(payload.get('mk') or ''))}")
    lines.append(f"Источник: {info['name']}")
    lines.append(f"Окно: {info['window_text']}")
    if not info["dolyoty"]:
        lines.append("")
        lines.append("Для этого источника долёты отключены, статистика считается календарным днём.")
    return "\n".join(lines)


def _nms_styp_buttons(payload: dict) -> list:
    info = _nms_source_info(str(payload.get("src") or ""))
    rows = [[_nm_btn("☀️ День / окно источника", "nms:styp:day")]]
    if info["dolyoty"]:
        rows.append([_nm_btn("🌙 Долёты", "nms:styp:flight")])
    back_target = "mgrlist" if str(payload.get("entry") or "") == "mgr" else "src"
    rows.append([_nm_btn("⬅️ Назад", f"nms:back:{back_target}"), _nm_btn("❌ Отмена", "nms:x")])
    return rows


def _nms_month_text(yyyymm: str, payload: dict) -> str:
    try:
        year, month = int(str(yyyymm)[:4]), int(str(yyyymm)[4:6])
    except Exception:
        today = _sched_pb_kyiv_today()
        year, month = today.year, today.month
    month_name = _SCHED_PB_MONTH_NAMES[month] if 1 <= month <= 12 else ""
    dates = sorted(payload.get("dates") or [])
    if not dates:
        sel_line = "Выбрано: —"
    elif len(dates) == 1:
        sel_line = f"Выбрано: {_bld_fmt_date(dates[0])}"
    else:
        try:
            n = (datetime.strptime(dates[-1], "%Y-%m-%d").date() - datetime.strptime(dates[0], "%Y-%m-%d").date()).days + 1
        except Exception:
            n = 0
        sel_line = f"Выбрано: {_bld_fmt_date(dates[0])}-{_bld_fmt_date(dates[-1])} ({n} дн.)"
    return "\n".join([
        _panel_header(), "",
        "📊 Статистика по источнику — дата", "",
        f"Месяц: {month_name} {year}",
        sel_line,
        "Нажмите на дату (одна дата = день, две — диапазон; третий клик сбрасывает выбор).",
    ])


def _nms_month_buttons(yyyymm: str, payload: dict) -> list:
    try:
        year, month = int(str(yyyymm)[:4]), int(str(yyyymm)[4:6])
    except Exception:
        today0 = _sched_pb_kyiv_today()
        year, month = today0.year, today0.month
    today = _sched_pb_kyiv_today()
    chosen = set(payload.get("dates") or [])
    rows = []
    hdr_labels = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"]
    rows.append([Button.inline(d, b"nms:noop") for d in hdr_labels])
    cal = _sched_pb_cal_mod.Calendar(firstweekday=0)
    for week in cal.monthdayscalendar(year, month):
        row = []
        for day in week:
            if day == 0:
                row.append(Button.inline(" ", b"nms:noop"))
                continue
            try:
                d_obj = _sched_pb_date_cls(year, month, day)
            except Exception:
                row.append(Button.inline(" ", b"nms:noop"))
                continue
            iso = d_obj.isoformat()
            if d_obj > today:
                row.append(Button.inline(".", b"nms:noop"))
            else:
                mark = "✅" if iso in chosen else str(day)
                cb = "nms:d:{:04d}{:02d}{:02d}".format(year, month, day).encode("utf-8")
                if len(cb) > 64:
                    cb = b"nms:noop"
                row.append(Button.inline(mark, cb))
        rows.append(row)
    prev_y, prev_m = (year, month - 1) if month > 1 else (year - 1, 12)
    next_y, next_m = (year, month + 1) if month < 12 else (year + 1, 1)
    min_ym = _nms_min_yyyymm()
    nav_row = []
    if f"{prev_y:04d}{prev_m:02d}" >= min_ym:
        nav_row.append(Button.inline("⬅️", "nms:cal:{:04d}{:02d}".format(prev_y, prev_m).encode("utf-8")))
    else:
        nav_row.append(Button.inline(".", b"nms:noop"))
    if (year, month) < (today.year, today.month):
        nav_row.append(Button.inline("➡️", "nms:cal:{:04d}{:02d}".format(next_y, next_m).encode("utf-8")))
    else:
        nav_row.append(Button.inline(".", b"nms:noop"))
    rows.append(nav_row)
    rows.append([Button.inline("➡️ Далее", b"nms:tomgr")])
    rows.append([Button.inline("⬅️ Назад", b"nms:back:styp"), Button.inline("❌ Отмена", b"nms:x")])
    return rows


# Manager-first entry ("👥 По менеджерам"): the closer's/manager's own linked
# source is resolved implicitly via _ss_source_for_manager_panel (existing
# manager_source_links reverse lookup, already used by the screenshot-config
# feature) -- no source_key selection step for this flow. Same downstream
# styp/calendar/confirm screens as source-first; only the manager-selection
# step is replaced by this dedicated paginated list, and payload["mks"] is
# pre-fixed to the single chosen manager, so the existing "mgr" step is
# skipped entirely (see the "tomgr" action branch below).
_NMS_MGR_PAGE_SIZE = 10


def _nms_active_managers_for_picker() -> list:
    try:
        return _manager_rows(only_active=True, only_enabled=True, exclude_closers=True)
    except Exception:
        return []


def _nms_mgrlist_page_count(total: int) -> int:
    return max(1, (total + _NMS_MGR_PAGE_SIZE - 1) // _NMS_MGR_PAGE_SIZE)


def _nms_managers_list_text(payload: dict, mgr_rows: list) -> str:
    # mgr_rows is always the caller's snapshot -- never re-queried here, so
    # the counts/pagination shown always match the SAME read that produced
    # the tokens and buttons for this render.
    total = len(mgr_rows)
    page_count = _nms_mgrlist_page_count(total)
    page = max(0, min(int(payload.get("mpage") or 0), page_count - 1))
    lines = [
        _panel_header(), "",
        "📊 Статистика по менеджеру — выбор менеджера", "",
        f"Активных менеджеров: {total}" + (f" · страница {page + 1}/{page_count}" if page_count > 1 else ""),
    ]
    if not mgr_rows:
        lines.append("Менеджеры не найдены.")
    else:
        lines.append("Выберите менеджера. Статистика будет по окну его источника.")
    return "\n".join(lines)


def _nms_manager_tokens_for_page(mgr_rows: list, page: int) -> dict:
    # Short opaque token (absolute list index, as a string) standing in for
    # manager_key in callback_data. Kept out of callback_data entirely and
    # instead frozen into the wizard payload at render time, so: (1) the
    # callback never risks the 64-byte limit regardless of manager_key
    # length, and (2) a later pickmgr click always resolves to the SAME
    # manager the admin actually saw, even if the manager list changes
    # in between (resolution reads the stored map, not a live recompute).
    start = page * _NMS_MGR_PAGE_SIZE
    page_rows = mgr_rows[start:start + _NMS_MGR_PAGE_SIZE]
    tokens = {}
    for i, r in enumerate(page_rows):
        mk = normalize_manager_key(r.get("manager_key") or "")
        if mk:
            tokens[str(start + i)] = mk
    return tokens


def _nms_build_mgrlist_payload(mpage, mgr_rows: list) -> dict:
    # Takes the caller's mgr_rows snapshot instead of querying -- see
    # _nms_render_mgrlist, the single entrypoint that reads the DB once and
    # feeds the SAME list into this, the text, and the buttons below, so a
    # concurrent add/remove between two separate reads can never make the
    # token map and the rendered buttons disagree about what index N is.
    total = len(mgr_rows)
    page_count = _nms_mgrlist_page_count(total)
    try:
        page = max(0, min(int(mpage or 0), page_count - 1))
    except Exception:
        page = 0
    return {
        "entry": "mgr",
        "mpage": page,
        "manager_tokens": _nms_manager_tokens_for_page(mgr_rows, page),
    }


def _nms_managers_list_buttons(payload: dict, mgr_rows: list) -> list:
    total = len(mgr_rows)
    page_count = _nms_mgrlist_page_count(total)
    page = max(0, min(int(payload.get("mpage") or 0), page_count - 1))
    start = page * _NMS_MGR_PAGE_SIZE
    page_rows = mgr_rows[start:start + _NMS_MGR_PAGE_SIZE]
    rows = []
    for i, r in enumerate(page_rows):
        mk = normalize_manager_key(r.get("manager_key") or "")
        if not mk:
            continue
        token = str(start + i)
        label = _manager_short_label(r)
        cb = f"nms:pickmgr:{token}".encode("utf-8")
        rows.append([Button.inline(f"👤 {label}", cb)])
    if not page_rows:
        rows.append([_nm_btn("Менеджеры не найдены", "nms:noop")])
    if page_count > 1:
        nav_row = [
            Button.inline("⬅️", f"nms:mpage:{page - 1}".encode("utf-8")) if page > 0 else Button.inline(".", b"nms:noop"),
            Button.inline("➡️", f"nms:mpage:{page + 1}".encode("utf-8")) if page < page_count - 1 else Button.inline(".", b"nms:noop"),
        ]
        rows.append(nav_row)
    rows.append([Button.inline("⬅️ Назад", b"nms:back:src"), Button.inline("❌ Отмена", b"nms:x")])
    return rows


def _nms_render_mgrlist(mpage) -> tuple:
    """Single DB read (_nms_active_managers_for_picker) for one manager-list
    screen render. payload (incl. manager_tokens), text, and buttons are all
    built from that ONE snapshot -- no function below this point re-queries,
    so the token map and the visible buttons can never disagree about which
    manager index N is, even under concurrent add/remove."""
    mgr_rows = _nms_active_managers_for_picker()
    payload = _nms_build_mgrlist_payload(mpage, mgr_rows)
    text = _nms_managers_list_text(payload, mgr_rows)
    buttons = _nms_managers_list_buttons(payload, mgr_rows)
    return payload, text, buttons


def _nms_mgr_text(payload: dict) -> str:
    src = str(payload.get("src") or "")
    linked = _nms_linked_manager_keys(src)
    n = len(payload.get("mks") or [])
    lines = [
        _panel_header(), "",
        "📊 Статистика по источнику — менеджеры", "",
    ]
    if not linked:
        lines.append("⚠️ У источника нет привязанных менеджеров. Отчёт будет по всем менеджерам.")
    else:
        lines.append(f"Выберите менеджеров источника (выбрано: {n} из {len(linked)}):")
    return "\n".join(lines)


def _nms_mgr_buttons(payload: dict) -> list:
    src = str(payload.get("src") or "")
    linked = _nms_linked_manager_keys(src)
    rows = []
    if not linked:
        rows.append([_nm_btn("➡️ Далее (все менеджеры)", "nms:confirm")])
        rows.append([_nm_btn("⬅️ Назад", "nms:back:cal"), _nm_btn("❌ Отмена", "nms:x")])
        return rows
    chosen = set(payload.get("mks") or [])
    try:
        mgr_rows = _manager_rows(only_active=True, only_enabled=True, exclude_closers=True)
    except Exception:
        mgr_rows = []
    for r in mgr_rows:
        mk = normalize_manager_key(r.get("manager_key") or "")
        if not mk or mk not in linked:
            continue
        mark = "✅" if mk in chosen else "⬜"
        label = f"{mark} {_manager_short_label(r)}"[:40]
        cb = f"nms:m:{mk}".encode("utf-8")
        if len(cb) > 64:
            continue
        rows.append([Button.inline(label, cb)])
    rows.append([
        Button.inline("Выбрать всех", b"nms:all"),
        Button.inline("Снять всех", b"nms:none"),
    ])
    rows.append([Button.inline("➡️ Далее", b"nms:confirm")])
    rows.append([
        Button.inline("⬅️ Назад", b"nms:back:cal"),
        Button.inline("❌ Отмена", b"nms:x"),
    ])
    return rows


def _nms_confirm_text(payload: dict) -> str:
    src = str(payload.get("src") or "")
    info = _nms_source_info(src)
    styp = str(payload.get("styp") or "day")
    dates = sorted(payload.get("dates") or [])
    mks = list(payload.get("mks") or [])
    is_mgr_entry = str(payload.get("entry") or "") == "mgr"
    d1_disp = _bld_fmt_date(dates[0]) if dates else "-"
    d2_disp = _bld_fmt_date(dates[-1]) if dates else "-"
    period_disp = d1_disp if len(dates) <= 1 else f"{d1_disp} - {d2_disp}"
    kind_label = "☀️ День" if styp == "day" else "🌙 Долёты"
    title = "📊 Статистика по менеджеру — подтверждение" if is_mgr_entry else "📊 Статистика по источнику — подтверждение"
    lines = [
        _panel_header(), "",
        title, "",
        f"Источник: {info['name']}",
        f"Тип: {kind_label}",
        f"Окно: {info['window_text']}",
        f"Период: {period_disp}",
    ]
    if is_mgr_entry:
        lines.append(f"Менеджер: {_tp_v8_manager_label_by_key(str(payload.get('mk') or ''))}")
    else:
        linked = _nms_linked_manager_keys(src)
        if not linked:
            lines.append("Менеджеры: все (у источника нет привязок)")
            lines.append("")
            lines.append("⚠️ У источника нет привязанных менеджеров. Отчёт будет по всем менеджерам.")
        else:
            lines.append(f"Менеджеры: {len(mks)} из {len(linked)}")
    return "\n".join(lines)


def _nms_confirm_buttons(payload: dict) -> list:
    back_target = "cal" if str(payload.get("entry") or "") == "mgr" else "mgr"
    return [
        [Button.inline("📊 Показать отчёт", b"nms:go")],
        [Button.inline("⬅️ Назад", f"nms:back:{back_target}".encode("utf-8")), Button.inline("❌ Отмена", b"nms:x")],
    ]


_NMS_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _title_for_menu(menu: str) -> Tuple[str, list]:  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "nm_stats2":
        return _nms_sources_screen()
    if callable(_NMS_PREV_TITLE_FOR_MENU):
        return _NMS_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []


@client.on(events.CallbackQuery)
async def _nms_callback(event):
    """AdminBot-only: source-first statistics wizard. State lives in panel_wizard_state
    (wizard='nms'), survives restart. Reuses the existing generic panel-command
    submit/spawn mechanism to run /nmstat (main.py) -- no stats logic here, no new
    @client.on handlers beyond this one, no schema changes."""
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("nms:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        parts = data.split(":")
        action = parts[1] if len(parts) > 1 else ""

        if action == "noop":
            await _pb_safe_answer(event, )
            return

        if action == "src":
            key = parts[2] if len(parts) > 2 else ""
            if not key:
                await _pb_safe_answer(event, )
                return
            payload = {"src": key, "styp": "day", "dates": [], "mks": [], "ym": ""}
            _wizard_set(chat_id, user_id, "nms", "styp", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_styp_text(payload), buttons=_nms_styp_buttons(payload))
            return

        # Manager-first entry ("👥 По менеджерам"): fresh entry points, same
        # as "src" above -- no pre-existing wizard state required. All four
        # mgrlist render sites go through _nms_render_mgrlist, which reads
        # the manager list from the DB exactly ONCE and builds the payload
        # (with its token->manager_key map), the text, and the buttons all
        # from that single snapshot; "pickmgr" below reads that stored map
        # instead of trusting a raw manager_key from callback_data, so it
        # must run AFTER the wizard-state-required boundary.
        if action == "entry":
            sub = parts[2] if len(parts) > 2 else ""
            if sub != "mgr":
                await _pb_safe_answer(event, )
                return
            payload, text, buttons = _nms_render_mgrlist(0)
            _wizard_set(chat_id, user_id, "nms", "mgrlist", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, text, buttons=buttons)
            return

        if action == "mpage":
            try:
                page_n = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                page_n = 0
            payload, text, buttons = _nms_render_mgrlist(max(0, page_n))
            _wizard_set(chat_id, user_id, "nms", "mgrlist", payload)
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, text, buttons=buttons)
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[nms] manager list page render failed: {exc!r}")
            return

        # Every action below requires existing wizard state.
        wstate = _wizard_get(chat_id, user_id)
        if str(wstate.get("wizard") or "") != "nms":
            await _pb_safe_answer(event, "Мастер сброшен, начните заново.", alert=True)
            try:
                text, buttons = _title_for_menu("nm_stats2")
                await _safe_event_edit(event, text, buttons=buttons)
            except Exception:
                pass
            return
        payload = wstate.get("payload") or {}

        if action == "pickmgr":
            token = parts[2] if len(parts) > 2 else ""
            tokens = payload.get("manager_tokens") or {}
            mk = normalize_manager_key(str(tokens.get(token) or ""))
            # Revalidate against the CURRENT picker-eligible set (not just the
            # frozen token map) -- a manager could have been disabled/removed/
            # turned into a closer between render and click.
            valid_keys = {normalize_manager_key(r.get("manager_key") or "") for r in _nms_active_managers_for_picker()}
            if not mk or mk not in valid_keys:
                await _pb_safe_answer(event, "Список менеджеров обновился, откройте его заново.", alert=True)
                try:
                    fresh_payload, fresh_text, fresh_buttons = _nms_render_mgrlist(payload.get("mpage"))
                    _wizard_set(chat_id, user_id, "nms", "mgrlist", fresh_payload)
                    await _safe_event_edit(event, fresh_text, buttons=fresh_buttons)
                except Exception:
                    pass
                return
            src_key = _ss_source_for_manager_panel(mk)
            if not src_key:
                await _pb_safe_answer(event, "У менеджера нет привязанного источника. Отчёт недоступен в этом режиме.", alert=True)
                return
            new_payload = {
                "entry": "mgr", "src": src_key, "mk": mk, "styp": "day", "dates": [], "mks": [mk], "ym": "",
                "mpage": int(payload.get("mpage") or 0),
            }
            _wizard_set(chat_id, user_id, "nms", "styp", new_payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_styp_text(new_payload), buttons=_nms_styp_buttons(new_payload))
            return

        if action == "styp":
            sub = parts[2] if len(parts) > 2 else "day"
            if sub not in ("day", "flight"):
                sub = "day"
            payload["styp"] = sub
            today = _sched_pb_kyiv_today()
            ym = f"{today.year:04d}{today.month:02d}"
            payload["ym"] = ym
            _wizard_set(chat_id, user_id, "nms", "cal", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_month_text(ym, payload), buttons=_nms_month_buttons(ym, payload))
            return

        if action == "cal":
            yyyymm = parts[2] if len(parts) > 2 else ""
            payload["ym"] = yyyymm
            _wizard_set(chat_id, user_id, "nms", "cal", payload)
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, _nms_month_text(yyyymm, payload), buttons=_nms_month_buttons(yyyymm, payload))
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[nms] month render failed: {exc!r}")
            return

        if action == "d":
            yyyymmdd = parts[2] if len(parts) > 2 else ""
            try:
                d_obj = datetime.strptime(yyyymmdd, "%Y%m%d").date()
            except Exception:
                await _pb_safe_answer(event, "Некорректная дата", alert=True)
                return
            if d_obj > _sched_pb_kyiv_today():
                await _pb_safe_answer(event, "Дата ещё не наступила", alert=True)
                return
            iso = d_obj.isoformat()
            dates = list(payload.get("dates") or [])
            if iso in dates:
                dates.remove(iso)
            elif len(dates) >= 2:
                dates = [iso]
            else:
                dates.append(iso)
            payload["dates"] = dates
            payload["ym"] = yyyymmdd[:6]
            _wizard_set(chat_id, user_id, "nms", "cal", payload)
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(
                    event, _nms_month_text(yyyymmdd[:6], payload), buttons=_nms_month_buttons(yyyymmdd[:6], payload),
                )
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[nms] calendar render failed: {exc!r}")
            return

        if action == "tomgr":
            if not (payload.get("dates") or []):
                await _pb_safe_answer(event, "Выберите хотя бы одну дату", alert=True)
                return
            if str(payload.get("entry") or "") == "mgr":
                # manager-first: mks is already fixed to the single chosen
                # manager (set at "pickmgr") -- skip the manager-selection
                # step entirely and go straight to confirmation.
                _wizard_set(chat_id, user_id, "nms", "confirm", payload)
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, _nms_confirm_text(payload), buttons=_nms_confirm_buttons(payload))
                return
            src = str(payload.get("src") or "")
            linked = _nms_linked_manager_keys(src)
            if linked and not payload.get("mks"):
                payload["mks"] = sorted(linked)  # default: all linked managers pre-selected
            _wizard_set(chat_id, user_id, "nms", "mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_mgr_text(payload), buttons=_nms_mgr_buttons(payload))
            return

        if action == "m":
            mk = normalize_manager_key(parts[2] if len(parts) > 2 else "")
            if not mk:
                await _pb_safe_answer(event, )
                return
            mks = list(payload.get("mks") or [])
            if mk in mks:
                mks.remove(mk)
            else:
                mks.append(mk)
            payload["mks"] = mks
            _wizard_set(chat_id, user_id, "nms", "mgr", payload)
            await _pb_safe_answer(event, )
            try:
                await _safe_event_edit(event, _nms_mgr_text(payload), buttons=_nms_mgr_buttons(payload))
            except Exception as exc:
                if "MessageNotModifiedError" not in repr(exc):
                    print(f"[nms] manager render failed: {exc!r}")
            return

        if action == "all":
            src = str(payload.get("src") or "")
            linked = _nms_linked_manager_keys(src)
            payload["mks"] = sorted(linked)
            _wizard_set(chat_id, user_id, "nms", "mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_mgr_text(payload), buttons=_nms_mgr_buttons(payload))
            return

        if action == "none":
            payload["mks"] = []
            _wizard_set(chat_id, user_id, "nms", "mgr", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_mgr_text(payload), buttons=_nms_mgr_buttons(payload))
            return

        if action == "confirm":
            src = str(payload.get("src") or "")
            linked = _nms_linked_manager_keys(src)
            if linked and not (payload.get("mks") or []):
                await _pb_safe_answer(event, "Выберите хотя бы одного менеджера", alert=True)
                return
            _wizard_set(chat_id, user_id, "nms", "confirm", payload)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _nms_confirm_text(payload), buttons=_nms_confirm_buttons(payload))
            return

        if action == "go":
            src = str(payload.get("src") or "")
            styp = str(payload.get("styp") or "day")
            dates = sorted(payload.get("dates") or [])
            mks = list(payload.get("mks") or [])
            if not src or not dates:
                await _pb_safe_answer(event, "Мастер сброшен, начните заново.", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, "nms:go"):
                await _pb_safe_answer(event, "Уже выполняю...")
                return
            d1, d2 = dates[0], dates[-1]
            cmd = f"/nmstat {src} {d1} {d2} {styp}"
            if mks:
                cmd += " " + ",".join(mks)
            _wizard_clear(chat_id, user_id)
            await _panel_answer_fast(event, "📊 Запросил отчёт")
            try:
                await _safe_event_edit(
                    event,
                    "⏳ Формирую отчёт по источнику.\nПанель можно использовать дальше.",
                    buttons=_back_to_panel_buttons(),
                )
            except Exception:
                pass
            status_msg_id = await _panel_status_send(
                chat_id, "⏳ Выполняю выбранное действие.\nПанель можно использовать дальше.",
                cmd,
            )
            _panel_spawn_command_task(cmd, user_id, chat_id, status_msg_id)
            return

        if action == "back":
            target = parts[2] if len(parts) > 2 else ""
            if target == "src":
                _wizard_clear(chat_id, user_id)
                await _pb_safe_answer(event, )
                try:
                    text, buttons = _title_for_menu("nm_stats2")
                    await _safe_event_edit(event, text, buttons=buttons)
                except Exception:
                    pass
                return
            if target == "styp":
                _wizard_set(chat_id, user_id, "nms", "styp", payload)
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, _nms_styp_text(payload), buttons=_nms_styp_buttons(payload))
                return
            if target == "cal":
                ym = str(payload.get("ym") or "")
                if not ym:
                    today = _sched_pb_kyiv_today()
                    ym = f"{today.year:04d}{today.month:02d}"
                _wizard_set(chat_id, user_id, "nms", "cal", payload)
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, _nms_month_text(ym, payload), buttons=_nms_month_buttons(ym, payload))
                return
            if target == "mgr":
                _wizard_set(chat_id, user_id, "nms", "mgr", payload)
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, _nms_mgr_text(payload), buttons=_nms_mgr_buttons(payload))
                return
            if target == "mgrlist":
                new_payload, new_text, new_buttons = _nms_render_mgrlist(payload.get("mpage"))
                _wizard_set(chat_id, user_id, "nms", "mgrlist", new_payload)
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, new_text, buttons=new_buttons)
                return
            await _pb_safe_answer(event, )
            return

        if action == "x":
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "Отменено")
            try:
                text, buttons = _title_for_menu("nm_reports")
                await _safe_event_edit(event, text, buttons=buttons)
            except Exception:
                pass
            return

        await _pb_safe_answer(event, )
    except Exception as exc:
        print(f"[nms] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

# --- TPILOT NMS SOURCE STATS WIZARD END ---


# --- TPILOT MORNING PREFLIGHT STAGE 1 START ---
# Daily ~07:50 AdminBot morning readiness report for TODAY only. All checking
# logic lives in preflight_check.py (pure, read-only, no Telegram calls); this
# block only schedules the daily tick, sends/edits/deletes messages, stores
# the daily sent-flag + last message reference in the existing settings KV
# (_pb_get_setting/_pb_set_setting), and handles the "OK" button. No DB
# schema changes, no calculation changes, no changes to any other feature.

try:
    from preflight_check import (
        build_report as _pf_build_report,
        render_admin_text as _pf_render_admin_text,
        run_deep_verification as _pf_run_deep_verification,
        apply_deep_results as _pf_apply_deep_results,
        DEEP_VERIFY_AVAILABLE as _PF_DEEP_VERIFY_AVAILABLE,
        report_is_ok as _pf_report_is_ok,
        report_has_recheckable_problem as _pf_report_has_recheckable_problem,
        apply_correction_note as _pf_apply_correction_note,
        CORRECTION_NOTE_ADMIN as _PF_CORRECTION_NOTE_ADMIN,
        CORRECTED_TITLE_ADMIN as _PF_CORRECTED_TITLE_ADMIN,
    )
    _PF_STAGE1_OK = True
except Exception as _pf_import_err:
    _pf_build_report = None  # type: ignore[assignment]
    _pf_render_admin_text = None  # type: ignore[assignment]
    _pf_run_deep_verification = None  # type: ignore[assignment]
    _pf_apply_deep_results = None  # type: ignore[assignment]
    _PF_DEEP_VERIFY_AVAILABLE = False
    _PF_STAGE1_OK = False
    _pf_report_is_ok = None  # type: ignore[assignment]
    _pf_report_has_recheckable_problem = None  # type: ignore[assignment]
    _pf_apply_correction_note = None  # type: ignore[assignment]
    _PF_CORRECTION_NOTE_ADMIN = "✅ Неполадки устранены. Готовность перепроверена. Всё готово к работе."
    _PF_CORRECTED_TITLE_ADMIN = "✅ Обновлено: готовность перепроверена"
    print(f"[preflight] import error: {_pf_import_err!r}")

_PF_SEND_HOUR_START = 7
_PF_SEND_MINUTE_START = 50
_PF_SEND_HOUR_CUTOFF = 12  # after this hour, wait for tomorrow instead of a late send

# Deep verification (read-only Telegram-side link check) starts well before
# the send window so results are ready by send time on a best-effort basis.
# PanelBot is the only process that enqueues/runs deep verification;
# PartnerBot only ever reads the resulting blob (see _pf_verify_blob_key).
_PF_VERIFY_HOUR_START = 7
_PF_VERIFY_MINUTE_START = 25
_PF_VERIFY_DEADLINE_HOUR = 7
_PF_VERIFY_DEADLINE_MINUTE = 48

_PF_VERIFY_IN_PROGRESS: Dict[str, Optional[str]] = {"morning": None, "evening": None}


def _pf_verify_blob_key(period: str, target_date_iso: str) -> str:
    return f"preflight_verify_{period}_{target_date_iso}"


def _pf_verify_window_open(now: datetime, verify_hour: int, verify_minute: int, cutoff_hour: int) -> bool:
    if now.hour < verify_hour or (now.hour == verify_hour and now.minute < verify_minute):
        return False
    if now.hour >= cutoff_hour:
        return False
    return True


def _pf_deadline_loop_time(now: datetime, deadline_hour: int, deadline_minute: int) -> float:
    target = now.replace(hour=deadline_hour, minute=deadline_minute, second=0, microsecond=0)
    remaining = (target - now).total_seconds()
    if remaining < 60:
        remaining = 60.0  # always give at least a minute, even for a late/restarted start
    return asyncio.get_event_loop().time() + remaining


def _pf_read_verify_blob(period: str, target_date_iso: str) -> Optional[dict]:
    """Read a previously-stored deep-verification blob for (period,
    target_date_iso). Returns None if absent, unparsable, or for a
    different date (never applies a mismatched date's result)."""
    raw = _pb_get_setting(_pf_verify_blob_key(period, target_date_iso))
    if not raw:
        return None
    try:
        blob = json.loads(raw)
    except Exception:
        return None
    if str(blob.get("target_date") or "") != target_date_iso:
        return None
    return blob


async def _pf_ensure_deep_verification(period: str, target_date_iso: str, deadline_ts: float, *, force: bool = False) -> None:
    """Kick off preflight_check.run_deep_verification() as a background task
    at most once per (period, target_date) per PanelBot process lifetime,
    and store the resulting blob via the 2-column-safe _pf_set_setting.
    Never blocks the caller (the 60s tick loop) -- the actual verification
    (which can take minutes) runs in its own task. Restart-safe: if a
    completed blob for this exact target_date already exists in the
    settings KV, does nothing (no duplicate manager_queue enqueue) UNLESS
    force=True.

    AUTO-RECHECK 20260712: force=True skips the "already have a completed
    blob" short-circuit and re-runs verification even though a blob already
    exists for this exact (period, target_date) -- used by the auto-recheck
    flow (see _pf_admin_evening_tick) to refresh a stale timeout/partial
    blob. The in-progress guard below still applies (never two concurrent
    verifies for the same period+date); the freshly-computed blob
    OVERWRITES the same settings key, scoped to this exact (period,
    target_date) only -- default (force=False) behavior and every other
    date/kind's stored blob are completely unaffected."""
    if not (_PF_STAGE1_OK and _PF_DEEP_VERIFY_AVAILABLE and callable(_pf_run_deep_verification)):
        return
    if _PF_VERIFY_IN_PROGRESS.get(period) == target_date_iso:
        return  # already running in this process
    if not force and _pf_read_verify_blob(period, target_date_iso) is not None:
        return  # already have a completed result for this exact date

    _PF_VERIFY_IN_PROGRESS[period] = target_date_iso

    async def _pf_verify_runner() -> None:
        try:
            blob = await _pf_run_deep_verification(target_date_iso, TPILOT_DB_PATH, period, deadline_ts)
            _pf_set_setting(_pf_verify_blob_key(period, target_date_iso), json.dumps(blob, ensure_ascii=False))
        except Exception as e:
            print(f"[preflight-verify] run error period={period} date={target_date_iso}: {e!r}")
        finally:
            if _PF_VERIFY_IN_PROGRESS.get(period) == target_date_iso:
                _PF_VERIFY_IN_PROGRESS[period] = None

    _pb_track_task(_pf_verify_runner())


def _pf_kyiv_now() -> datetime:
    # W3.2 (02_S9_TIMEZONE_CONTRACT.md 2.3/2.4, TZ-2): the silent OS-local fallback is
    # removed -- storage.w3_now() raises W3TimezoneError instead of quietly returning a
    # non-Kyiv instant, which is the inventory's #1 risk (a quiet date shift on the
    # preflight-verify send window).
    from storage import w3_now as _pf_w3_now
    return _pf_w3_now()


def _pf_within_send_window(now: datetime) -> bool:
    if now.hour < _PF_SEND_HOUR_START or (now.hour == _PF_SEND_HOUR_START and now.minute < _PF_SEND_MINUTE_START):
        return False
    if now.hour >= _PF_SEND_HOUR_CUTOFF:
        return False
    return True


def _pf_set_setting(key: str, value: str) -> None:
    """Preflight-safe KV write: canonical 2-column (key, value) schema only.

    Production's central settings table has no updated_at column; the
    generic _pb_set_setting's 3-column INSERT fails there and is swallowed
    by its own try/except, so preflight flags/message-ids would never
    persist -- causing a repeated report every tick between 07:50 and the
    cutoff. This local writer uses only the schema storage.set_setting has
    always used, so it works on both the sanitized local DB and production.
    """
    try:
        con = _connect_panel_db()
        try:
            con.execute(
                "INSERT INTO settings(key, value) VALUES(?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                (str(key), str(value)),
            )
            con.commit()
        finally:
            con.close()
    except Exception as e:
        print(f"[preflight] set_setting failed key={key}: {e!r}")


async def _pf_send_admin_report(chat_id: int, today_iso: str) -> None:
    try:
        report = _pf_build_report(today_iso=today_iso, db_path=TPILOT_DB_PATH)
        deep_blob = _pf_read_verify_blob("morning", today_iso)
        if deep_blob is not None and callable(_pf_apply_deep_results):
            report = _pf_apply_deep_results(report, deep_blob, period_kind="today")
        text = _pf_render_admin_text(report, period_kind="today")
    except Exception as e:
        print(f"[preflight] build_report/render error: {e!r}")
        return

    # Delete the previous day's stored report message for this chat (if any).
    # Never touches any other message. Safe no-op if already gone / no rights.
    msg_key = f"preflight_msg_admin_{chat_id}"
    prev_ref = _pb_get_setting(msg_key)
    if prev_ref:
        prev_date, _, prev_mid = prev_ref.partition(":")
        if prev_date and prev_date != today_iso and prev_mid.strip().isdigit():
            try:
                await client.delete_messages(int(chat_id), [int(prev_mid)])
            except Exception as e:
                print(f"[preflight] previous message delete failed chat={chat_id}: {e!r}")

    try:
        msg = await client.send_message(
            int(chat_id), _safe_text(text),
            buttons=[[Button.inline("✅ Ознакомился", b"pfok:a")]],
        )
    except Exception as e:
        print(f"[preflight] send failed chat={chat_id}: {e!r}")
        return

    try:
        mid = int(getattr(msg, "id", 0) or 0)
        if mid:
            _pf_set_setting(msg_key, f"{today_iso}:{mid}")
    except Exception:
        pass
    _pf_set_setting(f"preflight_admin_sent_{today_iso}_{chat_id}", "1")


async def _pf_admin_tick() -> None:
    if not _PF_STAGE1_OK:
        return
    now = _pf_kyiv_now()
    today_iso = now.date().isoformat()

    if _pf_verify_window_open(now, _PF_VERIFY_HOUR_START, _PF_VERIFY_MINUTE_START, _PF_SEND_HOUR_CUTOFF):
        deadline_ts = _pf_deadline_loop_time(now, _PF_VERIFY_DEADLINE_HOUR, _PF_VERIFY_DEADLINE_MINUTE)
        try:
            await _pf_ensure_deep_verification("morning", today_iso, deadline_ts)
        except Exception as e:
            print(f"[preflight-verify] ensure error morning {today_iso}: {e!r}")

    if not _pf_within_send_window(now):
        return
    targets = _notification_targets()
    if not targets:
        return
    for chat_id in targets:
        try:
            if _pb_get_setting(f"preflight_admin_sent_{today_iso}_{chat_id}") == "1":
                continue
            await _pf_send_admin_report(chat_id, today_iso)
        except Exception as e:
            print(f"[preflight] tick error chat={chat_id}: {e!r}")


async def _preflight_admin_loop() -> None:
    while True:
        try:
            await _pf_admin_tick()
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"[preflight] loop error: {e!r}")
        await asyncio.sleep(60)


@client.on(events.CallbackQuery)
async def _preflight_ok_callback(event):
    try:
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("pfok:"):
            return
        try:
            await event.delete()
        except Exception as e:
            # Already deleted, or the bot lost permission -- safe, log only.
            print(f"[preflight] OK-button delete failed: {e!r}")
        # "pfok:a" (legacy Stage 1) and anything ending in "m" -> morning text;
        # anything ending in "e" -> evening text (see pfok:ae below).
        is_evening = data.endswith("e")
        try:
            await _pb_safe_answer(event, "Хорошего вечера ☀️" if is_evening else "Хорошего дня ☀️")
        except Exception:
            pass
    except Exception:
        pass

# --- TPILOT MORNING PREFLIGHT STAGE 1 END ---


# --- TPILOT EVENING PREFLIGHT (ADMIN, TOMORROW) START ---
# Daily ~16:50 AdminBot readiness report for TOMORROW only. Mirrors the
# Stage 1 morning block above exactly (same build_report/render_admin_text
# from preflight_check.py, just called with tomorrow's date and
# period_kind="tomorrow"), with its own KV keys so it never collides with
# the morning report's sent-flag/message-id state for the same chat.

_PF_EVE_SEND_HOUR_START = 16
_PF_EVE_SEND_MINUTE_START = 50
_PF_EVE_SEND_HOUR_CUTOFF = 20  # after this hour, wait for tomorrow's tick instead of a late send

_PF_EVE_VERIFY_HOUR_START = 16
_PF_EVE_VERIFY_MINUTE_START = 25
_PF_EVE_VERIFY_DEADLINE_HOUR = 16
_PF_EVE_VERIFY_DEADLINE_MINUTE = 48


def _pf_eve_within_send_window(now: datetime) -> bool:
    if now.hour < _PF_EVE_SEND_HOUR_START or (now.hour == _PF_EVE_SEND_HOUR_START and now.minute < _PF_EVE_SEND_MINUTE_START):
        return False
    if now.hour >= _PF_EVE_SEND_HOUR_CUTOFF:
        return False
    return True


# --- AUTO-RECHECK + MESSAGE CORRECTION 20260712 START -----------------------
# If a sent evening report has a plausibly TRANSIENT problem (deep-link
# verification timeout/partial -- see preflight_check.report_has_recheckable_
# problem), automatically re-run deep verification a bounded number of times
# and, if it resolves, correct the already-sent message in place instead of
# leaving a stale red report or sending a duplicate. All state lives in the
# existing 2-column settings KV (no schema change); every key is scoped to
# (tomorrow_iso, chat_id) so it can never leak into another date/chat.

_PF_RECHECK_MAX_ATTEMPTS = 3
_PF_RECHECK_INTERVAL_SEC = 300  # ~5 minutes between automatic re-check attempts


def _pf_eve_status_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_eve_status_{date_iso}_{chat_id}"


def _pf_eve_recheck_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_eve_recheck_{date_iso}_{chat_id}"


def _pf_eve_recheck_ts_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_eve_recheck_ts_{date_iso}_{chat_id}"


def _pf_eve_resolved_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_eve_resolved_{date_iso}_{chat_id}"


async def _pf_correct_message(chat_id: int, prev_mid: int, corrected_text: str, fallback_titled_text: str, buttons) -> tuple:
    """Apply a corrected report to a previously-sent message: prefer an
    in-place edit; on failure (any reason other than MessageNotModifiedError,
    which is treated as a no-op success), fall back to delete+send using the
    SAME corrected_text; if delete also fails, send exactly ONE new message
    using fallback_titled_text (a clearly-labeled "Обновлено" variant) so a
    later tick never sends a duplicate. Returns (ok, new_mid) -- new_mid is
    set only when a NEW message was actually sent (an in-place edit keeps
    the existing mid, so new_mid is None in that case). Never raises."""
    if prev_mid:
        edited = False
        try:
            await client.edit_message(int(chat_id), int(prev_mid), _safe_text(corrected_text), buttons=buttons)
            edited = True
        except Exception as e:
            if e.__class__.__name__ == "MessageNotModifiedError":
                edited = True
            else:
                print(f"[preflight-recheck] edit failed chat={chat_id}: {e!r}")
        if edited:
            return True, None

        deleted = False
        try:
            await client.delete_messages(int(chat_id), [int(prev_mid)])
            deleted = True
        except Exception as e:
            print(f"[preflight-recheck] delete failed chat={chat_id}: {e!r}")

        if deleted:
            try:
                msg = await client.send_message(int(chat_id), _safe_text(corrected_text), buttons=buttons)
                return True, (int(getattr(msg, "id", 0) or 0) or None)
            except Exception as e:
                print(f"[preflight-recheck] send-after-delete failed chat={chat_id}: {e!r}")
                return False, None

    # No prior message id at all, OR delete also failed -- one new message
    # with a clearly-labeled corrected title, never a silent duplicate of
    # the normal report.
    try:
        msg = await client.send_message(int(chat_id), _safe_text(fallback_titled_text), buttons=buttons)
        return True, (int(getattr(msg, "id", 0) or 0) or None)
    except Exception as e:
        print(f"[preflight-recheck] fallback send failed chat={chat_id}: {e!r}")
        return False, None


async def _pf_admin_apply_correction(chat_id: int, tomorrow_iso: str, report: Dict[str, Any]) -> None:
    """Render the now-OK report (same render_admin_text as the normal
    evening report) with the correction note, and update the previously-
    sent problem message via _pf_correct_message. Sets status=ok and
    resolved=1 on success so this can never run twice for the same
    (chat, date) -- no duplicate corrected messages on later ticks."""
    try:
        text = _pf_render_admin_text(report, period_kind="tomorrow")
    except Exception as e:
        print(f"[preflight-recheck] render error chat={chat_id}: {e!r}")
        return
    note = _PF_CORRECTION_NOTE_ADMIN
    corrected = _pf_apply_correction_note(text, note) if callable(_pf_apply_correction_note) else f"{note}\n\n{text}"
    fallback_titled = f"{_PF_CORRECTED_TITLE_ADMIN}\n\n{text}"

    msg_key = f"preflight_msg_admin_evening_{chat_id}"
    prev_ref = _pb_get_setting(msg_key)
    prev_mid = 0
    if prev_ref:
        prev_date, _, prev_mid_s = prev_ref.partition(":")
        if prev_date == tomorrow_iso and prev_mid_s.strip().isdigit():
            prev_mid = int(prev_mid_s)

    ok, new_mid = await _pf_correct_message(
        chat_id, prev_mid, corrected, fallback_titled,
        [[Button.inline("✅ Ознакомился", b"pfok:ae")]],
    )
    if not ok:
        return
    if new_mid:
        _pf_set_setting(msg_key, f"{tomorrow_iso}:{new_mid}")
    _pf_set_setting(_pf_eve_status_key(tomorrow_iso, chat_id), "ok")
    _pf_set_setting(_pf_eve_resolved_key(tomorrow_iso, chat_id), "1")


async def _pf_admin_evening_maybe_correct(chat_id: int, tomorrow_iso: str, now: datetime) -> None:
    """Called on every tick for a chat that already has a sent evening
    report. If the original send was a problem and a fresh blob now shows
    it resolved, corrects the message in place. Otherwise, if the problem
    is still present but plausibly transient (report_has_recheckable_
    problem) and the retry budget/interval allow it, triggers ONE more
    bounded automatic re-check (force=True) and records the attempt. Never
    raises; always a safe no-op once resolved=1 or the retry budget is
    exhausted."""
    if _pb_get_setting(_pf_eve_resolved_key(tomorrow_iso, chat_id)) == "1":
        return
    if _pb_get_setting(_pf_eve_status_key(tomorrow_iso, chat_id)) != "problem":
        return

    try:
        report = _pf_build_report(today_iso=tomorrow_iso, db_path=TPILOT_DB_PATH)
        deep_blob = _pf_read_verify_blob("evening", tomorrow_iso)
        if deep_blob is not None and callable(_pf_apply_deep_results):
            report = _pf_apply_deep_results(report, deep_blob, period_kind="tomorrow")
    except Exception as e:
        print(f"[preflight-recheck] rebuild error chat={chat_id}: {e!r}")
        return

    if callable(_pf_report_is_ok) and _pf_report_is_ok(report):
        await _pf_admin_apply_correction(chat_id, tomorrow_iso, report)
        return

    if not (callable(_pf_report_has_recheckable_problem) and _pf_report_has_recheckable_problem(report)):
        return  # a structural (non-transient) problem -- do not retry forever

    try:
        attempts = int(_pb_get_setting(_pf_eve_recheck_key(tomorrow_iso, chat_id)) or "0")
    except Exception:
        attempts = 0
    if attempts >= _PF_RECHECK_MAX_ATTEMPTS:
        return

    try:
        last_ts = float(_pb_get_setting(_pf_eve_recheck_ts_key(tomorrow_iso, chat_id)) or "0")
    except Exception:
        last_ts = 0.0
    now_ts = now.timestamp()
    if last_ts and (now_ts - last_ts) < _PF_RECHECK_INTERVAL_SEC:
        return

    deadline_ts = _pf_deadline_loop_time(now, _PF_EVE_VERIFY_DEADLINE_HOUR, _PF_EVE_VERIFY_DEADLINE_MINUTE)
    try:
        await _pf_ensure_deep_verification("evening", tomorrow_iso, deadline_ts, force=True)
    except Exception as e:
        print(f"[preflight-recheck] force verify error chat={chat_id}: {e!r}")
        return
    _pf_set_setting(_pf_eve_recheck_key(tomorrow_iso, chat_id), str(attempts + 1))
    _pf_set_setting(_pf_eve_recheck_ts_key(tomorrow_iso, chat_id), str(now_ts))

# --- AUTO-RECHECK + MESSAGE CORRECTION 20260712 END -------------------------


async def _pf_send_admin_evening_report(chat_id: int, tomorrow_iso: str) -> None:
    try:
        report = _pf_build_report(today_iso=tomorrow_iso, db_path=TPILOT_DB_PATH)
        deep_blob = _pf_read_verify_blob("evening", tomorrow_iso)
        if deep_blob is not None and callable(_pf_apply_deep_results):
            report = _pf_apply_deep_results(report, deep_blob, period_kind="tomorrow")
        text = _pf_render_admin_text(report, period_kind="tomorrow")
    except Exception as e:
        print(f"[preflight-eve] build_report/render error: {e!r}")
        return

    msg_key = f"preflight_msg_admin_evening_{chat_id}"
    prev_ref = _pb_get_setting(msg_key)
    if prev_ref:
        prev_date, _, prev_mid = prev_ref.partition(":")
        if prev_date and prev_date != tomorrow_iso and prev_mid.strip().isdigit():
            try:
                await client.delete_messages(int(chat_id), [int(prev_mid)])
            except Exception as e:
                print(f"[preflight-eve] previous message delete failed chat={chat_id}: {e!r}")

    try:
        msg = await client.send_message(
            int(chat_id), _safe_text(text),
            buttons=[[Button.inline("✅ Ознакомился", b"pfok:ae")]],
        )
    except Exception as e:
        print(f"[preflight-eve] send failed chat={chat_id}: {e!r}")
        return

    try:
        mid = int(getattr(msg, "id", 0) or 0)
        if mid:
            _pf_set_setting(msg_key, f"{tomorrow_iso}:{mid}")
    except Exception:
        pass
    _pf_set_setting(f"preflight_admin_evening_sent_{tomorrow_iso}_{chat_id}", "1")
    # AUTO-RECHECK 20260712: record whether this FIRST send was already ok
    # or a problem, so later ticks know whether a correction is relevant at
    # all. An already-ok first send is marked resolved=1 too (nothing ever
    # needs correcting for it).
    is_ok = bool(callable(_pf_report_is_ok) and _pf_report_is_ok(report))
    _pf_set_setting(_pf_eve_status_key(tomorrow_iso, chat_id), "ok" if is_ok else "problem")
    if is_ok:
        _pf_set_setting(_pf_eve_resolved_key(tomorrow_iso, chat_id), "1")


async def _pf_admin_evening_tick() -> None:
    if not _PF_STAGE1_OK:
        return
    now = _pf_kyiv_now()
    tomorrow_iso = (now.date() + timedelta(days=1)).isoformat()

    if _pf_verify_window_open(now, _PF_EVE_VERIFY_HOUR_START, _PF_EVE_VERIFY_MINUTE_START, _PF_EVE_SEND_HOUR_CUTOFF):
        deadline_ts = _pf_deadline_loop_time(now, _PF_EVE_VERIFY_DEADLINE_HOUR, _PF_EVE_VERIFY_DEADLINE_MINUTE)
        try:
            await _pf_ensure_deep_verification("evening", tomorrow_iso, deadline_ts)
        except Exception as e:
            print(f"[preflight-verify] ensure error evening {tomorrow_iso}: {e!r}")

    if not _pf_eve_within_send_window(now):
        return
    targets = _notification_targets()
    if not targets:
        return
    for chat_id in targets:
        try:
            if _pb_get_setting(f"preflight_admin_evening_sent_{tomorrow_iso}_{chat_id}") == "1":
                # AUTO-RECHECK 20260712: already sent -- see if a correction
                # is needed/possible instead of doing nothing forever.
                await _pf_admin_evening_maybe_correct(chat_id, tomorrow_iso, now)
                continue
            await _pf_send_admin_evening_report(chat_id, tomorrow_iso)
        except Exception as e:
            print(f"[preflight-eve] tick error chat={chat_id}: {e!r}")


async def _preflight_admin_evening_loop() -> None:
    while True:
        try:
            await _pf_admin_evening_tick()
        except asyncio.CancelledError:
            return
        except Exception as e:
            print(f"[preflight-eve] loop error: {e!r}")
        await asyncio.sleep(60)

# --- TPILOT EVENING PREFLIGHT (ADMIN, TOMORROW) END ---


# --- TPILOT PREFLIGHT MANUAL TRIGGER (pf:manual_check) 20260713 START ------
# Admin-pressable manual readiness check -- TWO buttons, "🛡 Проверить
# сегодня" (today/morning-style) and "🛡 Проверить завтра" (tomorrow/evening-
# style). Both go through the SAME shared _pf_manual_check_run(chat_id,
# user_id, mode) helper and the SAME native functions the scheduled jobs use
# (_pf_build_report / _pf_ensure_deep_verification(force=True) /
# _pf_apply_deep_results / _pf_render_admin_text / _pf_correct_message) --
# never a bespoke direct call/signature, which is what caused the earlier
# ad-hoc external script to send a wrong message at the wrong time.
#
# "tomorrow" mode shares the SAME stored message slot
# (preflight_msg_admin_evening_{chat_id}) and status/resolved KV as the
# scheduled evening report (unchanged from the previous single-button
# patch), so a manual press and the automatic evening recheck loop never
# fight over two different messages. "today" mode reuses the existing
# scheduled MORNING slot (preflight_msg_admin_{chat_id}) the same way, for
# the same reason -- one canonical "today readiness" message per chat,
# whoever (schedule or admin) last refreshed it.
#
# The old single callback "pf:manual_check" is kept as a permanent alias for
# "tomorrow" -- any already-rendered old button/message keeps working.
# PartnerBot is never touched here (no import, no call, no message to any
# buyer) -- this is an AdminBot-only, chat-scoped action.

_PF_MANUAL_LABEL_TODAY = "🛡 Проверить сегодня"
_PF_MANUAL_LABEL_TOMORROW = "🛡 Проверить завтра"
_PF_MANUAL_NOTE_OK_TODAY = "✅ Готовность на сегодня перепроверена вручную. Всё готово к работе."
_PF_MANUAL_NOTE_OK_TOMORROW = "✅ Готовность на завтра перепроверена вручную. Всё готово к работе."
_PF_MANUAL_NOTE_PROBLEM_TODAY = "🛡 Ручная перепроверка готовности на сегодня"
_PF_MANUAL_NOTE_PROBLEM_TOMORROW = "🛡 Ручная перепроверка готовности на завтра"
_PF_MANUAL_VERIFY_BUDGET_SEC = 90.0
_PF_MANUAL_POLL_INTERVAL_SEC = 3.0

_PF_MANUAL_CALLBACK_MODES = {
    "pf:manual_check_today": "today",
    "pf:manual_check_tomorrow": "tomorrow",
    "pf:manual_check": "tomorrow",  # backward-compat alias for the original single button
}


def _pf_today_status_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_today_status_{date_iso}_{chat_id}"


def _pf_today_resolved_key(date_iso: str, chat_id: int) -> str:
    return f"preflight_today_resolved_{date_iso}_{chat_id}"


def _pf_manual_mode_config(mode: str) -> Dict[str, Any]:
    """All the per-mode wiring in one place so _pf_manual_check_run stays a
    single shared implementation instead of two near-duplicate copies.
    "today" reuses the scheduled MORNING report's own native period/kind/
    message slot; "tomorrow" reuses the scheduled EVENING ones -- exactly
    mirrors what each scheduled job already does for its own date."""
    if mode == "today":
        return {
            "verify_period": "morning",
            "period_kind": "today",
            "target_date": lambda now: now.date().isoformat(),
            "status_label": _PF_MANUAL_LABEL_TODAY,
            "note_ok": _PF_MANUAL_NOTE_OK_TODAY,
            "note_problem_title": _PF_MANUAL_NOTE_PROBLEM_TODAY,
            "msg_key": lambda chat_id: f"preflight_msg_admin_{chat_id}",
            "sent_key": lambda date_iso, chat_id: f"preflight_admin_sent_{date_iso}_{chat_id}",
            "status_key": _pf_today_status_key,
            "resolved_key": _pf_today_resolved_key,
            "ok_button_data": b"pfok:a",
        }
    return {
        "verify_period": "evening",
        "period_kind": "tomorrow",
        "target_date": lambda now: (now.date() + timedelta(days=1)).isoformat(),
        "status_label": _PF_MANUAL_LABEL_TOMORROW,
        "note_ok": _PF_MANUAL_NOTE_OK_TOMORROW,
        "note_problem_title": _PF_MANUAL_NOTE_PROBLEM_TOMORROW,
        "msg_key": lambda chat_id: f"preflight_msg_admin_evening_{chat_id}",
        "sent_key": lambda date_iso, chat_id: f"preflight_admin_evening_sent_{date_iso}_{chat_id}",
        "status_key": _pf_eve_status_key,
        "resolved_key": _pf_eve_resolved_key,
        "ok_button_data": b"pfok:ae",
    }


async def _pf_manual_cleanup_stale_message(chat_id: int, msg_key: str, target_iso: str) -> None:
    """20260713: the scheduled morning/evening/partner send paths already
    delete a stored message that belongs to a DIFFERENT date before sending
    a new one -- the manual trigger did not, so a manual press whose stored
    slot pointed at yesterday's table would send a new message and silently
    overwrite the key, leaving the old table in the chat forever. Mirrors
    the exact same policy: only deletes when the stored date differs from
    target_iso (same-date stays untouched -- _pf_correct_message edits it
    in place afterward); delete failure never blocks the new report. Never
    raises."""
    prev_ref = _pb_get_setting(msg_key)
    if not prev_ref:
        return
    prev_date, _, prev_mid = prev_ref.partition(":")
    if prev_date and prev_date != target_iso and prev_mid.strip().isdigit():
        try:
            await client.delete_messages(int(chat_id), [int(prev_mid)])
        except Exception as e:
            print(f"[preflight-manual] stale message delete failed chat={chat_id}: {e!r}")


async def _pf_manual_check_run(chat_id: int, user_id: int, mode: str = "tomorrow") -> None:
    if not _PF_STAGE1_OK:
        try:
            await client.send_message(int(chat_id), "⚠️ Модуль проверки готовности недоступен (ошибка импорта).")
        except Exception:
            pass
        return

    cfg = _pf_manual_mode_config(mode if mode == "today" else "tomorrow")
    now = _pf_kyiv_now()
    target_iso = cfg["target_date"](now)

    status_mid = 0
    try:
        msg = await client.send_message(int(chat_id), f"⏳ {cfg['status_label']}...")
        status_mid = int(getattr(msg, "id", 0) or 0)
    except Exception as e:
        print(f"[preflight-manual] status send failed chat={chat_id} mode={mode}: {e!r}")

    # Force a fresh deep-verify run via the SAME guarded helper the scheduled
    # auto-recheck uses (never a raw/ad-hoc call), using the correct existing
    # kind for this mode (morning for today, evening for tomorrow), then wait
    # a bounded budget for it to actually land before rendering -- a manual
    # press should show a genuinely fresh result, not a stale blob.
    deadline_ts = asyncio.get_event_loop().time() + _PF_MANUAL_VERIFY_BUDGET_SEC
    try:
        await _pf_ensure_deep_verification(cfg["verify_period"], target_iso, deadline_ts, force=True)
    except Exception as e:
        print(f"[preflight-manual] force verify error chat={chat_id} mode={mode}: {e!r}")

    waited = 0.0
    while waited < _PF_MANUAL_VERIFY_BUDGET_SEC:
        if _PF_VERIFY_IN_PROGRESS.get(cfg["verify_period"]) != target_iso:
            break
        await asyncio.sleep(_PF_MANUAL_POLL_INTERVAL_SEC)
        waited += _PF_MANUAL_POLL_INTERVAL_SEC

    try:
        report = _pf_build_report(today_iso=target_iso, db_path=TPILOT_DB_PATH)
        deep_blob = _pf_read_verify_blob(cfg["verify_period"], target_iso)
        if deep_blob is not None and callable(_pf_apply_deep_results):
            report = _pf_apply_deep_results(report, deep_blob, period_kind=cfg["period_kind"])
        text = _pf_render_admin_text(report, period_kind=cfg["period_kind"])
    except Exception as e:
        print(f"[preflight-manual] build_report/render error chat={chat_id} mode={mode}: {e!r}")
        if status_mid:
            try:
                # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal,
                # no other failure path reaches the report/pfok-close screen.
                await client.edit_message(int(chat_id), status_mid, "❌ Ошибка при построении отчёта готовности.", buttons=_terminal_ok_button())
            except Exception:
                pass
        return

    is_ok = bool(callable(_pf_report_is_ok) and _pf_report_is_ok(report))
    note = cfg["note_ok"] if is_ok else cfg["note_problem_title"]
    final_text = (
        _pf_apply_correction_note(text, note)
        if callable(_pf_apply_correction_note) else f"{note}\n\n{text}"
    )
    fallback_titled = f"{_PF_CORRECTED_TITLE_ADMIN}\n\n{text}"
    buttons = [[Button.inline("✅ Ознакомился", cfg["ok_button_data"])]]

    msg_key = cfg["msg_key"](chat_id)
    await _pf_manual_cleanup_stale_message(chat_id, msg_key, target_iso)
    prev_ref = _pb_get_setting(msg_key)
    prev_mid = 0
    if prev_ref:
        prev_date, _, prev_mid_s = prev_ref.partition(":")
        if prev_date == target_iso and prev_mid_s.strip().isdigit():
            prev_mid = int(prev_mid_s)

    if prev_mid:
        ok, new_mid = await _pf_correct_message(chat_id, prev_mid, final_text, fallback_titled, buttons)
    else:
        # No stored message for this date yet -- a plain first send, never
        # the "Обновлено" correction title (there is nothing to correct).
        ok, new_mid = True, None
        try:
            msg = await client.send_message(int(chat_id), _safe_text(final_text), buttons=buttons)
            new_mid = int(getattr(msg, "id", 0) or 0) or None
        except Exception as e:
            ok = False
            print(f"[preflight-manual] send failed chat={chat_id} mode={mode}: {e!r}")

    if status_mid:
        # The transient "⏳ ..." status message is always redundant once the
        # real report has been edited in place or (re)sent -- clean it up.
        try:
            await client.delete_messages(int(chat_id), [status_mid])
        except Exception:
            pass

    if not ok:
        return
    if new_mid:
        _pf_set_setting(msg_key, f"{target_iso}:{new_mid}")
    _pf_set_setting(cfg["sent_key"](target_iso, chat_id), "1")
    _pf_set_setting(cfg["status_key"](target_iso, chat_id), "ok" if is_ok else "problem")
    _pf_set_setting(cfg["resolved_key"](target_iso, chat_id), "1" if is_ok else "0")


@client.on(events.CallbackQuery)
async def _pf_manual_check_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        mode = _PF_MANUAL_CALLBACK_MODES.get(data)
        if mode is None:
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        if _panel_callback_is_duplicate(chat_id, user_id, data):
            await _pb_safe_answer(event, "Уже выполняю проверку...")
            return
        await _pb_safe_answer(event, "⏳ Запускаю ручную проверку готовности...")
        _pb_track_task(_pf_manual_check_run(chat_id, user_id, mode))
    except Exception as exc:
        print(f"[preflight-manual] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


# Make both buttons discoverable from the AdminBot "🧰 Сервис" screen,
# without touching the existing service-menu implementation -- same
