# --- TPILOT BIZLINKS READINESS REPAIR (bizfix:) START ---
# "🔄 Проверить и исправить" on the bizlinks_show screen. On-demand self-heal for
# ONE specific already-selected date: finds expected (scheduled) managers who are
# below the configured per-manager link count for that exact date and reuses the
# existing, already-idempotent /bizlink_create_n command (same panel_commands
# queue + controller round-trip BLD's "Ссылки на дату" already uses) to create
# only the missing slots. Never deletes/recreates active slots itself -- any
# tg_limit cleanup that occurs is entirely inside the existing, unmodified
# tg_limit_auto recovery path. Runs as a background task so the button press
# itself never blocks the bot (a single manager's repair can legitimately take
# minutes); a duplicate-click guard prevents a second run for the same date
# while one is already in flight.

async def _bizfix_expected_incomplete(target_date: str, count: int) -> list:
    """Read-only: [(manager_key, active_count)] for scheduled managers on
    target_date whose active link count is below `count`. Reuses the same
    schedule helper and active-link definition as the display path."""
    expected_keys = set()
    try:
        if _SCHED_PB_OK and callable(_sched_pb_working_date):
            expected_keys = {
                normalize_manager_key(k) for k in (_sched_pb_working_date(target_date, TPILOT_DB_PATH) or [])
            }
    except Exception:
        expected_keys = set()
    if not expected_keys:
        return []
    try:
        rows = _bsl_links_for_date(target_date, TPILOT_DB_PATH)
    except Exception:
        rows = []
    active_by_mk: Dict[str, int] = {}
    for r in rows:
        mk = normalize_manager_key(r.get("manager_key") or "")
        if not mk:
            continue
        if (str(r.get("status") or "") == "created"
                and str(r.get("link_url") or "").strip()
                and not str(r.get("deleted_at") or "").strip()):
            active_by_mk[mk] = active_by_mk.get(mk, 0) + 1
    out = []
    for mk in sorted(expected_keys):
        active = active_by_mk.get(mk, 0)
        if active < count:
            out.append((mk, active))
    return out


def _bizfix_date_disp(target_date: str) -> str:
    try:
        return datetime.strptime(target_date, "%Y-%m-%d").strftime("%d.%m.%Y")
    except Exception:
        return str(target_date or "")


async def _bizfix_run(chat_id: int, user_id: int, target_date: str) -> None:
    try:
        count = _pb_bizlink_default_count()
    except Exception:
        count = 15
    date_disp = _bizfix_date_disp(target_date)

    try:
        incomplete = await _bizfix_expected_incomplete(target_date, count)
    except Exception as e:
        incomplete = []
        print(f"[bizfix] expected-incomplete lookup failed: {e!r}")

    if not incomplete:
        try:
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, done.
            await client.send_message(
                int(chat_id),
                f"✅ Проверка {date_disp}: все запланированные менеджеры уже готовы ({count}/{count}).",
                buttons=_terminal_ok_button(),
            )
        except Exception:
            pass
        return

    try:
        label_map = _pb_build_label_map()
    except Exception:
        label_map = {}

    status_msg_id = 0
    try:
        msg = await client.send_message(
            int(chat_id),
            f"⏳ Проверка и исправление на {date_disp}\nНайдено неполных: {len(incomplete)}",
        )
        status_msg_id = int(getattr(msg, "id", 0) or 0)
    except Exception:
        pass

    results = []
    for mk, active_before in incomplete:
        label = str(label_map.get(mk) or mk)
        try:
            row = await _submit_and_wait(
                f"/bizlink_create_n {mk} {count} {target_date}",
                user_id, chat_id, chat_id,
            )
            status = str(row.get("status") or "")
            ok = status == "done"
            text = str((row.get("result_text") if ok else (row.get("error_text") or row.get("result_text"))) or "")
            results.append(f"{'✅' if ok else '⚠️'} {label} ({mk}): {text[:250]}")
        except Exception as e:
            results.append(f"❌ {label} ({mk}): {e!r}"[:250])
        await asyncio.sleep(5)

    report_text = "\n\n".join([f"📦 Итог проверки {date_disp}"] + results)
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, fix run complete.
        if status_msg_id:
            await client.edit_message(int(chat_id), status_msg_id, _safe_text(report_text), buttons=_terminal_ok_button())
        else:
            await client.send_message(int(chat_id), _safe_text(report_text), buttons=_terminal_ok_button())
    except Exception:
        try:
            await client.send_message(int(chat_id), _safe_text(report_text), buttons=_terminal_ok_button())
        except Exception:
            pass

    # Show the post-repair state for this exact date so the admin sees the result
    # without a manual extra tap.
    try:
        await _pb_send_menu_message(int(chat_id), f"bizlinks_show:{target_date}")
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _bizfix_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("bizfix:"):
            return
        target_date = data.split(":", 1)[1] if ":" in data else ""
        if not target_date:
            await _pb_safe_answer(event, "Некорректная дата", alert=True)
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        if _panel_callback_is_duplicate(chat_id, user_id, f"bizfix:{target_date}"):
            await _pb_safe_answer(event, "Уже выполняю проверку...")
            return
        await _pb_safe_answer(event, "⏳ Проверяю и исправляю...")
        _pb_track_task(_bizfix_run(chat_id, user_id, target_date))
    except Exception as exc:
        print(f"[bizfix] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

# --- TPILOT BIZLINKS READINESS REPAIR (bizfix:) END ---


# --- TPILOT PROXY BUY STAGE4 (Proxy-Seller automatic SOCKS5 purchase) START ---
# UI-only: this block submits /manager_proxy_buy_calc and
# /manager_proxy_buy_confirm through the existing panel_commands queue
# (_submit_and_wait) exactly like the manual SOCKS5 flow submits
# /manager_proxy_set -- every real provider HTTP call, storage write, and
# manager-field update happens in the controller (main.py), never here.
# Structured data travels back as a JSON string in result_text (panel_
# commands has no result_json column).

def _pbuy_parse_result_json(row: dict) -> dict:
    """Parse the JSON payload the Stage 4 buy-flow commands return in
    result_text. Never raises -- returns a safe {"ok": False, ...} dict on
    any parse failure or queue-level error (e.g. timeout)."""
    status = str((row or {}).get("status") or "")
    if status not in ("done", "error"):
        return {"ok": False, "message": "Команда не выполнена вовремя. Попробуйте ещё раз."}
    text = str((row or {}).get("result_text") or (row or {}).get("error_text") or "")
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {"ok": False, "message": text or "Неизвестная ошибка."}


def _pbuy_calc_preview_text(data: dict) -> str:
    lines = [
        "🛒 Покупка SOCKS5 автоматически",
        "",
        f"Менеджер: {data.get('display_name') or data.get('manager_key') or '_'}",
        f"Страна: {data.get('country_name') or '_'} / {data.get('country_alpha3') or '_'}",
        f"Период: {data.get('period_id') or '_'}",
        f"Количество: {data.get('quantity') or '_'}",
    ]
    price = data.get("price")
    total = data.get("total")
    currency = str(data.get("currency") or "").strip()
    if total is not None:
        lines.append(f"Цена: {total} {currency}".rstrip())
    elif price is not None:
        lines.append(f"Цена: {price} {currency}".rstrip())
    else:
        lines.append("Цена: не удалось определить")
    balance = data.get("balance")
    if balance is not None:
        lines.append(f"Баланс: {balance}")
    lines.append("")
    lines.append("⚠️ Деньги ещё не списаны.")
    return "\n".join(lines)


def _pbuy_confirm_buttons(key: str, *, ret: str = ""):
    key = normalize_manager_key(key or "")
    cancel_cb = f"pxm:menu:{key}".encode() if ret == "proxy_card" else f"wiz:buyproxy:cancel:{key}".encode()
    return [
        [Button.inline("✅ Подтверди��ь покупку", f"wiz:buyproxy:confirm:{key}".encode())],
        [Button.inline("❌ Отмена", cancel_cb)],
    ]


def _pbuy_recover_buttons(key: str, order_id) -> list:
    key = normalize_manager_key(key or "")
    order_id = str(order_id or "").strip()
    rows = [[Button.inline("🔄 Дозабрать proxy", f"wiz:buyproxy:recover:{key}:{order_id}".encode())]]
    rows.extend(_back_to_panel_buttons())
    return rows


def _pbuy_result_text(data: dict) -> str:
    ok = bool(data.get("check_ok"))
    lines = [
        "✅ Прокси куплен и настроен" if ok else "⚠️ Прокси куплен, но проверка не прошла",
        "",
        f"Менеджер: {data.get('display_name') or data.get('manager_key') or '_'}",
        "Тип: SOCKS5",
        f"Страна: {data.get('country_name') or '_'}",
    ]
    info_text = str(data.get("info_text") or "").strip()
    if info_text:
        lines.append("")
        lines.append(info_text)
    if not ok:
        guard_text = str(data.get("guard_text") or "").strip()
        if guard_text:
            lines.append("")
            lines.append(f"Причина: {guard_text[:300]}")
    lines.append("")
    lines.append(f"Срок до: {data.get('expires_at') or 'не определён'}")
    lines.append(f"Проверка: {'✅ работает' if ok else '⚠️ не работает'}")
    order_id = data.get("provider_order_id")
    order_number = data.get("provider_order_number")
    proxy_id = data.get("provider_proxy_id")
    if order_id:
        lines.append(f"Provider order id: {order_id}")
    if order_number:
        lines.append(f"Provider order number: {order_number}")
    if proxy_id:
        lines.append(f"Provider proxy id: {proxy_id}")
    return "\n".join(lines)


def _ppool_guard_failed_buttons(lease_id, manager_key: Optional[str] = None) -> list:
    """Recovery buttons shown when a just-bought/assigned proxy's guard
    check failed (Stage 6.1B). Every button here is no-spend: check/sync
    are read-only provider calls, card is a local read, and 'pick another
    from pool' re-enters the existing no-spend onboarding picker."""
    rows = [
        [Button.inline("🧪 Проверить ещё раз", f"ppool:check:{lease_id}".encode())],
        [Button.inline("🔄 Обновить данные proxy", b"ppool:sync")],
        [Button.inline("🌐 Открыть карточку proxy", f"ppool:card:{lease_id}".encode())],
    ]
    if manager_key:
        rows.append([Button.inline("🟢 Выбрать другой proxy из пула", f"wiz:add_manager:frompool:{normalize_manager_key(manager_key)}".encode())])
    rows.extend(_back_to_panel_buttons())
    return rows


async def _pbuy_run_calc(chat_id: int, user_id: int, key: str, *, ret: str = "") -> None:
    row = await _submit_and_wait(f"/manager_proxy_buy_calc {key}", user_id, chat_id, chat_id)
    data = _pbuy_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Не удалось рассчитать стоимость покупки.")
        if ret == "proxy_card":
            _wizard_clear(chat_id, user_id)
            try:
                await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_pxm_menu_buttons(key))
            except Exception:
                pass
            return
        _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_add_manager_proxy_choice_buttons(key))
        except Exception:
            pass
        return
    _wizard_set(chat_id, user_id, "add_manager", "buyproxy_confirm", {"key": key, "ret": ret})
    try:
        await client.send_message(chat_id, _safe_text(_pbuy_calc_preview_text(data)), buttons=_pbuy_confirm_buttons(key, ret=ret))
    except Exception:
        pass


async def _pbuy_run_confirm(chat_id: int, user_id: int, key: str, *, ret: str = "") -> None:
    try:
        await client.send_message(chat_id, "⏳ Покупаю и жду выдачу прокси... это может занять до 5 минут.")
    except Exception:
        pass
    row = await _submit_and_wait(f"/manager_proxy_buy_confirm {key}", user_id, chat_id, chat_id)
    data = _pbuy_parse_result_json(row)
    if not data.get("ok"):
        order_id = data.get("order_id")
        if str(data.get("error") or "") == "provisioning_pending" and order_id:
            # Money is already spent -- never offer "buy again" here, only
            # the no-spend recovery re-check. ret is carried forward via a
            # minimal wizard-state payload (not callback_data) so recover
            # (possibly clicked several times) keeps returning here.
            msg = str(data.get("message") or "Покупка совершена, proxy ещё не готов у провайдера.")
            if ret == "proxy_card":
                _wizard_set(chat_id, user_id, "pxm", "buy_recover_pending", {"key": key, "ret": ret})
            else:
                _wizard_clear(chat_id, user_id)
            try:
                await client.send_message(chat_id, "⏳ " + _safe_text(msg), buttons=_pbuy_recover_buttons(key, order_id))
            except Exception:
                pass
            return
        msg = str(data.get("message") or "Не удалось купить прокси.")
        if ret == "proxy_card":
            _wizard_clear(chat_id, user_id)
            try:
                await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_pxm_menu_buttons(key))
            except Exception:
                pass
            return
        _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_add_manager_proxy_choice_buttons(key))
        except Exception:
            pass
        return
    if ret == "proxy_card":
        _wizard_clear(chat_id, user_id)
        try:
            # TPILOT PROXY RESULT CARD 20260718: never immediately expose the
            # password here -- a check_ok=False guard failure still shows its
            # (password-free) diagnostic text, then either way the masked
            # result card follows (full reveal only via the PIN-gated button).
            if not data.get("check_ok"):
                await client.send_message(
                    chat_id,
                    _safe_text(_pbuy_result_text(data)),
                    buttons=_ppool_guard_failed_buttons(data.get("lease_id"), key),
                )
            await _pxm_send_result_card(chat_id, key)
        except Exception:
            pass
        return
    if await _prep_resume_after_proxy(chat_id, user_id, key):
        return
    _wizard_set(chat_id, user_id, "add_manager", "auth_choice", {"key": key})
    try:
        if data.get("check_ok"):
            # PROXY USAGE DETECTION 20260711: clean success card (privileged
            # AdminBot moment, right after a successful buy) instead of the
            # old multi-line technical dump.
            card_text = await _ppool_success_card_text_from_lease(data, fallback_text=_pbuy_result_text(data))
            await client.send_message(
                chat_id,
                _safe_text(card_text) + "\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key),
            )
        else:
            # Proxy is bought and stays in the pool regardless -- only the
            # wording/buttons differ. Onboarding still proceeds to the auth
            # chooser (the manager row + proxy fields are already set); the
            # recovery buttons are additional, non-blocking options. Not a
            # clean "success" moment (guard failed) -- keeps the diagnostic
            # text with the failure reason, not the minimal success card.
            await client.send_message(
                chat_id,
                _safe_text(_pbuy_result_text(data)) + "\n\nМожно продолжить (выбрать способ входа) или сначала разобраться с proxy.\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key) + _ppool_guard_failed_buttons(data.get("lease_id"), key),
            )
    except Exception:
        pass


async def _pbuy_run_recover(chat_id: int, user_id: int, key: str, order_id: str, *, ret: str = "") -> None:
    row = await _submit_and_wait(f"/manager_proxy_buy_recover {key} {order_id}", user_id, chat_id, chat_id)
    data = _pbuy_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Proxy пока не готов.")
        if ret == "proxy_card":
            _wizard_set(chat_id, user_id, "pxm", "buy_recover_pending", {"key": key, "ret": ret})
        try:
            await client.send_message(chat_id, "⏳ " + _safe_text(msg), buttons=_pbuy_recover_buttons(key, order_id))
        except Exception:
            pass
        return
    if ret == "proxy_card":
        _wizard_clear(chat_id, user_id)
        try:
            if not data.get("check_ok"):
                await client.send_message(chat_id, _safe_text(_pbuy_result_text(data)), buttons=_ppool_guard_failed_buttons(data.get("lease_id"), key))
            await _pxm_send_result_card(chat_id, key)
        except Exception:
            pass
        return
    if await _prep_resume_after_proxy(chat_id, user_id, key):
        return
    _wizard_set(chat_id, user_id, "add_manager", "auth_choice", {"key": key})
    try:
        if data.get("check_ok"):
            await client.send_message(
                chat_id,
                _safe_text(_pbuy_result_text(data)) + "\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key),
            )
        else:
            await client.send_message(
                chat_id,
                _safe_text(_pbuy_result_text(data)) + "\n\nМожно продолжить (выбрать способ входа) или сначала разобраться с proxy.\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key) + _ppool_guard_failed_buttons(data.get("lease_id"), key),
            )
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _pbuy_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data.startswith("wiz:add_manager:buyproxy:"):
            key = normalize_manager_key(data.split(":", 3)[3])
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"pbuy:calc:{key}"):
                await _pb_safe_answer(event, "Уже считаю стоимость...")
                return
            await _pb_safe_answer(event, "⏳ Считаю стоимость...")
            _pb_track_task(_pbuy_run_calc(chat_id, user_id, key))
            return

        if data.startswith("wiz:buyproxy:confirm:"):
            key = normalize_manager_key(data.split(":", 3)[3])
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"pbuy:confirm:{key}"):
                await _pb_safe_answer(event, "Уже выполняю покупку...")
                return
            # Spend-action safety: the "buyproxy_confirm" wizard step for
            # this exact key is a ONE-TIME token -- consume it here, before
            # spawning the purchase task, so a delayed second tap on the
            # same button (past the short dedupe window above) can never
            # trigger a second real purchase.
            state = _wizard_get(chat_id, user_id)
            step_ok = (
                state
                and str(state.get("wizard") or "") == "add_manager"
                and str(state.get("step") or "") == "buyproxy_confirm"
                and str((state.get("payload") or {}).get("key") or "") == key
            )
            if not step_ok:
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            ret = str((state.get("payload") or {}).get("ret") or "")
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Покупаю прокси...")
            _pb_track_task(_pbuy_run_confirm(chat_id, user_id, key, ret=ret))
            return

        if data.startswith("wiz:buyproxy:recover:"):
            # No spend here -- read-only re-check of an already-placed
            # order (list_proxies / download_proxies only). No one-time
            # token needed: a repeated click just re-checks the provider
            # again, which is safe and idempotent on the "still pending"
            # path; the short dedupe window below covers rapid double-taps.
            parts = data.split(":", 4)
            key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            order_id = parts[4].strip() if len(parts) > 4 else ""
            if not key or not order_id:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"pbuy:recover:{key}:{order_id}"):
                await _pb_safe_answer(event, "Уже проверяю...")
                return
            # ret is carried via wizard state (set by _pbuy_run_confirm's/
            # _pbuy_run_recover's own provisioning_pending branch as
            # pxm/buy_recover_pending), not callback_data.
            ret = ""
            try:
                _st = _wizard_get(chat_id, user_id)
                _payload = (_st or {}).get("payload") or {}
                if str(_st.get("wizard") or "") == "pxm" and normalize_manager_key(str(_payload.get("key") or "")) == key:
                    ret = str(_payload.get("ret") or "")
            except Exception:
                ret = ""
            await _pb_safe_answer(event, "⏳ Проверяю у провайдера...")
            _pb_track_task(_pbuy_run_recover(chat_id, user_id, key, order_id, ret=ret))
            return

        if data.startswith("wiz:buyproxy:cancel:"):
            key = normalize_manager_key(data.split(":", 3)[3])
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
            await _pb_safe_answer(event, "Отменено")
            try:
                await event.edit(
                    f"❌ Покупка отменена.\n\nМенеджер: {key}",
                    buttons=_add_manager_proxy_choice_buttons(key),
                )
            except Exception:
                await client.send_message(chat_id, f"❌ Покупка отменена.\n\nМенеджер: {key}", buttons=_add_manager_proxy_choice_buttons(key))
            return
    except Exception as exc:
        print(f"[pbuy] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

# --- TPILOT PROXY BUY STAGE4 END ---


# --- TPILOT PROXY POOL STAGE6.1A (choose proxy from pool during onboarding) START ---
# UI-only: submits /proxy_pool_list available and /proxy_pool_assign
# through the existing panel_commands queue -- same architecture as the
# buy-flow and pool-card assign flows. Never calls the provider, never
# spends. "available" == status in (free, orphaned), computed by the
# controller's _handle_proxy_pool_list_command (Stage 6.1 addition).

def _frompool_item_label(item: dict) -> str:
    lease_id = item.get("lease_id")
    host = item.get("host") or "?"
    port = item.get("port") or "?"
    status = str(item.get("status") or "")
    badge = _PPOOL_STATUS_LABELS.get(status, status or "?")
    expires = item.get("expires_at") or "не определено"
    return f"#{lease_id} | {host}:{port} | {badge} | до {expires}"


def _frompool_picker_text(manager_key: str) -> str:
    return f"🌐 Выбор proxy из пула для менеджера {manager_key}\n\nВыберите свободный proxy:"


def _frompool_picker_buttons(manager_key: str, items: list) -> list:
    key = normalize_manager_key(manager_key or "")
    rows = []
    for item in items[:30]:
        lease_id = item.get("lease_id")
        if lease_id is None:
            continue
        rows.append([Button.inline(_frompool_item_label(item), f"wiz:frompool:pick:{key}:{lease_id}".encode())])
    rows.append([Button.inline("⬅️ Назад к выбору proxy", f"wiz:frompool:back:{key}".encode())])
    return rows


def _frompool_empty_buttons(manager_key: str, prepared: "bool | None" = None) -> list:
    # TPILOT PREPARED ACCOUNTS PHASE 7B BLOCKER-2 FIX (2026-08-11): same
    # auto-detect contract as _add_manager_proxy_choice_buttons -- the
    # "🔓 Подключить без proxy" bypass must never appear anywhere in the
    # 📦 Подготовить на потом (QR/Phone) track, including this empty-pool
    # screen reached via 🌐 Выбрать proxy из пула. `prepared` defaults to
    # None (auto-detect from the live managers row) so the one existing
    # call site stays correct with zero further changes.
    key = normalize_manager_key(manager_key or "")
    if prepared is None:
        row = _manager_row_by_key(key)
        prepared = bool(row and str(row.get("status") or "").strip().lower() == "prepared")
    rows = [
        [Button.inline("🛒 Купить SOCKS5 автоматически", f"wiz:add_manager:buyproxy:{key}".encode())],
        [Button.inline("🌐 Подключить SOCKS5 proxy", f"wiz:add_manager:proxy:{key}".encode())],
    ]
    if not prepared:
        rows.append([Button.inline("🔓 Подключить без proxy", f"wiz:add_manager:bypass:{key}".encode())])
    rows.append([Button.inline("⬅️ Назад к панели", b"menu:main")])
    return rows


def _frompool_confirm_state_ok(state: Optional[dict], manager_key: str, lease_id: int) -> bool:
    """Pure one-time-token check for the onboarding pool-pick confirm
    step -- mirrors _ppool_assign_confirm_state_ok (Stage 6 P3)."""
    try:
        payload = (state or {}).get("payload") or {}
        return bool(
            state
            and str(state.get("wizard") or "") == "frompool"
            and str(state.get("step") or "") == "confirm"
            and normalize_manager_key(str(payload.get("manager_key") or "")) == normalize_manager_key(manager_key)
            and int(payload.get("lease_id") or 0) == int(lease_id)
        )
    except Exception:
        return False


async def _frompool_run_picker(chat_id: int, user_id: int, manager_key: str) -> None:
    row = await _submit_and_wait("/proxy_pool_list available", user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Не удалось получить список прокси.")
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_add_manager_proxy_choice_buttons(manager_key))
        except Exception:
            pass
        return
    items = data.get("items") or []
    if not items:
        try:
            await client.send_message(chat_id, "Свободных proxy в пуле нет", buttons=_frompool_empty_buttons(manager_key))
        except Exception:
            pass
        return
    try:
        await client.send_message(chat_id, _safe_text(_frompool_picker_text(manager_key)), buttons=_frompool_picker_buttons(manager_key, items))
    except Exception:
        pass


async def _frompool_run_confirm_screen(chat_id: int, user_id: int, manager_key: str, lease_id: int, *, ret: str = "") -> None:
    key = normalize_manager_key(manager_key or "")
    _wizard_set(chat_id, user_id, "frompool", "confirm", {"manager_key": key, "lease_id": lease_id, "ret": ret})
    cancel_cb = f"pxm:menu:{key}".encode() if ret == "proxy_card" else f"wiz:add_manager:frompool:{key}".encode()
    try:
        await client.send_message(
            chat_id,
            f"Подключить proxy #{lease_id} к менеджеру {key}?",
            buttons=[
                [Button.inline("✅ Подтвердить", f"wiz:frompool:confirm:{key}:{lease_id}".encode())],
                [Button.inline("❌ Отмена", cancel_cb)],
            ],
        )
    except Exception:
        pass


async def _frompool_run_assign(chat_id: int, user_id: int, manager_key: str, lease_id: int, *, ret: str = "") -> None:
    key = normalize_manager_key(manager_key or "")
    row = await _submit_and_wait(f"/proxy_pool_assign {lease_id} {key}", user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Не удалось подключить прокси.")
        if ret == "proxy_card":
            _wizard_clear(chat_id, user_id)
            try:
                await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_pxm_menu_buttons(key))
            except Exception:
                pass
            return
        _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_add_manager_proxy_choice_buttons(key))
        except Exception:
            pass
        return
    if ret == "proxy_card":
        _wizard_clear(chat_id, user_id)
        try:
            # TPILOT PROXY RESULT CARD 20260718: never immediately expose the
            # password here -- the masked result card follows either way,
            # full reveal only via the PIN-gated button.
            if not data.get("check_ok"):
                await client.send_message(
                    chat_id,
                    _safe_text(_ppool_assign_result_text(data)),
                    buttons=_ppool_guard_failed_buttons(lease_id, key),
                )
            await _pxm_send_result_card(chat_id, key)
        except Exception:
            pass
        return
    if await _prep_resume_after_proxy(chat_id, user_id, key):
        return
    _wizard_set(chat_id, user_id, "add_manager", "auth_choice", {"key": key})
    try:
        if data.get("check_ok"):
            # PROXY USAGE DETECTION 20260711: clean success card.
            card_text = await _ppool_success_card_text_from_lease(data, fallback_text=_ppool_assign_result_text(data))
            await client.send_message(
                chat_id,
                _safe_text(card_text) + "\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key),
            )
        else:
            await client.send_message(
                chat_id,
                _safe_text(_ppool_assign_result_text(data)) + "\n\nМожно продолжить (выбрать способ входа) или сначала разобраться с proxy.\n\n" + _auth_chooser_text(),
                buttons=_auth_chooser_buttons("add", key) + _ppool_guard_failed_buttons(lease_id, key),
            )
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _frompool_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data.startswith("wiz:add_manager:frompool:"):
            key = normalize_manager_key(data.split(":", 3)[3]) if len(data.split(":", 3)) > 3 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"frompool:list:{key}"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            await _pb_safe_answer(event, "⏳ Загружаю доступные proxy...")
            _pb_track_task(_frompool_run_picker(chat_id, user_id, key))
            return

        if data.startswith("wiz:frompool:back:"):
            key = normalize_manager_key(data.split(":", 3)[3]) if len(data.split(":", 3)) > 3 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            # TPILOT PROXY METHOD MENU 20260718: read ret from the CURRENT
            # wizard state (set by pxm:pool: before the picker was shown) --
            # never overwritten yet at this point, since the picker itself
            # never touches wizard state.
            ret = ""
            try:
                _st = _wizard_get(chat_id, user_id)
                _payload = (_st or {}).get("payload") or {}
                if str(_st.get("wizard") or "") == "pxm" and normalize_manager_key(str(_payload.get("key") or "")) == key:
                    ret = str(_payload.get("ret") or "")
            except Exception:
                ret = ""
            await _pb_safe_answer(event, )
            if ret == "proxy_card":
                _wizard_clear(chat_id, user_id)
                try:
                    await client.send_message(chat_id, _safe_text(_pxm_menu_text(key)), buttons=_pxm_menu_buttons(key))
                except Exception:
                    pass
                return
            _wizard_set(chat_id, user_id, "add_manager", "proxy_choice", {"key": key})
            try:
                await client.send_message(chat_id, f"➕ Добавление менеджера\n\nМенеджер: {key}\n\nВыберите способ подключения.", buttons=_add_manager_proxy_choice_buttons(key))
            except Exception:
                pass
            return

        if data.startswith("wiz:frompool:pick:"):
            parts = data.split(":", 4)
            key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            try:
                lease_id = int(parts[4]) if len(parts) > 4 else 0
            except Exception:
                lease_id = 0
            if not key or not lease_id:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            ret = ""
            try:
                _st = _wizard_get(chat_id, user_id)
                _payload = (_st or {}).get("payload") or {}
                if str(_st.get("wizard") or "") == "pxm" and normalize_manager_key(str(_payload.get("key") or "")) == key:
                    ret = str(_payload.get("ret") or "")
            except Exception:
                ret = ""
            await _pb_safe_answer(event, )
            _pb_track_task(_frompool_run_confirm_screen(chat_id, user_id, key, lease_id, ret=ret))
            return

        if data.startswith("wiz:frompool:confirm:"):
            parts = data.split(":", 4)
            key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            try:
                lease_id = int(parts[4]) if len(parts) > 4 else 0
            except Exception:
                lease_id = 0
            if not key or not lease_id:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"frompool:confirm:{key}:{lease_id}"):
                await _pb_safe_answer(event, "Уже подключаю...")
                return
            # One-time token: consumed BEFORE spawning the assign task, so
            # a delayed second tap (past the dedupe window above) can
            # never trigger a second assignment.
            state = _wizard_get(chat_id, user_id)
            if not _frompool_confirm_state_ok(state, key, lease_id):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            ret = str(((state or {}).get("payload") or {}).get("ret") or "")
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Подключаю...")
            _pb_track_task(_frompool_run_assign(chat_id, user_id, key, lease_id, ret=ret))
            return
    except Exception as exc:
        print(f"[frompool] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

# --- TPILOT PROXY POOL STAGE6.1A END ---


# --- TPILOT PROXY METHOD MENU 20260718 CALLBACK (moved 20260718 order-fix:
# was originally defined near the top of the file, before `client` is
# created at module scope -- @client.on(...) is evaluated at decoration
# time, so that raised NameError: name 'client' is not defined on every
# real startup. Placed here, next to _frompool_callback/_pbuy_callback
# (the two flows this handler routes into), now that `client` exists. ---
@client.on(events.CallbackQuery)
async def _pxm_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data.startswith("pxm:menu:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, )
            await _safe_event_edit(event, _safe_text(_pxm_menu_text(key)), buttons=_pxm_menu_buttons(key))
            return

        if data.startswith("pxm:back:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, )
            text, buttons = _title_for_menu(f"proxy:{key}")
            await _safe_event_edit(event, text, buttons=buttons)
            return

        if data.startswith("pxm:manual:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            await _pb_safe_answer(event, )
            await _pxm_enter_manual(event, chat_id, user_id, key)
            return

        if data.startswith("pxm:pool:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"pxm:pool:{key}"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            # Carries ret through the picker step (which itself never touches
            # wizard state) so wiz:frompool:pick:/back: can read it back.
            _wizard_set(chat_id, user_id, "pxm", "pool_pending", {"key": key, "ret": "proxy_card"})
            await _pb_safe_answer(event, "⏳ Загружаю доступные proxy...")
            _pb_track_task(_frompool_run_picker(chat_id, user_id, key))
            return

        if data.startswith("pxm:buy:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"pxm:buy:{key}"):
                await _pb_safe_answer(event, "Уже считаю стоимость...")
                return
            await _pb_safe_answer(event, "⏳ Считаю стоимость...")
            _pb_track_task(_pbuy_run_calc(chat_id, user_id, key, ret="proxy_card"))
            return

        if data.startswith("pxm:cardresult:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, )
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal.
            await _safe_event_edit(event, _safe_text(_pxm_result_card_text(key)), buttons=_pxm_result_card_buttons(key) + _terminal_ok_button())
            return

        if data.startswith("pxm:reveal:"):
            key = normalize_manager_key(data.split(":", 2)[2]) if len(data.split(":", 2)) > 2 else ""
            if not key:
                await _pb_safe_answer(event, "Пустой manager_key", alert=True)
                return
            if not _manager_row_by_key(key):
                await _pb_safe_answer(event, )
                await _safe_event_edit(event, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
                return
            pin_value = _ppool_pin_env_value()
            if not pin_value:
                await _pb_safe_answer(event, "PIN не настроен", alert=True)
                return
            _wizard_set(chat_id, user_id, "pxm", "reveal_pin", {"key": key})
            await _pb_safe_answer(event, )
            try:
                await client.send_message(chat_id, "🔐 Показать полный proxy\n\nВведите PIN одним сообщением.", buttons=_back_to_panel_buttons())
            except Exception:
                pass
            return
    except Exception as exc:
        print(f"[pxm] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass
