# --- PROXY RENEWAL RELIABILITY R6 (panel_bot button routing) 20260808 END ---


def _prenew_parse_result_json(row: dict) -> dict:
    """Parse the JSON payload the Stage 5 renewal-flow commands return in
    result_text. Never raises -- returns a safe {"ok": False, ...} dict on
    any parse failure or queue-level error (e.g. timeout)."""
    status = str((row or {}).get("status") or "")
    if status not in ("done", "error"):
        return {"ok": False, "message": "Команда не выполнена вовремя. Попробуйте ещё раз."}
    text = str((row or {}).get("result_text") or (row or {}).get("error_text") or "")
    try:
        data = json.loads(text)
        if isinstance(data, dict):
            return data
    except Exception:
        pass
    return {"ok": False, "message": text or "Неизвестная ошибка."}


def _prenew_calc_preview_text(data: dict) -> str:
    lines = [
        "🔁 Продление прокси",
        "",
        f"lease_id: {data.get('lease_id') or '_'}",
        f"Менеджер: {data.get('display_name') or data.get('manager_key') or '_'}",
        f"Хост: {data.get('host') or '_'}:{data.get('port') or '_'}",
        f"Истекает сейчас: {data.get('expires_at') or '_'}",
        f"Период: {data.get('period_id') or '_'}",
    ]
    price = data.get("price")
    total = data.get("total")
    currency = str(data.get("currency") or "").strip()
    if total is not None:
        lines.append(f"Цена продления: {total} {currency}".rstrip())
    elif price is not None:
        lines.append(f"Цена продления: {price} {currency}".rstrip())
    else:
        lines.append("Цена продления: не удалось определить")
    balance = data.get("balance")
    if balance is not None:
        lines.append(f"Баланс: {balance}")
    lines.append("")
    lines.append("⚠️ Деньги ещё не списаны.")
    return "\n".join(lines)


def _prenew_confirm_state_ok(state: Optional[dict], lease_id: int) -> bool:
    """Pure one-time-token check: True only if `state` (as returned by
    _wizard_get) is exactly the pending 'proxy_renew'/'confirm' step for
    this lease_id. Extracted as its own function so it's independently
    testable without mocking Telethon."""
    try:
        return bool(
            state
            and str(state.get("wizard") or "") == "proxy_renew"
            and str(state.get("step") or "") == "confirm"
            and int((state.get("payload") or {}).get("lease_id") or 0) == int(lease_id)
        )
    except Exception:
        return False


def _prenew_confirm_buttons(lease_id) -> list:
    return [
        [Button.inline("✅ Подтвердить продление", f"renew:confirm:{lease_id}".encode())],
        [Button.inline("❌ Отмена", f"renew:cancel:{lease_id}".encode())],
    ]


_PRENEW_LAST_STATUS_LABELS = {
    "renew_ok": "успешно",
    "renew_unverified": "требуется проверка",
    "deferred": "отложено администратором",
}


def _prenew_last_status_display(raw: Any) -> str:
    """NB-4 fix (Proxy Renewal Reliability review, 20260808): classify
    proxy_leases.last_renew_status for user display -- NEVER echoes the raw
    provider-error suffix stored after 'renew_failed:' (main.py's
    _prenew_execute_renewal writes status_text=f"renew_failed:{err_text}",
    and err_text, while scrubbed, is not a guaranteed-safe user-facing
    text). Also fixes the exact bug the review found: a SUCCESSFUL renewal
    (status 'renew_ok') must never render as an error. Unknown/empty ->
    neutral fallback, never the raw value."""
    s = str(raw or "").strip()
    if not s:
        return "нет данных"
    if s in _PRENEW_LAST_STATUS_LABELS:
        return _PRENEW_LAST_STATUS_LABELS[s]
    if s.startswith("renew_failed"):
        return "ошибка"
    if s.startswith("blocked"):
        return "заблокировано настройками"
    return "нет данных"


def _prenew_result_text(data: dict) -> str:
    """BL-2 fix (Proxy Renewal Reliability review, 20260808): on failure
    this NEVER shows data['message'] (a possibly-raw provider error string
    -- errors[]/customData/etc. can end up in it via _pbuy_safe_error's
    best-effort scrub, which is not a guaranteed-safe user-facing text).
    Only the classified reason/action from main.py's _prenew_classify_
    provider_error ever reach the screen; an unclassified/legacy result
    (missing reason/action) gets a fixed neutral fallback, never the raw
    message."""
    ok = bool(data.get("ok"))
    lines = [
        "✅ Прокси продлён" if ok else "❌ Продление не выполнено",
        "",
        f"lease_id: {data.get('lease_id') or '_'}",
        f"Менеджер: {data.get('display_name') or data.get('manager_key') or '_'}",
    ]
    if ok:
        lines.append(f"Хост: {data.get('host') or '_'}:{data.get('port') or '_'}")
        lines.append(f"Новый срок: {data.get('expires_at') or 'не определён (уточните у провайдера)'}")
    else:
        reason = data.get("reason") or "Не удалось выполнить продление."
        action = data.get("action") or "Откройте карточку прокси и проверьте состояние."
        lines.append(f"Причина: {reason}")
        lines.append(f"Что делать: {action}")
    return "\n".join(lines)


async def _prenew_run_calc(chat_id: int, user_id: int, lease_id: int) -> None:
    row = await _submit_and_wait(f"/proxy_renew_calc {lease_id}", user_id, chat_id, chat_id)
    data = _prenew_parse_result_json(row)
    if not data.get("ok"):
        # BL-2 fix: never show data['message'] (possibly raw provider
        # error) -- classified reason/action only, neutral fallback.
        reason = data.get("reason") or "Не удалось ��ыполнить продление."
        action = data.get("action") or "Откройте карточку прокси и проверьте состояние."
        msg = f"Причина: {reason}\nЧто делать: {action}"
        try:
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, no
            # retry action -- admin must go re-check the proxy card manually.
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_back_to_panel_buttons() + _terminal_ok_button())
        except Exception:
            pass
        return
    _wizard_set(chat_id, user_id, "proxy_renew", "confirm", {"lease_id": lease_id})
    try:
        await client.send_message(chat_id, _safe_text(_prenew_calc_preview_text(data)), buttons=_prenew_confirm_buttons(lease_id))
    except Exception:
        pass


async def _prenew_run_confirm(chat_id: int, user_id: int, lease_id: int) -> None:
    try:
        await client.send_message(chat_id, "⏳ Продлеваю прокси...")
    except Exception:
        pass
    row = await _submit_and_wait(f"/proxy_renew_confirm {lease_id}", user_id, chat_id, chat_id)
    data = _prenew_parse_result_json(row)
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal (success
        # or failure), no button-level retry either way.
        await client.send_message(chat_id, _safe_text(_prenew_result_text(data)), buttons=_back_to_panel_buttons() + _terminal_ok_button())
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _prenew_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data.startswith("renew:calc:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"renew:calc:{lease_id}"):
                await _pb_safe_answer(event, "Уже считаю стоимость...")
                return
            await _pb_safe_answer(event, "⏳ Считаю стоимость продления...")
            _pb_track_task(_prenew_run_calc(chat_id, user_id, lease_id))
            return

        if data.startswith("renew:confirm:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"renew:confirm:{lease_id}"):
                await _pb_safe_answer(event, "Уже выполняю продление...")
                return
            # Spend-action safety: the "confirm" wizard step for this exact
            # lease_id is a ONE-TIME token -- consume it here, before
            # spawning the renewal task, so a delayed second tap on the
            # same button (past the short dedupe window above) can never
            # trigger a second real renewal.
            state = _wizard_get(chat_id, user_id)
            if not _prenew_confirm_state_ok(state, lease_id):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Продлеваю прокси...")
            _pb_track_task(_prenew_run_confirm(chat_id, user_id, lease_id))
            return

        if data.startswith("renew:cancel:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                lease_id = 0
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "Отменено")
            try:
                # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal.
                await event.edit(f"❌ Продление отменено.\n\nlease_id: {lease_id}", buttons=_back_to_panel_buttons() + _terminal_ok_button())
            except Exception:
                await client.send_message(chat_id, f"❌ Продление отменено.\n\nlease_id: {lease_id}", buttons=_back_to_panel_buttons() + _terminal_ok_button())
            return

        if data.startswith("renew:defer:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"renew:defer:{lease_id}"):
                await _pb_safe_answer(event, "Уже отложено")
                return
            await _pb_safe_answer(event, "⏰ Откладываю напоминание...")
            row = await _submit_and_wait(f"/proxy_renew_defer {lease_id}", user_id, chat_id, chat_id)
            defer_data = _prenew_parse_result_json(row)
            try:
                # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal
                # either way, no button-level retry.
                if defer_data.get("ok"):
                    await event.edit(f"⏰ Напоминание отложено.\n\nlease_id: {lease_id}", buttons=_back_to_panel_buttons() + _terminal_ok_button())
                else:
                    await event.edit(f"⚠️ Не удалось отложить: {defer_data.get('message') or ''}", buttons=_back_to_panel_buttons() + _terminal_ok_button())
            except Exception:
                pass
            return
    except Exception as exc:
        print(f"[prenew] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass

