async def _ppool_edit_or_send(event, chat_id: int, text: str, buttons=None) -> None:
    """Stage 6.1D: prefer editing the message that triggered this action
    in place (avoids accumulating stale proxy-pool cards in the chat);
    fall back to a new message if there's no event to edit, or the edit
    itself fails for any reason (message too old, already edited by
    another handler, etc.). Used only for the no-side-effect pool
    list/card/check/sync screens -- buy/renew/recover results are
    deliberately left as their own persisted messages."""
    if event is not None:
        try:
            await _safe_event_edit(event, text, buttons=buttons)
            return
        except Exception:
            pass
    try:
        await client.send_message(chat_id, text, buttons=buttons)
    except Exception:
        pass


