def _ppool_list_item_label(item: dict) -> str:
    status = str(item.get("status") or "")
    badge = _PPOOL_STATUS_LABELS.get(status, status or "?")
    host = str(item.get("host") or "?")
    port = item.get("port") or "?"
    return f"{badge} {host}:{port}"


def _ppool_list_text(filt: str, data: dict) -> str:
    items = data.get("items") or []
    if filt == "external":
        # PROXY USAGE DETECTION 20260711: сторонние прокси -- used by a live
        # manager's own config, but no matching proxy_leases row at all.
        # Masked line only, never a password.
        lines = ["🌐 Сторонние прокси", "", "Найдены у менеджеров, но не в пуле.", ""]
        if not items:
            lines.append("Сторонних прокси не найдено.")
        else:
            for item in items[:30]:
                used_by = item.get("used_by") or []
                login = used_by[0].get("proxy_login") if used_by else ""
                lines.append(f"`{_ppool_masked_line(item.get('host'), item.get('port'), login)}`")
                lines.extend(_ppool_used_by_bullets(used_by))
                lines.append("")
            if len(items) > 30:
                lines.append(f"...и ещё {len(items) - 30}")
        return "\n".join(lines).rstrip()
    label = _PPOOL_FILTER_LABELS.get(filt, "📋 Все прокси")
    lines = [f"🌐 Пул прокси — {label}", ""]
    if not items:
        lines.append("Прокси в пуле пока нет.")
    else:
        lines.append(f"Всего: {len(items)}")
    return "\n".join(lines)


def _ppool_list_buttons(filt: str, data: dict) -> list:
    if filt == "external":
        # External items have no lease_id (nothing in the pool to open a
        # card for) -- the masked lines + used_by are already in the text.
        rows = [[Button.inline("🔙 Назад", b"menu:ppool")]]
        rows.extend(_back_to_panel_buttons())
        return rows
    rows = []
    for item in (data.get("items") or [])[:50]:
        lease_id = item.get("lease_id")
        if lease_id is None:
            continue
        rows.append([Button.inline(_ppool_list_item_label(item), f"ppool:card:{lease_id}".encode())])
    rows.append([Button.inline("🔙 Назад", b"menu:ppool")])
    rows.extend(_back_to_panel_buttons())
    return rows


