def _ppool_assign_result_text(data: dict) -> str:
    ok = bool(data.get("check_ok"))
    lines = [
        "✅ Прокси подключён" if ok else "⚠️ Прокси подключён, но проверка не прошла",
        "",
        f"lease_id: {data.get('lease_id') if data.get('lease_id') is not None else '_'}",
        f"Менеджер: {data.get('display_name') or data.get('manager_key') or '_'}",
    ]
    old_key = data.get("old_manager_key")
    if old_key:
        lines.append(f"Отключён от: {old_key}")
    info_text = str(data.get("info_text") or "").strip()
    if info_text:
        lines.append("")
        lines.append(info_text)
    if not ok:
        guard_text = str(data.get("guard_text") or "").strip()
        if guard_text:
            lines.append("")
            lines.append(f"Причина: {guard_text[:300]}")
    lines.append("")
    lines.append(f"Проверка: {'✅ работает' if ok else '⚠️ не работает'}")
    return "\n".join(lines)


# --- PROXY USAGE DETECTION 20260711 START -------------------------------
# Masked (non-privileged) proxy line, compact "used by" rendering, the
# multi-assign warning/confirm screen, and the clean post-install success
# card. Full host:port:login:password only ever appears via
# _proxy_success_card_text (privileged, immediately-after-install moment,
# same trust tier as the existing PIN reveal) or the PIN reveal itself --
# never here, never in any list/card.

def _ppool_masked_line(host: Any, port: Any, login: Any) -> str:
    """Normal (non-privileged) proxy line format: host:port:login:****.
    Password is NEVER included, not even masked characters of it."""
    h = str(host or "_")
    p = port if port not in (None, "") else "_"
    l = str(login or "_")
    return f"{h}:{p}:{l}:****"


def _ppool_used_by_bullets(used_by: list) -> list:
    """One compact bullet line per manager (name · key · @username). Never
    includes login/password. Capped at 10 for a short, professional card
    even if a proxy is heavily multi-assigned."""
    lines = []
    for u in (used_by or [])[:10]:
        name = str(u.get("display_name") or u.get("manager_key") or "?").strip()
        key = str(u.get("manager_key") or "").strip()
        uname = str(u.get("telegram_username") or "").strip()
        bits = [name]
        if key and key != name:
            bits.append(key)
        if uname:
            bits.append(f"@{uname}")
        lines.append("• " + " · ".join(bits))
    if len(used_by or []) > 10:
        lines.append(f"...и ещё {len(used_by) - 10}")
    return lines


def _ppool_used_by_lines(used_by: list, *, prefix: str = "Занят") -> list:
    """Compact 'used by' block with a header line, e.g. 'Занят:' followed
    by one bullet per manager. Empty list -> no lines at all."""
    if not used_by:
        return []
    return [f"{prefix}:"] + _ppool_used_by_bullets(used_by)


def _ppool_multi_assign_warning_text(used_by: list) -> str:
    lines = ["⚠️ Прокси уже используется", "", "Сейчас на нём работает:"]
    lines.extend(_ppool_used_by_bullets(used_by))
    lines.append("")
    lines.append("Установить этот прокси ещё одному аккаунту?")
    return "\n".join(lines)


def _ppool_multi_assign_buttons(lease_id, manager_key: str) -> list:
    return [
        [Button.inline("✅ Да, установить", f"ppool:assign_multi:{lease_id}:{manager_key}".encode())],
        [Button.inline("❌ Отмена", f"ppool:card:{lease_id}".encode())],
    ]


def _ppool_assign_multi_confirm_state_ok(state: Optional[dict], lease_id: int, manager_key: str) -> bool:
    """Pure one-time-token check for the multi-assign confirm step --
    mirrors _ppool_assign_confirm_state_ok."""
    try:
        payload = (state or {}).get("payload") or {}
        return bool(
            state
            and str(state.get("wizard") or "") == "ppool"
            and str(state.get("step") or "") == "assign_multi_confirm"
            and int(payload.get("lease_id") or 0) == int(lease_id)
            and normalize_manager_key(str(payload.get("manager_key") or "")) == normalize_manager_key(manager_key)
        )
    except Exception:
        return False


def _proxy_success_card_text(*, manager_key: str, display_name: str, telegram_username: str,
                              host: Any, port: Any, login: Any, password: Any) -> str:
    """Minimalistic post-install success card. Full host:port:login:password
    appears here ONLY -- the same privileged trust tier as the existing PIN
    reveal (immediately after a successful buy/assign/apply in AdminBot).
    Callers must source `password` from a safe local read (lease flows:
    _ppool_reveal_creds_once; manual one-line set: the operator's own
    just-parsed input) -- never from panel_commands result_text."""
    lines = ["✅ П��окси у��тановлен", "", "Аккаунт:", f"• Ключ: {manager_key or '_'}"]
    name = str(display_name or "").strip()
    if name and name != manager_key:
        lines.append(f"• Имя: {name}")
    uname = str(telegram_username or "").strip().lstrip("@")
    if uname:
        lines.append(f"• Username: @{uname}")
    proxy_row = ":".join(str(v or "_").replace("`", "'") for v in (host, port, login, password))
    lines.extend(["", "Прокси:", f"`{proxy_row}`", "", "Удалите сообщение после копирования."])
    return "\n".join(lines)


async def _ppool_success_card_text_from_lease(data: dict, *, fallback_text: str) -> str:
    """Build the clean success card for a lease-based flow (buy-confirm /
    pool assign / from-pool onboarding) by reading the real host/port/
    login/password via the SAME privileged local-read helper the PIN
    reveal flow already uses (_ppool_reveal_creds_once) -- never from
    panel_commands result_text. Falls back to the caller-supplied plain
    text if the lease has no password on file (nothing to show)."""
    lease_id = data.get("lease_id")
    creds = None
    if lease_id is not None:
        try:
            creds = _ppool_reveal_creds_once(int(lease_id))
        except Exception:
            creds = None
    if not creds:
        return fallback_text
    return _proxy_success_card_text(
        manager_key=str(data.get("manager_key") or ""),
        display_name=str(data.get("display_name") or data.get("manager_key") or ""),
        telegram_username=str(data.get("telegram_username") or ""),
        host=creds.get("host"), port=creds.get("port"), login=creds.get("login"), password=creds.get("password"),
    )

# --- PROXY USAGE DETECTION 20260711 END ---------------------------------


async def _ppool_run_assign_picker(chat_id: int, user_id: int, lease_id: int) -> None:
    try:
        await client.send_message(chat_id, _safe_text(_ppool_assign_picker_text(lease_id)), buttons=_ppool_assign_picker_buttons(lease_id))
    except Exception:
        pass


async def _ppool_run_assign_confirm_screen(chat_id: int, user_id: int, lease_id: int, manager_key: str) -> None:
    row = await _submit_and_wait(f"/proxy_pool_card {lease_id}", user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Не удалось получить карточку прокси.")
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_ppool_root_buttons())
        except Exception:
            pass
        return
    old_manager_key = data.get("manager_key")
    # PROXY USAGE DETECTION 20260711 (blocker fix): a real usage conflict is
    # any live manager OTHER than the target AND OTHER than this lease's own
    # current owner (old_manager_key) already using this host+port -- the
    # lease's own current owner is excluded here, mirroring
    # _handle_proxy_pool_assign_command's own conflict filter, so a plain
    # reassign FROM the current owner TO a new manager (the existing,
    # already-supported single-owner transfer below) is never misrouted
    # into the multi-assign warning just because the owner being replaced
    # still shows up in used_by. Only an INDEPENDENT manager (neither the
    # target nor the current owner) triggers the warning.
    conflict = [
        u for u in (data.get("used_by") or [])
        if normalize_manager_key(str(u.get("manager_key") or "")) != normalize_manager_key(manager_key)
        and normalize_manager_key(str(u.get("manager_key") or "")) != normalize_manager_key(str(old_manager_key or ""))
    ]
    if conflict:
        _wizard_set(chat_id, user_id, "ppool", "assign_multi_confirm", {"lease_id": lease_id, "manager_key": manager_key})
        try:
            await client.send_message(
                chat_id,
                _safe_text(_ppool_multi_assign_warning_text(conflict)),
                buttons=_ppool_multi_assign_buttons(lease_id, manager_key),
            )
        except Exception:
            pass
        return
    _wizard_set(chat_id, user_id, "ppool", "assign_confirm", {"lease_id": lease_id, "manager_key": manager_key})
    try:
        await client.send_message(
            chat_id,
            _safe_text(_ppool_assign_confirm_text(lease_id, manager_key, old_manager_key)),
            buttons=_ppool_assign_confirm_buttons(lease_id, manager_key),
        )
    except Exception:
        pass


async def _ppool_run_assign(chat_id: int, user_id: int, lease_id: int, manager_key: str, *, multi: bool = False) -> None:
    cmd = f"/proxy_pool_assign {lease_id} {manager_key}" + (" multi" if multi else "")
    row = await _submit_and_wait(cmd, user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    if not data.get("ok"):
        # PROXY USAGE DETECTION 20260711: a race (or a direct card-button tap
        # that skipped the confirm screen) can still surface proxy_in_use
        # here -- show the same multi-assign warning instead of a flat error.
        if str(data.get("error") or "") == "proxy_in_use" and not multi:
            _wizard_set(chat_id, user_id, "ppool", "assign_multi_confirm", {"lease_id": lease_id, "manager_key": manager_key})
            try:
                await client.send_message(
                    chat_id,
                    _safe_text(_ppool_multi_assign_warning_text(data.get("used_by") or [])),
                    buttons=_ppool_multi_assign_buttons(lease_id, manager_key),
                )
            except Exception:
                pass
            return
        msg = str(data.get("message") or "Не удалось подключить прокси.")
        try:
            await client.send_message(chat_id, "⚠️ " + _safe_text(msg), buttons=_ppool_card_buttons("all", {"lease_id": lease_id}))
        except Exception:
            pass
        return
    try:
        if data.get("check_ok"):
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): genuine
            # success -- terminal. Appended only in this branch, not the
            # guard-failed one below (which has a real retry action).
            buttons = _ppool_card_buttons("all", {"lease_id": lease_id, "manager_key": data.get("manager_key"), "status": data.get("status")}) + _terminal_ok_button()
            # PROXY USAGE DETECTION 20260711: clean success card only on a
            # genuine success -- the guard-failed branch below keeps the
            # diagnostic text (with the failure reason), same distinction
            # the buy-confirm flow already makes.
            text = await _ppool_success_card_text_from_lease(data, fallback_text=_ppool_assign_result_text(data))
        else:
            # Assignment still succeeded (lease stays linked) -- only offer
            # the no-spend recovery actions alongside, same as the buy flow.
            buttons = _ppool_guard_failed_buttons(lease_id, data.get("manager_key"))
            text = _ppool_assign_result_text(data)
        await client.send_message(chat_id, _safe_text(text), buttons=buttons)
    except Exception:
        pass


