# --- TPILOT PROXY RENEWAL (TPilot-managed prolong) UX 20260721 BEGIN ---
# Button-only «Продление прокси» UX. Every screen submits a /proxy_renewal_*
# command through the existing _submit_and_wait queue and renders the JSON;
# the controller side owns all provider/spend logic. NO spend happens without
# an explicit «Продлить» tap (manual) -- the calc preview is no-spend. Never
# shows a proxy login/password (only provider_proxy_id + host:port). Callbacks
# carry only short numeric lease ids.

def _prn_root_buttons() -> list:
    rows = [
        [Button.inline("📋 К продлению", b"prn:due")],
        [Button.inline("❌ Ошибки продления", b"prn:errors")],
        [Button.inline("⚙️ Автопродление / настройки", b"prn:config")],
    ]
    rows.extend(_back_to_panel_buttons())
    return rows


def _prn_error_text(data: dict, *, fallback_reason: str, fallback_action: str = "Повторите попытку позже.") -> str:
    """BL-2 follow-up fix (independent re-review correction, 20260809):
    shared failure renderer for every prn: screen -- NEVER shows data['message']
    (main.py's renewal handlers only guarantee a best-effort _pbuy_safe_error
    scrub there, which can still carry provider errors[]/customData/raw
    exception text). Only the classified reason/action (main.py's
    _prenew_classify_provider_error, already wired through _renewal_calc_
    preview/_prenew_preflight_check/_prenew_execute_renewal) ever reach the
    screen; an unclassified/legacy result gets a fixed neutral fallback."""
    reason = data.get("reason") or fallback_reason
    action = data.get("action") or fallback_action
    return f"⚠️ Причина: {reason}\nЧто делать: {action}"


def _prn_status_text(data: dict) -> str:
    if not data.get("ok"):
        return _prn_error_text(data, fallback_reason="Не удалось получить статус продления.")
    auto = "🟢 ВКЛ" if int(data.get("automation_enabled") or 0) == 1 else "⚪ ВЫКЛ"
    paused = " ⏸ пауза" if int(data.get("paused") or 0) == 1 else ""
    estop = " ⛔ EMERGENCY STOP" if int(data.get("emergency_stop") or 0) == 1 else ""
    balance = data.get("balance")
    balance_line = f"Баланс Proxy-Seller: {balance:.2f} $" if isinstance(balance, (int, float)) else "Баланс Proxy-Seller: недоступен"
    lines = [
        "💳 Продление прокси",
        "",
        f"Автопродление: {auto}{paused}{estop}",
        f"Окно продления: за {data.get('lead_days')} дн. до истечения",
        f"К продлению сейчас: {data.get('due_count')}",
        f"Ошибок продления: {data.get('failed_count')}",
        balance_line,
        "",
        "Автопродление на сайте Proxy-Seller не используется — TPilot продлевает нужные прокси сам.",
    ]
    return "\n".join(lines)


def _prn_due_buttons(data: dict) -> list:
    rows = []
    for item in (data.get("due") or [])[:20]:
        lid = item.get("lease_id")
        if lid is None:
            continue
        label = f"#{item.get('provider_proxy_id')} {item.get('host')}:{item.get('port')} · {item.get('days_left')}д"
        rows.append([Button.inline(label[:60], f"prn:calc:{lid}".encode())])
    rows.append([Button.inline("🔙 Назад", b"prn:root")])
    rows.extend(_back_to_panel_buttons())
    return rows


def _prn_due_text(data: dict) -> str:
    if not data.get("ok"):
        return _prn_error_text(data, fallback_reason="Не удалось получить список.")
    due = data.get("due") or []
    if not due:
        return "📋 К продлению\n\nНет прокси, требующих продления в ближайшее окно."
    lines = ["📋 К продлению", "", f"Всего: {data.get('due_count')}", "", "Выберите прокси, чтобы рассчитать и продлить:"]
    return "\n".join(lines)


def _prn_calc_text(data: dict) -> str:
    if not data.get("ok"):
        return _prn_error_text(
            data, fallback_reason="Не удалось рассчитать стоимость.",
            fallback_action="Откройте карточку прокси и проверьте состояние.",
        )
    return (
        "💳 Расчёт продления (без списания)\n\n"
        f"Прокси: #{data.get('provider_proxy_id')}\n"
        f"Стоимость: {data.get('total')} {data.get('currency') or ''}\n"
        f"Период: {data.get('period_id')}\n\n"
        "⚠️ Нажмите «Продлить», чтобы СПИСАТЬ средства и продлить этот прокси через Proxy-Seller."
    )


def _prn_calc_buttons(lease_id: int) -> list:
    return [
        [Button.inline("✅ Продлить (списать)", f"prn:confirm:{int(lease_id)}".encode())],
        [Button.inline("❌ Отмена", b"prn:due")],
    ] + _back_to_panel_buttons()


def _prn_config_buttons(data: dict) -> list:
    cfg = data.get("config") or data
    auto_on = int(cfg.get("automation_enabled") or 0) == 1
    paused = int(cfg.get("paused") or 0) == 1
    estop = int(cfg.get("emergency_stop") or 0) == 1
    rows = []
    if auto_on:
        rows.append([Button.inline("⚪ Выключить автопродление", b"prn:cfg:disable_auto")])
    else:
        rows.append([Button.inline("🟢 Включить автопродление (согласие)", b"prn:cfg:enable_auto")])
    rows.append([
        Button.inline("▶️ Снять паузу" if paused else "⏸ Пауза", b"prn:cfg:resume" if paused else b"prn:cfg:pause"),
    ])
    rows.append([
        Button.inline("♻️ Снять EMERGENCY STOP" if estop else "⛔ EMERGENCY STOP", b"prn:cfg:clear_emergency" if estop else b"prn:cfg:emergency_stop"),
    ])
    rows.append([Button.inline("🔙 Назад", b"prn:root")])
    rows.extend(_back_to_panel_buttons())
    return rows


def _prn_config_text(data: dict) -> str:
    cfg = data.get("config") or {}
    if not cfg:
        return "⚠️ Не удалось получить настройки продления."
    auto = "🟢 ВКЛ" if int(cfg.get("automation_enabled") or 0) == 1 else "⚪ ВЫКЛ"
    return "\n".join([
        "⚙️ Автопродление / настройки",
        "",
        f"Автопродление: {auto}",
        f"Пауза: {'да' if int(cfg.get('paused') or 0) == 1 else 'нет'}",
        f"Emergency stop: {'да' if int(cfg.get('emergency_stop') or 0) == 1 else 'нет'}",
        f"Окно (дней): {cfg.get('lead_days')}",
        f"Лимит на операцию: {cfg.get('max_amount_per_op') or 'не задан'}",
        f"Дневной бюджет: {cfg.get('max_daily_spend') or 'не задан'}",
        f"Порог баланса: {cfg.get('min_balance_warn') or 'не задан'}",
        "",
        "⚠️ Включение автопродления = согласие на автоматические списания в пределах лимитов.",
    ])


def _prn_errors_text(data: dict) -> str:
    if not data.get("ok"):
        return "⚠️ Не удалось получить ошибки."
    n = data.get("failed_count") or 0
    if not n:
        return "❌ Ошибки продления\n\nНет неудавшихся операций."
    # BLOCKER-1 fix (retry-policy correction, 20260809): NB-4 -- status
    # 'failed' now means, by construction, ONLY the spend-ambiguous bucket
    # (a provably-no-spend rejection is freed for retry instead of staying
    # 'failed' -- see main.py _renewal_wrapped_execute's
    # spend_provably_absent branch). "Will be retried automatically" was
    # never true for these and is now actively misleading -- they require
    # a provider-refresh reconcile confirmation or manual verification,
    # never an automatic second prolong/make.
    return (
        f"❌ Ошибки продления\n\nНеподтверждённых операций: {n}\n"
        "Повторное списание для них автоматически не выполняется — "
        "синхронизируйте пул или проверьте прокси вручную."
    )


async def _prn_run(event, chat_id: int, user_id: int, command: str, text_fn, buttons_fn) -> None:
    row = await _submit_and_wait(command, user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    try:
        await _ppool_edit_or_send(event, chat_id, _safe_text(text_fn(data)), buttons_fn(data))
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _prn_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("prn:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data == "prn:root":
            await _pb_safe_answer(event, "⏳")
            await _prn_run(event, chat_id, user_id, "/proxy_renewal_status", _prn_status_text, lambda d: _prn_root_buttons())
            return
        if data == "prn:due":
            await _pb_safe_answer(event, "⏳ Загружаю список...")
            await _prn_run(event, chat_id, user_id, "/proxy_renewal_status", _prn_due_text, _prn_due_buttons)
            return
        if data == "prn:errors":
            await _pb_safe_answer(event, "⏳")
            await _prn_run(event, chat_id, user_id, "/proxy_renewal_status", _prn_errors_text, lambda d: _prn_root_buttons())
            return
        if data == "prn:config":
            await _pb_safe_answer(event, "⏳")
            await _prn_run(event, chat_id, user_id, "/proxy_renewal_config", _prn_config_text, _prn_config_buttons)
            return
        if data.startswith("prn:calc:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            await _pb_safe_answer(event, "⏳ Рассчитываю (без списания)...")
            await _prn_run(event, chat_id, user_id, f"/proxy_renewal_calc {lease_id}", _prn_calc_text, lambda d: _prn_calc_buttons(lease_id))
            return
        if data.startswith("prn:confirm:"):
            try:
                lease_id = int(data.split(":", 2)[2])
            except Exception:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"prn:confirm:{lease_id}"):
                await _pb_safe_answer(event, "Уже выполняю...")
                return
            await _pb_safe_answer(event, "💳 Продлеваю...")

            def _confirm_text(d: dict) -> str:
                if d.get("skipped"):
                    return "ℹ️ Продление уже выполняется для этого прокси (дедуп)."
                if d.get("ok"):
                    return f"✅ Продлено.\nНовый срок: {d.get('expires_at')}\nСумма: {d.get('total')} {d.get('currency') or ''}"
                # BL-2 follow-up fix (independent re-review correction,
                # 20260809): NEVER show d['message']/d['error'] (raw
                # provider text) -- classified reason/action only.
                reason = d.get("reason") or "Не удалось выполнить продление."
                action = d.get("action") or "проверьте прокси и состояние Proxy-Seller."
                return f"⚠️ Продление не выполнено\n\nПричина: {reason}\nЧто делать: {action}"
            await _prn_run(event, chat_id, user_id, f"/proxy_renewal_confirm {lease_id} {user_id}", _confirm_text, lambda d: _prn_root_buttons())
            return
        if data.startswith("prn:cfg:"):
            action = data.split(":", 2)[2]
            if action not in ("enable_auto", "disable_auto", "pause", "resume", "emergency_stop", "clear_emergency"):
                await _pb_safe_answer(event, "Неизвестное действие", alert=True)
                return
            await _pb_safe_answer(event, "⏳")
            arg = f"enable_auto {user_id}" if action == "enable_auto" else action
            await _prn_run(event, chat_id, user_id, f"/proxy_renewal_config {arg}", lambda d: "✅ Готово. Обновляю настройки...", lambda d: _prn_config_buttons({"config": {}}))
            # then refresh the config screen truthfully
            await _prn_run(event, chat_id, user_id, "/proxy_renewal_config", _prn_config_text, _prn_config_buttons)
            return
    except Exception:
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass
# --- TPILOT PROXY RENEWAL (TPilot-managed prolong) UX 20260721 END ---


# --- TPILOT PROXY POOL STAGE6.1C (PIN password reveal) + STAGE6.1F (auto-renew toggle) ---
# Password reveal is deliberately PANEL-SIDE: it reads proxy_leases.password
# directly via a local sqlite3 connection, NEVER through panel_commands/
# _submit_and_wait -- the raw secret never enters that queue, so there is
# nothing for scrub_panel_command_result to have to clean up afterward.

def _ppool_pin_env_value() -> str:
    """PIN source for password reveal: PANEL_ADMIN_PASSWORD preferred,
    falling back to MANAGER_ADMIN_PASSWORD (the SAME existing fallback
    _pin_password() already uses elsewhere in this file). Empty means "no
    PIN configured" -- callers must deny, never fall open."""
    return str(globals().get("PANEL_ADMIN_PASSWORD") or globals().get("MANAGER_ADMIN_PASSWORD") or "").strip()


def _ppool_pin_matches(raw: str, pin_value: str) -> bool:
    """Constant-time PIN comparison (hmac.compare_digest) so a wrong PIN
    cannot be probed character-by-character via response timing. Empty
    configured PIN always denies -- callers must never fall open."""
    import hmac as _pin_hmac
    if not pin_value:
        return False
    return _pin_hmac.compare_digest(
        str(raw or "").encode("utf-8"), str(pin_value).encode("utf-8")
    )


def _ppool_reveal_creds_once(lease_id: int) -> Optional[Dict[str, str]]:
    """Direct local read of proxy_leases.host/port/login/password for one lease.
    Never logs the values, never goes through panel_commands. Returns None if
    the lease doesn't exist or has no password (same gate as before -- a proxy
    without a password is treated as nothing to reveal)."""
    try:
        con = _connect_panel_db()
        try:
            row = con.execute(
                "SELECT host, port, login, password FROM proxy_leases WHERE id=?", (int(lease_id),)
            ).fetchone()
        finally:
            con.close()
        if not row:
            return None
        pw = str(row["password"] or "").strip()
        if not pw:
            return None
        return {
            "host": str(row["host"] or "").strip(),
            "port": str(row["port"] or "").strip(),
            "login": str(row["login"] or "").strip(),
            "password": pw,
        }
    except Exception:
        return None


async def _ppool_run_autorenew_toggle(chat_id: int, user_id: int, lease_id: int, enabled: bool, *, event=None) -> None:
    row = await _submit_and_wait(f"/proxy_pool_autorenew {lease_id} {'1' if enabled else '0'}", user_id, chat_id, chat_id)
    data = _ppool_parse_result_json(row)
    if not data.get("ok"):
        msg = str(data.get("message") or "Не удалось изменить автопродление.")
        try:
            await _ppool_edit_or_send(event, chat_id, "⚠️ " + _safe_text(msg), _ppool_card_buttons("all", {"lease_id": lease_id}))
        except Exception:
            pass
        return
    # Refresh the card so the toggle button label reflects the new state.
    await _ppool_run_card(chat_id, user_id, lease_id, event=event)


# --- TPILOT PROXY METHOD MENU 20260718 REVEAL (moved 20260718 order-fix:
# was originally defined near the top of the file, before `client` is
# created at module scope -- same NameError as _pxm_callback, see the
# note above _pxm_enter_manual. Placed here, right next to its closest
# architectural sibling _ppool_reveal_pin_input (same PIN mechanism, same
# reveal_pin step name, different wizard discriminator: 'pxm' vs 'ppool'
# below), now that `client` exists. ---
@client.on(events.NewMessage)
async def _pxm_reveal_pin_input(event):
    """Standalone text-input handler for the 'pxm'/'reveal_pin' wizard step
    -- mirrors _ppool_reveal_pin_input's exact structure/security model
    (same PIN source via _ppool_pin_env_value, same deny-on-wrong/deny-on-
    unconfigured behavior, same never-log rule) for a manager-keyed
    context. Deliberately a SEPARATE handler (not a branch inside the
    existing lease-keyed one) so the existing ppool: reveal flow is never
    touched -- exactly mirrors how _ppool_reveal_pin_input itself is
    already a standalone handler separate from the giant wizard dispatcher."""
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if not state or str(state.get("wizard") or "") != "pxm" or str(state.get("step") or "") != "reveal_pin":
        return
    key = normalize_manager_key(str((state.get("payload") or {}).get("key") or ""))
    _wizard_clear(chat_id, user_id)
    try:
        await event.delete()
    except Exception:
        pass
    if not key:
        return

    pin_value = _ppool_pin_env_value()
    if not pin_value:
        try:
            # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, admin
            # misconfiguration, no in-chat recovery.
            await client.send_message(chat_id, "PIN не настроен", buttons=_pxm_result_card_buttons(key) + _terminal_ok_button())
        except Exception:
            pass
        return
    if not _ppool_pin_matches(raw, pin_value):
        try:
            await client.send_message(chat_id, "⚠️ Неверный PIN. Proxy не показан.", buttons=_pxm_result_card_buttons(key))
        except Exception:
            pass
        return

    # Revalidate the manager AFTER PIN success -- never trust anything
    # captured before this point.
    if not _manager_row_by_key(key):
        try:
            await client.send_message(chat_id, f"Менеджер не найден: {key}", buttons=_pxm_manager_not_found_buttons())
        except Exception:
            pass
        return
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal; raw
        # secret shown, one-tap dismiss matches the flow's own
        # delete-after-copy intent.
        await client.send_message(chat_id, _safe_text(_pxm_full_reveal_text(key)), buttons=_pxm_full_reveal_buttons(key) + _terminal_ok_button())
    except Exception:
        pass


@client.on(events.NewMessage)
async def _ppool_reveal_pin_input(event):
    """Standalone text-input handler for the 'ppool'/'reveal_pin' wizard
    step -- deliberately separate from the giant panel_wizard_input
    dispatcher (which has no 'ppool' branch, so the two never collide).
    Never logs the PIN or the revealed password."""
    if not _is_allowed(event):
        return
    raw = str(event.raw_text or "").strip()
    if not raw or raw.startswith("/"):
        return
    chat_id = int(event.chat_id or 0)
    user_id = int(event.sender_id or 0)
    state = _wizard_get(chat_id, user_id)
    if not state or str(state.get("wizard") or "") != "ppool" or str(state.get("step") or "") != "reveal_pin":
        return
    try:
        lease_id = int((state.get("payload") or {}).get("lease_id") or 0)
    except Exception:
        lease_id = 0
    _wizard_clear(chat_id, user_id)
    try:
        await event.delete()
    except Exception:
        pass

    # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): every branch below
    # uses the minimal {"lease_id": lease_id} dict (no has_password key), so
    # _ppool_card_buttons degrades to nav-only -- genuinely no retry action
    # in any of these screens, all terminal.
    pin_value = _ppool_pin_env_value()
    if not pin_value:
        try:
            await client.send_message(chat_id, "PIN не настроен", buttons=_ppool_card_buttons("all", {"lease_id": lease_id}) + _terminal_ok_button())
        except Exception:
            pass
        return
    if not _ppool_pin_matches(raw, pin_value):
        try:
            await client.send_message(chat_id, "⚠️ Неверный PIN. Пароль не показан.", buttons=_ppool_card_buttons("all", {"lease_id": lease_id}) + _terminal_ok_button())
        except Exception:
            pass
        return

    creds = _ppool_reveal_creds_once(lease_id)
    if not creds:
        try:
            await client.send_message(chat_id, "У этого proxy нет пароля.", buttons=_ppool_card_buttons("all", {"lease_id": lease_id}) + _terminal_ok_button())
        except Exception:
            pass
        return
    # ONBOARDING SOURCE PICK 20260711: one copyable monospace row instead of a
    # password-only line, so the whole SOCKS5 credential set can be pasted in one
    # go. Still gated behind the same PIN check above -- this is the only place
    # in the project the full proxy password is ever shown. Backticks in a field
    # are defensively neutralized so they can never break out of the code span.
    proxy_row = ":".join(
        str(v or "_").replace("`", "'")
        for v in (creds["host"], creds["port"], creds["login"], creds["password"])
    )
    try:
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): raw secret shown,
        # text explicitly asks the admin to delete after use -- OK is the
        # self-serve mechanism for that.
        await client.send_message(
            chat_id,
            f"🔐 Proxy #{lease_id}:\n\n`{proxy_row}`\n\n⚠️ Удалите это сообщение после использования.",
            buttons=_ppool_card_buttons("all", {"lease_id": lease_id}) + _terminal_ok_button(),
        )
    except Exception:
        pass


@client.on(events.CallbackQuery)
async def _ppool_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("ppool:"):
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)

        if data.startswith("ppool:list:"):
            parts = data.split(":", 2)
            filt = parts[2] if len(parts) > 2 else "all"
            if filt not in _PPOOL_FILTER_LABELS:
                filt = "all"
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:list:{filt}"):
                await _pb_safe_answer(event, "Обновляю...")
                return
            await _pb_safe_answer(event, "⏳ Загружаю список...")
            _pb_track_task(_ppool_run_list(chat_id, user_id, filt, event=event))
            return

        if data.startswith("ppool:details:"):
            parts = data.split(":", 3)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            details = bool(len(parts) > 3 and parts[3] == "1")
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:details:{lease_id}:{details}"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            await _pb_safe_answer(event, )
            _pb_track_task(_ppool_run_card(chat_id, user_id, lease_id, details=details, event=event))
            return

        if data.startswith("ppool:card:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:card:{lease_id}"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            await _pb_safe_answer(event, "⏳ Загружаю карточку...")
            _pb_track_task(_ppool_run_card(chat_id, user_id, lease_id, event=event))
            return

        if data.startswith("ppool:reveal:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            pin_source = _ppool_pin_env_value()
            if not pin_source:
                await _pb_safe_answer(event, "PIN не настроен", alert=True)
                return
            _wizard_set(chat_id, user_id, "ppool", "reveal_pin", {"lease_id": lease_id})
            await _pb_safe_answer(event, )
            try:
                await client.send_message(chat_id, f"🔐 Показать пароль для proxy #{lease_id}\n\nВведите PIN одним сообщением.", buttons=_back_to_panel_buttons())
            except Exception:
                pass
            return

        if data.startswith("ppool:autorenew:"):
            parts = data.split(":", 3)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            enabled_arg = parts[3] if len(parts) > 3 else ""
            if not lease_id or enabled_arg not in ("0", "1"):
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:autorenew:{lease_id}:{enabled_arg}"):
                await _pb_safe_answer(event, "Обновляю...")
                return
            await _pb_safe_answer(event, "⏳ Обновляю автопродление...")
            _pb_track_task(_ppool_run_autorenew_toggle(chat_id, user_id, lease_id, enabled_arg == "1", event=event))
            return

        if data.startswith("ppool:assign_confirm:"):
            parts = data.split(":", 3)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            manager_key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            if not lease_id or not manager_key:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:assign_confirm:{lease_id}:{manager_key}"):
                await _pb_safe_answer(event, "Уже подключаю...")
                return
            # Idempotency/safety: the "assign_confirm" wizard step for this
            # exact lease_id+manager_key is a ONE-TIME token -- consume it
            # here, before spawning the assign task, so a delayed second
            # tap on the same button (past the short dedupe window above)
            # can never trigger a second real assignment.
            state = _wizard_get(chat_id, user_id)
            if not _ppool_assign_confirm_state_ok(state, lease_id, manager_key):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Подключаю...")
            _pb_track_task(_ppool_run_assign(chat_id, user_id, lease_id, manager_key))
            return

        if data.startswith("ppool:assign_multi:"):
            # PROXY USAGE DETECTION 20260711: explicit multi-assign
            # confirmation ("✅ Да, установить" on the usage-conflict
            # warning) -- same one-time-token discipline as assign_confirm.
            parts = data.split(":", 3)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            manager_key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            if not lease_id or not manager_key:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:assign_multi:{lease_id}:{manager_key}"):
                await _pb_safe_answer(event, "Уже подключаю...")
                return
            state = _wizard_get(chat_id, user_id)
            if not _ppool_assign_multi_confirm_state_ok(state, lease_id, manager_key):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Подключаю...")
            _pb_track_task(_ppool_run_assign(chat_id, user_id, lease_id, manager_key, multi=True))
            return

        if data.startswith("ppool:assign_to:"):
            parts = data.split(":", 3)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            manager_key = normalize_manager_key(parts[3]) if len(parts) > 3 else ""
            if not lease_id or not manager_key:
                await _pb_safe_answer(event, "Некорректные данные", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:assign_to:{lease_id}:{manager_key}"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            await _pb_safe_answer(event, )
            _pb_track_task(_ppool_run_assign_confirm_screen(chat_id, user_id, lease_id, manager_key))
            return

        if data.startswith("ppool:assign:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            await _pb_safe_answer(event, )
            _pb_track_task(_ppool_run_assign_picker(chat_id, user_id, lease_id))
            return

        if data.startswith("ppool:unassign_confirm:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:unassign_confirm:{lease_id}"):
                await _pb_safe_answer(event, "Уже отвязываю...")
                return
            state = _wizard_get(chat_id, user_id)
            if not _ppool_unassign_confirm_state_ok(state, lease_id):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Отвязываю...")
            _pb_track_task(_ppool_run_unassign(chat_id, user_id, lease_id))
            return

        if data.startswith("ppool:unassign:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            await _pb_safe_answer(event, )
            _pb_track_task(_ppool_run_unassign_confirm_screen(chat_id, user_id, lease_id))
            return

        if data.startswith("ppool:check:"):
            parts = data.split(":", 2)
            try:
                lease_id = int(parts[2]) if len(parts) > 2 else 0
            except Exception:
                lease_id = 0
            if not lease_id:
                await _pb_safe_answer(event, "Некорректный lease_id", alert=True)
                return
            if _panel_callback_is_duplicate(chat_id, user_id, f"ppool:check:{lease_id}"):
                await _pb_safe_answer(event, "Уже проверяю...")
                return
            await _pb_safe_answer(event, "⏳ Проверяю...")
            _pb_track_task(_ppool_run_check(chat_id, user_id, lease_id, event=event))
            return

        if data == "ppool:sync_confirm":
            if _panel_callback_is_duplicate(chat_id, user_id, "ppool:sync_confirm"):
                await _pb_safe_answer(event, "Уже синхронизирую...")
                return
            # One-time token: the "sync_confirm" wizard step is consumed
            # here, before spawning the sync task, so a delayed second tap
            # (past the short dedupe window above) can never trigger a
            # second sync run from the same confirmation.
            state = _wizard_get(chat_id, user_id)
            if not _ppool_sync_confirm_state_ok(state):
                await _pb_safe_answer(event, "Запрос на подтверждение уже обработан или устарел.", alert=True)
                return
            _wizard_clear(chat_id, user_id)
            await _pb_safe_answer(event, "⏳ Синхронизирую...")
            _pb_track_task(_ppool_run_sync(chat_id, user_id, event=event))
            return

        if data == "ppool:sync":
            if _panel_callback_is_duplicate(chat_id, user_id, "ppool:sync"):
                await _pb_safe_answer(event, "Загружаю...")
                return
            _wizard_set(chat_id, user_id, "ppool", "sync_confirm", {})
            await _pb_safe_answer(event, )
            try:
                await client.send_message(chat_id, _safe_text(_ppool_sync_confirm_text()), buttons=_ppool_sync_confirm_buttons())
            except Exception:
                pass
            return
    except Exception as exc:
        print(f"[ppool] callback error: {exc!r}")
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


