# --- TPILOT AUTO STATUS TOGGLE UI (Patch A) START ---
# Global kill-switch for AUTOMATIC lead-status writes in main.py (settings key
# 'auto_status_enabled'). Mirrors the LLM F1 toggle pattern (menu:llm_toggle) exactly:
# direct settings write via _pb_set_setting, then re-render the same screen in place.
# Does NOT touch manual manager status in any way (lead_status_overrides, ManagerBot
# mb:s:/mb:e: callbacks, /lead fix) -- manual status stays the single source of truth.
_AUTOSTATUS_PREV_TITLE_FOR_MENU = globals().get("_title_for_menu")


def _autostatus_render_automation() -> Tuple[str, list]:
    # N5.3 (D9): render the CANONICAL Автоматизация screen after every
    # auto-status outcome (confirm-stale / do-success / do-stale / malformed)
    # -- mirrors the LLM toggle's reference behavior (nm_llm_toggle_do ->
    # _nm_automation_screen). Previously this delegated to PREV("automation")
    # = the OLD Gen-2 automation screen, ejecting the operator from the
    # canonical tree after every toggle. Fallback chain preserved.
    _nm_screen_fn = globals().get("_nm_automation_screen")
    if callable(_nm_screen_fn):
        try:
            return _nm_screen_fn()
        except Exception:
            pass
    if callable(_AUTOSTATUS_PREV_TITLE_FOR_MENU):
        return _AUTOSTATUS_PREV_TITLE_FOR_MENU("automation")
    return _panel_header(), []


def _title_for_menu(menu: str):  # type: ignore[override]
    raw = str(menu or "main")
    if raw == "autostatus_toggle":
        # N3: historical instant-flip callback -- kept working verbatim for
        # any already-sent Telegram button (contract: historical routes stay
        # handled). The automation screen no longer emits this bare route;
        # it now emits autostatus_toggle_confirm:<target> (see below).
        current = _pb_get_setting("auto_status_enabled")
        new_val = "0" if current != "0" else "1"
        _pb_set_setting("auto_status_enabled", new_val)
        return _autostatus_render_automation()
    if raw.startswith("autostatus_toggle_confirm:"):
        target = raw.split(":", 1)[1]
        if target not in ("0", "1"):
            # N3.1: malformed/forged target -- treated as stale/invalid, never
            # rendered as a (misleading) confirm screen and never mutates.
            text, buttons = _autostatus_render_automation()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        current = _pb_get_setting("auto_status_enabled")
        current_on = current != "0"
        target_on = target != "0"
        if current_on == target_on:
            # Stale: the screen the admin clicked from is already out of
            # date -- no destructive option offered, just the fresh card.
            text, buttons = _autostatus_render_automation()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        action_label = "включить" if target_on else "выключить"
        state_label = "🟢 включены" if current_on else "🔴 выключены"
        text = "\n".join([
            _panel_header(), "",
            "**⏯ Автостатусы: подтверждение**", "",
            f"Текущее состояние: {state_label}",
            f"Если подтвердите — автоматические статусы будут **{action_label}**.",
        ])
        buttons = [
            [Button.inline("✅ Подтвердить", f"menu:autostatus_toggle_do:{target}".encode())],
            # N5.3 (D9): cancel returns to the canonical Автоматизация screen.
            [Button.inline("❌ Отмена", b"menu:nm_automation")],
        ]
        return text, buttons
    if raw.startswith("autostatus_toggle_do:"):
        target = raw.split(":", 1)[1]
        if target not in ("0", "1"):
            # N3.1: malformed/forged target -- never written, treated as
            # stale/invalid, canonical screen rerendered from fresh state.
            text, buttons = _autostatus_render_automation()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        current = _pb_get_setting("auto_status_enabled")
        if (current != "0") == (target != "0"):
            # Stale-state no-op: already at target, do not reapply.
            text, buttons = _autostatus_render_automation()
            return "ℹ️ Состояние уже изменилось.\n\n" + text, buttons
        _pb_set_setting("auto_status_enabled", target)
        return _autostatus_render_automation()
    if callable(_AUTOSTATUS_PREV_TITLE_FOR_MENU):
        return _AUTOSTATUS_PREV_TITLE_FOR_MENU(menu)
    return _panel_header(), []

# --- TPILOT AUTO STATUS TOGGLE UI (Patch A) END ---


