# --- N5.3.1: real Telegram blockquote for the quoted title. The project
# sends every panel message through Telethon's DEFAULT markdown parse mode
# (documented: no parse_mode='html' anywhere), whose parser has no quote
# syntax. This mechanism parses the text with the SAME markdown parser
# Telethon would use internally (so **bold**/`code` behave identically),
# then prepends a MessageEntityBlockquote covering exactly the first line
# when that line is the panel title -- and passes the result as explicit
# formatting_entities. For any other text both overrides below delegate
# verbatim to their PREV implementations.
def _pb_render_with_title_quote(text: str):
    """Returns (clean_text, entities) with a blockquote entity over the
    title line, or (text, None) when the text does not start with the
    panel title (icon + _N531_TITLE_BODY)."""
    try:
        raw = str(text or "")
        first_nl = raw.find("\n")
        first_line = raw if first_nl == -1 else raw[:first_nl]
        if _N531_TITLE_BODY not in first_line:
            return raw, None
        from telethon.extensions import markdown as _tl_md
        from telethon.tl.types import MessageEntityBlockquote
        clean, entities = _tl_md.parse(raw)
        clean_first_nl = clean.find("\n")
        clean_first = clean if clean_first_nl == -1 else clean[:clean_first_nl]
        qlen = len(clean_first.encode("utf-16-le")) // 2
        entities = [MessageEntityBlockquote(offset=0, length=qlen)] + list(entities or [])
        return clean, entities
    except Exception:
        return str(text or ""), None


_N531_PREV_SEND_FRESH_PANEL = globals().get("_send_fresh_panel")
_N531_PREV_SAFE_EVENT_EDIT = globals().get("_safe_event_edit")


async def _send_fresh_panel(chat_id: int, user_id: int = 0, *, delete_previous: bool = True) -> None:  # type: ignore[override]
    text, buttons = _title_for_menu("main")
    clean, entities = _pb_render_with_title_quote(text)
    if entities is None:
        if callable(_N531_PREV_SEND_FRESH_PANEL):
            await _N531_PREV_SEND_FRESH_PANEL(chat_id, user_id, delete_previous=delete_previous)
        return
    if delete_previous:
        await _delete_active_panel(int(chat_id))
    msg = await client.send_message(int(chat_id), clean, formatting_entities=entities, buttons=buttons)
    try:
        _set_active_panel_message(int(chat_id), int(getattr(msg, "id", 0) or 0), int(user_id or 0))
    except Exception:
        pass


async def _safe_event_edit(event, text: str, buttons=None) -> None:  # type: ignore[override]
    clean, entities = _pb_render_with_title_quote(text)
    if entities is None:
        if callable(_N531_PREV_SAFE_EVENT_EDIT):
            await _N531_PREV_SAFE_EVENT_EDIT(event, text, buttons=buttons)
        return
    try:
        await event.edit(clean, formatting_entities=entities, buttons=buttons)
    except Exception as e:
        if e.__class__.__name__ == "MessageNotModifiedError":
            try:
                await _pb_safe_answer(event, "Панель уже обновлена")
            except Exception:
                pass
            return
        raise


async def _pb_send_menu_message(chat_id: int, menu_route: str) -> None:
    """N5.3.2 (Z1): ONE canonical send path for the post-action/wizard
    re-renders that used to call client.send_message with _title_for_menu
    output directly -- bypassing the N5.3.1 blockquote mechanism, so the
    quoted title rendered as a plain line on those paths. Routes through
    the SAME _pb_render_with_title_quote used by _send_fresh_panel/
    _safe_event_edit (no duplicated blockquote-building code); non-title
    screens fall back to the exact old behavior (markdown parse_mode).
    Never raises (mirrors the try/except-pass the 5 original call sites
    already had)."""
    try:
        text, buttons = _title_for_menu(menu_route)
        clean, entities = _pb_render_with_title_quote(text)
        if entities is None:
            await client.send_message(int(chat_id), text, buttons=buttons)
        else:
            await client.send_message(int(chat_id), clean, formatting_entities=entities, buttons=buttons)
    except Exception:
        pass

