# --- TPILOT HEALTH NOTIFICATION V2 20260807 (panel_bot callback) START ---
# hv2: namespace -- currently exactly two actions, both read-only/
# navigation-only (no state mutation): 'card' opens the existing unified
# manager card, 'diag' runs the strictly read-only /hnv2_diag command via
# the existing panel_commands bridge (main.py owns the read-only
# guarantee -- see _hnv2_diag_text's docstring). Every state-CHANGING
# health action (restart/relogin/QR/devlogin/proxy-check/deepcheck) routes
# through the buttons' own already-registered callback_data (relogin:/
# wiz:qr_start:/devlogin:start:/cmd:/...) built in
# _hnv2_health_notification_buttons above -- this handler never needs to
# know about those, Telethon dispatches them to their own existing
# handlers directly.
@client.on(events.CallbackQuery)
async def _hnv2_callback(event):
    try:
        if not _is_allowed(event):
            return
        data = (event.data or b"").decode("utf-8", "ignore")
        if not data.startswith("hv2:"):
            return
        parts = data.split(":", 2)
        if len(parts) < 3:
            await _pb_safe_answer(event, "Некорректные данные", alert=True)
            return
        action = parts[1]
        try:
            manager_id = int(parts[2])
        except Exception:
            manager_id = 0
        if manager_id <= 0:
            await _pb_safe_answer(event, "Некорректный менеджер", alert=True)
            return
        chat_id = int(event.chat_id or 0)
        user_id = int(event.sender_id or 0)
        if _panel_callback_is_duplicate(chat_id, user_id, data):
            await _pb_safe_answer(event, "Уже выполняю...")
            return

        row = _manager_row_by_id(manager_id)
        key = normalize_manager_key((row or {}).get("manager_key") or "")
        if not row or not key:
            await _pb_safe_answer(event, "Менеджер не найден (устарело)", alert=True)
            return
        if str(row.get("status") or "").lower() in ("archived", "deleted"):
            await _pb_safe_answer(event, "Менеджер архивирован", alert=True)
            return

        if action == "card":
            await _panel_answer_fast(event, "⏳ Открываю...")
            _pb_track_task(_pb_send_menu_message(chat_id, f"menu:manager_full:{key}"))
            return

        if action == "diag":
            await _panel_answer_fast(event, "⏳ Диагностика...")
            _pb_track_task(_hnv2_run_diag(chat_id, key))
            return

        await _pb_safe_answer(event, "Неизвестное действие", alert=True)
    except Exception:
        try:
            await _pb_safe_answer(event, "Ошибка", alert=True)
        except Exception:
            pass


async def _hnv2_run_diag(chat_id: int, manager_key: str) -> None:
    """Submits the strictly read-only /hnv2_diag command through the
    EXISTING panel_commands bridge (_submit_and_wait) -- same transport
    every other cmd:/... button already uses, so no new command channel,
    no new timeout handling, no new result-delivery path is introduced.
    Never raises."""
    try:
        result = await _submit_and_wait(f"/hnv2_diag {manager_key}", 0, chat_id, chat_id)
        text = str((result or {}).get("result_text") or "Диагностика не удалась.")
        # TPILOT TERMINAL OK 20260809 (Ф4 bot-wide audit): terminal, diagnostic result.
        await client.send_message(chat_id, _safe_text(text), buttons=_terminal_ok_button())
    except Exception:
        try:
            await client.send_message(chat_id, "Диагностика не удалась.", buttons=_terminal_ok_button())
        except Exception:
            pass

